const LEARN_DATA={"lessons":{"mt_WcfaSfVT33":{"topicId":"mt_WcfaSfVT33","title":"One-to-one counting","audience":"family","keyIdea":"Every object gets exactly one number word.","explain":{"kid":["When you count things, each thing gets exactly one number. Point to each object once and say one number for it.","Don't skip any, and don't count any twice. A good trick is to slide each thing into a 'done' pile as you count it."],"adult":["One-to-one correspondence means pairing each object with exactly one number word, said in order. It is the first rule of reliable counting.","The usual slips are counting an object twice, skipping one, or saying the words faster than pointing. Touching or moving each item fixes most of them. The same pairing idea comes back later, for example when matching items between two sets to compare their sizes."]},"familyTip":"Count stairs, socks or grapes together, touching each one. Make a deliberate mistake now and then and let your child catch you.","practice":[{"type":"mc","id":"p1","prompt":"Sam counts {n} apples but touches one apple twice. What number does Sam say at the end?","choices":["{=n-1}","{n}","{=n+1}"],"answer":2,"hint":"Each touch gets a number word. One apple got two words.","explain":"{n} apples plus one extra touch gives {=n+1} number words, one too many.","params":{"n":[4,8]}},{"type":"numeric","id":"p2","prompt":"Count the stars: ★ ★ ★ ★ ★ ★ ★. How many are there?","answer":7,"hint":"Point at each star once as you say a number.","explain":"There are 7 stars."},{"type":"mc","id":"p3","prompt":"Which way of counting blocks is most reliable?","choices":["Point at each block once while saying one number","Say the numbers quickly while looking at the pile","Count the big blocks, then guess the rest"],"answer":0,"hint":"Think about which way makes sure every block gets one number.","explain":"Pointing at each block once, with one number each, pairs every block with exactly one number word."},{"type":"order","id":"p4","prompt":"Put the counting words in order.","items":["one","two","three","four","five"],"hint":"Start with the smallest number.","explain":"Counting words always come in the same order: one, two, three, four, five."},{"type":"numeric","id":"p5","prompt":"Ben touches each of {n} shells once, saying one number for each. What number does he say last?","answer":"n","hint":"One touch, one number.","explain":"He says {n}: one number for each shell.","params":{"n":[4,10]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Count the hearts: ♥ ♥ ♥ ♥ ♥ ♥ ♥ ♥ ♥. How many?","answer":9,"hint":"Slide your finger along and count each heart once.","explain":"There are 9 hearts."},{"type":"mc","id":"m2","prompt":"Mia counts cups and says 'one, two, three, four', but she missed one cup without giving it a number. How many cups are there really?","choices":["3","4","5"],"answer":2,"hint":"The missed cup still needs a number.","explain":"Four cups got numbers and one was missed, so there are 5 cups."},{"type":"mc","id":"m3","prompt":"Ravi points to 3 pencils but says 'one, two, three, four'. What went wrong?","choices":["He said one more number than the pencils he pointed to","He pointed at too many pencils","Nothing went wrong"],"answer":0,"hint":"Compare the number of words with the number of pencils.","explain":"He said four words for three pencils, so his words and his pointing did not match one-to-one."},{"type":"numeric","id":"m4","prompt":"Leo touches each of {n} toy cars once and says one number for each. What number does he say last?","answer":"n","hint":"One touch, one number.","explain":"He says {n}: one number for each of the {n} cars.","params":{"n":[4,9]}},{"type":"numeric","id":"m5","prompt":"Zara counts {n} beads but touches one bead twice. What number does she say at the end?","answer":"n+1","hint":"The bead touched twice got two numbers.","explain":"{n} beads plus one extra touch gives {=n+1} number words, one too many.","params":{"n":[4,9]}},{"type":"numeric","id":"m6","prompt":"Omar counts {n} spoons but skips one by mistake. What number does he say last?","answer":"n-1","hint":"The skipped spoon got no number.","explain":"He gives numbers to only {=n-1} of the {n} spoons, so he says {=n-1}.","params":{"n":[5,10]}},{"type":"mc","id":"m7","prompt":"What is the best way to make sure you don't count a sock twice?","choices":["Move each sock to a new pile as you count it","Count as fast as you can","Only count the socks you can see from far away"],"answer":0,"hint":"How can you tell which socks are already counted?","explain":"Moving each counted sock to a new pile means it can't be counted again."}]},"status":"self-checked","visual":{"type":"counters","caption":"Tap or drag each counter down to count it. Each one gets exactly one number.","opts":{"mode":"count","n":5}}},"mt_dmNvjroCPT":{"topicId":"mt_dmNvjroCPT","title":"How many in total?","audience":"family","keyIdea":"The last number you say when counting tells you how many there are.","explain":{"kid":["When you finish counting, the last number you say tells you how many there are.","It does not matter which one you start with. It does not matter how they are laid out. A line of 6 and a messy pile of 6 are both 6."],"adult":["This is the cardinality principle: the final number word names the size of the whole set. A child who recounts from one when asked 'how many?' can recite numbers but hasn't yet linked the last word to the total.","Two related facts: the order you count in doesn't change the total, and spreading out or bunching up the objects doesn't change it either."]},"familyTip":"Ask 'so how many is that?' after counting. If your child starts again from one, count together and stress the last word.","practice":[{"type":"mc","id":"p1","prompt":"You count shells, and the last number you say is {n}. How many shells are there?","choices":["1","{n}","{=n+1}"],"answer":1,"hint":"Which number did you say last?","explain":"The last number you said was {n}, so there are {n} shells.","params":{"n":[5,12]}},{"type":"mc","id":"p2","prompt":"8 counters in a line are pushed together into a pile. How many counters are there now?","choices":["Fewer than 8","8","More than 8"],"answer":1,"hint":"Did any counters get added or taken away?","explain":"Moving counters doesn't add or remove any, so there are still 8."},{"type":"numeric","id":"p3","prompt":"Count the triangles: ▲ ▲ ▲ ▲ ▲ ▲ ▲ ▲ ▲ ▲ ▲ ▲. How many?","answer":12,"hint":"Count in a steady rhythm, one triangle per word.","explain":"There are 12 triangles."},{"type":"mc","id":"p4","prompt":"Lily counts some toys starting with the teddy and gets 6. Jo counts the same toys starting with the car. What should Jo get?","choices":["6","5","It depends where Jo starts"],"answer":0,"hint":"Does the starting point change how many toys there are?","explain":"The number of toys is the same whatever order you count them in, so Jo also gets 6."},{"type":"numeric","id":"p5","prompt":"{n} counters in a line are pushed together into a pile. How many counters are there now?","answer":"n","hint":"Did any counters get added or taken away?","explain":"Moving counters doesn't add or take any away, so there are still {n}.","params":{"n":[5,12]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"After counting 'one, two, … nine', someone asks 'How many?' What is the best answer?","choices":["Nine","Count again from one","One"],"answer":0,"hint":"The last number you said tells you.","explain":"The last number word, nine, is the total."},{"type":"numeric","id":"m2","prompt":"How many stars altogether? ★ ★ ★   ★ ★   ★ ★ ★ ★","answer":9,"hint":"Count every star across all the groups.","explain":"3 + 2 + 4 = 9 stars."},{"type":"mc","id":"m3","prompt":"Ten coins are spread out on a table. Another ten coins are stacked in a tower. Which has more coins?","choices":["The spread-out coins","The tower","They have the same"],"answer":2,"hint":"Count each set in your head.","explain":"Both sets have ten coins; the arrangement doesn't change the number."},{"type":"numeric","id":"m4","prompt":"You count leaves and the last number you say is {n}. How many leaves are there?","answer":"n","hint":"The last number tells you.","explain":"There are {n} leaves: the last number said is the total.","params":{"n":[5,12]}},{"type":"numeric","id":"m5","prompt":"Stars are in two groups: {a} on the left and {b} on the right. You count every star, one by one. How many stars are there?","answer":"a+b","hint":"Keep counting from the left group straight into the right group.","explain":"{a} and {b} more makes {=a+b} stars.","params":{"a":[2,6],"b":[2,6]}},{"type":"numeric","id":"m6","prompt":"A tower of {n} blocks gets knocked over and the blocks scatter across the floor. How many blocks are there now?","answer":"n","hint":"Did any blocks disappear?","explain":"Still {n}. Moving the blocks doesn't change how many there are.","params":{"n":[6,12]}},{"type":"mc","id":"m7","prompt":"Jay counts 7 cars starting from the red one. Kim counts them again starting from the blue one. What should Kim get?","choices":["7","More than 7","Fewer than 7"],"answer":0,"hint":"Does the starting car change how many cars there are?","explain":"Kim also gets 7. The order you count in doesn't change the total."}]},"status":"self-checked","visual":{"type":"tenframe","caption":"Add red and blue counters. How many altogether? The ten-frame shows how close you are to 10.","opts":{"a":3,"b":4}}},"mt_OvyoRo47K-":{"topicId":"mt_OvyoRo47K-","title":"Adding by putting groups together","audience":"family","keyIdea":"Adding means putting groups together to find how many altogether.","explain":{"kid":["Adding means putting groups together and finding how many there are altogether. 3 red cars and 2 blue cars make 5 cars, so 3 + 2 = 5.","You can count them all, or start at the bigger number and count on: 3… 4, 5."],"adult":["Addition models combining two separate groups; the total is the size of the combined group. Strategies usually develop from 'count all', to 'count on from the larger number', to just knowing the fact.","Order doesn't matter (3 + 2 = 2 + 3). That property is called commutativity, and it is what lets you start from the larger number."]},"familyTip":"Use snack time: 'You have 3 crackers and I give you 2 more. How many now?' Then swap the order and ask again.","practice":[{"type":"numeric","id":"p1","prompt":"{a} apples and {b} apples. How many apples altogether?","answer":"a+b","hint":"Start at {a} and count on {b} more.","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,6],"b":[2,6]}},{"type":"mc","id":"p2","prompt":"Which number sentence matches 'two cats and five cats'?","choices":["2 + 5 = 7","5 − 2 = 3","2 + 5 = 8"],"answer":0,"hint":"You are putting the groups together, so add.","explain":"Two cats and five cats make seven: 2 + 5 = 7."},{"type":"numeric","id":"p3","prompt":"Start at 6 and count on 3: 7, 8, 9. So what is 6 + 3?","answer":9,"hint":"The last number you counted on to is the answer.","explain":"6 + 3 = 9."},{"type":"mc","id":"p4","prompt":"Is 2 + 6 the same as 6 + 2?","choices":["Yes, both are 8","No, 2 + 6 is bigger","No, 6 + 2 is bigger"],"answer":0,"hint":"Work both out.","explain":"Both are 8; you can add in either order."},{"type":"numeric","id":"p5","prompt":"Start at {a} and count on {b}. What is {a} + {b}?","answer":"a+b","hint":"Say the next {b} numbers after {a}.","explain":"Counting on {b} from {a} lands on {=a+b}, so {a} + {b} = {=a+b}.","params":{"a":[5,9],"b":[1,3]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is 5 + 4?","answer":9,"hint":"Start at 5 and count on 4.","explain":"5 + 4 = 9."},{"type":"numeric","id":"m2","prompt":"A bag has 7 marbles. You put in 3 more. How many marbles are in the bag now?","answer":10,"hint":"Combine 7 and 3.","explain":"7 + 3 = 10."},{"type":"mc","id":"m3","prompt":"Which one is NOT equal to 6?","choices":["3 + 3","4 + 2","5 + 2"],"answer":2,"hint":"Work out each one.","explain":"3 + 3 and 4 + 2 both make 6, but 5 + 2 = 7."},{"type":"numeric","id":"m4","prompt":"What is {a} + {b}?","answer":"a+b","hint":"Start at the bigger number and count on.","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"numeric","id":"m5","prompt":"There are {a} ducks on a pond. {b} more ducks land. How many ducks are there now?","answer":"a+b","hint":"Put the two groups together.","explain":"{a} + {b} = {=a+b} ducks.","params":{"a":[3,9],"b":[2,6]}},{"type":"mc","id":"m6","prompt":"Which is the same as {a} + {b}?","choices":["{b} + {a}","{a} − {b}","{=a+b+1}"],"answer":0,"hint":"You can add in either order.","explain":"{a} + {b} and {b} + {a} both make {=a+b}.","params":{"a":[2,8],"b":[2,8]},"where":"a>b"},{"type":"numeric","id":"m7","prompt":"You have {a} red pencils and {b} blue pencils. How many pencils do you have altogether?","answer":"a+b","hint":"Combine both colours.","explain":"{a} + {b} = {=a+b} pencils.","params":{"a":[2,9],"b":[2,9]}}]},"status":"self-checked","visual":{"type":"counters","caption":"Two groups. Push them together and count them all.","opts":{"mode":"combine","a":3,"b":2}}},"mt_zuKAX6lcYR":{"topicId":"mt_zuKAX6lcYR","title":"Subtracting by taking away","audience":"family","keyIdea":"Subtracting means taking some away and finding how many are left.","explain":{"kid":["Subtracting means taking some away and finding how many are left. 7 birds sit on a fence, 3 fly away, and 4 are left: 7 − 3 = 4.","You can count back (6, 5, 4), or think 'what do I add to 3 to make 7?'"],"adult":["Subtraction models taking away part of a group. It also answers 'how many more?' (comparing) and 'what's the missing part?' questions.","Unlike addition, order matters: 7 − 3 is not 3 − 7. Linking subtraction to addition (3 + ? = 7) builds the idea of inverse operations, which algebra uses all the time."]},"familyTip":"Act it out with toys: line up 7, 'send' 3 away, and ask how many stayed. Then ask the 'what do I add?' version.","practice":[{"type":"numeric","id":"p1","prompt":"You have {a} sweets and eat {b}. How many are left?","answer":"a-b","hint":"Count back {b} from {a}.","explain":"{a} − {b} = {=a-b}.","params":{"a":[6,10],"b":[2,4]}},{"type":"mc","id":"p2","prompt":"Which matches 'I had 8 balloons and 2 popped'?","choices":["8 − 2 = 6","8 + 2 = 10","2 − 8 = 6"],"answer":0,"hint":"Balloons were taken away, and you start with the 8.","explain":"Start with 8 and take away 2: 8 − 2 = 6."},{"type":"numeric","id":"p3","prompt":"Count back 3 from 10: 9, 8, 7. So what is 10 − 3?","answer":7,"hint":"The last number you counted back to is the answer.","explain":"10 − 3 = 7."},{"type":"mc","id":"p4","prompt":"Which addition fact helps you work out 9 − 5?","choices":["5 + 4 = 9","9 + 5 = 14","5 + 5 = 10"],"answer":0,"hint":"Look for a fact with 5 and 9 where 9 is the total.","explain":"5 + 4 = 9, so 9 − 5 = 4."},{"type":"numeric","id":"p5","prompt":"Count back {b} from {a}. What is {a} − {b}?","answer":"a-b","hint":"Say {b} numbers going down from {a}.","explain":"Counting back {b} from {a} lands on {=a-b}, so {a} − {b} = {=a-b}.","params":{"a":[8,12],"b":[1,3]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is 12 − 5?","answer":7,"hint":"Think: 5 + ? = 12.","explain":"5 + 7 = 12, so 12 − 5 = 7."},{"type":"numeric","id":"m2","prompt":"6 children are playing and 2 go home. How many are still playing?","answer":4,"hint":"Take 2 away from 6.","explain":"6 − 2 = 4."},{"type":"mc","id":"m3","prompt":"Is 6 − 2 the same as 2 − 6?","choices":["No, order matters in subtraction","Yes, both are 4","Yes, both are 8"],"answer":0,"hint":"Try it with real objects: can you take 6 away from 2?","explain":"6 − 2 = 4, but 2 − 6 is not 4: taking 6 from 2 goes below zero (to −4, which you'll meet later). Order matters in subtraction."},{"type":"numeric","id":"m4","prompt":"What is {a} − {b}?","answer":"a-b","hint":"Count back {b} from {a}.","explain":"{a} − {b} = {=a-b}.","params":{"a":[6,15],"b":[2,5]}},{"type":"numeric","id":"m5","prompt":"{a} birds sit on a fence. {b} fly away. How many are left?","answer":"a-b","hint":"Take away the birds that flew off.","explain":"{a} − {b} = {=a-b} birds.","params":{"a":[5,12],"b":[1,4]}},{"type":"mc","id":"m6","prompt":"Which addition fact helps you work out {=a+b} − {a}?","choices":["{a} + {b} = {=a+b}","{=a+b} + {a} = {=2*a+b}","{a} + {a} = {=2*a}"],"answer":0,"hint":"Look for a fact where {=a+b} is the total.","explain":"{a} + {b} = {=a+b}, so {=a+b} − {a} = {b}.","params":{"a":[3,9],"b":[2,9]},"where":"a!=b"},{"type":"numeric","id":"m7","prompt":"□ + {a} = {=a+b}. What number goes in the box?","answer":"b","hint":"What do you add to {a} to make {=a+b}?","explain":"{b} + {a} = {=a+b}, so the box is {b}.","params":{"a":[2,9],"b":[2,9]}}]},"status":"self-checked","visual":{"type":"counters","caption":"Tap or drag counters away. How many are left?","opts":{"mode":"takeaway","n":8}}},"mt_8RmpkDxT9L":{"topicId":"mt_8RmpkDxT9L","title":"Reading +, − and =","audience":"family","keyIdea":"+ means add, − means take away, and = means 'is the same as'.","explain":{"kid":["+ means plus, or add. − means minus, or take away. = means equals, or 'is the same as'.","4 + 1 = 5 is read 'four plus one equals five'. You can also write it the other way round: 5 = 4 + 1."],"adult":["Number sentences are a child's first algebraic notation. Read + as 'plus', − as 'minus' (or 'subtract') and = as 'equals, the same amount as'.","Show sentences in both directions, like 5 = 4 + 1, so that = doesn't come to mean 'the answer goes next'. That habit causes trouble later."]},"familyTip":"Write a sum with a gap for the symbol, such as 4 _ 2 = 6, and let your child fill in the sign.","practice":[{"type":"mc","id":"p1","prompt":"How do you read 6 − 2 = 4?","choices":["six minus two equals four","six plus two equals four","six equals two minus four"],"answer":0,"hint":"− is read 'minus'.","explain":"6 − 2 = 4 is 'six minus two equals four'."},{"type":"mc","id":"p2","prompt":"Fill the gap: {a} □ {b} = {=a+b}. Which symbol goes in the box?","choices":["+","−","="],"answer":0,"hint":"Is {=a+b} bigger or smaller than {a}?","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"mc","id":"p3","prompt":"Which symbol goes in the box? 9 □ 3 = 6","choices":["+","−","="],"answer":1,"hint":"Is 6 smaller or bigger than 9? Smaller means something was taken away.","explain":"9 − 3 = 6."},{"type":"order","id":"p4","prompt":"Build the number sentence for 'five take away one is four'.","items":["5","−","1","=","4"],"hint":"Start with the number you begin with.","explain":"5 − 1 = 4."},{"type":"mc","id":"p5","prompt":"Fill the gap: {a} □ {b} = {=a-b}. Which symbol goes in the box?","choices":["+","−","="],"answer":1,"hint":"Is {=a-b} bigger or smaller than {a}?","explain":"{a} − {b} = {=a-b}.","params":{"a":[6,12],"b":[1,4]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which says 'two plus two is the same as four'?","choices":["2 + 2 = 4","2 − 2 = 4","4 + 2 = 2"],"answer":0,"hint":"Look for plus, then equals.","explain":"2 + 2 = 4."},{"type":"mc","id":"m2","prompt":"Which symbol goes in the box? 8 □ 2 = 10","choices":["+","−","="],"answer":0,"hint":"10 is bigger than 8.","explain":"8 + 2 = 10."},{"type":"mc","id":"m3","prompt":"Which number sentence is written correctly?","choices":["7 = 5 + 2","7 + = 5 2","= 7 5 + 2"],"answer":0,"hint":"Each symbol needs a number on both sides.","explain":"7 = 5 + 2 is a correct, true sentence: 7 is the same as 5 + 2."},{"type":"mc","id":"m4","prompt":"Which symbol goes in the box? {a} □ {b} = {=a+b}","choices":["+","−","="],"answer":0,"hint":"Is the answer bigger or smaller than {a}?","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"mc","id":"m5","prompt":"Which symbol goes in the box? {a} □ {b} = {=a-b}","choices":["+","−","="],"answer":1,"hint":"Is the answer bigger or smaller than {a}?","explain":"{a} − {b} = {=a-b}.","params":{"a":[5,15],"b":[1,4]}},{"type":"mc","id":"m6","prompt":"How do you read {a} + {b} = {=a+b}?","choices":["{a} plus {b} equals {=a+b}","{a} minus {b} equals {=a+b}","{a} equals {b} plus {=a+b}"],"answer":0,"hint":"+ is read 'plus'.","explain":"It's read '{a} plus {b} equals {=a+b}'.","params":{"a":[2,9],"b":[2,9]}},{"type":"mc","id":"m7","prompt":"What does = mean?","choices":["Is the same as","The answer comes next","Add"],"answer":0,"hint":"Think of a balanced seesaw.","explain":"= means both sides are the same amount."}]},"status":"self-checked","visual":{"type":"symbols","caption":"Choose + or −, change the numbers, and read the sentence. The bottom row shows what = means.","opts":{"a":7,"b":2,"op":"-"}}},"mt_oIzycTBeE4":{"topicId":"mt_oIzycTBeE4","title":"What the equals sign means","audience":"family","keyIdea":"= means both sides are worth the same, like a balanced seesaw.","explain":{"kid":["= means both sides are worth the same, like a balanced seesaw.","3 + 4 = 7 is true, and so is 7 = 3 + 4. Even 3 + 4 = 5 + 2 is true, because both sides make 7."],"adult":["The equals sign states a relationship ('is the same as'), not an instruction to calculate. Many learners read = as 'and the answer is', which leads to errors like 8 + 4 = □ + 5, then writing 12 in the box.","Asking whether sentences are true or false (9 = 4 + 5, 2 + 6 = 6 + 3) builds the balanced view of equations that algebra depends on."]},"familyTip":"Use a seesaw or kitchen scales: 'Is this side the same as that side?' Swap which side the answer is on.","practice":[{"type":"mc","id":"p1","prompt":"True or false: 3 + 4 = 5 + 2","choices":["True","False"],"answer":0,"hint":"Work out each side separately.","explain":"Both sides equal 7, so it is true."},{"type":"numeric","id":"p2","prompt":"{a} + {b} = □ + {c}. What number goes in the box?","answer":"a+b-c","hint":"The left side makes {=a+b}. What plus {c} makes {=a+b}?","explain":"{a} + {b} = {=a+b} and {=a+b-c} + {c} = {=a+b}, so the box is {=a+b-c}.","params":{"a":[3,9],"b":[2,9],"c":[1,9]},"where":"a+b>c"},{"type":"mc","id":"p3","prompt":"True or false: 9 = 4 + 5","choices":["True","False"],"answer":0,"hint":"The sum can be on either side.","explain":"4 + 5 = 9, so it is true."},{"type":"mc","id":"p4","prompt":"True or false: 2 + 6 = 6 + 3","choices":["True","False"],"answer":1,"hint":"Work out each side.","explain":"2 + 6 = 8 but 6 + 3 = 9, so it is false."},{"type":"mc","id":"p5","prompt":"True or false: {a} + {b} = {=a+1} + {=b-1}","choices":["True","False"],"answer":0,"hint":"Work out each side.","explain":"Both sides make {=a+b}, so it is true.","params":{"a":[2,9],"b":[2,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"10 = 6 + □. What goes in the box?","answer":4,"hint":"6 plus what makes 10?","explain":"6 + 4 = 10."},{"type":"numeric","id":"m2","prompt":"5 + 5 = 3 + □. What goes in the box?","answer":7,"hint":"The left side is 10.","explain":"5 + 5 = 10 and 3 + 7 = 10."},{"type":"mc","id":"m3","prompt":"Someone writes 8 + 4 = 12 + 5 = 17. What's wrong?","choices":["8 + 4 is not the same as 12 + 5, so the first = is false","Nothing is wrong","The answer should be 16"],"answer":0,"hint":"Check whether each pair of sides joined by = really is equal.","explain":"8 + 4 = 12, which is not 12 + 5. Each = must join two things of equal value."},{"type":"numeric","id":"m4","prompt":"{a} + {b} = {c} + □. What goes in the box?","answer":"a+b-c","hint":"Work out the left side first.","explain":"The left side is {=a+b}, and {c} + {=a+b-c} = {=a+b}.","params":{"a":[2,9],"b":[2,9],"c":[1,8]},"where":"a+b>c"},{"type":"mc","id":"m5","prompt":"True or false: {a} + {b} = {b} + {a}","choices":["True","False"],"answer":0,"hint":"Work out each side.","explain":"Both sides make {=a+b}, so it's true.","params":{"a":[2,9],"b":[2,9]},"where":"a!=b"},{"type":"mc","id":"m6","prompt":"True or false: {a} + {b} = {=a+b+1}","choices":["True","False"],"answer":1,"hint":"Work out the left side.","explain":"{a} + {b} = {=a+b}, not {=a+b+1}, so it's false.","params":{"a":[2,9],"b":[2,9]}},{"type":"numeric","id":"m7","prompt":"{a} = {b} + □. What goes in the box?","answer":"a-b","hint":"{b} plus what makes {a}?","explain":"{b} + {=a-b} = {a}.","params":{"a":[5,15],"b":[1,9]},"where":"a>b"}]},"status":"self-checked","visual":{"type":"balance","caption":"Make the right side the same value as the left. The scale levels when both sides are equal.","opts":{"mode":"equal","left":[3,4],"right":5}}},"mt_PZ909yPrEC":{"topicId":"mt_PZ909yPrEC","title":"Multiplying as repeated adding","audience":"family","keyIdea":"Multiplying is a quick way to add equal groups.","explain":{"kid":["Multiplying is a fast way to add equal groups. 3 bags with 4 sweets in each is 4 + 4 + 4 = 12.","We write it 3 × 4 = 12 and say 'three groups of four'."],"adult":["a × b counts a equal groups of b. Two models are used: repeated addition (4 + 4 + 4) and arrays (3 rows of 4). Arrays show clearly why 3 × 4 = 4 × 3: turn the array on its side.","Some schools read 3 × 4 as 'three groups of four' and others as 'three, four times'. Both give 12, and an array shows why the order doesn't change the answer. Repeated addition only works for equal groups; later, multiplication is extended to scaling, which is how it makes sense for fractions."]},"familyTip":"Spot equal groups at home: wheels on cars, legs on chairs, eggs in a box. Ask 'how many groups, and how many in each?'","practice":[{"type":"mc","id":"p1","prompt":"Which multiplication matches 5 + 5 + 5?","choices":["3 × 5","5 × 5","3 + 5"],"answer":0,"hint":"How many fives are there?","explain":"There are three fives, so it is 3 × 5 = 15."},{"type":"numeric","id":"p2","prompt":"{a} groups of {b}. How many altogether?","answer":"a*b","hint":"Add {b} again and again, {a} times.","explain":"{a} × {b} = {=a*b}.","params":{"a":[2,5],"b":[2,5]}},{"type":"numeric","id":"p3","prompt":"Two rows of dots: ●●●●● and ●●●●●. How many dots?","answer":10,"hint":"Two rows of 5.","explain":"2 × 5 = 10."},{"type":"mc","id":"p4","prompt":"Is 2 + 3 + 4 an example of equal groups, like a multiplication?","choices":["No, because the groups are not the same size","Yes, it is three groups","Yes, it is groups of 4"],"answer":0,"hint":"Multiplication counts groups that are all the same size.","explain":"The groups are 2, 3 and 4, which are different sizes, so this is not repeated addition of equal groups."},{"type":"numeric","id":"p5","prompt":"{a} rows of {b} dots. How many dots?","answer":"a*b","hint":"Add one row at a time.","explain":"{a} × {b} = {=a*b} dots.","params":{"a":[2,4],"b":[3,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Write 6 + 6 + 6 + 6 as 4 × 6. What does it equal?","answer":24,"hint":"Add 6 four times.","explain":"4 × 6 = 24."},{"type":"mc","id":"m2","prompt":"Which one is the same as 3 groups of 2?","choices":["2 + 2 + 2","3 + 2","3 + 3 + 3"],"answer":0,"hint":"Make 3 groups with 2 in each.","explain":"3 groups of 2 is 2 + 2 + 2 = 6, which we write 3 × 2."},{"type":"numeric","id":"m3","prompt":"5 boxes with 2 eggs in each. How many eggs?","answer":10,"hint":"5 groups of 2.","explain":"5 × 2 = 10."},{"type":"numeric","id":"m4","prompt":"{a} bags each hold {b} sweets. How many sweets altogether?","answer":"a*b","hint":"{a} groups of {b}.","explain":"{a} × {b} = {=a*b}.","params":{"a":[2,6],"b":[2,9]}},{"type":"mc","id":"m5","prompt":"Which multiplication matches adding {b} again and again, {a} times?","choices":["{a} × {b}","{a} + {b}","{=a+b} × {b}"],"answer":0,"hint":"How many groups, and how many in each?","explain":"{a} groups of {b} is {a} × {b} = {=a*b}.","params":{"a":[2,5],"b":[2,9]},"where":"a!=b"},{"type":"numeric","id":"m6","prompt":"An array has {a} rows with {b} dots in each row. How many dots?","answer":"a*b","hint":"Add one row at a time.","explain":"{a} × {b} = {=a*b} dots.","params":{"a":[2,5],"b":[2,6]}},{"type":"mc","id":"m7","prompt":"Which of these shows equal groups?","choices":["3 plates with 4 grapes on each","Plates with 2, 5 and 3 grapes","One plate with 12 grapes next to an empty plate"],"answer":0,"hint":"Equal groups all hold the same number.","explain":"Only the 3 plates of 4 have the same number in each group, so that is 3 × 4."}]},"status":"self-checked","visual":{"type":"array","caption":"Rows of counters: 3 rows of 4 is 4 + 4 + 4. Change the rows and columns.","opts":{"rows":3,"cols":4}}},"mt_LpSuPgL31x":{"topicId":"mt_LpSuPgL31x","title":"Dividing by sharing equally","audience":"family","keyIdea":"Dividing means sharing fairly into equal groups.","explain":{"kid":["Dividing means sharing fairly, so every group gets the same. 12 grapes shared between 3 friends gives 4 each: 12 ÷ 3 = 4.","It can also mean 'how many groups of 3 can I make from 12?' The answer is 4 again."],"adult":["Division has two meanings: sharing (12 into 3 groups: how many in each?) and grouping (how many 3s fit into 12?). Both give 12 ÷ 3 = 4.","Division undoes multiplication (3 × 4 = 12). The 'equal shares' idea is exactly what fractions build on: 1/3 of 12 is one of three equal shares."]},"familyTip":"Share snacks out 'one for you, one for me' and ask whether it came out fair. Try amounts that don't share evenly, too.","practice":[{"type":"numeric","id":"p1","prompt":"{=a*b} grapes are shared fairly between {a} children. How many grapes does each child get?","answer":"b","hint":"Give one each in turn until they run out.","explain":"{=a*b} ÷ {a} = {b}.","params":{"a":[2,4],"b":[2,5]}},{"type":"numeric","id":"p2","prompt":"How many groups of 4 can you make from 8 cupcakes?","answer":2,"hint":"Keep taking 4 away until none are left.","explain":"8 ÷ 4 = 2."},{"type":"mc","id":"p3","prompt":"9 sweets are shared as 4, 3 and 2. Is that fair sharing?","choices":["No, the shares are not equal","Yes, all 9 were given out","Yes, everyone got some"],"answer":0,"hint":"Fair sharing means everyone gets the same.","explain":"The shares are different sizes. Fair sharing of 9 between 3 would give 3 each."},{"type":"mc","id":"p4","prompt":"Which fact helps you work out 15 ÷ 3?","choices":["3 × 5 = 15","15 − 3 = 12","3 + 15 = 18"],"answer":0,"hint":"Division undoes multiplication.","explain":"3 × 5 = 15, so 15 ÷ 3 = 5."},{"type":"numeric","id":"p5","prompt":"How many groups of {a} can you make from {=a*b} cupcakes?","answer":"b","hint":"Keep taking {a} away until none are left.","explain":"{=a*b} ÷ {a} = {b}.","params":{"a":[2,5],"b":[2,4]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is 12 ÷ 4?","answer":3,"hint":"How many 4s make 12?","explain":"4 × 3 = 12, so 12 ÷ 4 = 3."},{"type":"numeric","id":"m2","prompt":"18 pencils are put into packs of 6. How many packs?","answer":3,"hint":"How many 6s make 18?","explain":"6 × 3 = 18, so there are 3 packs."},{"type":"numeric","id":"m3","prompt":"6 cookies are shared equally between 3 children. How many does each child get?","answer":2,"hint":"Share one at a time.","explain":"6 ÷ 3 = 2."},{"type":"numeric","id":"m4","prompt":"{=a*b} stickers are shared equally between {a} friends. How many does each friend get?","answer":"b","hint":"Share them out one at a time.","explain":"{=a*b} ÷ {a} = {b}, because {a} × {b} = {=a*b}.","params":{"a":[2,5],"b":[2,6]}},{"type":"numeric","id":"m5","prompt":"How many groups of {a} can you make from {=a*b} counters?","answer":"b","hint":"How many {a}s make {=a*b}?","explain":"{a} × {b} = {=a*b}, so you can make {b} groups.","params":{"a":[2,5],"b":[2,6]}},{"type":"mc","id":"m6","prompt":"Which fact helps you work out {=a*b} ÷ {a}?","choices":["{a} × {b} = {=a*b}","{=a*b} − {a} = {=a*b-a}","{a} + {b} = {=a+b}"],"answer":0,"hint":"Division undoes multiplication.","explain":"{a} × {b} = {=a*b}, so {=a*b} ÷ {a} = {b}.","params":{"a":[2,5],"b":[2,9]}},{"type":"mc","id":"m7","prompt":"Is it fair to share 10 grapes as 5 and 5?","choices":["Yes, both shares are equal","No, 10 can't be shared","No, one share is bigger"],"answer":0,"hint":"Compare the two shares.","explain":"5 and 5 are equal shares, so it's fair: 10 ÷ 2 = 5."}]},"status":"self-checked","visual":{"type":"share","caption":"Deal the counters into equal groups, one each at a time.","opts":{"total":12,"groups":3}}},"mt_vKcxX6iNOA":{"topicId":"mt_vKcxX6iNOA","title":"Fraction words and notation","audience":"family","keyIdea":"The denominator says how many equal parts the whole has; the numerator says how many of them you mean.","explain":{"kid":["A fraction like 3/4 has two numbers. The bottom number is the denominator. It tells you how many equal parts the whole is cut into. The top number is the numerator. It tells you how many of those parts we mean.","So 3/4 means: cut it into 4 equal parts and take 3. A fraction with 1 on top, like 1/4, is called a unit fraction."],"adult":["The numerator counts the parts. The denominator says how many equal parts make the whole. A unit fraction has 1 on top. A proper fraction is less than 1, like 3/4. An improper fraction has a top number equal to or bigger than the bottom, like 7/4. A mixed number, like 1¾, is a whole number and a fraction.","Equivalent fractions have the same value, like 1/2 and 2/4. A fraction is in simplest form when no number except 1 divides both the top and the bottom, as in 3/7 (but not 6/9)."]},"familyTip":"When cutting a sandwich or pizza, name it: 'four equal pieces, so each is one quarter, 1/4'.","practice":[{"type":"mc","id":"p1","prompt":"In 2/5, which number is the denominator?","choices":["5","2","7"],"answer":0,"hint":"The denominator is the bottom number.","explain":"The denominator is 5: the whole is cut into 5 equal parts."},{"type":"mc","id":"p2","prompt":"Which is a unit fraction?","choices":["1/6","2/6","6/1"],"answer":0,"hint":"A unit fraction has 1 on top.","explain":"1/6 has numerator 1, so it is a unit fraction."},{"type":"mc","id":"p3","prompt":"Which is an improper fraction?","choices":["7/4","3/4","1/2"],"answer":0,"hint":"Look for a top number at least as big as the bottom number.","explain":"7/4 has a numerator bigger than its denominator, so it is improper (it is more than 1 whole)."},{"type":"mc","id":"p4","prompt":"A pizza is cut into {d} equal slices and you eat {n}. What fraction did you eat?","choices":["{n}/{d}","{d}/{n}","{n}/{=d-n}"],"answer":0,"hint":"The whole is {d} slices.","explain":"{n} of {d} equal slices is {n}/{d}.","params":{"n":[1,5],"d":[3,8]},"where":"n<d"},{"type":"mc","id":"p5","prompt":"In {n}/{d}, which number is the numerator?","choices":["{n}","{d}","{=n+d}"],"answer":0,"hint":"The numerator is the top number.","explain":"The numerator is {n}: it counts how many parts we mean.","params":{"n":[1,7],"d":[2,9]},"where":"n<d"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"What is the numerator of 5/9?","choices":["5","9","14"],"answer":0,"hint":"The numerator is the top number.","explain":"The numerator is 5."},{"type":"mc","id":"m2","prompt":"What does the denominator tell you?","choices":["How many equal parts the whole is split into","How many parts you have","How big the whole is"],"answer":0,"hint":"Think of the bottom number in 3/4.","explain":"The denominator gives the number of equal parts in the whole."},{"type":"mc","id":"m3","prompt":"Which fraction is in simplest form?","choices":["3/7","2/4","6/9"],"answer":0,"hint":"Can the top and bottom both be divided by the same number (other than 1)?","explain":"2/4 simplifies to 1/2 and 6/9 to 2/3, but 3/7 can't be simplified."},{"type":"mc","id":"m4","prompt":"In {n}/{d}, which number is the denominator?","choices":["{d}","{n}","{=n+d}"],"answer":0,"hint":"The denominator is on the bottom.","explain":"The denominator is {d}: the whole is cut into {d} equal parts.","params":{"n":[1,8],"d":[2,9]},"where":"n<d"},{"type":"mc","id":"m5","prompt":"A cake is cut into {d} equal slices and you eat {n}. What fraction of the cake did you eat?","choices":["{n}/{d}","{d}/{n}","{n}/{=n+d}"],"answer":0,"hint":"The bottom number is the number of equal slices in the whole cake.","explain":"{n} of {d} equal slices is {n}/{d}.","params":{"n":[1,8],"d":[2,9]},"where":"n<d"},{"type":"mc","id":"m6","prompt":"Which is a proper fraction?","choices":["3/5","5/3","4/4"],"answer":0,"hint":"In a proper fraction the numerator is smaller than the denominator.","explain":"3/5 is less than one whole; 5/3 and 4/4 are improper."},{"type":"mc","id":"m7","prompt":"What is a mixed number?","choices":["A whole number and a fraction together, like 1¾","A fraction with 1 on top","Two fractions added together"],"answer":0,"hint":"Think of '1 and three quarters'.","explain":"A mixed number combines a whole number and a fraction, such as 1¾."}]},"status":"self-checked","visual":{"type":"fracbar","caption":"Split the bar into equal parts and shade some. The fraction updates as you go.","opts":{"d":4,"shade":1}}},"mt_cFltwUQi-d":{"topicId":"mt_cFltwUQi-d","title":"Fractions of amounts","audience":"family","keyIdea":"To find a fraction of an amount, split it into equal groups, then take some of the groups.","explain":{"kid":["To find a fraction of an amount, share it into equal groups. For 1/4 of 12, split 12 into 4 equal groups. There are 3 in each, so 1/4 of 12 is 3.","For 3/4 of 12, take 3 of those groups: 3 + 3 + 3 = 9."],"adult":["Divide by the denominator to find one part, then multiply by the numerator: 3/4 of 12 = (12 ÷ 4) × 3 = 9.","The same works for lengths and shapes, as long as the parts are equal in size. A shape cut into 4 unequal pieces does not show quarters."]},"familyTip":"Ask for a fraction of a handful: 'Can you give me a quarter of these 12 raisins?' Check by counting the groups.","practice":[{"type":"numeric","id":"p1","prompt":"Find 1/{d} of {=d*k}.","answer":"k","hint":"Split {=d*k} into {d} equal groups.","explain":"{=d*k} ÷ {d} = {k}.","params":{"d":[2,5],"k":[2,5]}},{"type":"numeric","id":"p2","prompt":"What is 1/3 of 9?","answer":3,"hint":"Split 9 into 3 equal groups.","explain":"9 ÷ 3 = 3."},{"type":"numeric","id":"p3","prompt":"What is 3/4 of 8?","answer":6,"hint":"First find 1/4 of 8, then take 3 of them.","explain":"1/4 of 8 is 2, so 3/4 is 3 × 2 = 6."},{"type":"mc","id":"p4","prompt":"A rectangle is cut into 4 pieces of different sizes. Does that show quarters?","choices":["No, quarters must be 4 equal parts","Yes, there are 4 pieces","Yes, if you count the biggest piece"],"answer":0,"hint":"What does a fraction need its parts to be?","explain":"Quarters are 4 equal parts. Four pieces of different sizes don't show quarters."},{"type":"numeric","id":"p5","prompt":"Find {n}/{d} of {=d*k}.","answer":"n*k","hint":"First find 1/{d} of {=d*k}.","explain":"1/{d} of {=d*k} is {k}, so {n}/{d} is {n} × {k} = {=n*k}.","params":{"d":[3,5],"n":[2,4],"k":[2,4]},"where":"n<d"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is 1/4 of 20?","answer":5,"hint":"Split 20 into 4 equal groups.","explain":"20 ÷ 4 = 5."},{"type":"numeric","id":"m2","prompt":"What is 2/4 of 8?","answer":4,"hint":"1/4 of 8 is 2.","explain":"2 × 2 = 4 (the same as 1/2 of 8)."},{"type":"numeric","id":"m3","prompt":"A ribbon is 12 cm long. How many cm is 3/4 of it?","answer":9,"hint":"1/4 of 12 cm is 3 cm.","explain":"3 × 3 = 9 cm."},{"type":"numeric","id":"m4","prompt":"What is 1/{d} of {=d*k}?","answer":"k","hint":"Split {=d*k} into {d} equal groups.","explain":"{=d*k} ÷ {d} = {k}.","params":{"d":[2,6],"k":[2,6]}},{"type":"numeric","id":"m5","prompt":"What is {n}/{d} of {=d*k}?","answer":"n*k","hint":"Find 1/{d} first.","explain":"1/{d} of {=d*k} is {k}, so {n}/{d} is {n} × {k} = {=n*k}.","params":{"d":[3,6],"n":[2,5],"k":[2,5]},"where":"n<d"},{"type":"numeric","id":"m6","prompt":"A ribbon is {=d*k} cm long. How many cm is 1/{d} of it?","answer":"k","hint":"Divide the length by {d}.","explain":"{=d*k} ÷ {d} = {k} cm.","params":{"d":[2,5],"k":[2,6]}},{"type":"mc","id":"m7","prompt":"How do you find 1/5 of 20?","choices":["Divide 20 by 5","Multiply 20 by 5","Subtract 5 from 20"],"answer":0,"hint":"1/5 means one of 5 equal parts.","explain":"20 ÷ 5 = 4, so 1/5 of 20 is 4."}]},"status":"self-checked","visual":{"type":"share","caption":"Share 12 into 4 equal groups. One group is a quarter of 12.","opts":{"total":12,"groups":4,"show":1}}},"mt_ahSqW_kK1b":{"topicId":"mt_ahSqW_kK1b","title":"Changes and separation words","audience":"family","keyIdea":"Melt, freeze, evaporate and condense name changes of state; sieve, filter, evaporate and magnet name ways to separate mixtures.","explain":{"kid":["Melt: solid to liquid. Freeze: liquid to solid. Evaporate: liquid to gas. Condense: gas to liquid.","A sieve catches big bits. A filter catches tiny bits that do not dissolve. A magnet pulls out iron."],"adult":["The words come in pairs. Melt and freeze. Evaporate and condense. To get a solid back after dissolving, evaporate the water.","To separate a mixture, ask how the parts differ. Size: use a sieve. Does it dissolve? Filter out what does not, then evaporate to get back what does. Is it iron? Use a magnet."]},"familyTip":"Mix dried peas, rice and paper clips. Ask how to separate them, then try it.","practice":[{"type":"mc","id":"p1","prompt":"Gas turning to liquid is…","choices":["condensing","melting","freezing"],"answer":0,"hint":"Drops on a cold window.","explain":"Condensing."},{"type":"mc","id":"p2","prompt":"Which separates iron filings from sand?","choices":["a magnet","a sieve","evaporating"],"answer":0,"hint":"Iron is magnetic.","explain":"Use a magnet."},{"type":"numeric","id":"p3","prompt":"A sieve catches {n} stones out of {=n+m}. How many go through?","answer":"m","hint":"Take away.","explain":"{m}.","params":{"n":[1,6],"m":[1,6]}},{"type":"numeric","id":"p4","prompt":"You separate {n} paper clips with a magnet, {m} at a time. How many goes? ({n} is a multiple of {m})","answer":"n/m","hint":"Share.","explain":"{n} ÷ {m} = {=n/m}.","params":{"n":[6,12],"m":[2,3]},"where":"n%m==0"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Solid to liquid is…","choices":["melting","freezing","condensing"],"answer":0,"hint":"Ice cream.","explain":"Melting."},{"type":"mc","id":"m2","prompt":"Liquid to gas is…","choices":["evaporating","freezing","melting"],"answer":0,"hint":"Puddles dry up.","explain":"Evaporating."},{"type":"mc","id":"m3","prompt":"Which separates sand from water?","choices":["filter","magnet","sieve with big holes"],"answer":0,"hint":"Sand is fine and insoluble.","explain":"A filter."},{"type":"mc","id":"m4","prompt":"Which gets salt from salt water?","choices":["evaporate","filter","magnet"],"answer":0,"hint":"Salt is dissolved.","explain":"Evaporate the water."},{"type":"numeric","id":"m5","prompt":"{n} g of sand and {m} g of salt are mixed. You remove the sand. How many grams are left?","answer":"m","hint":"Only salt.","explain":"{m} g.","params":{"n":[10,40],"m":[5,30]}},{"type":"numeric","id":"m6","prompt":"You do {n} separations, {m} with a filter. How many without a filter?","answer":"n-m","hint":"Take away.","explain":"{=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"mc","id":"m7","prompt":"Liquid to solid is…","choices":["freezing","melting","evaporating"],"answer":0,"hint":"Ice cubes.","explain":"Freezing."}]},"status":"self-checked","visual":{"type":"separate","caption":"Iron filings, gravel, sand and salt in water. Name each method as you try it.","opts":{"mix":[["iron filings","magnet"],["gravel","sieve"],["sand","filter"],["salt (dissolved)","evaporate"],["water","none"]]}}},"mt_UKmtuAsSLN":{"topicId":"mt_UKmtuAsSLN","title":"Reversible changes","audience":"family","keyIdea":"A reversible change can be undone: melting, freezing, dissolving and mixing make no new material.","explain":{"kid":["Melt ice and you get water. Freeze it and you get ice back. That change can go back, so it is reversible.","No new material is made. It is still water."],"adult":["Changes of state (melting, freezing, boiling, condensing), dissolving and mixing are reversible: the same material comes back. Burning, rusting and cooking make new materials, so they are irreversible.","A good test: can you get the starting materials back by a simple method such as cooling, heating, filtering or evaporating? If yes, it is reversible."]},"familyTip":"Make ice lollies from juice, then melt one. Is it the same juice? Now toast bread: can you untoast it?","practice":[{"type":"mc","id":"p1","prompt":"Melting chocolate is…","choices":["reversible","irreversible"],"answer":0,"hint":"Cool it.","explain":"It sets again: reversible."},{"type":"mc","id":"p2","prompt":"Burning paper is…","choices":["irreversible","reversible"],"answer":0,"hint":"Can you get the paper back?","explain":"Ash cannot become paper: irreversible."},{"type":"numeric","id":"p3","prompt":"{n} ice cubes melt, then all refreeze. How many ice cubes?","answer":"n","hint":"Same as before.","explain":"{n} again.","params":{"n":[3,9]}},{"type":"numeric","id":"p4","prompt":"You dissolve {n} g of salt and evaporate the water. How many grams of salt do you get back?","answer":"n","hint":"Reversible.","explain":"{n} g.","params":{"n":[5,30]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Dissolving sugar in tea is…","choices":["reversible","irreversible"],"answer":0,"hint":"Evaporate the water.","explain":"Sugar is left behind: reversible."},{"type":"mc","id":"m2","prompt":"Cooking an egg is…","choices":["irreversible","reversible"],"answer":0,"hint":"Can you uncook it?","explain":"A new material forms."},{"type":"mc","id":"m3","prompt":"A reversible change makes…","choices":["no new material","a new material","only gas"],"answer":0,"hint":"Same stuff.","explain":"No new material."},{"type":"mc","id":"m4","prompt":"Ice is taken out of the freezer and warms up. What happens?","choices":["It melts back to water","It turns into a new material","It stays ice for ever"],"answer":0,"hint":"Reversible.","explain":"It melts back into water: the same material."},{"type":"numeric","id":"m5","prompt":"{n} g of wax melts. What mass of wax sets again, in g?","answer":"n","hint":"Nothing lost.","explain":"{n} g.","params":{"n":[10,60]}},{"type":"numeric","id":"m6","prompt":"{n} changes: {m} are reversible. How many are irreversible?","answer":"n-m","hint":"Take away.","explain":"{=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"mc","id":"m7","prompt":"Mixing sand and gravel is…","choices":["reversible (sieve them)","irreversible"],"answer":0,"hint":"Can you sort them out?","explain":"A sieve separates them."}]},"status":"self-checked","visual":{"type":"particles","caption":"Water: cool it to freeze, warm it to melt. The particles are the same water every time.","opts":{"mp":0,"bp":100,"temp":5,"name":"water","min":-20,"max":40}}},"mt_hCVPYlF-7Y":{"topicId":"mt_hCVPYlF-7Y","title":"Square and cube numbers","audience":"learner","keyIdea":"A square number is n × n (written n²); a cube number is n × n × n (written n³).","explain":{"kid":["Make a square with 3 rows of 3 tiles. That is 9 tiles. So 9 is a square number. We write 3² = 9.","Stack 3 layers of 3 by 3 cubes. That is 27 cubes, so 27 is a cube number: 3³ = 27."],"adult":["n² (n squared) means n × n; the name comes from the square of tiles. n³ (n cubed) means n × n × n; the name comes from a cube of blocks.","The first square numbers are 1, 4, 9, 16, 25, 36, 49, 64, 81, 100. The first cubes are 1, 8, 27, 64, 125. 64 is both: 8² and 4³. A common mistake is 3² = 6: squaring is not doubling."]},"familyTip":"Build squares from coins: 1, 4, 9, 16. Do the gaps between them make a pattern?","practice":[{"type":"numeric","id":"p1","prompt":"What is {n}²?","answer":"n*n","hint":"n × n.","explain":"{n} × {n} = {=n*n}.","params":{"n":[2,12]}},{"type":"numeric","id":"p2","prompt":"What is {n}³?","answer":"n*n*n","hint":"n × n × n.","explain":"{n} × {n} × {n} = {=n*n*n}.","params":{"n":[2,5]}},{"type":"mc","id":"p3","prompt":"Is 3² the same as 3 × 2?","choices":["No, 3² = 9","Yes, both are 6","Yes, both are 9"],"answer":0,"hint":"Squared, not doubled.","explain":"3² = 3 × 3 = 9, but 3 × 2 = 6."},{"type":"mc","id":"p4","prompt":"Which is a square number?","choices":["36","20","12"],"answer":0,"hint":"6 × 6?","explain":"36 = 6 × 6."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A square has {n} tiles on each side. How many tiles?","answer":"n*n","hint":"n².","explain":"{n}² = {=n*n}.","params":{"n":[3,10]}},{"type":"numeric","id":"m2","prompt":"A cube is {n} blocks long, wide and tall. How many blocks?","answer":"n*n*n","hint":"n³.","explain":"{n}³ = {=n*n*n}.","params":{"n":[2,5]}},{"type":"mc","id":"m3","prompt":"Which number is both a square and a cube?","choices":["64","16","27"],"answer":0,"hint":"8² and 4³.","explain":"64 = 8² = 4³."},{"type":"numeric","id":"m4","prompt":"What is {n}² − {m}²?","answer":"n*n-m*m","hint":"Square each first.","explain":"{=n*n} − {=m*m} = {=n*n-m*m}.","params":{"n":[6,10],"m":[2,5]}},{"type":"mc","id":"m5","prompt":"What is 1³?","choices":["1","3","0"],"answer":0,"hint":"1 × 1 × 1.","explain":"1."},{"type":"mc","id":"m6","prompt":"Which is a cube number?","choices":["125","100","50"],"answer":0,"hint":"5 × 5 × 5.","explain":"125 = 5³."},{"type":"numeric","id":"m7","prompt":"The square root of {=n*n} is…","answer":"n","hint":"Which number squared?","explain":"{n} × {n} = {=n*n}.","params":{"n":[2,12]}}]},"status":"self-checked","visual":{"type":"squares","caption":"Change n. Count the tiles in the square and the little cubes in the stack.","opts":{"n":3}}},"mt_9m2jSzGnvC":{"topicId":"mt_9m2jSzGnvC","title":"Slopes of parallel and perpendicular lines","audience":"learner","keyIdea":"Parallel lines have equal slopes; perpendicular lines have slopes that multiply to −1.","explain":{"kid":["Two lines that never meet are parallel. They have the same steepness, the same slope.","Lines that meet at a right angle are perpendicular. If one has slope 2, the other has slope −1/2."],"adult":["If y = m₁x + c₁ and y = m₂x + c₂, the lines are parallel when m₁ = m₂, and perpendicular when m₁ × m₂ = −1, so m₂ = −1/m₁: flip the fraction and change the sign.","To write a line through (a, b) parallel to y = 3x + 1, keep m = 3: y − b = 3(x − a). For a perpendicular line, use m = −1/3 instead. Vertical and horizontal lines are the special case with no defined product."]},"familyTip":"Draw y = 2x on squared paper, then a line through (0, 3) that crosses it at a right angle. Check its slope is −1/2.","practice":[{"type":"numeric","id":"p1","prompt":"A line has slope {m}. What slope does a parallel line have?","answer":"m","hint":"Same slope.","explain":"Parallel: {m}.","params":{"m":[2,9]}},{"type":"mc","id":"p2","prompt":"A line has slope 2. Which slope is perpendicular?","choices":["−1/2","1/2","−2"],"answer":0,"hint":"Flip and change sign.","explain":"−1/2, because 2 × (−1/2) = −1."},{"type":"numeric","id":"p3","prompt":"Line A has slope {m}. Line B is perpendicular. What is slope A × slope B?","answer":-1,"hint":"Always the same.","explain":"Perpendicular slopes multiply to −1.","params":{"m":[2,9]}},{"type":"mc","id":"p4","prompt":"y = 3x + 1 and y = 3x − 4 are…","choices":["parallel","perpendicular","the same line"],"answer":0,"hint":"Compare slopes.","explain":"Both slopes are 3, intercepts differ: parallel."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Slope −1/3 is perpendicular to slope…","choices":["3","−3","1/3"],"answer":0,"hint":"Flip and change sign.","explain":"−1/3 × 3 = −1."},{"type":"numeric","id":"m2","prompt":"Line through (0, {c}) parallel to y = {m}x + 1. What is its y-intercept?","answer":"c","hint":"y = mx + c.","explain":"c = {c}.","params":{"m":[2,6],"c":[2,9]}},{"type":"mc","id":"m3","prompt":"y = 2x + 5 and y = −0.5x are…","choices":["perpendicular","parallel","neither"],"answer":0,"hint":"2 × (−0.5).","explain":"2 × −0.5 = −1: perpendicular."},{"type":"numeric","id":"m4","prompt":"A line with slope {m} passes through (1, {b}). A parallel line passes through (0, 0). What is its y-value at x = 2?","answer":"2*m","hint":"y = mx.","explain":"y = {m} × 2 = {=2*m}.","params":{"m":[2,6],"b":[1,9]}},{"type":"mc","id":"m5","prompt":"y = 4x and y = 4x are…","choices":["the same line","parallel and different","perpendicular"],"answer":0,"hint":"Same slope and intercept.","explain":"Identical lines."},{"type":"mc","id":"m6","prompt":"y = x + 1 and y = −x + 1 are…","choices":["perpendicular","parallel","neither"],"answer":0,"hint":"1 × (−1).","explain":"1 × −1 = −1."},{"type":"mc","id":"m7","prompt":"y = 2x and y = 3x are…","choices":["neither","parallel","perpendicular"],"answer":0,"hint":"Slopes differ, product 6.","explain":"Different slopes, product not −1."}]},"status":"self-checked","visual":{"type":"slopes","caption":"Blue line has slope 2. Change the green slope: find the parallel one and the perpendicular one.","opts":{"m":2,"start":1}},"lab":{"type":"graphlab","caption":"Make a line parallel to y = 2x + 1 that passes through the targets: keep a = 2, change b.","opts":{"f":"a*x+b","a":1,"b":0,"xr":[-5,5],"yr":[-5,9],"targets":[[0,-2],[2,2]]}}},"mt_MyGblah2yY":{"topicId":"mt_MyGblah2yY","title":"Writing fraction facts","audience":"family","keyIdea":"We can write fraction facts like 1/2 of 6 = 3, and different fractions can name the same amount.","explain":{"kid":["We can write fraction facts as number sentences: 1/2 of 6 = 3.","Different fractions can be the same amount. Cut a cake into 4 equal pieces and take 2: that's the same as half the cake. So 2/4 = 1/2."],"adult":["Writing 'fraction of' sentences connects fractions to division: 1/2 of 6 is 6 ÷ 2.","Recognising 2/4 = 1/2 is the first taste of equivalence. The whole is cut into twice as many parts and twice as many are taken, so the amount stays the same."]},"familyTip":"Fold a sheet of paper in half, then in half again, and shade 2 of the 4 parts. Is it still half?","practice":[{"type":"numeric","id":"p1","prompt":"What is half of {=2*k}? (That's 1/2 of {=2*k}.)","answer":"k","hint":"Split {=2*k} into 2 equal groups.","explain":"{=2*k} ÷ 2 = {k}.","params":{"k":[3,9]}},{"type":"mc","id":"p2","prompt":"Which is the same amount as 1/2?","choices":["2/4","1/4","2/3"],"answer":0,"hint":"Picture a cake cut into 4 equal pieces.","explain":"Two quarters make a half, so 2/4 = 1/2."},{"type":"numeric","id":"p3","prompt":"2/4 of 8 = ?","answer":4,"hint":"1/4 of 8 is 2.","explain":"2 × 2 = 4, which is the same as 1/2 of 8."},{"type":"mc","id":"p4","prompt":"How do you write 'a quarter of 12 is 3'?","choices":["1/4 of 12 = 3","4/1 of 12 = 3","1/4 + 12 = 3"],"answer":0,"hint":"A quarter is 1/4, and 'is' becomes =.","explain":"1/4 of 12 = 3."},{"type":"numeric","id":"p5","prompt":"1/3 of {=3*k} = ?","answer":"k","hint":"Split {=3*k} into 3 equal groups.","explain":"{=3*k} ÷ 3 = {k}.","params":{"k":[2,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"1/3 of 6 = ?","answer":2,"hint":"Split 6 into 3 equal groups.","explain":"6 ÷ 3 = 2."},{"type":"mc","id":"m2","prompt":"True or false: 2/4 of 10 = 1/2 of 10","choices":["True","False"],"answer":0,"hint":"Is 2/4 the same amount as 1/2?","explain":"Both equal 5, because 2/4 and 1/2 are the same amount."},{"type":"numeric","id":"m3","prompt":"1/2 of 14 = ?","answer":7,"hint":"Split 14 into 2 equal groups.","explain":"14 ÷ 2 = 7."},{"type":"numeric","id":"m4","prompt":"1/2 of {=2*k} = ?","answer":"k","hint":"Split {=2*k} into 2 equal groups.","explain":"{=2*k} ÷ 2 = {k}.","params":{"k":[2,9]}},{"type":"numeric","id":"m5","prompt":"2/4 of {=4*k} = ?","answer":"2*k","hint":"1/4 of {=4*k} is {k}.","explain":"2 × {k} = {=2*k}, the same as 1/2 of {=4*k}.","params":{"k":[2,6]}},{"type":"mc","id":"m6","prompt":"True or false: 2/4 of {=4*k} = 1/2 of {=4*k}","choices":["True","False"],"answer":0,"hint":"Are 2/4 and 1/2 the same amount?","explain":"Both are {=2*k}, because 2/4 = 1/2.","params":{"k":[2,5]}},{"type":"mc","id":"m7","prompt":"Which is the same amount as 2/4?","choices":["1/2","1/4","2/2"],"answer":0,"hint":"Picture 2 quarters of a pizza.","explain":"Two quarters make one half."}]},"status":"self-checked","visual":{"type":"fracbar","caption":"Shade parts of the whole. Switch between a bar and a pie.","opts":{"d":3,"shade":1,"pie":true}}},"mt_Kr3IyA6m-O":{"topicId":"mt_Kr3IyA6m-O","title":"Fractions on a number line","audience":"family","keyIdea":"Fractions are numbers with their own place on the number line.","explain":{"kid":["Fractions are numbers, so they have a place on the number line. Split the gap from 0 to 1 into equal jumps.","With 4 equal jumps, the marks are 1/4, 2/4 and 3/4, and 4/4 is at 1."],"adult":["Seeing fractions as points on a line, not only as slices of shapes, matters for later work with decimals, measures and algebra. To place n/d, split 0 to 1 into d equal intervals and count n of them from 0.","Fractions bigger than 1, like 5/4, carry on past 1. A bigger denominator means smaller jumps, so 1/4 is less than 1/3."]},"familyTip":"Draw a line from 0 to 1 on a strip of paper, fold it into equal parts and label the creases.","practice":[{"type":"mc","id":"p1","prompt":"0 to 1 is split into {d} equal jumps. What is the first mark?","choices":["1/{d}","{d}","1/{=d+1}"],"answer":0,"hint":"Each jump is one of {d} equal parts.","explain":"One jump out of {d} equal jumps is 1/{d}.","params":{"d":[3,8]}},{"type":"mc","id":"p2","prompt":"Where does 3/4 go?","choices":["Three of four equal jumps from 0","Between 0 and 1/4","Past 1"],"answer":0,"hint":"The denominator gives the number of jumps between 0 and 1.","explain":"Split 0 to 1 into 4 equal jumps and count 3 of them."},{"type":"mc","id":"p3","prompt":"Which is bigger, 1/3 or 1/4?","choices":["1/3","1/4","They are equal"],"answer":0,"hint":"Is a third of a cake bigger or smaller than a quarter?","explain":"Splitting into 3 gives bigger parts than splitting into 4, so 1/3 > 1/4."},{"type":"order","id":"p4","prompt":"Put these in order, smallest first.","items":["1/4","1/2","3/4","1"],"hint":"Think of quarters on the line: 1/2 is the same as 2/4.","explain":"1/4 < 2/4 (= 1/2) < 3/4 < 4/4 (= 1)."},{"type":"mc","id":"p5","prompt":"Which is smaller, 1/{a} or 1/{b}?","choices":["1/{b}","1/{a}","They are equal"],"answer":0,"hint":"More equal parts means smaller parts.","explain":"Splitting into {b} gives smaller parts than splitting into {a}, so 1/{b} is smaller.","params":{"a":[2,9],"b":[2,9]},"where":"a<b"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"0 to 1 is split into 5 equal jumps. Which fraction is at the mark after 2 jumps?","choices":["2/5","1/2","5/2"],"answer":0,"hint":"Count the jumps from 0 out of the total.","explain":"2 jumps out of 5 is 2/5."},{"type":"mc","id":"m2","prompt":"Where is 4/4 on the number line?","choices":["At 1","Between 0 and 1","At 4"],"answer":0,"hint":"4 jumps out of 4.","explain":"4/4 is one whole, so it sits at 1."},{"type":"order","id":"m3","prompt":"Put these numbers in order on the number line, smallest first.","items":["0","1/3","2/3","1"],"hint":"Thirds: split 0 to 1 into 3 equal jumps.","explain":"0 < 1/3 < 2/3 < 1."},{"type":"mc","id":"m4","prompt":"0 to 1 is split into {d} equal jumps. Which fraction is at the mark after {n} jumps?","choices":["{n}/{d}","{d}/{n}","1/{=n+d}"],"answer":0,"hint":"Count the jumps from 0, out of the total number of jumps.","explain":"{n} jumps out of {d} is {n}/{d}.","params":{"n":[1,7],"d":[3,8]},"where":"n<d"},{"type":"mc","id":"m5","prompt":"Which is bigger, 1/{a} or 1/{b}?","choices":["1/{a}","1/{b}","They are equal"],"answer":0,"hint":"Fewer equal parts means bigger parts.","explain":"Splitting into {a} gives bigger parts than splitting into {b}, so 1/{a} is bigger.","params":{"a":[2,9],"b":[2,9]},"where":"a<b"},{"type":"order","id":"m6","prompt":"Put these fifths in order, smallest first.","items":["1/5","2/5","4/5","6/5"],"hint":"They all have the same denominator, so compare the numerators.","explain":"1/5 < 2/5 < 4/5 < 6/5 (and 6/5 is past 1)."},{"type":"mc","id":"m7","prompt":"Where does 5/4 go on the number line?","choices":["Just past 1","Between 0 and 1","At 5"],"answer":0,"hint":"4/4 is at 1.","explain":"5/4 is one more quarter after 4/4 = 1."}]},"status":"self-checked","visual":{"type":"numline","caption":"Drag the point along the number line. It snaps to each equal step.","opts":{"d":4,"max":1,"start":3}}},"mt_FbDKeLfBCo":{"topicId":"mt_FbDKeLfBCo","title":"Equivalent fractions","audience":"family","keyIdea":"Equivalent fractions are different names for the same amount.","explain":{"kid":["Equivalent fractions are different names for the same amount: 1/2 = 2/4 = 4/8.","Cut every piece into 2 smaller pieces. Now there are twice as many pieces, and you take twice as many. It is still the same amount."],"adult":["Multiplying or dividing the numerator and denominator by the same non-zero number gives an equivalent fraction: 1/3 = 2/6 = 3/9. On a number line, equivalent fractions mark the same point.","Adding the same number to top and bottom does not work (1/2 is not 2/3). This is one of the most common fraction misconceptions."]},"familyTip":"Fold paper strips into halves, quarters and eighths and line them up to see which lengths match.","practice":[{"type":"numeric","id":"p1","prompt":"1/{d} = ?/{=d*k}. What is the missing numerator?","answer":"k","hint":"The denominator was multiplied by {k}.","explain":"{d} × {k} = {=d*k}, so the numerator is 1 × {k} = {k}.","params":{"d":[2,5],"k":[2,5]}},{"type":"mc","id":"p2","prompt":"Which is NOT equal to 1/2?","choices":["3/5","4/8","5/10"],"answer":0,"hint":"Is the top exactly half of the bottom?","explain":"4/8 and 5/10 are halves, but 3 is not half of 5."},{"type":"numeric","id":"p3","prompt":"2/3 = 4/?. What is the missing denominator?","answer":6,"hint":"The numerator was doubled.","explain":"Double the denominator too: 3 × 2 = 6."},{"type":"mc","id":"p4","prompt":"Ben says 1/2 = 2/3 because he added 1 to the top and the bottom. Is he right?","choices":["No, you must multiply or divide both by the same number","Yes, he did the same to both","Yes, both are less than 1"],"answer":0,"hint":"Compare a half and two-thirds of a cake.","explain":"2/3 is bigger than 1/2. Adding the same number changes the value; multiplying both by the same number doesn't."},{"type":"numeric","id":"p5","prompt":"Fill in the box: {n}/{d} = {=n*k}/□","answer":"d*k","hint":"The numerator was multiplied by {k}.","explain":"{n} × {k} = {=n*k}, so the box is {d} × {k} = {=d*k}.","params":{"n":[1,3],"d":[2,5],"k":[2,4]},"where":"n<d"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"3/4 = ?/8. What is the missing numerator?","answer":6,"hint":"4 × 2 = 8.","explain":"Multiply the top by 2 as well: 3 × 2 = 6."},{"type":"mc","id":"m2","prompt":"Which fraction equals 2/5?","choices":["4/10","3/6","2/10"],"answer":0,"hint":"Multiply top and bottom by the same number.","explain":"2/5 = (2 × 2)/(5 × 2) = 4/10."},{"type":"numeric","id":"m3","prompt":"6/9 = 2/?. What is the missing denominator?","answer":3,"hint":"6 ÷ 3 = 2.","explain":"Divide the bottom by 3 as well: 9 ÷ 3 = 3."},{"type":"numeric","id":"m4","prompt":"{n}/{d} = ?/{=d*k}. What is the missing numerator?","answer":"n*k","hint":"What was the denominator multiplied by?","explain":"{d} × {k} = {=d*k}, so the numerator is {n} × {k} = {=n*k}.","params":{"n":[1,4],"d":[2,5],"k":[2,5]},"where":"n<d"},{"type":"numeric","id":"m5","prompt":"{n}/{d} = {=n*k}/?. What is the missing denominator?","answer":"d*k","hint":"What was the numerator multiplied by?","explain":"{n} × {k} = {=n*k}, so the denominator is {d} × {k} = {=d*k}.","params":{"n":[1,4],"d":[2,5],"k":[2,5]},"where":"n<d"},{"type":"mc","id":"m6","prompt":"Which fraction equals {n}/{d}?","choices":["{=n*k}/{=d*k}","{=n+k}/{=d+k}","{=n*k}/{d}"],"answer":0,"hint":"Multiply the top and bottom by the same number.","explain":"{n}/{d} = ({n} × {k})/({d} × {k}) = {=n*k}/{=d*k}.","params":{"n":[1,4],"d":[2,5],"k":[2,4]},"where":"n<d"},{"type":"mc","id":"m7","prompt":"Can you add the same number to the top and bottom to get an equivalent fraction?","choices":["No, you multiply or divide both by the same number","Yes, always","Only with even numbers"],"answer":0,"hint":"Try it with 1/2 → 2/3.","explain":"1/2 isn't equal to 2/3, so adding doesn't work. Multiplying or dividing both does."}]},"status":"self-checked","visual":{"type":"fracbar","caption":"Shade both bars. When the shading lines up, the fractions are equivalent.","opts":{"d":2,"shade":1,"compare":4,"compareShade":0}}},"mt_ddCyW84sRo":{"topicId":"mt_ddCyW84sRo","title":"Equations as a balance","audience":"family","keyIdea":"Do the same thing to both sides and the equation stays balanced.","explain":{"kid":["An equation is like balanced scales: both sides weigh the same. If x + 3 = 7, take 3 off both sides to keep it balanced, and you get x = 4.","The golden rule: whatever you do to one side, do to the other."],"adult":["An equation says two expressions are equal. Doing the same operation to both sides (adding, subtracting, multiplying, or dividing by a non-zero number) keeps them equal, so each step gives an equivalent equation.","Example: 2x + 1 = 9. Subtract 1 from both sides: 2x = 8. Divide both sides by 2: x = 4. Check by substituting: 2 × 4 + 1 = 9."]},"familyTip":"Play 'mystery bag': a bag with some counters plus 3 loose counters balances 7 counters. How many are in the bag?","practice":[{"type":"numeric","id":"p1","prompt":"x + {a} = {=a+b}. Find x.","answer":"b","hint":"Take {a} from both sides.","explain":"x = {=a+b} − {a} = {b}.","params":{"a":[2,6],"b":[2,9]}},{"type":"mc","id":"p2","prompt":"What is a good first step to solve x + 5 = 12?","choices":["Subtract 5 from both sides","Add 5 to both sides","Subtract 5 from the left side only"],"answer":0,"hint":"You want x on its own, and you must keep the balance.","explain":"Subtracting 5 from both sides gives x = 7 and keeps the equation balanced."},{"type":"numeric","id":"p3","prompt":"2x = 10. What is x?","answer":5,"hint":"Divide both sides by 2.","explain":"x = 10 ÷ 2 = 5."},{"type":"order","id":"p4","prompt":"Put the steps in order to solve 2x + 1 = 9.","items":["2x + 1 = 9","2x = 8","x = 4","Check: 2 × 4 + 1 = 9"],"hint":"First undo the + 1, then undo the × 2.","explain":"Subtract 1 from both sides, divide both sides by 2, then check."},{"type":"numeric","id":"p5","prompt":"{a}x = {=a*b}. Find x.","answer":"b","hint":"Divide both sides by {a}.","explain":"x = {=a*b} ÷ {a} = {b}.","params":{"a":[2,5],"b":[2,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"x − 4 = 6. What is x?","answer":10,"hint":"Add 4 to both sides.","explain":"x = 6 + 4 = 10."},{"type":"numeric","id":"m2","prompt":"3x + 2 = 14. What is x?","answer":4,"hint":"Subtract 2 from both sides, then divide by 3.","explain":"3x = 12, so x = 4. Check: 3 × 4 + 2 = 14."},{"type":"mc","id":"m3","prompt":"Which step keeps 5 + x = 9 balanced?","choices":["Take 5 from both sides","Take 5 from the left side only","Add 5 to the left and take 5 from the right"],"answer":0,"hint":"Both sides must change in the same way.","explain":"Taking 5 from both sides gives x = 4, and the equation stays balanced."},{"type":"numeric","id":"m4","prompt":"x + {a} = {=a+b}. What is x?","answer":"b","hint":"Take {a} from both sides.","explain":"x = {=a+b} − {a} = {b}.","params":{"a":[2,9],"b":[3,15]}},{"type":"numeric","id":"m5","prompt":"{a}x = {=a*b}. What is x?","answer":"b","hint":"Divide both sides by {a}.","explain":"x = {=a*b} ÷ {a} = {b}.","params":{"a":[2,6],"b":[2,9]}},{"type":"numeric","id":"m6","prompt":"{a}x + {b} = {=a*c+b}. What is x?","answer":"c","hint":"Take {b} from both sides first.","explain":"Subtract {b}: {a}x = {=a*c}. Divide by {a}: x = {c}.","params":{"a":[2,5],"b":[1,9],"c":[1,9]}},{"type":"numeric","id":"m7","prompt":"x − {a} = {b}. What is x?","answer":"a+b","hint":"Add {a} to both sides.","explain":"x = {b} + {a} = {=a+b}.","params":{"a":[2,9],"b":[1,9]}}]},"status":"self-checked","visual":{"type":"balance","caption":"Keep the scale level: do the same thing to both sides until x is alone.","opts":{"mode":"solve","a":1,"b":3,"c":7}}},"mt_hTbTvblMUQ":{"topicId":"mt_hTbTvblMUQ","title":"Letters as numbers","audience":"family","keyIdea":"In algebra a letter stands for a number, and 3a means 3 × a.","explain":{"kid":["In algebra a letter stands for a number. In 3a, a is a number and 3a means 3 × a. If a = 2, then 3a = 6.","The letter a doesn't mean 'apples'. It's a number we might not know yet, and in some problems it can change."],"adult":["A letter represents a number: sometimes one particular unknown, sometimes any value. The conventions are: 3a means 3 × a, ab means a × b, a/2 means a ÷ 2, and the same letter means the same number throughout one expression or equation.","A common misconception is treating the letter as an object ('3a is three apples'). That breaks down quickly: what would a × a mean?"]},"familyTip":"Make up 'think of a number' puzzles: 'I think of n, double it and add 1, and get 11.' What is n?","practice":[{"type":"numeric","id":"p1","prompt":"If n = {n}, what is 2n?","answer":"2*n","hint":"2n means 2 × n.","explain":"2 × {n} = {=2*n}.","params":{"n":[2,9]}},{"type":"mc","id":"p2","prompt":"What does 4b mean?","choices":["4 × b","4 + b","A number in the forties"],"answer":0,"hint":"A number written next to a letter means multiply.","explain":"4b means 4 × b."},{"type":"numeric","id":"p3","prompt":"If a = 3, what is a + a + a?","answer":9,"hint":"Replace each a with 3.","explain":"3 + 3 + 3 = 9 (and that's 3a)."},{"type":"numeric","id":"p4","prompt":"If a = 1, what is 3a + 2?","answer":5,"hint":"Work out 3a first.","explain":"3 × 1 + 2 = 5."},{"type":"numeric","id":"p5","prompt":"If a = {a}, what is a + a + a?","answer":"3*a","hint":"Replace each a with {a}.","explain":"{a} + {a} + {a} = {=3*a} (and that's 3a).","params":{"a":[2,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"If x = 4, what is 3x − 2?","answer":10,"hint":"3x means 3 × 4.","explain":"3 × 4 − 2 = 10."},{"type":"mc","id":"m2","prompt":"Can x stand for different numbers in different problems?","choices":["Yes, a letter can stand for any number","No, x is always 10","No, x always means multiply"],"answer":0,"hint":"Think about what a letter in algebra represents.","explain":"x can be any number. Within a single problem, the same letter keeps the same value."},{"type":"mc","id":"m3","prompt":"Which is equal to a + a + a + a?","choices":["4a","a + 4","a4 (a number with digits a and 4)"],"answer":0,"hint":"How many a's are added?","explain":"Four lots of a is 4 × a, written 4a."},{"type":"numeric","id":"m4","prompt":"If n = {n}, what is {k}n?","answer":"k*n","hint":"{k}n means {k} × n.","explain":"{k} × {n} = {=k*n}.","params":{"n":[2,9],"k":[2,6]}},{"type":"numeric","id":"m5","prompt":"If a = {a}, what is {b}a + {c}?","answer":"b*a+c","hint":"Work out {b}a first.","explain":"{b} × {a} + {c} = {=b*a+c}.","params":{"a":[1,9],"b":[2,5],"c":[1,9]}},{"type":"numeric","id":"m6","prompt":"If x = {x}, what is x + x + x?","answer":"3*x","hint":"Replace each x with {x}.","explain":"{x} + {x} + {x} = {=3*x} (that's 3x).","params":{"x":[2,9]}},{"type":"mc","id":"m7","prompt":"What does ab mean?","choices":["a × b","a + b","A number with the digits a and b"],"answer":0,"hint":"Letters written next to each other are multiplied.","explain":"ab means a × b."}]},"status":"self-checked","visual":{"type":"balance","caption":"The bag x hides a number. Keep the scale balanced to find it.","opts":{"mode":"solve","a":1,"b":5,"c":12}}},"mt_jHgRQ4hR0g":{"topicId":"mt_jHgRQ4hR0g","title":"Order of operations","audience":"learner","keyIdea":"Brackets first, then × and ÷ (left to right), then + and − (left to right).","explain":{"kid":["When a sum has more than one operation, everyone follows the same order so they all get the same answer. Do brackets first (in the US these are called parentheses), then multiply and divide, then add and subtract.","So 2 + 3 × 4 is 2 + 12 = 14, not 5 × 4 = 20. When two operations are on the same level, you work from left to right."],"adult":["You may know this as BIDMAS or BODMAS (UK) or PEMDAS (US). They all describe one convention: brackets/parentheses, then powers (indices/exponents), then × and ÷, then + and −. Operations on the same level are done left to right.","The two classic mistakes are working strictly left to right (2 + 3 × 4 = 20) and assuming addition always comes before subtraction. In fact 10 − 4 + 2 = 8, because + and − share a level and you go left to right."]},"familyTip":"Type 2 + 3 × 4 into a phone calculator and a basic calculator. Do they agree? Which one follows the convention?","practice":[{"type":"numeric","id":"p1","prompt":"Calculate {a} × {b} − {c}.","answer":"a*b-c","hint":"Multiply before you subtract.","explain":"{a} × {b} = {=a*b}, then {=a*b} − {c} = {=a*b-c}.","params":{"a":[2,6],"b":[2,6],"c":[1,9]},"where":"a*b>c"},{"type":"numeric","id":"p2","prompt":"Work out (2 + 3) × 4.","answer":20,"hint":"Brackets come first.","explain":"2 + 3 = 5, then 5 × 4 = 20."},{"type":"numeric","id":"p3","prompt":"Work out 10 − 4 + 2.","answer":8,"hint":"+ and − are on the same level, so go left to right.","explain":"10 − 4 = 6, then 6 + 2 = 8."},{"type":"mc","id":"p4","prompt":"What do you do first in 12 ÷ (2 + 4)?","choices":["2 + 4","12 ÷ 2","It doesn't matter"],"answer":0,"hint":"Look for brackets.","explain":"Brackets first: 2 + 4 = 6, then 12 ÷ 6 = 2."},{"type":"numeric","id":"p5","prompt":"Calculate {a} × ({b} + {c}).","answer":"a*(b+c)","hint":"Brackets first.","explain":"{b} + {c} = {=b+c}, then {a} × {=b+c} = {=a*(b+c)}.","params":{"a":[2,5],"b":[1,6],"c":[1,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Work out {a} + {b} × {c}.","answer":"a+b*c","hint":"Multiply first.","explain":"{b} × {c} = {=b*c}, then {a} + {=b*c} = {=a+b*c}.","params":{"a":[2,9],"b":[2,9],"c":[2,9]}},{"type":"numeric","id":"m2","prompt":"Work out ({a} + {b}) × {c}.","answer":"(a+b)*c","hint":"Brackets first.","explain":"{a} + {b} = {=a+b}, then {=a+b} × {c} = {=(a+b)*c}.","params":{"a":[2,9],"b":[2,9],"c":[2,6]}},{"type":"numeric","id":"m3","prompt":"Work out {a} − {b} + {c}.","answer":"a-b+c","hint":"+ and − share a level: go left to right.","explain":"{a} − {b} = {=a-b}, then {=a-b} + {c} = {=a-b+c}.","params":{"a":[10,30],"b":[2,9],"c":[2,9]}},{"type":"numeric","id":"m4","prompt":"Work out {=a*b} ÷ {b} + {c}.","answer":"a+c","hint":"Divide before you add.","explain":"{=a*b} ÷ {b} = {a}, then {a} + {c} = {=a+c}.","params":{"a":[2,9],"b":[2,6],"c":[1,9]}},{"type":"numeric","id":"m5","prompt":"Work out 20 − 2 × 5.","answer":10,"hint":"Multiply first.","explain":"2 × 5 = 10, then 20 − 10 = 10."},{"type":"mc","id":"m6","prompt":"Ana says 6 + 4 ÷ 2 = 5. What is the right answer?","choices":["8","5","2"],"answer":0,"hint":"Which operation comes first?","explain":"Divide first: 4 ÷ 2 = 2, then 6 + 2 = 8."},{"type":"numeric","id":"m7","prompt":"Work out 3 × (8 − 5) + 1.","answer":10,"hint":"Brackets, then multiply, then add.","explain":"8 − 5 = 3, then 3 × 3 = 9, then 9 + 1 = 10."}]},"status":"self-checked","visual":{"type":"bidmas","caption":"Step through it: brackets, then × and ÷, then + and −.","opts":{"expr":"20 − 3 × (2 + 4)"}}},"mt_i9rJbuFO3p":{"topicId":"mt_i9rJbuFO3p","title":"Writing equations from problems","audience":"learner","keyIdea":"Use a letter for the unknown number, then write what you know as an equation.","explain":{"kid":["A missing-number puzzle like □ + 7 = 12 can use a letter instead of a box: n + 7 = 12. The letter stands for the number you don't know yet.","To turn a word problem into an equation, pick a letter for the unknown, then write the facts with +, −, × or ÷ and an = sign."],"adult":["Writing an equation is translation: you name the unknown with a letter, then state the relationship the problem describes. 'I think of a number, add 7 and get 12' becomes n + 7 = 12.","Say what your letter means before you start (let m = marbles in one bag). Then check your equation by reading it back in words and seeing whether it matches the story."]},"familyTip":"Make up a 'think of a number' puzzle for someone else, write it as an equation, and see if they can solve it.","practice":[{"type":"mc","id":"p1","prompt":"'A number plus 7 is 12.' Which equation matches?","choices":["n + 7 = 12","7n = 12","n = 7 + 12"],"answer":0,"hint":"'Plus' means +, and 'is' means =.","explain":"n + 7 = 12."},{"type":"mc","id":"p2","prompt":"3 bags with the same number of marbles hold 24 marbles in total. Let m be the number in one bag. Which equation matches?","choices":["3m = 24","m + 3 = 24","m = 3 × 24"],"answer":0,"hint":"3 bags of m marbles is 3 × m.","explain":"3m = 24 (so m = 8)."},{"type":"mc","id":"p3","prompt":"You had some money, spent £5, and have £8 left. Let x be what you started with. Which equation matches?","choices":["x − 5 = 8","5 − x = 8","x + 8 = 5"],"answer":0,"hint":"Start with x, then take away what you spent.","explain":"x − 5 = 8 (so you started with £13)."},{"type":"numeric","id":"p4","prompt":"In n + {a} = {b}, what is n?","answer":"b-a","hint":"What do you add to {a} to make {b}?","explain":"n = {b} − {a} = {=b-a}.","params":{"a":[2,9],"b":[10,20]}},{"type":"mc","id":"p5","prompt":"{a} bags with the same number of marbles hold {=a*k} marbles in total. Let m be the number in one bag. Which equation matches?","choices":["{a}m = {=a*k}","m + {a} = {=a*k}","m = {a} × {=a*k}"],"answer":0,"hint":"{a} bags of m marbles is {a} × m.","explain":"{a}m = {=a*k}, so m = {k}.","params":{"a":[2,6],"k":[2,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"'A number plus {a} is {b}.' Which equation matches?","choices":["n + {a} = {b}","{a}n = {b}","n = {a} + {b}"],"answer":0,"hint":"'Plus' means +.","explain":"n + {a} = {b}.","params":{"a":[2,9],"b":[10,30]}},{"type":"mc","id":"m2","prompt":"{a} boxes with the same number of pens hold {=a*k} pens in total. Let p be the pens in one box. Which equation matches?","choices":["{a}p = {=a*k}","p + {a} = {=a*k}","p = {a} × {=a*k}"],"answer":0,"hint":"{a} boxes of p pens is {a} × p.","explain":"{a}p = {=a*k}, so p = {k}.","params":{"a":[2,6],"k":[2,9]}},{"type":"mc","id":"m3","prompt":"'I think of a number and subtract {a}. The answer is {b}.' Which equation matches?","choices":["n − {a} = {b}","{a} − n = {b}","n + {b} = {a}"],"answer":0,"hint":"Start with the number, then subtract {a}.","explain":"n − {a} = {b}.","params":{"a":[2,9],"b":[2,12]}},{"type":"numeric","id":"m4","prompt":"I think of a number, subtract {a} and get {b}. What was the number?","answer":"a+b","hint":"Undo the subtraction.","explain":"n − {a} = {b}, so n = {b} + {a} = {=a+b}.","params":{"a":[2,9],"b":[2,12]}},{"type":"mc","id":"m5","prompt":"'Twice a number is 18.' Which equation matches?","choices":["2n = 18","n + 2 = 18","n² = 18"],"answer":0,"hint":"'Twice' means 2 ×.","explain":"2n = 18, so n = 9."},{"type":"mc","id":"m6","prompt":"Before you write an equation for a word problem, what should you decide first?","choices":["What the letter stands for","What the answer is","Which operation is hardest"],"answer":0,"hint":"The letter needs a meaning.","explain":"Say what your letter stands for (for example, m = marbles in one bag) before writing the equation."},{"type":"numeric","id":"m7","prompt":"'A number times 4 is 28.' What is the number?","answer":7,"hint":"4n = 28.","explain":"4n = 28, so n = 28 ÷ 4 = 7."}]},"status":"self-checked","visual":{"type":"balance","caption":"2x + 3 = 11 on a scale. Take the same from both sides, then share.","opts":{"mode":"solve","a":2,"b":3,"c":11}}},"mt_Jvg8X0N5u0":{"topicId":"mt_Jvg8X0N5u0","title":"Using simple formulae","audience":"learner","keyIdea":"A formula is a rule for working something out: put the numbers in and follow the order of operations.","explain":{"kid":["A formula is a rule that tells you how to work something out. For a rectangle: perimeter = 2 × (length + width).","For a rectangle 5 cm long and 3 cm wide: 2 × (5 + 3) = 2 × 8 = 16 cm. Remember: brackets first!"],"adult":["Formulae package up a calculation you would otherwise redo every time: cost = price × quantity, perimeter = 2 × (length + width), time = distance ÷ speed. To use one, replace each word with its value, then calculate in the correct order.","Keep track of units. If the length is in cm, the perimeter is in cm. A cost in pence won't match a price in pounds unless you convert."]},"familyTip":"Measure a table or a book and use perimeter = 2 × (length + width) to find its perimeter. Then check with a tape measure.","practice":[{"type":"numeric","id":"p1","prompt":"Perimeter = 2 × (length + width). What is the perimeter of a {l} cm by {w} cm rectangle, in cm?","answer":"2*(l+w)","hint":"Add length and width first.","explain":"2 × ({l} + {w}) = 2 × {=l+w} = {=2*(l+w)} cm.","params":{"l":[3,10],"w":[2,8]}},{"type":"numeric","id":"p2","prompt":"Cost = price × quantity. Pens cost £2 each and you buy 7. What is the cost in £?","answer":14,"hint":"Multiply the price by how many.","explain":"£2 × 7 = £14."},{"type":"numeric","id":"p3","prompt":"Time = distance ÷ speed. You travel 120 km at 60 km per hour. How many hours does it take?","answer":2,"hint":"Divide the distance by the speed.","explain":"120 ÷ 60 = 2 hours."},{"type":"mc","id":"p4","prompt":"In perimeter = 2 × (length + width), what do you work out first?","choices":["length + width","2 × length","2 × width + length"],"answer":0,"hint":"Brackets first.","explain":"Work out length + width, then double it."},{"type":"numeric","id":"p5","prompt":"Cost = price × quantity. Apples cost {p}p each and you buy {q}. What is the cost in pence?","answer":"p*q","hint":"Multiply the price by how many.","explain":"{p}p × {q} = {=p*q}p.","params":{"p":[10,40],"q":[2,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Perimeter = 2 × (length + width). Length {l} cm, width {w} cm. What is the perimeter in cm?","answer":"2*(l+w)","hint":"Brackets first.","explain":"2 × ({l} + {w}) = 2 × {=l+w} = {=2*(l+w)} cm.","params":{"l":[3,12],"w":[2,9]}},{"type":"numeric","id":"m2","prompt":"Cost = price × quantity. Tickets cost £{p} each and you buy {q}. What is the total cost in £?","answer":"p*q","hint":"Multiply the price by the quantity.","explain":"£{p} × {q} = £{=p*q}.","params":{"p":[2,9],"q":[2,9]}},{"type":"numeric","id":"m3","prompt":"Distance = speed × time. A cyclist rides at {s} km per hour for {t} hours. How far do they go, in km?","answer":"s*t","hint":"Multiply speed by time.","explain":"{s} × {t} = {=s*t} km.","params":{"s":[8,20],"t":[2,5]}},{"type":"numeric","id":"m4","prompt":"Number of legs = 4 × number of dogs. How many legs do {n} dogs have?","answer":"4*n","hint":"Put {n} in place of 'number of dogs'.","explain":"4 × {n} = {=4*n} legs.","params":{"n":[2,12]}},{"type":"numeric","id":"m5","prompt":"Area = length × width. A rug is 3 m by 2 m. What is its area in m²?","answer":6,"hint":"Multiply the length by the width.","explain":"3 × 2 = 6 m²."},{"type":"mc","id":"m6","prompt":"Cost = price × quantity. The price is 50p and the quantity is 4. What is the cost?","choices":["£2","£200","54p"],"answer":0,"hint":"50p × 4 = 200p. How many pounds is that?","explain":"50p × 4 = 200p = £2."},{"type":"numeric","id":"m7","prompt":"Time = distance ÷ speed. You drive 90 miles at 30 miles per hour. How many hours does it take?","answer":3,"hint":"Divide the distance by the speed.","explain":"90 ÷ 30 = 3 hours."}]},"status":"self-checked","visual":{"type":"formula","caption":"Change the length and width. The formula P = 2 × (l + w) gives the rectangle's perimeter, worked out step by step.","opts":{"name":"P","expr":"2 × (l + w)","vars":{"l":[1,10,4],"w":[1,6,3]},"pic":"rect","what":"perimeter","unit":"cm"}}},"mt_KwdjWEmMNo":{"topicId":"mt_KwdjWEmMNo","title":"Algebraic notation","audience":"learner","keyIdea":"Algebra drops the × sign: 3y means 3 × y, ab means a × b, a² means a × a, and a/b means a ÷ b.","explain":{"kid":["In algebra we write things the short way. 3y means 3 × y. ab means a × b. a/2 means a ÷ 2.","a² (say 'a squared') means a × a, not 2 × a. So if a = 5, then a² = 25 but 2a = 10."],"adult":["Algebraic notation is shorthand you need to read fluently: 3y = 3 × y = y + y + y; ab = a × b; a² = a × a; a/b = a ÷ b; x/2 is half of x; and brackets group, so 3(a + b) means 3 × (a + b).","Numbers go in front of letters (3y, not y3), and 1y is just written y. Watch for the classic trap: a² is a × a, not 2a."]},"familyTip":"Write your age as an expression in a sentence, such as 'In y years I'll be 13 + y', and get someone to read it back to you.","practice":[{"type":"mc","id":"p1","prompt":"What does 5y mean?","choices":["5 × y","5 + y","y to the power 5"],"answer":0,"hint":"A number next to a letter means multiply.","explain":"5y = 5 × y."},{"type":"mc","id":"p2","prompt":"Which is the same as m × m?","choices":["m²","2m","m + m"],"answer":0,"hint":"A letter multiplied by itself is 'squared'.","explain":"m × m = m²."},{"type":"mc","id":"p3","prompt":"How do you write 'p divided by 4'?","choices":["p/4","4p","4/p"],"answer":0,"hint":"Division is written as a fraction, with p on top.","explain":"p ÷ 4 = p/4."},{"type":"numeric","id":"p4","prompt":"Work out a² when a = {a}.","answer":"a*a","hint":"a² = a × a.","explain":"{a} × {a} = {=a*a}.","params":{"a":[2,9]}},{"type":"numeric","id":"p5","prompt":"If p = {=4*h}, what is p/4?","answer":"h","hint":"p/4 means p ÷ 4.","explain":"{=4*h} ÷ 4 = {h}.","params":{"h":[2,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"If a = {a}, what is a²?","answer":"a*a","hint":"a² = a × a.","explain":"a² = {a} × {a} = {=a*a}.","params":{"a":[2,9]}},{"type":"numeric","id":"m2","prompt":"If a = {a} and b = {b}, what is ab?","answer":"a*b","hint":"ab = a × b.","explain":"{a} × {b} = {=a*b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"mc","id":"m3","prompt":"Which is the same as {k}y?","choices":["y added together {k} times","y to the power {k}","{k} + y"],"answer":0,"hint":"{k}y = {k} × y.","explain":"{k}y = {k} × y, which is y added together {k} times.","params":{"k":[2,6]}},{"type":"numeric","id":"m4","prompt":"If x = {=2*h}, what is x/2?","answer":"h","hint":"x/2 means x ÷ 2.","explain":"{=2*h} ÷ 2 = {h}.","params":{"h":[2,9]}},{"type":"mc","id":"m5","prompt":"Which is written the usual way in algebra?","choices":["3ab","ab3","a3b"],"answer":0,"hint":"Numbers go first.","explain":"By convention the number goes first: 3ab."},{"type":"mc","id":"m6","prompt":"What does 2(x + 1) mean?","choices":["2 × (x + 1)","2x + 1","2 + x + 1"],"answer":0,"hint":"A number in front of a bracket multiplies everything in it.","explain":"2(x + 1) = 2 × (x + 1) = 2x + 2."},{"type":"mc","id":"m7","prompt":"Is a² the same as 2a?","choices":["No: a² is a × a, but 2a is 2 × a","Yes, always","Only when a is even"],"answer":0,"hint":"Try a = 5.","explain":"With a = 5: a² = 25 but 2a = 10. They're different (they only match when a is 0 or 2)."}]},"status":"self-checked","visual":{"type":"array","caption":"3n means 3 lots of n. Change n and watch 3n change.","opts":{"rows":3,"cols":4,"label":"n"}}},"mt_vHzVa3SURC":{"topicId":"mt_vHzVa3SURC","title":"Substituting into formulae","audience":"learner","keyIdea":"Replace each letter with its value, then calculate in the right order.","explain":{"kid":["Substituting means swapping each letter for its number. If v = u + at, with u = 2, a = 3 and t = 4, then v = 2 + 3 × 4 = 14.","Put the numbers in, then use the order of operations: multiply before you add."],"adult":["Substitution is how you use formulae in science and maths: replace each letter with its value, then evaluate using the order of operations. For v = u + at with u = 2, a = 3 and t = 4: v = 2 + 3 × 4 = 14.","Writing out the substituted line in full, with brackets around negative values, prevents most errors. With a = −2, 3a² means 3 × (−2)² = 3 × 4 = 12."]},"familyTip":"Use F = 9C/5 + 32 to convert today's temperature from °C to °F, and compare it with a weather app.","practice":[{"type":"numeric","id":"p1","prompt":"v = u + at. Find v when u = {u}, a = {a} and t = {t}.","answer":"u+a*t","hint":"Multiply a × t first.","explain":"{a} × {t} = {=a*t}, then {u} + {=a*t} = {=u+a*t}.","params":{"u":[1,9],"a":[2,5],"t":[2,6]}},{"type":"numeric","id":"p2","prompt":"P = 2l + 2w. If l = 5 and w = 3, what is P?","answer":16,"hint":"2l means 2 × l.","explain":"2 × 5 + 2 × 3 = 10 + 6 = 16."},{"type":"numeric","id":"p3","prompt":"A = ½bh. If b = 6 and h = 4, what is A?","answer":12,"hint":"Multiply b and h, then halve.","explain":"6 × 4 = 24, and half of 24 is 12."},{"type":"mc","id":"p4","prompt":"If x = 4, what is 3x²?","choices":["48","144","24"],"answer":0,"hint":"Square x first, then multiply by 3.","explain":"x² = 16, and 3 × 16 = 48. (144 would be (3x)².)"},{"type":"numeric","id":"p5","prompt":"P = 2l + 2w. Find P when l = {l} and w = {w}.","answer":"2*l+2*w","hint":"2l means 2 × l.","explain":"2 × {l} + 2 × {w} = {=2*l} + {=2*w} = {=2*l+2*w}.","params":{"l":[2,9],"w":[2,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"v = u + at. If u = {u}, a = {a} and t = {t}, what is v?","answer":"u+a*t","hint":"Multiply a × t first.","explain":"{a} × {t} = {=a*t}, then {u} + {=a*t} = {=u+a*t}.","params":{"u":[1,9],"a":[2,5],"t":[2,6]}},{"type":"numeric","id":"m2","prompt":"P = 2l + 2w. If l = {l} and w = {w}, what is P?","answer":"2*l+2*w","hint":"2l means 2 × l.","explain":"2 × {l} + 2 × {w} = {=2*l} + {=2*w} = {=2*l+2*w}.","params":{"l":[2,9],"w":[2,9]}},{"type":"numeric","id":"m3","prompt":"A = ½bh. If b = {b} and h = {h}, what is A?","answer":"b*h/2","hint":"Multiply b and h, then halve.","explain":"{b} × {h} = {=b*h}, and half of that is {=b*h/2}.","params":{"b":[2,10],"h":[2,10]},"where":"(b*h)%2==0"},{"type":"numeric","id":"m4","prompt":"If x = {x}, what is {k}x²?","answer":"k*x*x","hint":"Square first, then multiply.","explain":"{x}² = {=x*x}, then {k} × {=x*x} = {=k*x*x}.","params":{"x":[2,6],"k":[2,4]}},{"type":"numeric","id":"m5","prompt":"F = 9C/5 + 32. If C = {=5*k}, what is F?","answer":"9*k+32","hint":"Work out 9C/5 first.","explain":"9 × {=5*k} ÷ 5 = {=9*k}, then {=9*k} + 32 = {=9*k+32}.","params":{"k":[0,8]}},{"type":"numeric","id":"m6","prompt":"s = d/t. If d = 100 and t = 4, what is s?","answer":25,"hint":"d/t means d ÷ t.","explain":"100 ÷ 4 = 25."},{"type":"mc","id":"m7","prompt":"If a = −3, what is a²?","choices":["9","−9","−6"],"answer":0,"hint":"(−3) × (−3): a negative times a negative is positive.","explain":"(−3)² = (−3) × (−3) = 9."}]},"status":"self-checked","visual":{"type":"formula","caption":"Slide n. Each time, n is replaced by its value in 3n − 5, then worked out in the right order.","opts":{"name":"y","expr":"3 × n − 5","vars":{"n":[2,10,4]}}}},"mt_VUQNveSYjQ":{"topicId":"mt_VUQNveSYjQ","title":"Using inverse operations","audience":"learner","keyIdea":"+ undoes −, and × undoes ÷, so you can work backwards and check your answers.","explain":{"kid":["Inverse operations undo each other. Add 5 then subtract 5 and you're back where you started. Multiplying by 3 and dividing by 3 work the same way.","You can use this to check answers: if 56 ÷ 7 = 8, then 8 × 7 should be 56. You can also work backwards: 'I doubled a number and got 18', so halve 18 to get 9."],"adult":["Each operation has an inverse that undoes it: + and −, × and ÷. That gives you two tools. Checking: verify 437 − 189 = 248 by adding 248 + 189. Working backwards: to undo 'multiply by 4 then add 3', subtract 3 and then divide by 4. You undo the last step first.","That reverse-order idea is exactly what you'll do when you solve equations."]},"familyTip":"Next time you do a subtraction or division, check it with the inverse. It takes seconds and catches most slips.","practice":[{"type":"mc","id":"p1","prompt":"Which calculation checks 56 ÷ 7 = 8?","choices":["8 × 7","56 × 7","8 + 7"],"answer":0,"hint":"× undoes ÷.","explain":"8 × 7 = 56, so the division is right."},{"type":"numeric","id":"p2","prompt":"I double a number and get {=2*n}. What was the number?","answer":"n","hint":"Undo doubling by halving.","explain":"{=2*n} ÷ 2 = {n}.","params":{"n":[3,15]}},{"type":"numeric","id":"p3","prompt":"I multiply a number by 4, then add 3, and get 23. What was the number?","answer":5,"hint":"Undo the last step first: subtract 3, then divide by 4.","explain":"23 − 3 = 20, and 20 ÷ 4 = 5."},{"type":"mc","id":"p4","prompt":"To undo 'add 6, then multiply by 2', what do you do?","choices":["Divide by 2, then subtract 6","Subtract 6, then divide by 2","Multiply by 2, then add 6"],"answer":0,"hint":"Undo the steps in reverse order.","explain":"The last step was × 2, so undo that first (÷ 2), then undo + 6 (− 6)."},{"type":"numeric","id":"p5","prompt":"I add {c} to a number, then multiply by {k}, and get {=k*(n+c)}. What was the number?","answer":"n","hint":"Undo the last step first: divide by {k}.","explain":"{=k*(n+c)} ÷ {k} = {=n+c}, then {=n+c} − {c} = {n}.","params":{"n":[1,9],"k":[2,5],"c":[1,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which calculation checks {=a*b} ÷ {a} = {b}?","choices":["{b} × {a}","{=a*b} × {a}","{b} + {a}"],"answer":0,"hint":"× undoes ÷.","explain":"{b} × {a} = {=a*b}, which confirms the division.","params":{"a":[2,9],"b":[2,9]}},{"type":"numeric","id":"m2","prompt":"I multiply a number by {k}, then add {c}, and get {=k*n+c}. What was the number?","answer":"n","hint":"Undo the last step first.","explain":"{=k*n+c} − {c} = {=k*n}, then {=k*n} ÷ {k} = {n}.","params":{"n":[2,12],"k":[2,5],"c":[1,9]}},{"type":"numeric","id":"m3","prompt":"I add {c} to a number and get {=n+c}. What was the number?","answer":"n","hint":"Undo + {c} with − {c}.","explain":"{=n+c} − {c} = {n}.","params":{"n":[2,20],"c":[2,9]}},{"type":"numeric","id":"m4","prompt":"I think of a number, subtract {k}, then double it, and get {=2*(n-k)}. What was the number?","answer":"n","hint":"Undo the doubling first, then the subtraction.","explain":"Halve {=2*(n-k)} to get {=n-k}, then add {k} to get {n}.","params":{"n":[3,15],"k":[1,9]},"where":"n>k"},{"type":"mc","id":"m5","prompt":"What is the inverse of dividing by 5?","choices":["Multiplying by 5","Adding 5","Subtracting 5"],"answer":0,"hint":"What undoes ÷ 5?","explain":"× 5 undoes ÷ 5."},{"type":"numeric","id":"m6","prompt":"To check 437 − 189 = 248, you work out 248 + 189. What do you get?","answer":437,"hint":"Add the two numbers.","explain":"248 + 189 = 437, so the subtraction was right."},{"type":"mc","id":"m7","prompt":"To undo 'subtract 4, then divide by 3', what do you do?","choices":["Multiply by 3, then add 4","Add 4, then multiply by 3","Divide by 3, then subtract 4"],"answer":0,"hint":"Undo the last step first.","explain":"The last step was ÷ 3, so undo it with × 3, then undo − 4 with + 4."}]},"status":"self-checked","visual":{"type":"balance","caption":"Undo each step with its inverse, doing it to both sides: take away, then divide.","opts":{"mode":"solve","a":3,"b":2,"c":14}}},"mt_FX4a2Q8XXN":{"topicId":"mt_FX4a2Q8XXN","title":"Expanding single brackets","audience":"learner","keyIdea":"Multiply everything inside the bracket by the term outside: 3(2x + 5) = 6x + 15.","explain":{"kid":["To expand a bracket, multiply each thing inside by the number outside. 3(x + 4) = 3 × x + 3 × 4 = 3x + 12.","Think of 3 bags, each holding x sweets plus 4 more sweets: altogether you have 3x + 12 sweets."],"adult":["Expanding uses the distributive law: a(b + c) = ab + ac. So 3(2x + 5) = 6x + 15, and 4(x − 2) = 4x − 8.","The most common slip is multiplying only the first term: 3(x + 4) is not 3x + 4. With a negative outside, every sign inside flips: −2(x − 3) = −2x + 6."]},"familyTip":"Check an expansion by substituting a number: if x = 2, then 3(x + 4) = 18 and 3x + 12 = 18. If the two disagree, there's a mistake.","practice":[{"type":"mc","id":"p1","prompt":"Expand 3(x + 4).","choices":["3x + 12","3x + 4","x + 12"],"answer":0,"hint":"Multiply both x and 4 by 3.","explain":"3 × x + 3 × 4 = 3x + 12."},{"type":"mc","id":"p2","prompt":"Expand 2(5 − y).","choices":["10 − 2y","10 − y","7 − 2y"],"answer":0,"hint":"Multiply both 5 and y by 2.","explain":"2 × 5 − 2 × y = 10 − 2y."},{"type":"numeric","id":"p3","prompt":"{a}(x + {b}) = {a}x + □. What number goes in the box?","answer":"a*b","hint":"Multiply {b} by {a}.","explain":"{a} × {b} = {=a*b}, so {a}(x + {b}) = {a}x + {=a*b}.","params":{"a":[2,6],"b":[1,6]}},{"type":"mc","id":"p4","prompt":"Expand −2(x − 3).","choices":["−2x + 6","−2x − 6","−2x − 3"],"answer":0,"hint":"−2 × −3 is positive.","explain":"−2 × x = −2x and −2 × −3 = +6, so you get −2x + 6."},{"type":"mc","id":"p5","prompt":"Expand {a}(x − {b}).","choices":["{a}x − {=a*b}","{a}x − {b}","{a}x + {=a*b}"],"answer":0,"hint":"Multiply both terms by {a}, and keep the minus sign.","explain":"{a} × x − {a} × {b} = {a}x − {=a*b}.","params":{"a":[2,6],"b":[1,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Expand {a}(x + {b}).","choices":["{a}x + {=a*b}","{a}x + {b}","x + {=a*b}"],"answer":0,"hint":"Multiply both terms by {a}.","explain":"{a} × x + {a} × {b} = {a}x + {=a*b}.","params":{"a":[2,9],"b":[1,9]}},{"type":"numeric","id":"m2","prompt":"{a}(x + {b}) = {a}x + ?","answer":"a*b","hint":"Multiply {b} by {a}.","explain":"{a} × {b} = {=a*b}.","params":{"a":[2,9],"b":[1,9]}},{"type":"mc","id":"m3","prompt":"Expand {a}({b}x − {c}).","choices":["{=a*b}x − {=a*c}","{=a*b}x − {c}","{=a+b}x − {=a*c}"],"answer":0,"hint":"Multiply both terms by {a}.","explain":"{a} × {b}x = {=a*b}x and {a} × {c} = {=a*c}, so you get {=a*b}x − {=a*c}.","params":{"a":[2,6],"b":[2,6],"c":[1,9]},"where":"a*b!=a+b"},{"type":"numeric","id":"m4","prompt":"Check by substituting: if x = {x}, what is {a}(x + {b})?","answer":"a*(x+b)","hint":"Work out the bracket first.","explain":"{a} × ({x} + {b}) = {a} × {=x+b} = {=a*(x+b)}.","params":{"a":[2,9],"b":[1,9],"x":[1,5]}},{"type":"mc","id":"m5","prompt":"Expand 5(2a + 3b).","choices":["10a + 15b","10a + 3b","7a + 8b"],"answer":0,"hint":"Multiply both terms by 5.","explain":"5 × 2a = 10a and 5 × 3b = 15b."},{"type":"mc","id":"m6","prompt":"Which expansion is correct?","choices":["6(x − 1) = 6x − 6","6(x − 1) = 6x − 1","6(x − 1) = 6x + 6"],"answer":0,"hint":"Multiply both terms by 6.","explain":"6 × x − 6 × 1 = 6x − 6."},{"type":"mc","id":"m7","prompt":"Expand −3(y + 2).","choices":["−3y − 6","−3y + 6","−3y + 2"],"answer":0,"hint":"−3 × +2 is negative.","explain":"−3 × y = −3y and −3 × 2 = −6."}]},"status":"self-checked","visual":{"type":"array","caption":"Drag the split: 3 × (2 + 4) is 3 × 2 plus 3 × 4.","opts":{"rows":3,"cols":6,"split":2}}},"mt_aZENxGikHn":{"topicId":"mt_aZENxGikHn","title":"Writing expressions from words","audience":"learner","keyIdea":"Translate phrase by phrase, and watch the order for subtraction and division.","explain":{"kid":["You can turn words into algebra. If n is a number, '5 more than n' is n + 5, 'twice n' is 2n, and '3 less than n' is n − 3.","Careful with 'less than': '3 less than n' means start with n and take 3 away. That's n − 3, not 3 − n."],"adult":["Turning words into expressions is mostly vocabulary: 'more than' or 'increased by' means +; 'less than' or 'decreased by' means −; 'twice' or 'the product of' means ×; 'shared between' or 'the quotient of' means ÷.","Order matters for − and ÷: '7 less than n' is n − 7, and 'n divided by 3' is n/3. For combined phrases, build from the inside out: '5 more than twice a number' is 2n + 5."]},"familyTip":"Describe a phone plan or bus fare in words (such as '£10 a month plus £2 per extra GB'), then write it as an expression.","practice":[{"type":"mc","id":"p1","prompt":"Which expression means '{k} more than n'?","choices":["n + {k}","{k}n","{k} − n"],"answer":0,"hint":"'More than' means add.","explain":"n + {k}.","params":{"k":[2,9]}},{"type":"mc","id":"p2","prompt":"Which expression means '3 less than n'?","choices":["n − 3","3 − n","3n"],"answer":0,"hint":"Start with n, then take 3 away.","explain":"n − 3."},{"type":"mc","id":"p3","prompt":"Which expression means '5 more than twice a number n'?","choices":["2n + 5","2(n + 5)","5n + 2"],"answer":0,"hint":"Twice n is 2n. Then add 5.","explain":"2n + 5."},{"type":"mc","id":"p4","prompt":"Which expression means 'a number n shared equally between 4 people'?","choices":["n/4","4/n","n − 4"],"answer":0,"hint":"Sharing means dividing n.","explain":"n ÷ 4 = n/4."},{"type":"numeric","id":"p5","prompt":"If n = {n}, what is the value of 'twice n, minus {c}'?","answer":"2*n-c","hint":"Write it as 2n − {c}, then substitute.","explain":"2 × {n} − {c} = {=2*n-c}.","params":{"n":[3,9],"c":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which expression means '{k} less than n'?","choices":["n − {k}","{k} − n","{k}n"],"answer":0,"hint":"Start with n and take away {k}.","explain":"n − {k}.","params":{"k":[2,9]}},{"type":"mc","id":"m2","prompt":"Which expression means '{c} more than {k} times a number n'?","choices":["{k}n + {c}","{k}(n + {c})","{c}n + {k}"],"answer":0,"hint":"Build it from the inside: {k} times n first.","explain":"{k}n + {c}.","params":{"k":[2,9],"c":[1,9]},"where":"k!=c"},{"type":"numeric","id":"m3","prompt":"If n = {n}, what is the value of '{c} more than {k} times n'?","answer":"k*n+c","hint":"Write it as {k}n + {c}, then substitute.","explain":"{k} × {n} + {c} = {=k*n+c}.","params":{"k":[2,9],"c":[1,9],"n":[1,9]}},{"type":"mc","id":"m4","prompt":"Which expression means 'n divided by {k}'?","choices":["n/{k}","{k}/n","n − {k}"],"answer":0,"hint":"n goes on top.","explain":"n ÷ {k} = n/{k}.","params":{"k":[2,9]}},{"type":"mc","id":"m5","prompt":"Which expression means 'the product of a and b'?","choices":["ab","a + b","a/b"],"answer":0,"hint":"'Product' means multiply.","explain":"ab = a × b."},{"type":"mc","id":"m6","prompt":"Which expression means 'twice the sum of x and 3'?","choices":["2(x + 3)","2x + 3","x + 3 + 2"],"answer":0,"hint":"Find the sum first, then double it.","explain":"The sum is x + 3; twice that is 2(x + 3)."},{"type":"mc","id":"m7","prompt":"Sam is s years old. His sister is 4 years younger. Which expression gives her age?","choices":["s − 4","4 − s","s + 4"],"answer":0,"hint":"Younger means fewer years.","explain":"s − 4."}]},"status":"self-checked","visual":{"type":"formula","caption":"'Take 12 from a number x, then halve it' becomes (x − 12) ÷ 2. Slide x and watch it work out.","opts":{"name":"answer","expr":"(x − 12) ÷ 2","vars":{"x":[12,60,50]}}}},"mt_QhFEDyIwSO":{"topicId":"mt_QhFEDyIwSO","title":"Solving linear equations","audience":"learner","keyIdea":"Undo operations in reverse order, doing the same to both sides. If x is on both sides, gather the x terms first.","explain":{"kid":["To solve 2x + 3 = 11, undo the + 3 first (take 3 from both sides: 2x = 8), then undo the × 2 (divide both sides by 2: x = 4).","If there's a bracket, you can expand it first: 3(x + 1) = 18 becomes 3x + 3 = 18."],"adult":["Solving a linear equation means isolating the unknown using operations that keep both sides equal. Undo things in reverse order: for 5x − 7 = 18, add 7 (5x = 25), then divide by 5 (x = 5).","When x appears on both sides, gather the x terms on one side first: 5x + 2 = 2x + 14 → 3x + 2 = 14 → 3x = 12 → x = 4. Always check by substituting back into the original equation."]},"familyTip":"After solving, substitute your answer back into the original equation. If both sides match, you know you're right without looking at the answers.","practice":[{"type":"numeric","id":"p1","prompt":"Find x: {a}x + {b} = {=a*x+b}.","answer":"x","hint":"Subtract {b} from both sides, then divide by {a}.","explain":"{a}x = {=a*x}, so x = {x}.","params":{"a":[2,6],"b":[1,9],"x":[1,9]}},{"type":"numeric","id":"p2","prompt":"Solve 5x − 7 = 18.","answer":5,"hint":"Add 7 to both sides first.","explain":"5x = 25, so x = 5."},{"type":"numeric","id":"p3","prompt":"Solve 3(x + 1) = 18.","answer":5,"hint":"Expand, or divide both sides by 3 first.","explain":"x + 1 = 6, so x = 5."},{"type":"numeric","id":"p4","prompt":"Solve 5x + 2 = 2x + 14.","answer":4,"hint":"Subtract 2x from both sides first.","explain":"3x + 2 = 14, then 3x = 12, so x = 4."},{"type":"numeric","id":"p5","prompt":"Find x: {a}(x − {b}) = {=a*(x-b)}.","answer":"x","hint":"Divide both sides by {a} first.","explain":"x − {b} = {=x-b}, so x = {x}.","params":{"a":[2,5],"b":[1,4],"x":[2,9]},"where":"x>b"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Solve {a}x + {b} = {=a*x+b}.","answer":"x","hint":"Subtract {b}, then divide by {a}.","explain":"{a}x = {=a*x}, so x = {x}. Check: {a} × {x} + {b} = {=a*x+b}.","params":{"a":[2,9],"b":[1,15],"x":[1,10]}},{"type":"numeric","id":"m2","prompt":"Solve {a}x − {b} = {=a*x-b}.","answer":"x","hint":"Add {b} to both sides first.","explain":"{a}x = {=a*x}, so x = {x}.","params":{"a":[2,9],"b":[1,15],"x":[2,10]},"where":"a*x>b"},{"type":"numeric","id":"m3","prompt":"Solve {a}(x + {b}) = {=a*(x+b)}.","answer":"x","hint":"Divide both sides by {a} first.","explain":"x + {b} = {=x+b}, so x = {x}.","params":{"a":[2,6],"b":[1,6],"x":[1,9]}},{"type":"numeric","id":"m4","prompt":"Solve {a}x + {b} = {c}x + {=(a-c)*x+b}.","answer":"x","hint":"Subtract {c}x from both sides first.","explain":"{=a-c}x + {b} = {=(a-c)*x+b}, so {=a-c}x = {=(a-c)*x} and x = {x}.","params":{"a":[5,9],"c":[2,4],"b":[1,9],"x":[1,9]},"where":"a-c>=2"},{"type":"numeric","id":"m5","prompt":"Solve x/{d} + {b} = {=k+b}.","answer":"d*k","hint":"Subtract {b}, then multiply by {d}.","explain":"x/{d} = {k}, so x = {k} × {d} = {=d*k}.","params":{"d":[2,5],"k":[1,6],"b":[1,9]}},{"type":"mc","id":"m6","prompt":"Which step is correct for 4x − 5 = 23?","choices":["Add 5 to both sides to get 4x = 28","Subtract 5 from both sides to get 4x = 18","Divide only 4x by 4 to get x − 5 = 23"],"answer":0,"hint":"Undo the − 5, and do it to both sides.","explain":"Adding 5 to both sides gives 4x = 28, so x = 7."},{"type":"numeric","id":"m7","prompt":"Solve 7 − x = 2.","answer":5,"hint":"What do you take from 7 to leave 2?","explain":"7 − 5 = 2, so x = 5. (Or add x to both sides: 7 = 2 + x.)"}]},"status":"self-checked","visual":{"type":"balance","caption":"Solve 3x + 4 = 19 by keeping the scale level.","opts":{"mode":"solve","a":3,"b":4,"c":19}}},"mt_mmUVPwnv3o":{"topicId":"mt_mmUVPwnv3o","title":"Word problems with linear equations","audience":"learner","keyIdea":"Name the unknown, write an equation, solve it, then check the answer makes sense.","explain":{"kid":["Word problems get easier once you write an equation. 'Tom has some stickers. He gets 6 more and now has 20.' Let s be Tom's stickers at the start: s + 6 = 20, so s = 14.","Always check: 14 + 6 = 20 ✓. Also ask whether the answer makes sense: you can't have −3 stickers."],"adult":["A reliable routine: (1) say what the letter stands for, (2) write the equation from the story, (3) solve it, (4) check it against the original words, not just your equation.","Example: a taxi charges £3 plus £2 per mile and the fare was £17. Let m = miles: 3 + 2m = 17, so 2m = 14 and m = 7. Check: £3 + 7 × £2 = £17 ✓."]},"familyTip":"Find a real pricing rule (a taxi, a gym, a phone plan) and work out the unknown from a total, such as how many miles a £20 fare covers.","practice":[{"type":"numeric","id":"p1","prompt":"Tom has some stickers. He gets {a} more and now has {=s+a}. How many did he have at the start?","answer":"s","hint":"s + {a} = {=s+a}.","explain":"s = {=s+a} − {a} = {s}. Check: {s} + {a} = {=s+a} ✓.","params":{"a":[3,9],"s":[5,20]}},{"type":"numeric","id":"p2","prompt":"A taxi charges £3 plus £2 per mile. The fare was £17. How many miles was the trip?","answer":7,"hint":"3 + 2m = 17.","explain":"2m = 14, so m = 7."},{"type":"numeric","id":"p3","prompt":"Three friends share a bill equally and each pays £12. What was the total bill in £?","answer":36,"hint":"b ÷ 3 = 12.","explain":"b = 12 × 3 = 36."},{"type":"numeric","id":"p4","prompt":"A rectangle's length is 3 cm more than its width. Its perimeter is 26 cm. What is the width in cm?","answer":5,"hint":"Let the width be w. Then the length is w + 3, and the perimeter is 2(w + w + 3).","explain":"2(2w + 3) = 26, so 4w + 6 = 26, 4w = 20 and w = 5. Check: 2 × (5 + 8) = 26 ✓."},{"type":"numeric","id":"p5","prompt":"A gym charges a £{f} joining fee plus £{r} a week. Sam paid £{=f+r*w} in total. How many weeks was that?","answer":"w","hint":"Write {f} + {r}w = {=f+r*w}.","explain":"{r}w = {=r*w}, so w = {w}. Check: {f} + {r} × {w} = {=f+r*w} ✓.","params":{"f":[10,30],"r":[5,9],"w":[2,10]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A taxi charges £{f} plus £{r} per mile. The fare was £{=f+r*m}. How many miles was the trip?","answer":"m","hint":"Write {f} + {r}m = {=f+r*m}.","explain":"{r}m = {=r*m}, so m = {m}. Check: {f} + {r} × {m} = {=f+r*m} ✓.","params":{"f":[2,5],"r":[2,4],"m":[2,12]}},{"type":"numeric","id":"m2","prompt":"Mia has some sweets. She gets {a} more and now has {=s+a}. How many did she have at first?","answer":"s","hint":"s + {a} = {=s+a}.","explain":"s = {=s+a} − {a} = {s}.","params":{"a":[3,9],"s":[5,20]}},{"type":"numeric","id":"m3","prompt":"{n} friends share a bill equally and each pays £{k}. What was the bill in £?","answer":"n*k","hint":"b ÷ {n} = {k}.","explain":"b = {k} × {n} = {=n*k}.","params":{"n":[2,5],"k":[5,15]}},{"type":"numeric","id":"m4","prompt":"A rectangle's length is {d} cm more than its width. Its perimeter is {=4*w+2*d} cm. What is the width in cm?","answer":"w","hint":"Perimeter = 2(w + w + {d}) = 4w + {=2*d}.","explain":"4w + {=2*d} = {=4*w+2*d}, so 4w = {=4*w} and w = {w}.","params":{"w":[2,10],"d":[1,5]}},{"type":"numeric","id":"m5","prompt":"Two consecutive whole numbers add up to {=2*x+1}. What is the smaller one?","answer":"x","hint":"Call them n and n + 1.","explain":"n + n + 1 = {=2*x+1}, so 2n = {=2*x} and n = {x}.","params":{"x":[5,20]}},{"type":"mc","id":"m6","prompt":"You're solving a problem about the number of people on a bus and get x = −4. What should you do?","choices":["Recheck the equation: a negative number of people doesn't make sense","Write −4 as the answer","Round it to 4"],"answer":0,"hint":"Does the answer fit the story?","explain":"Answers must make sense in context. A negative count means the equation or the working has a mistake."},{"type":"numeric","id":"m7","prompt":"Ali is 3 times as old as his sister. Together they are 32. How old is his sister?","answer":8,"hint":"Let her age be s. Then Ali is 3s, and s + 3s = 32.","explain":"4s = 32, so s = 8 (and Ali is 24). Check: 8 + 24 = 32 ✓."}]},"status":"self-checked","visual":{"type":"balance","caption":"'4 tickets plus a £5 fee cost £33': 4x + 5 = 33 on a scale.","opts":{"mode":"solve","a":4,"b":5,"c":33}}},"mt_XLP1IM3Qbb":{"topicId":"mt_XLP1IM3Qbb","title":"Long multiplication","audience":"learner","keyIdea":"Multiply by each digit of the second number separately, then add the rows.","explain":{"kid":["To work out 34 × 26, split 26 into 20 and 6. First 34 × 6 = 204. Then 34 × 20 = 680. Add them: 204 + 680 = 884.","Line the digits up in columns. The second row is for the tens, so it is ten times bigger and ends in a 0."],"adult":["Long multiplication uses the distributive law: 346 × 27 = 346 × 20 + 346 × 7. Write each partial product on its own row, then add: 6,920 + 2,422 = 9,342.","Two checks catch most mistakes. Estimate first: 346 × 27 is about 350 × 30 = 10,500, so 9,342 is believable. And make sure the tens row has its placeholder 0."]},"familyTip":"Before you multiply, round both numbers and estimate. After you multiply, compare your answer with the estimate.","practice":[{"type":"numeric","id":"p1","prompt":"Work out 34 × 26.","answer":884,"hint":"Do 34 × 6, then 34 × 20, then add.","explain":"34 × 6 = 204 and 34 × 20 = 680, so 34 × 26 = 884."},{"type":"numeric","id":"p2","prompt":"Work out {a} × {b}.","answer":"a*b","hint":"Multiply by the ones digit, then by the tens, then add the two rows.","explain":"{a} × {=b%10} = {=a*(b%10)} and {a} × {=b-b%10} = {=a*(b-b%10)}, so {a} × {b} = {=a*b}.","params":{"a":[12,99],"b":[11,39]}},{"type":"mc","id":"p3","prompt":"In 346 × 27, what is the tens row (346 × 20)?","choices":["6920","692","2422"],"answer":0,"hint":"346 × 2 = 692. Now make it ten times bigger.","explain":"346 × 20 = 692 × 10 = 6920."},{"type":"mc","id":"p4","prompt":"Why does the second row of 52 × 34 end in 0?","choices":["Because that row is 52 × 30, not 52 × 3","Because 52 ends in 2","Because it's a carried digit"],"answer":0,"hint":"What is the 3 in 34 really worth?","explain":"The 3 in 34 means 30, and 52 × 30 = 1560, which ends in 0."},{"type":"numeric","id":"p5","prompt":"Work out the tens row: {a} × {=t*10}.","answer":"a*t*10","hint":"Work out {a} × {t}, then make it ten times bigger.","explain":"{a} × {t} = {=a*t}, so {a} × {=t*10} = {=a*t*10}.","params":{"a":[12,99],"t":[2,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Calculate {a} × {b}.","answer":"a*b","hint":"Split {b} into tens and ones.","explain":"{a} × {=b-b%10} = {=a*(b-b%10)} and {a} × {=b%10} = {=a*(b%10)}, so the answer is {=a*b}.","params":{"a":[21,99],"b":[12,49]}},{"type":"numeric","id":"m2","prompt":"Use long multiplication: {a} × {b}.","answer":"a*b","hint":"Two rows: one for the ones, one for the tens.","explain":"{a} × {=b%10} = {=a*(b%10)} and {a} × {=b-b%10} = {=a*(b-b%10)}, so {a} × {b} = {=a*b}.","params":{"a":[100,999],"b":[12,29]}},{"type":"numeric","id":"m3","prompt":"A box holds {b} pens. How many pens are in {a} boxes?","answer":"a*b","hint":"Multiply the number of boxes by the pens in each.","explain":"{a} × {b} = {=a*b} pens.","params":{"a":[12,60],"b":[12,36]}},{"type":"numeric","id":"m4","prompt":"Work out 1234 × 12.","answer":14808,"hint":"1234 × 2, then 1234 × 10, then add.","explain":"1234 × 2 = 2468 and 1234 × 10 = 12340, so the total is 14808."},{"type":"mc","id":"m5","prompt":"Which is the best estimate for 489 × 31?","choices":["About 15,000","About 1,500","About 150,000"],"answer":0,"hint":"Round to 500 × 30.","explain":"500 × 30 = 15,000. (The exact answer is 15,159.)"},{"type":"mc","id":"m6","prompt":"Sam works out 23 × 14 as 92 + 23 = 115. What went wrong?","choices":["He forgot the 0: 23 × 10 = 230, so the answer is 322","He forgot to carry a 1","Nothing, 115 is right"],"answer":0,"hint":"What is the 1 in 14 worth?","explain":"The tens row should be 23 × 10 = 230, so 92 + 230 = 322."},{"type":"numeric","id":"m7","prompt":"A school orders 24 boxes of 144 pencils. How many pencils is that?","answer":3456,"hint":"Work out 144 × 24.","explain":"144 × 4 = 576 and 144 × 20 = 2880, so 576 + 2880 = 3456."}]},"status":"self-checked","visual":{"type":"longmul","caption":"Watch 34 × 26 written out one row at a time.","opts":{"a":34,"b":26}}},"mt_WsM4EmdOLe":{"topicId":"mt_WsM4EmdOLe","title":"Long division and remainders","audience":"learner","keyIdea":"Divide, then decide what the remainder means: leftover, fraction, decimal, or round up or down.","explain":{"kid":["Long division by a two-digit number works like short division, with more writing. For 432 ÷ 15: 15 goes into 43 twice (30), leaving 13. Bring down the 2 to make 132. 15 goes into 132 eight times (120), leaving 12. So 432 ÷ 15 = 28 remainder 12.","What you do with the remainder depends on the question. If a minibus holds 15 people, 432 people need 29 minibuses, so that nobody is left behind."],"adult":["It helps to write out a few multiples of the divisor first (15, 30, 45, …). Then divide, multiply, subtract and bring down, one digit at a time.","The remainder can be written as a whole number (r 12), as a fraction (28 12/15 = 28 4/5), or as a decimal (28.8). In a word problem, decide whether to round up (buses needed) or down (full boxes you can fill)."]},"familyTip":"Check a division by multiplying back: 28 × 15 + 12 should give 432.","practice":[{"type":"numeric","id":"p1","prompt":"432 ÷ 15 = 28 remainder what?","answer":12,"hint":"28 × 15 = 420. How far is that from 432?","explain":"28 × 15 = 420, and 432 − 420 = 12."},{"type":"numeric","id":"p2","prompt":"{=d*q+r} ÷ {d} = {q} remainder what?","answer":"r","hint":"Work out {q} × {d}, then subtract it from {=d*q+r}.","explain":"{q} × {d} = {=d*q}, and {=d*q+r} − {=d*q} = {r}.","params":{"d":[12,25],"q":[5,30],"r":[1,11]},"where":"r<d"},{"type":"numeric","id":"p3","prompt":"What is {=d*q} ÷ {d}?","answer":"q","hint":"List multiples of {d} to help.","explain":"{d} × {q} = {=d*q}, so {=d*q} ÷ {d} = {q}.","params":{"d":[12,25],"q":[11,40]}},{"type":"mc","id":"p4","prompt":"432 people are going on a trip. Each minibus holds 15 people. How many minibuses are needed?","choices":["29","28","28 r 12"],"answer":0,"hint":"What happens to the 12 people left over?","explain":"432 ÷ 15 = 28 r 12. The 12 extra people need one more minibus, so 29."},{"type":"numeric","id":"p5","prompt":"Eggs are packed in boxes of {d}. How many full boxes can you make from {=d*q+r} eggs?","answer":"q","hint":"Divide, then ignore the eggs left over.","explain":"{=d*q+r} ÷ {d} = {q} r {r}, so you can fill {q} boxes.","params":{"d":[6,12],"q":[10,40],"r":[1,5]},"where":"r<d"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Work out {=d*q} ÷ {d}.","answer":"q","hint":"How many {d}s make {=d*q}?","explain":"{d} × {q} = {=d*q}, so the answer is {q}.","params":{"d":[11,30],"q":[12,60]}},{"type":"numeric","id":"m2","prompt":"{=d*q+r} ÷ {d} leaves a remainder. What is it?","answer":"r","hint":"Find the biggest multiple of {d} that fits.","explain":"{d} × {q} = {=d*q}, and {=d*q+r} − {=d*q} = {r}.","params":{"d":[11,25],"q":[10,40],"r":[1,10]},"where":"r<d"},{"type":"numeric","id":"m3","prompt":"{=d*q+r} children go on a trip. Each coach holds {d}. How many coaches are needed?","answer":"q+1","hint":"Divide, then think about the children left over.","explain":"{=d*q+r} ÷ {d} = {q} r {r}. The {r} extra children need one more coach, so {=q+1}.","params":{"d":[20,50],"q":[2,9],"r":[1,15]},"where":"r<d"},{"type":"numeric","id":"m4","prompt":"Pencils come in packs of {d}. How many full packs can you make from {=d*q+r} pencils?","answer":"q","hint":"Divide, then ignore the pencils left over.","explain":"{=d*q+r} ÷ {d} = {q} r {r}, so {q} full packs.","params":{"d":[12,24],"q":[5,20],"r":[1,11]},"where":"r<d"},{"type":"mc","id":"m5","prompt":"432 ÷ 15 = 28 r 12. Which mixed number is the same?","choices":["28 4/5","28 12/100","28 1/12"],"answer":0,"hint":"The remainder 12 is out of 15.","explain":"12/15 simplifies to 4/5, so the answer is 28 4/5."},{"type":"numeric","id":"m6","prompt":"Give 432 ÷ 15 as a decimal.","answer":28.8,"hint":"28 r 12 is 28 and 12/15, which is 28 and 4/5.","explain":"4/5 = 0.8, so 432 ÷ 15 = 28.8."},{"type":"mc","id":"m7","prompt":"When should you round a division answer up?","choices":["When everyone or everything must fit, like buses for a trip","Always","When the remainder is less than half"],"answer":0,"hint":"Think about who would be left behind.","explain":"Round up when leftovers still need a place, such as an extra bus or box."}]},"status":"self-checked","visual":{"type":"longdiv","caption":"432 ÷ 15, one digit at a time: divide, multiply, subtract, bring down.","opts":{"a":432,"b":15}}},"mt_8jFSnXxqQD":{"topicId":"mt_8jFSnXxqQD","title":"Brackets in expressions","audience":"learner","keyIdea":"Work out what is inside brackets first. Brackets group numbers together.","explain":{"kid":["Brackets (in the US, parentheses) tell you which part to work out first. In 3 × (4 + 2), you add first: 4 + 2 = 6, then 3 × 6 = 18.","Without brackets, 3 × 4 + 2 means 12 + 2 = 14. So brackets can change the answer."],"adult":["Grouping symbols mark part of an expression to treat as one number. They are round brackets ( ), square brackets [ ] and braces { }. Work out the innermost group first: 2 × [10 − (3 + 1)] = 2 × [10 − 4] = 2 × 6 = 12.","Brackets let you write exactly the calculation you mean. 'Add 4 and 2, then multiply by 3' is 3 × (4 + 2), not 3 × 4 + 2."]},"familyTip":"Take a calculation like 3 × 4 + 2 and see how many different answers you can make just by adding brackets.","practice":[{"type":"numeric","id":"p1","prompt":"Work out 3 × (4 + 2).","answer":18,"hint":"Do the bracket first.","explain":"4 + 2 = 6, then 3 × 6 = 18."},{"type":"numeric","id":"p2","prompt":"Work out {a} × ({b} + {c}).","answer":"a*(b+c)","hint":"Do the bracket first.","explain":"{b} + {c} = {=b+c}, then {a} × {=b+c} = {=a*(b+c)}.","params":{"a":[2,6],"b":[1,9],"c":[1,9]}},{"type":"numeric","id":"p3","prompt":"Work out ({a} − {b}) × {c}.","answer":"(a-b)*c","hint":"Do the bracket first.","explain":"{a} − {b} = {=a-b}, then {=a-b} × {c} = {=(a-b)*c}.","params":{"a":[6,15],"b":[1,5],"c":[2,6]}},{"type":"mc","id":"p4","prompt":"Which expression means 'add 4 and 2, then multiply by 3'?","choices":["3 × (4 + 2)","3 × 4 + 2","3 + 4 × 2"],"answer":0,"hint":"The adding must happen first, so it needs brackets.","explain":"3 × (4 + 2) adds first, then multiplies."},{"type":"numeric","id":"p5","prompt":"Work out 2 × [10 − (3 + 1)].","answer":12,"hint":"Start with the innermost bracket.","explain":"3 + 1 = 4, then 10 − 4 = 6, then 2 × 6 = 12."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Calculate {a} × ({b} + {c}).","answer":"a*(b+c)","hint":"Bracket first.","explain":"{b} + {c} = {=b+c}, and {a} × {=b+c} = {=a*(b+c)}.","params":{"a":[2,9],"b":[2,9],"c":[2,9]}},{"type":"numeric","id":"m2","prompt":"Calculate ({a} + {=c*k-a}) ÷ {c}.","answer":"k","hint":"Bracket first, then divide.","explain":"{a} + {=c*k-a} = {=c*k}, and {=c*k} ÷ {c} = {k}.","params":{"a":[1,9],"c":[2,6],"k":[2,9]},"where":"c*k>a"},{"type":"numeric","id":"m3","prompt":"Calculate {a} × [{b} − ({c} + {d})].","answer":"a*(b-c-d)","hint":"Start with the innermost bracket.","explain":"{c} + {d} = {=c+d}, then {b} − {=c+d} = {=b-c-d}, then {a} × {=b-c-d} = {=a*(b-c-d)}.","params":{"a":[2,5],"b":[10,20],"c":[1,4],"d":[1,4]}},{"type":"mc","id":"m4","prompt":"Do the brackets change the answer? Compare {a} × ({b} + {c}) with {a} × {b} + {c}.","choices":["Yes: they give {=a*(b+c)} and {=a*b+c}","No: both give {=a*(b+c)}","No: both give {=a*b+c}"],"answer":0,"hint":"Work out each one.","explain":"{a} × ({b} + {c}) = {=a*(b+c)}, but {a} × {b} + {c} = {=a*b+c}.","params":{"a":[2,6],"b":[2,9],"c":[1,9]}},{"type":"numeric","id":"m5","prompt":"Work out (12 − 4) ÷ 2.","answer":4,"hint":"Bracket first.","explain":"12 − 4 = 8, then 8 ÷ 2 = 4."},{"type":"mc","id":"m6","prompt":"What is 5 × (6 − 1)?","choices":["25","29","35"],"answer":0,"hint":"Do 6 − 1 first.","explain":"6 − 1 = 5, and 5 × 5 = 25. (29 would be 5 × 6 − 1.)"},{"type":"mc","id":"m7","prompt":"In 2 × [10 − (3 + 1)], what do you work out first?","choices":["3 + 1","2 × 10","10 − 3"],"answer":0,"hint":"Find the innermost bracket.","explain":"The round bracket (3 + 1) is inside the square one, so it comes first."}]},"status":"self-checked","visual":{"type":"bidmas","caption":"3 × (4 + 2): the bracket goes first.","opts":{"expr":"3 × (4 + 2)"}}},"mt_RXnyhCRYXA":{"topicId":"mt_RXnyhCRYXA","title":"Multi-step problems","audience":"learner","keyIdea":"Break the problem into steps, choose the operation for each step, and check the answer makes sense.","explain":{"kid":["Some problems need more than one step. 'Pens cost 45p each. Mia buys 6 pens and pays with £5. How much change does she get?' Step 1: 6 × 45p = 270p = £2.70. Step 2: £5 − £2.70 = £2.30.","Ask yourself: what do I need to find first? Which operation does that need: add, subtract, multiply or divide?"],"adult":["Multi-step problems are mostly about planning. Underline what you're asked, list what you know, and decide the order of the steps before calculating. Key words help, but they can mislead ('more' doesn't always mean add), so picture what is actually happening.","Finish by checking units and size. If 6 pens seem to cost more than £5, something has gone wrong. A rounded estimate first (6 × 50p = £3) gives a quick check."]},"familyTip":"When you shop, estimate the total before you reach the till, then see how close you were.","practice":[{"type":"numeric","id":"p1","prompt":"Pens cost 45p each. Mia buys 6 pens and pays with £5. How much change does she get, in pence?","answer":230,"hint":"First find the cost of 6 pens, then subtract it from 500p.","explain":"6 × 45p = 270p, and 500p − 270p = 230p (£2.30)."},{"type":"numeric","id":"p2","prompt":"A cinema has {r} rows of {s} seats. {t} seats are taken. How many seats are free?","answer":"r*s-t","hint":"First find the total number of seats.","explain":"{r} × {s} = {=r*s} seats, and {=r*s} − {t} = {=r*s-t} are free.","params":{"r":[8,15],"s":[10,20],"t":[20,79]}},{"type":"numeric","id":"p3","prompt":"{n} friends share a £{=n*e} bill equally, then each adds a £{t} tip. How much does each person pay in total, in £?","answer":"e+t","hint":"First share the bill, then add the tip.","explain":"£{=n*e} ÷ {n} = £{e}, and £{e} + £{t} = £{=e+t}.","params":{"n":[2,6],"e":[5,15],"t":[1,3]}},{"type":"mc","id":"p4","prompt":"Juice costs £1.20 a bottle. You need 30 bottles and you have £30. What should you work out?","choices":["30 × £1.20 = £36, so you don't have enough","£30 − £1.20 = £28.80 change","£30 ÷ £1.20 = 25, so you get £5 change"],"answer":0,"hint":"First find what 30 bottles cost.","explain":"30 bottles cost £36, which is more than £30, so you are £6 short."},{"type":"numeric","id":"p5","prompt":"A book has {p} pages. Leo reads {r} pages a day for {d} days. How many pages are left?","answer":"p-r*d","hint":"First find how many pages he has read.","explain":"{r} × {d} = {=r*d} pages read, so {p} − {=r*d} = {=p-r*d} are left.","params":{"p":[100,300],"r":[10,25],"d":[3,7]},"where":"p>r*d"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A box holds {b} apples. A shop has {n} full boxes and sells {s} apples. How many apples are left?","answer":"b*n-s","hint":"First find how many apples there were.","explain":"{n} × {b} = {=b*n}, and {=b*n} − {s} = {=b*n-s}.","params":{"b":[12,30],"n":[3,9],"s":[10,35]}},{"type":"numeric","id":"m2","prompt":"Tickets cost £{p} for adults and £{c} for children. What do {a} adults and {k} children pay in total, in £?","answer":"p*a+c*k","hint":"Find the adult cost and the child cost, then add.","explain":"{a} × £{p} = £{=p*a} and {k} × £{c} = £{=c*k}, so £{=p*a+c*k} in total.","params":{"p":[8,15],"c":[3,7],"a":[1,3],"k":[1,4]}},{"type":"numeric","id":"m3","prompt":"A {=2*n*q} m rope is cut into {n} equal pieces, then each piece is cut in half. How long is each small piece, in m?","answer":"q","hint":"Divide by {n}, then halve.","explain":"{=2*n*q} ÷ {n} = {=2*q} m, and half of that is {q} m.","params":{"n":[2,5],"q":[1,6]}},{"type":"numeric","id":"m4","prompt":"Sam saves £{s} a week. A bike costs £{=s*w+r}. How many weeks until he can afford it?","answer":"w+1","hint":"Divide the price by his weekly savings, then think about the remainder.","explain":"After {w} weeks he has £{=s*w}, which is £{r} short, so he needs {=w+1} weeks.","params":{"s":[5,15],"w":[4,12],"r":[1,14]},"where":"r<s"},{"type":"mc","id":"m5","prompt":"A coach holds 52 people. How do you work out how many coaches 300 people need?","choices":["Divide 300 by 52, then round up","Multiply 300 by 52","Subtract 52 from 300 once"],"answer":0,"hint":"Each coach takes 52 people.","explain":"300 ÷ 52 = 5 r 40, so 6 coaches are needed."},{"type":"numeric","id":"m6","prompt":"Pens cost 45p each. How many pens can you buy with £3?","answer":6,"hint":"£3 = 300p. How many 45s fit into 300?","explain":"300 ÷ 45 = 6 r 30, so you can buy 6 pens."},{"type":"mc","id":"m7","prompt":"Your working says 6 pens cost £14.70, but your estimate was 6 × 50p = £3. What should you do?","choices":["Recheck: £14.70 is far bigger than the estimate","Trust the working","Round it to £15"],"answer":0,"hint":"Do the two numbers agree?","explain":"An answer far from the estimate means there's a mistake to find."}]},"status":"self-checked","visual":{"type":"formula","caption":"Mia pays 500p for n pens at 45p each. Slide n and watch her change work out in order.","opts":{"name":"change","expr":"500 − n × 45","vars":{"n":[1,11,6]}}}},"mt_4WaKWECpcv":{"topicId":"mt_4WaKWECpcv","title":"Writing number sentences","audience":"learner","keyIdea":"Write calculations as expressions, and read what an expression tells you without working it out.","explain":{"kid":["A number sentence records a calculation. 'Three bags of 12 apples, plus 5 loose apples' is 3 × 12 + 5.","You can compare expressions without working them out. 3 × (18,932 + 921) is three times as big as 18,932 + 921, because it is three lots of the same thing."],"adult":["Writing an expression means recording the structure of a calculation, not just its answer: 'add 8 and 7, then multiply by 2' is 2 × (8 + 7).","Reading expressions without calculating is a key step towards algebra. You can see that 3 × (18,932 + 921) is three times 18,932 + 921, and that 500 − 199 is one more than 500 − 200."]},"familyTip":"Next time you work something out, write it as one expression first, then calculate.","practice":[{"type":"mc","id":"p1","prompt":"Which expression means 'add 8 and 7, then multiply by 2'?","choices":["2 × (8 + 7)","2 × 8 + 7","8 + 7 × 2"],"answer":0,"hint":"The adding comes first, so it needs brackets.","explain":"2 × (8 + 7) adds first, then doubles."},{"type":"mc","id":"p2","prompt":"How does {k} × ({a} + {b}) compare with {a} + {b}?","choices":["It is {k} times as big","It is {k} more","It is the same"],"answer":0,"hint":"{k} × something means {k} lots of it.","explain":"{k} × ({a} + {b}) is {k} lots of {a} + {b}, so it is {k} times as big.","params":{"k":[2,5],"a":[120,160],"b":[11,30]}},{"type":"mc","id":"p3","prompt":"Which is bigger: {a} − {b} or {a} − {=b+1}?","choices":["{a} − {b}","{a} − {=b+1}","They are equal"],"answer":0,"hint":"Which takes away more?","explain":"Taking away {=b+1} leaves one less than taking away {b}, so {a} − {b} is bigger.","params":{"a":[300,340],"b":[101,140]}},{"type":"mc","id":"p4","prompt":"Which expression matches '3 bags of 12 apples, plus 5 loose apples'?","choices":["3 × 12 + 5","3 × (12 + 5)","3 + 12 × 5"],"answer":0,"hint":"Three bags of 12 is 3 × 12.","explain":"3 × 12 + 5 = 41 apples."},{"type":"numeric","id":"p5","prompt":"Work out the value of {k} × {a} + {b}.","answer":"k*a+b","hint":"Multiply first, then add.","explain":"{k} × {a} = {=k*a}, then {=k*a} + {b} = {=k*a+b}.","params":{"k":[2,5],"a":[10,30],"b":[1,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which expression means 'multiply {a} by {b}, then add {c}'?","choices":["{a} × {b} + {c}","{a} × ({b} + {c})","{a} + {b} × {c}"],"answer":0,"hint":"Multiplying first doesn't need brackets.","explain":"{a} × {b} + {c}.","params":{"a":[2,9],"b":[2,9],"c":[2,9]}},{"type":"mc","id":"m2","prompt":"Which expression means 'add {a} and {b}, then multiply by {c}'?","choices":["{c} × ({a} + {b})","{c} × {a} + {b}","{a} + {b} × {c}"],"answer":0,"hint":"The adding must happen first.","explain":"{c} × ({a} + {b}).","params":{"a":[2,9],"b":[2,9],"c":[2,9]}},{"type":"mc","id":"m3","prompt":"How does ({a} + {b}) × {k} compare with {a} + {b}?","choices":["{k} times as big","{k} more","Exactly the same"],"answer":0,"hint":"× {k} means {k} lots.","explain":"It is {k} lots of {a} + {b}, so {k} times as big.","params":{"k":[2,6],"a":[120,150],"b":[11,30]}},{"type":"numeric","id":"m4","prompt":"{a} + {b} = {=a+b}. Without a calculator, what is {a} + {=b+1}?","answer":"a+b+1","hint":"Adding one more gives one more.","explain":"{a} + {=b+1} is one more than {=a+b}, so {=a+b+1}.","params":{"a":[1200,1240],"b":[101,140]}},{"type":"mc","id":"m5","prompt":"Which is bigger: 4 × (250 + 13) or 4 × 250 + 13?","choices":["4 × (250 + 13)","4 × 250 + 13","They are equal"],"answer":0,"hint":"In the first, the 13 is also multiplied by 4.","explain":"4 × (250 + 13) = 1052, but 4 × 250 + 13 = 1013."},{"type":"mc","id":"m6","prompt":"Which expression matches 'I had 50 stickers, gave away 12, then shared the rest equally between 2 friends'?","choices":["(50 − 12) ÷ 2","50 − 12 ÷ 2","50 ÷ 2 − 12"],"answer":0,"hint":"The giving away happens first.","explain":"(50 − 12) ÷ 2 = 19 stickers each."},{"type":"mc","id":"m7","prompt":"Which is the same as 7 × 99?","choices":["7 × 100 − 7","7 × 100 − 1","700 − 99"],"answer":0,"hint":"99 is 100 − 1, and all 7 lots lose 1.","explain":"7 × 99 = 7 × 100 − 7 × 1 = 693."}]},"status":"self-checked","visual":{"type":"array","caption":"Drag the split to see 4 × 13 as 4 × 10 + 4 × 3.","opts":{"rows":4,"cols":13,"split":10}}},"mt_v8xr0RK1hL":{"topicId":"mt_v8xr0RK1hL","title":"Function notation","audience":"learner","keyIdea":"f(x) is the output of the rule f when the input is x.","explain":{"kid":["f(x) = 2x + 3 is a rule. The letter f is its name and x is the input. To find f(4), put 4 in place of x: 2 × 4 + 3 = 11. So f(4) = 11.","f(x) does not mean f times x. Read it as 'f of x': the output when x goes in."],"adult":["Function notation names a rule and its input. If f(x) = x² − 1, then f(3) = 9 − 1 = 8 and f(−2) = 4 − 1 = 3. The brackets after f show the input. They do not mean multiply.","You can also work backwards. If f(x) = 2x + 3 and f(a) = 11, then 2a + 3 = 11, so a = 4. In context, f(3) = 10 might mean 'after 3 hours, 10 litres are left'."]},"familyTip":"Make a function machine: write a rule like 'double it and add 3', then test each other with inputs.","practice":[{"type":"numeric","id":"p1","prompt":"f(x) = 2x + 3. Find f(4).","answer":11,"hint":"Put 4 in place of x.","explain":"f(4) = 2 × 4 + 3 = 11."},{"type":"numeric","id":"p2","prompt":"f(x) = {a}x + {b}. Find f({c}).","answer":"a*c+b","hint":"Put {c} in place of x.","explain":"f({c}) = {a} × {c} + {b} = {=a*c+b}.","params":{"a":[2,9],"b":[1,9],"c":[2,9]}},{"type":"mc","id":"p3","prompt":"What does f(5) mean?","choices":["The output when the input is 5","f multiplied by 5","The input when the output is 5"],"answer":0,"hint":"Read it as 'f of 5'.","explain":"f(5) is the output of the rule when 5 goes in."},{"type":"numeric","id":"p4","prompt":"g(x) = x² − {b}. Find g({c}).","answer":"c*c-b","hint":"Square {c} first, then subtract.","explain":"g({c}) = {c}² − {b} = {=c*c} − {b} = {=c*c-b}.","params":{"b":[1,9],"c":[2,9]},"where":"c*c>b"},{"type":"numeric","id":"p5","prompt":"f(x) = {a}x + {b} and f(k) = {=a*k+b}. Find k.","answer":"k","hint":"Solve {a}k + {b} = {=a*k+b}.","explain":"{a}k + {b} = {=a*k+b}, so {a}k = {=a*k}, so k = {k}.","params":{"a":[2,6],"b":[1,9],"k":[2,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"f(x) = {a}x − {b}. Find f({c}).","answer":"a*c-b","hint":"Put {c} in place of x.","explain":"f({c}) = {a} × {c} − {b} = {=a*c-b}.","params":{"a":[2,9],"b":[1,9],"c":[2,9]},"where":"a*c>b"},{"type":"numeric","id":"m2","prompt":"h(x) = x² + {b}. Find h(−{c}).","answer":"c*c+b","hint":"A negative times a negative is positive.","explain":"(−{c})² = {=c*c}, so h(−{c}) = {=c*c} + {b} = {=c*c+b}.","params":{"b":[1,9],"c":[1,6]}},{"type":"mc","id":"m3","prompt":"f(x) = 3x. Sam says f(2) means 'f × 2'. What is wrong?","choices":["f(2) means put 2 into the rule, so f(2) = 6","Nothing: f(2) = 2f","f(2) means 3 + 2"],"answer":0,"hint":"The brackets show the input.","explain":"f(2) is 'f of 2': 3 × 2 = 6."},{"type":"numeric","id":"m4","prompt":"f(x) = {a}x + {b}. For which x is f(x) = {=a*k+b}?","answer":"k","hint":"Set {a}x + {b} = {=a*k+b} and solve.","explain":"{a}x + {b} = {=a*k+b}, so {a}x = {=a*k}, so x = {k}.","params":{"a":[2,7],"b":[1,9],"k":[1,9]}},{"type":"mc","id":"m5","prompt":"A taxi ride costs C(m) = 3 + 2m pounds, where m is the number of miles. What does C(5) = 13 mean?","choices":["A 5-mile ride costs £13","A £5 ride goes 13 miles","5 rides cost £13"],"answer":0,"hint":"The input is miles; the output is pounds.","explain":"C(5) = 13: an input of 5 miles gives an output of £13."},{"type":"numeric","id":"m6","prompt":"f(x) = x² − 1. Find f(−2).","answer":3,"hint":"Square −2 first.","explain":"(−2)² = 4, and 4 − 1 = 3."},{"type":"mc","id":"m7","prompt":"f(x) = 2x + 1. What is f(3) + f(1)?","choices":["10","9","8"],"answer":0,"hint":"Work out f(3) and f(1) separately.","explain":"f(3) = 7 and f(1) = 3, so the sum is 10. It is not f(4) = 9: you can't just add the inputs."}]},"status":"self-checked","visual":{"type":"plot","caption":"Drag the input x along the graph of f(x) = 2x + 3 and read the output.","opts":{"mode":"eval","f":"2*x+3","a":2,"xr":[-1,5],"yr":[-1,14],"step":0.5}}},"mt_q0LJXMQe70":{"topicId":"mt_q0LJXMQe70","title":"Gradient and the equation of a line","audience":"learner","keyIdea":"A straight line is y = mx + c. The gradient m is the steepness, and c is where the line crosses the y-axis.","explain":{"kid":["Gradient tells you how steep a line is. Pick two points. Gradient = change in y ÷ change in x. From (1, 3) to (3, 7), y goes up 4 while x goes up 2. So the gradient is 4 ÷ 2 = 2.","Every straight line can be written as y = mx + c. Here m is the gradient. c is where the line crosses the y-axis. This line is y = 2x + 1."],"adult":["Gradient = (y₂ − y₁) ÷ (x₂ − x₁), or rise over run. A line going down from left to right has a negative gradient. A flat line has gradient 0.","To find the equation, work out m. Then put one point into y = mx + c to find c. Through (1, 3) with m = 2: 3 = 2 + c, so c = 1 and y = 2x + 1. In the US this is often written y = mx + b."]},"familyTip":"Find a ramp or a step. Measure how far it rises and how far it runs, then work out its gradient.","practice":[{"type":"numeric","id":"p1","prompt":"Find the gradient of the line through (1, 3) and (3, 7).","answer":2,"hint":"Rise ÷ run.","explain":"Rise 7 − 3 = 4 and run 3 − 1 = 2, so the gradient is 4 ÷ 2 = 2."},{"type":"numeric","id":"p2","prompt":"Find the gradient of the line from (0, {b}) to ({r}, {=b+m*r}).","answer":"m","hint":"Rise ÷ run.","explain":"Rise {=m*r}, run {r}, so the gradient is {=m*r} ÷ {r} = {m}.","params":{"b":[0,9],"r":[1,5],"m":[1,6]}},{"type":"mc","id":"p3","prompt":"In y = 5x − 2, what is the gradient?","choices":["5","−2","5x"],"answer":0,"hint":"Compare with y = mx + c.","explain":"m is the number in front of x, so the gradient is 5."},{"type":"numeric","id":"p4","prompt":"A line has gradient {m} and passes through (1, {=m+c}). Find c in y = mx + c.","answer":"c","hint":"Put x = 1 and y = {=m+c} into y = {m}x + c.","explain":"{=m+c} = {m} × 1 + c, so c = {c}.","params":{"m":[2,9],"c":[1,9]}},{"type":"mc","id":"p5","prompt":"Which line is steeper: y = {a}x + 1 or y = {b}x + 9?","choices":["y = {a}x + 1","y = {b}x + 9","They are equally steep"],"answer":0,"hint":"Steepness comes from m, not c.","explain":"The gradients are {a} and {b}. The +9 only moves the line up; it doesn't make it steeper.","params":{"a":[2,9],"b":[1,8]},"where":"a>b"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Find the gradient of the line through ({p}, {q}) and ({=p+r}, {=q+m*r}).","answer":"m","hint":"Rise ÷ run.","explain":"Rise {=m*r} ÷ run {r} = {m}.","params":{"p":[0,5],"q":[0,5],"r":[1,4],"m":[1,5]}},{"type":"numeric","id":"m2","prompt":"Find the gradient of the line through (0, {=q+m*r}) and ({r}, {q}).","answer":"0-m","hint":"y goes down, so the gradient is negative.","explain":"Rise {q} − {=q+m*r} = −{=m*r}, run {r}, so the gradient is −{m}.","params":{"q":[0,5],"r":[1,4],"m":[1,5]}},{"type":"mc","id":"m3","prompt":"What is the gradient of a horizontal line?","choices":["0","1","It has no gradient"],"answer":0,"hint":"How much does y change?","explain":"y doesn't change, so rise = 0 and the gradient is 0."},{"type":"numeric","id":"m4","prompt":"A line has gradient {m} and passes through ({x}, {=m*x+c}). Find c.","answer":"c","hint":"Substitute into y = {m}x + c.","explain":"{=m*x+c} = {m} × {x} + c = {=m*x} + c, so c = {c}.","params":{"m":[2,5],"x":[1,4],"c":[1,9]}},{"type":"mc","id":"m5","prompt":"Which equation is the line with gradient 3 that crosses the y-axis at −4?","choices":["y = 3x − 4","y = −4x + 3","y = 3x + 4"],"answer":0,"hint":"y = mx + c.","explain":"m = 3 and c = −4, so y = 3x − 4."},{"type":"mc","id":"m6","prompt":"Ana says the gradient from (2, 1) to (6, 9) is 4 ÷ 8 = 0.5. What went wrong?","choices":["She did run ÷ rise; it should be 8 ÷ 4 = 2","She should add, not divide","Nothing: 0.5 is right"],"answer":0,"hint":"Which goes on top?","explain":"Rise is 9 − 1 = 8 and run is 6 − 2 = 4. Gradient = rise ÷ run = 2."},{"type":"mc","id":"m7","prompt":"A line goes down from left to right. Its gradient is…","choices":["negative","positive","zero"],"answer":0,"hint":"As x increases, y decreases.","explain":"y falls as x rises, so the gradient is negative."}]},"status":"self-checked","visual":{"type":"plot","caption":"Drag the two points. The gradient is rise ÷ run.","opts":{"mode":"line","p":[1,3],"q":[3,7],"xr":[-1,6],"yr":[-2,12]}},"lab":{"type":"graphlab","caption":"Type a rule like 2*x+1, or move a and b. Make the line pass through both red targets.","opts":{"f":"a*x+b","a":1,"b":0,"xr":[-5,5],"yr":[-5,9],"targets":[[0,1],[2,5]]}}},"mt_lRy8j6tZXT":{"topicId":"mt_lRy8j6tZXT","title":"Average rate of change","audience":"learner","keyIdea":"Average rate of change = change in output ÷ change in input. On a graph it is the gradient of the straight line joining two points.","explain":{"kid":["A car travels 120 km in 2 hours. Its average speed is 120 ÷ 2 = 60 km per hour. That is an average rate of change.","On a graph, join the two points with a straight line. Its gradient is the average rate of change. It doesn't matter how the graph wiggles in between."],"adult":["For f between x = a and x = b, the average rate of change is (f(b) − f(a)) ÷ (b − a). For f(x) = x² from x = 1 to x = 3, that is (9 − 1) ÷ 2 = 4.","The units are output units per input unit, such as km per hour or pounds per year. A negative answer means the amount fell on average."]},"familyTip":"On a journey, note the time and distance twice. Work out your average speed between them.","practice":[{"type":"numeric","id":"p1","prompt":"A car travels 120 km in 2 hours. What is its average speed in km per hour?","answer":60,"hint":"Distance ÷ time.","explain":"120 ÷ 2 = 60 km per hour."},{"type":"numeric","id":"p2","prompt":"A plant is {h} cm tall on day 0 and {=h+r*d} cm tall on day {d}. What is its average growth in cm per day?","answer":"r","hint":"Change in height ÷ change in time.","explain":"It grows {=r*d} cm in {d} days: {=r*d} ÷ {d} = {r} cm per day.","params":{"h":[2,9],"r":[1,5],"d":[2,7]}},{"type":"numeric","id":"p3","prompt":"f(x) = x². Find the average rate of change from x = 1 to x = 3.","answer":4,"hint":"(f(3) − f(1)) ÷ (3 − 1).","explain":"f(3) − f(1) = 9 − 1 = 8, and 8 ÷ 2 = 4."},{"type":"numeric","id":"p4","prompt":"f(x) = x². Find the average rate of change from x = {a} to x = {b}.","answer":"a+b","hint":"(f({b}) − f({a})) ÷ ({b} − {a}).","explain":"f({b}) − f({a}) = {=b*b} − {=a*a} = {=b*b-a*a}. Divide by {=b-a} to get {=a+b}.","params":{"a":[0,6],"b":[1,8]},"where":"b>a"},{"type":"mc","id":"p5","prompt":"A tank holds 50 litres at 2 pm and 20 litres at 5 pm. What is the average rate of change?","choices":["−10 litres per hour","10 litres per hour","−30 litres per hour"],"answer":0,"hint":"Change in litres ÷ change in hours. Did it go up or down?","explain":"(20 − 50) ÷ 3 = −10 litres per hour. Negative means it emptied."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A cyclist rides {=v*t} km in {t} hours. What is her average speed in km/h?","answer":"v","hint":"Distance ÷ time.","explain":"{=v*t} ÷ {t} = {v} km/h.","params":{"v":[8,25],"t":[2,5]}},{"type":"numeric","id":"m2","prompt":"f(x) = {a}x + {b}. Find the average rate of change from x = 1 to x = 5.","answer":"a","hint":"(f(5) − f(1)) ÷ 4.","explain":"f(5) − f(1) = {=a*4}, and {=a*4} ÷ 4 = {a}. For a straight line it is always the gradient.","params":{"a":[2,9],"b":[1,9]}},{"type":"numeric","id":"m3","prompt":"f(x) = x² + {c}. Find the average rate of change from x = {a} to x = {b}.","answer":"a+b","hint":"The + {c} cancels when you subtract.","explain":"f({b}) − f({a}) = {=b*b-a*a} and {b} − {a} = {=b-a}, so {=b*b-a*a} ÷ {=b-a} = {=a+b}.","params":{"a":[0,5],"b":[1,7],"c":[1,9]},"where":"b>a"},{"type":"mc","id":"m4","prompt":"On a graph, the average rate of change between two points is…","choices":["the gradient of the straight line joining them","the height of the higher point","the area under the graph"],"answer":0,"hint":"Think rise over run.","explain":"It is the gradient of the line (chord) joining the two points."},{"type":"mc","id":"m5","prompt":"A phone cost £600 new and £360 after 3 years. What is the average rate of change of its value?","choices":["−£80 per year","£80 per year","−£240 per year"],"answer":0,"hint":"(360 − 600) ÷ 3.","explain":"(360 − 600) ÷ 3 = −240 ÷ 3 = −80. It lost £80 per year on average."},{"type":"mc","id":"m6","prompt":"A runner's average speed over a race was 4 m/s. Which must be true?","choices":["Total distance ÷ total time was 4 m/s","She ran at exactly 4 m/s all the way","Her top speed was 4 m/s"],"answer":0,"hint":"An average can hide changes.","explain":"She may have sped up and slowed down; only the overall distance ÷ time is 4 m/s."},{"type":"numeric","id":"m7","prompt":"f(x) = x². Find the average rate of change from x = 2 to x = 4.","answer":6,"hint":"(f(4) − f(2)) ÷ 2.","explain":"(16 − 4) ÷ (4 − 2) = 12 ÷ 2 = 6."}]},"status":"self-checked","visual":{"type":"rate","caption":"Drag the two points on y = x². The red line's gradient is the average rate of change.","opts":{"f":"x*x","a":1,"b":3,"xr":[-1,5],"yr":[-2,20]}},"lab":{"type":"graphlab","caption":"Make the curve pass through both targets, then work out the change in y over the change in x.","opts":{"f":"a*x^2+b*x+c","a":1,"b":0,"c":0,"xr":[-1,5],"yr":[-2,20],"targets":[[1,1],[3,9]]}}},"mt_Y5xC--f9Eh":{"topicId":"mt_Y5xC--f9Eh","title":"From average to instantaneous rate","audience":"learner","keyIdea":"Shrink the gap between two points: the average rate closes in on the rate at a single instant, the gradient of the tangent.","explain":{"kid":["A speedometer shows your speed right now, not your average. How do we find a rate at one moment? Take a second point very close to the first. Then find the average rate over that tiny gap.","For y = x² at x = 3: from 3 to 4 the rate is 7. From 3 to 3.1 it is 6.1. From 3 to 3.01 it is 6.01. These close in on 6. So the rate at x = 3 is 6."],"adult":["A line through two points on a curve is a chord. As the second point slides towards the first, the chord turns into the tangent: the line that just touches the curve there.","The gradient of the tangent is the instantaneous rate of change. For y = x², the chord from 3 to 3 + h has gradient 6 + h. As h shrinks towards 0, this gets closer to 6."]},"familyTip":"In a car, compare the speedometer with the average speed for the whole trip.","practice":[{"type":"numeric","id":"p1","prompt":"For y = x², find the average rate of change from x = 3 to x = 4.","answer":7,"hint":"(16 − 9) ÷ 1.","explain":"(16 − 9) ÷ 1 = 7."},{"type":"numeric","id":"p2","prompt":"For y = x², find the average rate of change from x = 3 to x = 3.1.","answer":6.1,"hint":"3.1² = 9.61.","explain":"(9.61 − 9) ÷ 0.1 = 0.61 ÷ 0.1 = 6.1."},{"type":"numeric","id":"p3","prompt":"For y = x², the chord from x = {a} to x = {a} + h has gradient {=2*a} + h. What does this approach as h shrinks to 0?","answer":"2*a","hint":"What is {=2*a} + 0?","explain":"As h shrinks, {=2*a} + h gets closer to {=2*a}. That is the gradient of the tangent at x = {a}.","params":{"a":[1,9]}},{"type":"mc","id":"p4","prompt":"What is a tangent to a curve?","choices":["A line that just touches the curve at a point, with the same steepness there","Any line that crosses the curve twice","A line through the origin"],"answer":0,"hint":"Think of a ruler resting on the curve.","explain":"A tangent touches the curve at a point and has the curve's steepness there."},{"type":"numeric","id":"p5","prompt":"For y = x², find the chord gradient from x = {a} to x = {=a+1}.","answer":"2*a+1","hint":"Rise ÷ run, and the run is 1.","explain":"{=(a+1)*(a+1)} − {=a*a} = {=2*a+1}, and the run is 1, so the gradient is {=2*a+1}.","params":{"a":[1,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"For y = x², the chord from x = {a} to x = {a} + h has gradient {=2*a} + h. Find it when h = 0.1.","answer":"2*a+0.1","hint":"Add 0.1.","explain":"{=2*a} + 0.1 = {=2*a+0.1}.","params":{"a":[1,9]}},{"type":"numeric","id":"m2","prompt":"Chords of y = x² near x = {a} have gradients {=2*a+1}, {=2*a+0.1}, {=2*a+0.01}, … What is the gradient at x = {a}?","answer":"2*a","hint":"What number are they closing in on?","explain":"They close in on {=2*a}.","params":{"a":[1,9]}},{"type":"mc","id":"m3","prompt":"A speedometer reads 50 km/h. This is…","choices":["an instantaneous rate of change","the average over the whole trip","the distance travelled"],"answer":0,"hint":"Is it about one moment, or the whole trip?","explain":"It shows the rate at that moment: an instantaneous rate."},{"type":"mc","id":"m4","prompt":"Why can't we use a gap of exactly 0 to find the rate at a point?","choices":["Change in y ÷ change in x would be 0 ÷ 0, which has no value","Because the answer is always 0","Because tangents don't exist"],"answer":0,"hint":"What is the run if the gap is 0?","explain":"Both changes would be 0, and 0 ÷ 0 has no value. So we let the gap shrink instead."},{"type":"mc","id":"m5","prompt":"As the second point slides towards the first, the chord…","choices":["gets closer and closer to the tangent","gets steeper and steeper for ever","turns into the x-axis"],"answer":0,"hint":"Picture it on a curve.","explain":"The chord turns until it matches the tangent at that point."},{"type":"numeric","id":"m6","prompt":"For y = x², what is the gradient of the chord from x = 1 to x = 1.5?","answer":2.5,"hint":"1.5² = 2.25.","explain":"(2.25 − 1) ÷ 0.5 = 1.25 ÷ 0.5 = 2.5."},{"type":"mc","id":"m7","prompt":"The tangent to y = x² at x = 0 is…","choices":["flat (gradient 0)","vertical","the line y = x"],"answer":0,"hint":"The chord gradient from 0 to h is h.","explain":"The chord gradient h shrinks to 0, so the tangent is flat."}]},"status":"self-checked","visual":{"type":"plot","caption":"Shrink h and watch the chord (red) turn into the tangent (purple) at x = 3.","opts":{"mode":"secant","f":"x*x","a":3,"h":1,"xr":[0,5],"yr":[-2,22]}}},"mt_P9vcHUW9CJ":{"topicId":"mt_P9vcHUW9CJ","title":"Limits: what a function approaches","audience":"learner","keyIdea":"A limit is the value f(x) gets closer to as x gets closer to a number, even if f can't be worked out exactly there.","explain":{"kid":["Look at f(x) = (x² − 1) ÷ (x − 1). At x = 1 you get 0 ÷ 0, which has no value. Now try x = 0.9, 0.99 and 0.999. You get 1.9, 1.99 and 1.999. The outputs close in on 2.","We say the limit as x tends to 1 is 2. It is about where f is heading, not what happens at the point itself."],"adult":["Often algebra shows the limit. x² − 1 = (x − 1)(x + 1), so for x ≠ 1, f(x) = x + 1. As x → 1, x + 1 → 2. We write lim (x → 1) f(x) = 2.","If f is a smooth expression that can be worked out at a, the limit is just f(a). Limits matter most when you can't substitute, as with 0 ÷ 0. That is exactly what happens when a chord shrinks to a point."]},"familyTip":"Halve a number again and again: 1, 0.5, 0.25, … What value is it heading for?","practice":[{"type":"numeric","id":"p1","prompt":"What is the limit of 2x + 1 as x tends to 3?","answer":7,"hint":"It's a smooth expression, so substitute.","explain":"2 × 3 + 1 = 7."},{"type":"numeric","id":"p2","prompt":"Find the limit of {a}x + {b} as x tends to {c}.","answer":"a*c+b","hint":"Substitute x = {c}.","explain":"{a} × {c} + {b} = {=a*c+b}.","params":{"a":[2,9],"b":[1,9],"c":[1,5]}},{"type":"mc","id":"p3","prompt":"f(x) = (x² − 1) ÷ (x − 1) gives 1.9, 1.99, 1.999 at x = 0.9, 0.99, 0.999. What is the limit as x → 1?","choices":["2","1.999","There is no limit, because f(1) is 0 ÷ 0"],"answer":0,"hint":"Where are the outputs heading?","explain":"They close in on 2. f(1) having no value doesn't stop the limit existing."},{"type":"numeric","id":"p4","prompt":"For x ≠ {a}, (x² − {=a*a}) ÷ (x − {a}) = x + {a}. Find the limit as x → {a}.","answer":"2*a","hint":"Substitute into x + {a}.","explain":"x + {a} → {a} + {a} = {=2*a}.","params":{"a":[2,9]}},{"type":"numeric","id":"p5","prompt":"Find the limit of x² + {b} as x tends to {c}.","answer":"c*c+b","hint":"Substitute x = {c}.","explain":"{c}² + {b} = {=c*c} + {b} = {=c*c+b}.","params":{"b":[1,9],"c":[1,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Find the limit of {a}x − {b} as x → {c}.","answer":"a*c-b","hint":"Substitute.","explain":"{a} × {c} − {b} = {=a*c-b}.","params":{"a":[2,9],"b":[1,9],"c":[1,5]},"where":"a*c>b"},{"type":"numeric","id":"m2","prompt":"Simplify, then find the limit as x → {a}: (x² − {=a*a}) ÷ (x − {a}).","answer":"2*a","hint":"Factorise the top as a difference of two squares.","explain":"x² − {=a*a} = (x − {a})(x + {a}), so the expression is x + {a}, which tends to {=2*a}.","params":{"a":[2,9]}},{"type":"mc","id":"m3","prompt":"f(1.9) = 4.9, f(1.99) = 4.99, f(2.01) = 5.01 and f(2.1) = 5.1. What is the likely limit as x → 2?","choices":["5","4.99","5.1"],"answer":0,"hint":"Look from both sides.","explain":"From below and above the outputs close in on 5."},{"type":"mc","id":"m4","prompt":"Which statement is true?","choices":["A limit can exist where the function has no value","A limit always equals f(a)","If f(a) is 0 ÷ 0, the limit is 0"],"answer":0,"hint":"Think of (x² − 1) ÷ (x − 1) at x = 1.","explain":"That function has no value at 1, but its limit there is 2."},{"type":"numeric","id":"m5","prompt":"Find the limit of (x² − 9) ÷ (x − 3) as x → 3.","answer":6,"hint":"x² − 9 = (x − 3)(x + 3).","explain":"It simplifies to x + 3, which tends to 6."},{"type":"mc","id":"m6","prompt":"What does lim (x → 4) f(x) = 10 mean?","choices":["As x gets closer to 4, f(x) gets closer to 10","f(10) = 4","f(x) is never more than 10"],"answer":0,"hint":"Read it aloud: the limit as x tends to 4.","explain":"As x approaches 4, the outputs approach 10."},{"type":"numeric","id":"m7","prompt":"Find the limit of ({a}x² + {b}x) ÷ x as x → 0.","answer":"b","hint":"Divide each term by x first.","explain":"For x ≠ 0 it is {a}x + {b}, which tends to {b}.","params":{"a":[2,9],"b":[1,9]}}]},"status":"self-checked","visual":{"type":"plot","caption":"f(x) = (x² − 1) ÷ (x − 1) has a hole at x = 1. Move x closer and watch f(x).","opts":{"mode":"limit","f":"(x*x-1)/(x-1)","a":1,"start":0.5,"xr":[-1,3],"yr":[-1,5]}}},"mt_a-yA19-IoO":{"topicId":"mt_a-yA19-IoO","title":"The derivative from first principles","audience":"learner","keyIdea":"The derivative is the limit of the chord gradient (f(x + h) − f(x)) ÷ h as h tends to 0.","explain":{"kid":["To find the gradient of a curve at a point, take a chord to a point a tiny step h further along. Its gradient is (f(x + h) − f(x)) ÷ h. Then let h shrink to 0.","For f(x) = x², f(x + h) = x² + 2xh + h². Take away x² to get 2xh + h². Divide by h to get 2x + h. As h → 0 this becomes 2x. So the gradient of y = x² at any point is 2x."],"adult":["This is called differentiating from first principles. The derivative is f′(x) = lim (h → 0) of (f(x + h) − f(x)) ÷ h.","The key step is to expand and simplify before letting h → 0, so that you never divide by zero. For f(x) = 3x²: (3(x + h)² − 3x²) ÷ h = 6x + 3h, which tends to 6x."]},"familyTip":"Draw y = x² carefully. Measure the steepness at x = 1 and x = 2, and compare with 2x.","practice":[{"type":"mc","id":"p1","prompt":"In (f(x + h) − f(x)) ÷ h, what does h stand for?","choices":["A small step along the x-axis","The height of the curve","The gradient"],"answer":0,"hint":"It's the run of the chord.","explain":"h is the small step in x between the two points."},{"type":"numeric","id":"p2","prompt":"For f(x) = x², the gradient at any point is 2x. What is the gradient at x = {a}?","answer":"2*a","hint":"Double it.","explain":"2 × {a} = {=2*a}.","params":{"a":[1,12]}},{"type":"mc","id":"p3","prompt":"For f(x) = x², (f(x + h) − f(x)) ÷ h simplifies to…","choices":["2x + h","2x","x² + h"],"answer":0,"hint":"Expand (x + h)² first.","explain":"(x² + 2xh + h² − x²) ÷ h = (2xh + h²) ÷ h = 2x + h. Only then do we let h → 0."},{"type":"numeric","id":"p4","prompt":"For f(x) = {a}x², the chord gradient simplifies to {=2*a}x + {a}h. What is the gradient at x = {c}?","answer":"2*a*c","hint":"Let h → 0, then substitute.","explain":"As h → 0 it becomes {=2*a}x. At x = {c}: {=2*a} × {c} = {=2*a*c}.","params":{"a":[2,6],"c":[1,6]}},{"type":"numeric","id":"p5","prompt":"For f(x) = x² + {b}x, the chord gradient is 2x + {b} + h. What is the gradient at x = {c}?","answer":"2*c+b","hint":"Let h → 0 first.","explain":"As h → 0 it becomes 2x + {b}. At x = {c}: {=2*c} + {b} = {=2*c+b}.","params":{"b":[1,9],"c":[1,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"f(x) = x² has derivative 2x. Find the gradient at x = −{a}.","answer":"0-2*a","hint":"Double a negative number.","explain":"2 × (−{a}) = −{=2*a}.","params":{"a":[1,9]}},{"type":"mc","id":"m2","prompt":"Why do we simplify before letting h → 0?","choices":["To cancel h first, so we never divide by 0","Because h is always 1","To make the answer bigger"],"answer":0,"hint":"What would h = 0 do to ÷ h?","explain":"Cancelling h first avoids dividing by zero."},{"type":"mc","id":"m3","prompt":"Expand (x + h)².","choices":["x² + 2xh + h²","x² + h²","x² + xh + h²"],"answer":0,"hint":"(x + h)(x + h).","explain":"x² + xh + xh + h² = x² + 2xh + h². Forgetting the middle term is a common mistake."},{"type":"numeric","id":"m4","prompt":"For f(x) = {a}x, simplify the chord gradient ({a}(x + h) − {a}x) ÷ h.","answer":"a","hint":"Expand the bracket.","explain":"{a}x + {a}h − {a}x = {a}h, and {a}h ÷ h = {a}. A straight line has the same gradient everywhere.","params":{"a":[2,12]}},{"type":"numeric","id":"m5","prompt":"f(x) = {a}x² has derivative {=2*a}x. Find the gradient at x = {c}.","answer":"2*a*c","hint":"Substitute x = {c}.","explain":"{=2*a} × {c} = {=2*a*c}.","params":{"a":[2,6],"c":[1,6]}},{"type":"mc","id":"m6","prompt":"lim (h → 0) of (f(x + h) − f(x)) ÷ h is the gradient of…","choices":["the tangent at x","the chord from 0 to x","the x-axis"],"answer":0,"hint":"A chord with zero width.","explain":"As the chord shrinks it becomes the tangent at x."},{"type":"mc","id":"m7","prompt":"For f(x) = x³, f(x + h) = x³ + 3x²h + 3xh² + h³. What is the derivative?","choices":["3x²","3x² + 3xh + h²","x³"],"answer":0,"hint":"Subtract x³, divide by h, then let h → 0.","explain":"You get 3x² + 3xh + h², which tends to 3x² as h → 0."}]},"status":"self-checked","visual":{"type":"plot","caption":"First principles on y = x²: the chord gradient (f(1 + h) − f(1)) ÷ h as h → 0.","opts":{"mode":"secant","f":"x*x","a":1,"h":2,"xr":[-1,4],"yr":[-2,12]}}},"mt_h07IxxUQwx":{"topicId":"mt_h07IxxUQwx","title":"Derivative notation","audience":"learner","keyIdea":"f′(x) and dy/dx both mean the derivative: the gradient function.","explain":{"kid":["There are two common ways to write the derivative. If y = f(x), we can write f′(x), said 'f dash x' (or 'f prime x'). Or we can write dy/dx, said 'dee y by dee x'.","dy/dx is not a fraction you can cancel. It means the rate of change of y as x changes. If y = x², then dy/dx = 2x. At x = 3, dy/dx = 6."],"adult":["Leibniz's dy/dx reminds you of 'change in y over change in x'. Lagrange's f′(x) is shorter when a function has a name. Both describe the gradient function.","Other letters work too. If distance s depends on time t, then ds/dt is how fast distance changes: the velocity. f′(3) means the gradient at x = 3, not 3 times f′."]},"familyTip":"Spot rates in daily life (litres per minute, pounds per hour) and write each one as d(something)/d(something).","practice":[{"type":"mc","id":"p1","prompt":"How is f′(x) usually read?","choices":["f dash x (or f prime x)","f times x","f to the power x"],"answer":0,"hint":"The mark is a dash.","explain":"f′(x) is read 'f dash x' in the UK and 'f prime of x' in the US."},{"type":"numeric","id":"p2","prompt":"f′(x) = 2x. Find f′({a}).","answer":"2*a","hint":"Put {a} into f′.","explain":"f′({a}) = 2 × {a} = {=2*a}.","params":{"a":[1,12]}},{"type":"mc","id":"p3","prompt":"What does dy/dx mean?","choices":["The rate of change of y as x changes","d × y ÷ (d × x)","y divided by x"],"answer":0,"hint":"It's notation, not a fraction to cancel.","explain":"dy/dx is the rate of change of y with respect to x. You can't cancel the d's."},{"type":"numeric","id":"p4","prompt":"dy/dx = {a}x + {b}. Find the gradient when x = {c}.","answer":"a*c+b","hint":"Substitute x = {c}.","explain":"{a} × {c} + {b} = {=a*c+b}.","params":{"a":[2,9],"b":[1,9],"c":[1,5]}},{"type":"mc","id":"p5","prompt":"s is distance and t is time. What is ds/dt?","choices":["Velocity: how fast distance changes","Distance × time","The total distance"],"answer":0,"hint":"Rate of change of s with respect to t.","explain":"ds/dt is the rate of change of distance: the velocity."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"f′(x) = {a}x². Find f′({c}).","answer":"a*c*c","hint":"Square {c}, then multiply.","explain":"{a} × {c}² = {a} × {=c*c} = {=a*c*c}.","params":{"a":[2,6],"c":[1,5]}},{"type":"mc","id":"m2","prompt":"Sam writes f′(3) = 3f′. What is wrong?","choices":["f′(3) means the gradient at x = 3, not 3 times anything","Nothing","It should be f(3)′"],"answer":0,"hint":"Brackets show the input.","explain":"f′(3) is the gradient function evaluated at x = 3."},{"type":"mc","id":"m3","prompt":"For y = f(x), which pair mean the same thing?","choices":["dy/dx and f′(x)","dy/dx and y ÷ x","f′(x) and f(x)"],"answer":0,"hint":"Both are names for the gradient function.","explain":"dy/dx and f′(x) both mean the derivative."},{"type":"numeric","id":"m4","prompt":"V is volume in litres and t is time in minutes. dV/dt = {r} and stays the same. How many litres flow in during 3 minutes?","answer":"3*r","hint":"Rate × time.","explain":"{r} litres per minute × 3 minutes = {=3*r} litres.","params":{"r":[2,12]}},{"type":"mc","id":"m5","prompt":"If dy/dx = 0 at a point, the graph there is…","choices":["flat (horizontal tangent)","vertical","crossing the x-axis"],"answer":0,"hint":"A gradient of 0.","explain":"Zero gradient means the tangent is horizontal."},{"type":"mc","id":"m6","prompt":"If dy/dx is negative at a point, then…","choices":["y is decreasing as x increases","y is negative","x is negative"],"answer":0,"hint":"dy/dx describes the slope, not the value.","explain":"A negative gradient means the graph goes down there. y itself could be positive."},{"type":"numeric","id":"m7","prompt":"dy/dx = 3x² − {b}. Find dy/dx at x = {c}.","answer":"3*c*c-b","hint":"Square first, then multiply by 3.","explain":"3 × {=c*c} − {b} = {=3*c*c} − {b} = {=3*c*c-b}.","params":{"b":[1,9],"c":[1,4]},"where":"3*c*c>b"}]},"status":"self-checked","visual":{"type":"plot","caption":"Drag the point on y = x². dy/dx is the gradient of the tangent there.","opts":{"mode":"tangent","f":"x*x","a":1.5,"xr":[-3,3],"yr":[-2,9],"step":0.5}}},"mt_lt75XjH3E2":{"topicId":"mt_lt75XjH3E2","title":"Differentiating powers of x (the power rule)","audience":"learner","keyIdea":"To differentiate xⁿ, multiply by the power and then take one off the power: xⁿ becomes nxⁿ⁻¹.","explain":{"kid":["First principles always works, but it is slow. There is a short cut called the power rule. Multiply by the power, then take one off the power.","So x² becomes 2x, x³ becomes 3x², and x⁵ becomes 5x⁴. A plain x is x¹, so it becomes 1. A number on its own, like 7, has gradient 0."],"adult":["The power rule works for any power, including negative and fractional ones. Rewrite first: 1/x = x⁻¹, so its derivative is −x⁻², which is −1/x².","Likewise √x is x to the power ½, which gives ½ × x to the power −½, or 1/(2√x). That's why the laws of indices (exponents) matter here. Write each term as a power of x before you use the rule."]},"familyTip":"Make flashcards: a power of x on one side, its derivative on the other. Test each other.","practice":[{"type":"mc","id":"p1","prompt":"Differentiate x⁵.","choices":["5x⁴","5x⁵","x⁴"],"answer":0,"hint":"Multiply by the power, then take one off.","explain":"5 × x⁴ = 5x⁴."},{"type":"numeric","id":"p2","prompt":"y = {a}x³. Find dy/dx at x = {c}.","answer":"3*a*c*c","hint":"dy/dx = {=3*a}x².","explain":"dy/dx = {=3*a}x². At x = {c}: {=3*a} × {=c*c} = {=3*a*c*c}.","params":{"a":[1,5],"c":[1,4]}},{"type":"mc","id":"p3","prompt":"Differentiate 7.","choices":["0","7","7x"],"answer":0,"hint":"y = 7 is a flat line.","explain":"A flat line has gradient 0."},{"type":"numeric","id":"p4","prompt":"y = {a}x². Find the gradient at x = {c}.","answer":"2*a*c","hint":"dy/dx = {=2*a}x.","explain":"dy/dx = {=2*a}x, so at x = {c} it is {=2*a*c}.","params":{"a":[2,9],"c":[1,6]}},{"type":"mc","id":"p5","prompt":"Differentiate 1/x.","choices":["−x⁻²","x⁻²","−x⁻¹"],"answer":0,"hint":"Write 1/x as x⁻¹ first.","explain":"1/x = x⁻¹. Multiply by −1 and take one off the power: −x⁻². A common slip is to go from −1 to 0 instead of −2."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"f(x) = x⁴. Find f′({c}).","answer":"4*c*c*c","hint":"f′(x) = 4x³.","explain":"f′(x) = 4x³, so f′({c}) = 4 × {=c*c*c} = {=4*c*c*c}.","params":{"c":[1,5]}},{"type":"numeric","id":"m2","prompt":"y = {a}x⁴. Find dy/dx when x = {c}.","answer":"4*a*c*c*c","hint":"dy/dx = {=4*a}x³.","explain":"dy/dx = {=4*a}x³. At x = {c}: {=4*a} × {=c*c*c} = {=4*a*c*c*c}.","params":{"a":[1,4],"c":[1,3]}},{"type":"mc","id":"m3","prompt":"Differentiate x³.","choices":["3x²","3x³","x²"],"answer":0,"hint":"Multiply by 3, take one off the power.","explain":"3 × x² = 3x²."},{"type":"mc","id":"m4","prompt":"Differentiate √x.","choices":["1/(2√x)","2√x","½√x"],"answer":0,"hint":"√x is x to the power ½.","explain":"Multiply by ½ and take one off the power to get −½: ½ × x to the power −½ = 1/(2√x)."},{"type":"mc","id":"m5","prompt":"Differentiate x.","choices":["1","x","0"],"answer":0,"hint":"x is x¹.","explain":"1 × x⁰ = 1. The line y = x has gradient 1."},{"type":"mc","id":"m6","prompt":"Jo differentiates x⁻³ and gets −3x⁻². What went wrong?","choices":["One less than −3 is −4, so it should be −3x⁻⁴","It should be 3x⁻²","Nothing"],"answer":0,"hint":"Take one off −3.","explain":"−3 − 1 = −4, so the answer is −3x⁻⁴."},{"type":"numeric","id":"m7","prompt":"y = {a}x². At which x is the gradient {=2*a*k}?","answer":"k","hint":"dy/dx = {=2*a}x.","explain":"{=2*a}x = {=2*a*k}, so x = {k}.","params":{"a":[2,6],"k":[1,6]}}]},"status":"self-checked","visual":{"type":"power","caption":"Change the power n. The gradient graph is always n × x to the power (n − 1).","opts":{"n":3}}},"mt_jRXV4nBsz_":{"topicId":"mt_jRXV4nBsz_","title":"Differentiating sums and multiples","audience":"learner","keyIdea":"Differentiate term by term. A number multiplying a term stays; a number on its own disappears.","explain":{"kid":["You can differentiate a sum one term at a time. For y = x³ + x², dy/dx = 3x² + 2x.","A number in front stays in front, so 5x² becomes 5 × 2x = 10x. A number on its own, like + 4, becomes 0. So y = 5x² + 3x + 4 gives dy/dx = 10x + 3."],"adult":["In symbols, the derivative of af + bg is af′ + bg′. This is what lets you differentiate any polynomial quickly.","Products are different. The derivative of x²(x + 1) is not 2x × 1. Expand it first to x³ + x², then differentiate to get 3x² + 2x."]},"familyTip":"Write a polynomial, swap with a friend, differentiate each other's, then check together.","practice":[{"type":"numeric","id":"p1","prompt":"y = {a}x² + {b}x + {c}. Find dy/dx at x = 1.","answer":"2*a+b","hint":"dy/dx = {=2*a}x + {b}.","explain":"dy/dx = {=2*a}x + {b}. At x = 1: {=2*a} + {b} = {=2*a+b}.","params":{"a":[1,6],"b":[1,9],"c":[1,9]}},{"type":"mc","id":"p2","prompt":"Differentiate 5x² + 3x + 4.","choices":["10x + 3","10x + 7","5x + 3"],"answer":0,"hint":"What happens to the + 4?","explain":"10x + 3. The constant 4 has gradient 0, so it disappears."},{"type":"numeric","id":"p3","prompt":"y = x³ + {b}x. Find the gradient at x = {c}.","answer":"3*c*c+b","hint":"dy/dx = 3x² + {b}.","explain":"dy/dx = 3x² + {b}. At x = {c}: {=3*c*c} + {b} = {=3*c*c+b}.","params":{"b":[1,9],"c":[1,4]}},{"type":"mc","id":"p4","prompt":"Differentiate x²(x + 1).","choices":["3x² + 2x","2x","2x(x + 1)"],"answer":0,"hint":"Expand first.","explain":"x²(x + 1) = x³ + x², so the derivative is 3x² + 2x. You can't just multiply the derivatives."},{"type":"numeric","id":"p5","prompt":"f(x) = {a}x² − {b}x. Find f′({c}).","answer":"2*a*c-b","hint":"f′(x) = {=2*a}x − {b}.","explain":"f′(x) = {=2*a}x − {b}, so f′({c}) = {=2*a*c} − {b} = {=2*a*c-b}.","params":{"a":[1,6],"b":[1,9],"c":[1,5]},"where":"2*a*c>b"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"y = {a}x³ + {b}. Find dy/dx at x = {c}.","answer":"3*a*c*c","hint":"The + {b} disappears.","explain":"dy/dx = {=3*a}x², so at x = {c} it is {=3*a*c*c}.","params":{"a":[1,4],"b":[1,9],"c":[1,3]}},{"type":"numeric","id":"m2","prompt":"f(x) = x² + {b}x + {c}. Find f′({d}).","answer":"2*d+b","hint":"f′(x) = 2x + {b}.","explain":"f′(x) = 2x + {b}, so f′({d}) = {=2*d} + {b} = {=2*d+b}.","params":{"b":[1,9],"c":[1,9],"d":[1,6]}},{"type":"mc","id":"m3","prompt":"What is the derivative of a constant, such as 12?","choices":["0","12","1"],"answer":0,"hint":"y = 12 is flat.","explain":"A flat line has gradient 0."},{"type":"mc","id":"m4","prompt":"Differentiate 4x³ − 2x.","choices":["12x² − 2","12x² − 2x","4x² − 2"],"answer":0,"hint":"Term by term.","explain":"4 × 3x² = 12x² and −2x becomes −2."},{"type":"mc","id":"m5","prompt":"Differentiate (x + 2)².","choices":["2x + 4","2x + 2","2(x + 2)²"],"answer":0,"hint":"Expand first.","explain":"(x + 2)² = x² + 4x + 4, so the derivative is 2x + 4."},{"type":"numeric","id":"m6","prompt":"f(x) = x² − {=2*k}x. At what x is the gradient 0?","answer":"k","hint":"f′(x) = 2x − {=2*k}.","explain":"2x − {=2*k} = 0, so x = {k}.","params":{"k":[1,9]}},{"type":"mc","id":"m7","prompt":"f(x) = 3x² + 5. Which is correct?","choices":["f′(x) = 6x","f′(x) = 6x + 5","f′(x) = 3x"],"answer":0,"hint":"What happens to the 5?","explain":"3 × 2x = 6x, and the constant 5 disappears."}]},"status":"self-checked","visual":{"type":"plot","caption":"y = x² + 2x: drag the point. dy/dx = 2x + 2, term by term.","opts":{"mode":"tangent","f":"x*x+2*x","a":1,"xr":[-4,2],"yr":[-2,8],"step":0.5}}},"mt_vqlq_sKWKm":{"topicId":"mt_vqlq_sKWKm","title":"Equations of tangents and normals","audience":"learner","keyIdea":"The tangent at x = a has gradient f′(a) and passes through (a, f(a)). The normal is perpendicular to it.","explain":{"kid":["To find the tangent to a curve at a point, you need a gradient and a point. The derivative gives the gradient. The curve gives the point.","For y = x² at x = 3, the point is (3, 9). dy/dx = 2x, so the gradient is 6. Then 9 = 6 × 3 + c gives c = −9. So the tangent is y = 6x − 9."],"adult":["Use y − y₁ = m(x − x₁), with m = f′(a) and the point (a, f(a)). Rearrange into y = mx + c if needed.","The normal is the line at right angles to the tangent at the same point. Its gradient is −1 ÷ m, because perpendicular gradients multiply to −1. For y = x² at (3, 9), the normal has gradient −1/6."]},"familyTip":"Plot y = x² on graph paper. Draw your tangent at x = 3 and check that it just touches the curve.","practice":[{"type":"numeric","id":"p1","prompt":"The tangent to y = x² at x = 3 is y = 6x + c. Find c.","answer":-9,"hint":"The point is (3, 9).","explain":"9 = 6 × 3 + c = 18 + c, so c = −9."},{"type":"numeric","id":"p2","prompt":"Find the gradient of the tangent to y = x² at x = {a}.","answer":"2*a","hint":"dy/dx = 2x.","explain":"dy/dx = 2x, so at x = {a} the gradient is {=2*a}.","params":{"a":[1,12]}},{"type":"numeric","id":"p3","prompt":"The tangent to y = x² at x = {a} is y = {=2*a}x + c. Find c.","answer":"0-a*a","hint":"The point is ({a}, {=a*a}).","explain":"{=a*a} = {=2*a} × {a} + c = {=2*a*a} + c, so c = −{=a*a}.","params":{"a":[1,9]}},{"type":"mc","id":"p4","prompt":"A tangent has gradient 2. What is the gradient of the normal at the same point?","choices":["−1/2","1/2","−2"],"answer":0,"hint":"Perpendicular gradients multiply to −1.","explain":"2 × (−1/2) = −1, so the normal's gradient is −1/2."},{"type":"mc","id":"p5","prompt":"To find the tangent at x = a, which two things do you need?","choices":["The gradient f′(a) and the point (a, f(a))","Only f(a)","The gradient f(a) and the point (a, f′(a))"],"answer":0,"hint":"A line needs a gradient and a point.","explain":"The gradient comes from f′(a); the point is (a, f(a))."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Find the gradient of the tangent to y = x³ at x = {a}.","answer":"3*a*a","hint":"dy/dx = 3x².","explain":"3 × {=a*a} = {=3*a*a}.","params":{"a":[1,6]}},{"type":"numeric","id":"m2","prompt":"The tangent to y = x² + {b} at x = {a} is y = {=2*a}x + c. Find c.","answer":"b-a*a","hint":"The point is ({a}, {=a*a+b}).","explain":"{=a*a+b} = {=2*a*a} + c, so c = {=b-a*a}.","params":{"a":[1,6],"b":[1,9]}},{"type":"mc","id":"m3","prompt":"Which is the tangent to y = x² at (1, 1)?","choices":["y = 2x − 1","y = 2x + 1","y = x"],"answer":0,"hint":"Gradient 2x = 2, then find c.","explain":"1 = 2 × 1 + c, so c = −1: y = 2x − 1."},{"type":"numeric","id":"m4","prompt":"A tangent has gradient {m}. What is the gradient of the normal, as a decimal?","answer":"0-1/m","hint":"−1 ÷ {m}.","explain":"−1 ÷ {m} = {=0-1/m}.","params":{"m":[1,20]},"where":"100%m==0"},{"type":"mc","id":"m5","prompt":"The normal to a curve at a point is…","choices":["perpendicular to the tangent there","parallel to the tangent","always the x-axis"],"answer":0,"hint":"Normal means at right angles.","explain":"It meets the tangent at a right angle."},{"type":"mc","id":"m6","prompt":"Ben finds the tangent to y = x² at x = 2 and writes y = 2x. What went wrong?","choices":["He used 2 as the gradient; it's 2 × 2 = 4, giving y = 4x − 4","Nothing","He forgot to square 2"],"answer":0,"hint":"Work out dy/dx at x = 2.","explain":"The gradient is 4 and the point is (2, 4), so 4 = 8 + c and c = −4."},{"type":"numeric","id":"m7","prompt":"What is the gradient of the tangent to y = x² − 4x at x = 3?","answer":2,"hint":"dy/dx = 2x − 4.","explain":"2 × 3 − 4 = 6 − 4 = 2."}]},"status":"self-checked","visual":{"type":"plot","caption":"Tangent (purple) and normal (green) to y = x² at a point you choose. Equal scales, so the right angle looks right.","opts":{"mode":"tangent","f":"x*x","a":1,"normal":true,"xr":[-2.5,3],"yr":[-1,4],"step":0.5,"equal":true}}},"mt_ylruY6VhOf":{"topicId":"mt_ylruY6VhOf","title":"Matter is made of particles","audience":"learner","keyIdea":"Everything is made of tiny particles. How they are arranged and how they move explains solids, liquids and gases.","explain":{"kid":["All matter is made of particles that are far too small to see. In a solid, the particles are packed tightly in a fixed pattern and can only vibrate. In a liquid, they are close together but can slide past each other. In a gas, they are far apart and move fast in all directions.","This explains what we see. A solid keeps its shape. A liquid takes the shape of its container. A gas spreads out to fill any space."],"adult":["The particle model explains properties we can see. Gases can be squashed because there is empty space between the particles. Solids and liquids hardly squash at all, because their particles are already touching.","Heating gives particles more energy, so they vibrate or move faster. That's why heating can melt a solid or boil a liquid. The particles themselves do not get bigger or melt."]},"familyTip":"Fill a syringe (with no needle) with air, block the end with your finger and push. Then try it with water.","practice":[{"type":"mc","id":"p1","prompt":"In which state are the particles far apart and moving fast in all directions?","choices":["Gas","Liquid","Solid"],"answer":0,"hint":"Which state spreads out to fill a room?","explain":"In a gas the particles are far apart and move quickly."},{"type":"mc","id":"p2","prompt":"A substance melts at {m} °C and boils at {b} °C. What state is it in at {t} °C?","choices":["Liquid, because {t} °C is between its melting and boiling points","Solid, because {t} °C is below its boiling point","Gas, because {t} °C is above its melting point"],"answer":0,"hint":"Is {t} °C above the melting point? Is it below the boiling point?","explain":"{t} °C is above {m} °C (so it has melted) and below {b} °C (so it hasn't boiled). It is a liquid.","params":{"m":[10,30],"b":[80,100],"t":[40,60]}},{"type":"mc","id":"p3","prompt":"Why can a gas be squashed but a solid can't?","choices":["Gas particles have big spaces between them","Gas particles are smaller","Solid particles are glued together"],"answer":0,"hint":"Think about spacing.","explain":"There is space between gas particles to push them into. Solid particles are already touching."},{"type":"mc","id":"p4","prompt":"When ice melts, what happens to its particles?","choices":["They gain energy and start to slide past each other","They melt into smaller particles","They get bigger"],"answer":0,"hint":"The particles themselves don't change.","explain":"The particles gain energy and break out of their fixed pattern. They are still the same particles."},{"type":"numeric","id":"p5","prompt":"A sealed syringe holds {v} cm³ of air. You push the plunger until the air takes up half the space. What is the new volume in cm³?","answer":"v/2","hint":"Halve {v}.","explain":"Half of {v} is {=v/2} cm³. The same particles are just pushed closer together.","params":{"v":[10,50]},"where":"v%2==0"}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Oxygen melts at −218 °C and boils at −183 °C. What state is oxygen in at {t} °C?","choices":["Gas","Liquid","Solid"],"answer":0,"hint":"Compare {t} °C with its boiling point.","explain":"{t} °C is far above oxygen's boiling point of −183 °C, so it is a gas.","params":{"t":[0,30]}},{"type":"mc","id":"m2","prompt":"A metal melts at {m} °C. What state is it in at {t} °C?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Is it hot enough to melt?","explain":"{t} °C is below its melting point of {m} °C, so it is still solid.","params":{"m":[300,320],"t":[20,40]}},{"type":"mc","id":"m3","prompt":"Which state keeps its own shape?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Which particles are fixed in place?","explain":"Solid particles are held in a fixed pattern, so a solid keeps its shape."},{"type":"mc","id":"m4","prompt":"A smell spreads across a room. Why?","choices":["Gas particles move around and spread out","Smells are not made of particles","Only warm air can carry smells"],"answer":0,"hint":"Gas particles move in all directions.","explain":"The smell's gas particles move and mix with the air particles until they spread out."},{"type":"mc","id":"m5","prompt":"What is between the particles in a gas?","choices":["Empty space","Air","Water"],"answer":0,"hint":"Air is itself made of particles.","explain":"Nothing: there is empty space. Air can't be between them, because air is made of particles too."},{"type":"mc","id":"m6","prompt":"Ice and liquid water are made of the same particles. What is different?","choices":["How the particles are arranged and move","The size of the particles","What the particles are made of"],"answer":0,"hint":"Same particles, different state.","explain":"Only the arrangement and movement change; the particles are the same."},{"type":"mc","id":"m7","prompt":"When you heat a gas in a sealed box, its particles…","choices":["move faster","get bigger","turn into a liquid"],"answer":0,"hint":"Heating gives particles energy.","explain":"More energy means faster particles. They don't grow."}]},"status":"self-checked","visual":{"type":"particles","caption":"Heat and cool the water. Watch the particles' arrangement and speed.","opts":{"mp":0,"bp":100,"temp":20,"name":"water"}},"lab":{"type":"gaslab","caption":"Real moving particles: heat them, squeeze the box or add more. Watch them collide and the pressure change.","opts":{"n":30,"temp":300,"vol":1}}},"mt_b6kZgqolEd":{"topicId":"mt_b6kZgqolEd","title":"The particle model and density","audience":"learner","keyIdea":"The arrangement, movement and spacing of particles explain density, squashing, flowing and changes of state.","explain":{"kid":["The particle model explains things using particles. In a solid, particles are close and fixed. In a liquid they are close but move around. In a gas they are spread out.","Density is how much mass is packed into a space. Most solids are dense, because their particles are packed closely. Gases have a low density, because their particles are far apart."],"adult":["Density = mass ÷ volume, often in g/cm³. A 20 cm³ block with a mass of 54 g has a density of 54 ÷ 20 = 2.7 g/cm³. A change of state changes the spacing, so it changes the density. The mass stays the same.","Every model has limits. Real particles are not hard little balls. Simple diagrams also leave out the forces between them. Even so, the model predicts a lot."]},"familyTip":"Weigh a full glass of water, then work out its density using the volume printed on a measuring jug.","practice":[{"type":"numeric","id":"p1","prompt":"A block has a mass of 54 g and a volume of 20 cm³. What is its density in g/cm³?","answer":2.7,"hint":"Mass ÷ volume.","explain":"54 ÷ 20 = 2.7 g/cm³."},{"type":"numeric","id":"p2","prompt":"An object has a mass of {=d*v} g and a volume of {v} cm³. What is its density in g/cm³?","answer":"d","hint":"Mass ÷ volume.","explain":"{=d*v} ÷ {v} = {d} g/cm³.","params":{"d":[2,9],"v":[2,15]}},{"type":"mc","id":"p3","prompt":"Why is steam much less dense than liquid water?","choices":["The same particles are much more spread out","Steam particles are lighter","Steam has no mass"],"answer":0,"hint":"Same particles, different spacing.","explain":"The particles are identical, but in steam they are far apart, so less mass fits in each cm³."},{"type":"numeric","id":"p4","prompt":"A liquid has a density of {d} g/cm³. What is the mass of {v} cm³ of it, in g?","answer":"d*v","hint":"Mass = density × volume.","explain":"{d} × {v} = {=d*v} g.","params":{"d":[1,3],"v":[10,50]}},{"type":"mc","id":"p5","prompt":"When water boils, what is overcome?","choices":["The forces between water particles","The bonds inside each water particle","Nothing: the particles just get bigger"],"answer":0,"hint":"Boiling doesn't make a new substance.","explain":"Boiling overcomes the forces between particles. Each water particle stays whole."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A stone has a mass of {=d*v} g and a volume of {v} cm³. Find its density in g/cm³.","answer":"d","hint":"Mass ÷ volume.","explain":"{=d*v} ÷ {v} = {d} g/cm³.","params":{"d":[2,8],"v":[3,12]}},{"type":"numeric","id":"m2","prompt":"A metal has a density of {d} g/cm³. What is the mass of {v} cm³ of it, in g?","answer":"d*v","hint":"Density × volume.","explain":"{d} × {v} = {=d*v} g.","params":{"d":[2,11],"v":[2,10]}},{"type":"mc","id":"m3","prompt":"Which is best explained by particles being far apart?","choices":["Gases are easy to squash","Solids keep their shape","Liquids are hard to squash"],"answer":0,"hint":"Squashing needs space.","explain":"Gases squash because there is space between their particles."},{"type":"mc","id":"m4","prompt":"100 g of ice melts. What is the mass of the water?","choices":["100 g","Less than 100 g","More than 100 g"],"answer":0,"hint":"Are any particles lost?","explain":"Still 100 g. The same particles are just arranged differently."},{"type":"mc","id":"m5","prompt":"Which is a limit of the simple particle model?","choices":["It shows particles as hard balls, which they are not","It can't explain melting","It says gases have no particles"],"answer":0,"hint":"What do the diagrams leave out?","explain":"Real particles aren't hard spheres, and the diagrams don't show the forces between them."},{"type":"mc","id":"m6","prompt":"The gas in a balloon is cooled. Its particles…","choices":["slow down, and the balloon shrinks","shrink in size","stop moving completely"],"answer":0,"hint":"Less energy means less movement.","explain":"The particles slow down and hit the walls less, so the balloon shrinks. The particles stay the same size."},{"type":"mc","id":"m7","prompt":"Usually, which state of a substance has the highest density?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Where are particles packed closest?","explain":"Usually the solid. Water is a famous exception: ice floats because it is less dense than water."}]},"status":"self-checked","visual":{"type":"particles","caption":"Same particles, same mass: watch how much space they take up as the state changes.","opts":{"mp":0,"bp":100,"temp":-10,"name":"water","density":true}},"lab":{"type":"gaslab","caption":"Same particles, smaller box: the density and the pressure go up. Try the challenges.","opts":{"n":40,"temp":300,"vol":1}}},"mt_Z_Wu_77ybI":{"topicId":"mt_Z_Wu_77ybI","title":"Atoms, elements and compounds","audience":"learner","keyIdea":"An element has only one type of atom. A compound has two or more elements chemically joined.","explain":{"kid":["Atoms are the smallest bits of an element. There are about 118 elements. Oxygen, iron and carbon are three of them. Each element has its own kind of atom and a short symbol: O for oxygen, Fe for iron.","A compound forms when atoms of different elements join. Water, H₂O, is a compound. Each water particle has two hydrogen atoms joined to one oxygen atom."],"adult":["An atom has a tiny central nucleus, made of protons and neutrons. Electrons are arranged in shells around it. The number of protons decides which element the atom is.","Compounds can behave very differently from their elements. Sodium is a reactive metal and chlorine is a toxic gas. Together they make sodium chloride, which is table salt. A formula like CO₂ gives the ratio of atoms: one carbon to two oxygen."]},"familyTip":"Read the ingredients on a food or cleaning label. Which names are elements and which are compounds?","practice":[{"type":"mc","id":"p1","prompt":"Which of these is an element?","choices":["Oxygen, O₂","Water, H₂O","Carbon dioxide, CO₂"],"answer":0,"hint":"Look for only one kind of atom.","explain":"O₂ has only oxygen atoms, so it's an element, even though the atoms are joined in pairs."},{"type":"numeric","id":"p2","prompt":"How many atoms are in {n} molecules of water, H₂O?","answer":"3*n","hint":"Each H₂O has 2 + 1 atoms.","explain":"Each H₂O has 3 atoms, so {n} × 3 = {=3*n}.","params":{"n":[2,12]}},{"type":"mc","id":"p3","prompt":"What decides which element an atom is?","choices":["The number of protons","The number of neutrons","Its size"],"answer":0,"hint":"It's the atomic number.","explain":"The number of protons is the atomic number, and it decides the element."},{"type":"numeric","id":"p4","prompt":"How many hydrogen atoms are in {n} molecules of methane, CH₄?","answer":"4*n","hint":"Each CH₄ has 4 hydrogen atoms.","explain":"{n} × 4 = {=4*n}.","params":{"n":[2,12]}},{"type":"mc","id":"p5","prompt":"Sodium is a reactive metal and chlorine is a toxic gas. What is sodium chloride like?","choices":["A safe white solid: table salt","A reactive, toxic metal","A mixture you can separate with a magnet"],"answer":0,"hint":"Compounds are new substances.","explain":"Sodium chloride is table salt. Its properties are completely different from its elements."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"How many atoms in total are in {n} molecules of carbon dioxide, CO₂?","answer":"3*n","hint":"Each CO₂ has 1 + 2 atoms.","explain":"3 atoms each, so {n} × 3 = {=3*n}.","params":{"n":[2,12]}},{"type":"numeric","id":"m2","prompt":"How many oxygen atoms are in {n} molecules of oxygen, O₂?","answer":"2*n","hint":"Each O₂ has 2 atoms.","explain":"{n} × 2 = {=2*n}.","params":{"n":[2,15]}},{"type":"mc","id":"m3","prompt":"Which is a compound?","choices":["CO₂","O₂","Fe"],"answer":0,"hint":"More than one element, joined.","explain":"CO₂ has carbon and oxygen joined together."},{"type":"mc","id":"m4","prompt":"What is the symbol for iron?","choices":["Fe","I","Ir"],"answer":0,"hint":"It comes from the Latin word ferrum.","explain":"Fe. (I is iodine and Ir is iridium.)"},{"type":"mc","id":"m5","prompt":"Where are the protons and neutrons in an atom?","choices":["In the nucleus","In the shells","Spread evenly through the atom"],"answer":0,"hint":"The tiny centre.","explain":"Protons and neutrons are in the nucleus; electrons are in shells."},{"type":"mc","id":"m6","prompt":"Which statement about water, H₂O, is true?","choices":["Each molecule has 2 hydrogen atoms and 1 oxygen atom","Each molecule has 2 oxygen atoms","It is a mixture of hydrogen and oxygen"],"answer":0,"hint":"The small 2 belongs to H.","explain":"H₂O: 2 hydrogen and 1 oxygen, chemically joined, so it's a compound."},{"type":"mc","id":"m7","prompt":"What is the difference between a carbon atom and the element carbon?","choices":["An atom is one particle; the element is a substance made only of carbon atoms","There is no difference at all","The element contains other atoms too"],"answer":0,"hint":"One particle, or a lot of them?","explain":"An element is made of many atoms, all of the same type."}]},"status":"self-checked","visual":{"type":"atom","caption":"Build an atom. The number of protons decides the element.","opts":{"p":6,"n":6,"e":6}}},"mt_MBTVB-E-S7":{"topicId":"mt_MBTVB-E-S7","title":"Pure substances and mixtures","audience":"learner","keyIdea":"A pure substance contains only one element or compound. It melts and boils at exact temperatures, while mixtures melt and boil over a range.","explain":{"kid":["In science, 'pure' means one substance only, with nothing else mixed in. Pure water is only water particles. 'Pure' orange juice is a mixture of water, sugars and more.","A mixture has two or more substances that are not joined together. Air, sea water and salad are mixtures. You can often separate a mixture, for example by filtering or evaporating."],"adult":["You can test purity by melting or boiling. A pure substance changes state at one fixed temperature. Pure water boils at 100 °C at normal air pressure. Impurities lower the melting point and spread it over a range.","A formulation is a mixture designed for a job, with exact amounts of each part. Paints, medicines and fertilisers are formulations. Compounds are different from mixtures: their elements are chemically joined, in a fixed ratio."]},"familyTip":"Look at three drinks or foods at home. Which are pure in the science sense? (Hint: almost none.)","practice":[{"type":"mc","id":"p1","prompt":"In science, which is pure?","choices":["Distilled water","Fresh orange juice","Sea water"],"answer":0,"hint":"One substance only.","explain":"Distilled water contains only water. The others are mixtures."},{"type":"mc","id":"p2","prompt":"A sample melts over a range, from {a} °C to {=a+r} °C. What does this suggest?","choices":["It is a mixture (impure)","It is a pure substance","It is an element"],"answer":0,"hint":"Pure substances melt at one temperature.","explain":"Melting over a {r} °C range suggests impurities.","params":{"a":[40,80],"r":[3,9]}},{"type":"numeric","id":"p3","prompt":"A formulation is {p}% active ingredient. How many grams of active ingredient are in {=k*100} g?","answer":"p*k","hint":"Find {p}% of {=k*100}.","explain":"{p}% of {=k*100} g = {=p*k} g.","params":{"p":[5,40],"k":[1,9]}},{"type":"mc","id":"p4","prompt":"What is the difference between a mixture and a compound?","choices":["In a compound, the elements are chemically joined in a fixed ratio","A mixture is always a liquid","A compound can be separated by filtering"],"answer":0,"hint":"Joined, or just mixed?","explain":"Compound: elements joined in a fixed ratio. Mixture: substances not joined, in any amounts."},{"type":"mc","id":"p5","prompt":"Pure water boils at 100 °C at normal pressure. A water sample boils at {t} °C. What does that suggest?","choices":["It is not pure","It is pure","It has turned into a different compound"],"answer":0,"hint":"Pure water boils at exactly one temperature.","explain":"Boiling at {t} °C suggests something is dissolved in the water.","params":{"t":[101,106]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A pure substance melts at {m} °C. An impure sample of it will probably melt…","choices":["below {m} °C, over a range","at exactly {m} °C","above {=m+20} °C"],"answer":0,"hint":"Impurities lower and spread the melting point.","explain":"Impurities lower the melting point and spread it over a range, so below {m} °C.","params":{"m":[50,120]}},{"type":"numeric","id":"m2","prompt":"A fertiliser is {p}% nitrogen. How many kg of nitrogen are in {=k*10} kg?","answer":"p*k/10","hint":"Find {p}% of {=k*10}.","explain":"{p}% of {=k*10} kg = {=p*k/10} kg.","params":{"p":[10,30],"k":[1,9]}},{"type":"mc","id":"m3","prompt":"Which is a mixture?","choices":["Air","Oxygen","Carbon dioxide"],"answer":0,"hint":"Which has several substances not joined?","explain":"Air is a mixture of nitrogen, oxygen, argon, carbon dioxide and more."},{"type":"mc","id":"m4","prompt":"A label says 'pure apple juice'. Is it pure in the science sense?","choices":["No: it's a mixture of water, sugars and other substances","Yes, because nothing was added","Yes, because it is all one colour"],"answer":0,"hint":"Science 'pure' means one substance.","explain":"Even with nothing added, juice contains many substances."},{"type":"mc","id":"m5","prompt":"Which is a formulation?","choices":["Paint","Gold","Sea water"],"answer":0,"hint":"A mixture designed for a purpose, with exact amounts.","explain":"Paint is made to a recipe with exact amounts. Sea water is a mixture, but not designed."},{"type":"mc","id":"m6","prompt":"How could you test whether a white solid is pure?","choices":["Measure its melting point","Look at its colour","Weigh it"],"answer":0,"hint":"Pure substances melt at one temperature.","explain":"A sharp melting point at the expected value shows it is pure."},{"type":"mc","id":"m7","prompt":"Salt dissolved in water is…","choices":["a mixture","a compound","an element"],"answer":0,"hint":"Are the salt and water chemically joined?","explain":"The salt and water are not joined, so it is a mixture; you can get the salt back by evaporating."}]},"status":"self-checked","visual":{"type":"particles","caption":"Salt water is a mixture: two kinds of particle, not joined. It freezes below 0 °C and boils above 100 °C.","opts":{"mp":-2,"bp":101,"temp":20,"name":"salt water","mix":true}}},"mt_wfEfQuHOG-":{"topicId":"mt_wfEfQuHOG-","title":"The periodic table","audience":"learner","keyIdea":"Elements are arranged by atomic number in rows (periods) and columns (groups). Elements in a group have similar properties.","explain":{"kid":["The periodic table lists every element. Each box shows a symbol and a number, such as 6 for carbon. That number is the atomic number: how many protons each atom has.","Columns are called groups. Elements in the same group behave in similar ways. Rows are called periods. Metals are on the left and in the middle, and non-metals are on the right."],"adult":["In 1869 Dmitri Mendeleev put the known elements in order. He left gaps for elements no one had found yet and predicted their properties. When gallium and germanium were discovered, his predictions matched.","Patterns run down each group. In Group 1, the alkali metals, reactivity increases as you go down: lithium fizzes in water, while potassium bursts into a lilac flame. Group 0 (also called Group 18) holds the noble gases, which barely react at all."]},"familyTip":"Find a periodic table online and look up five elements you use at home.","practice":[{"type":"mc","id":"p1","prompt":"What are the columns of the periodic table called?","choices":["Groups","Periods","Shells"],"answer":0,"hint":"Rows are periods.","explain":"Columns are groups; rows are periods."},{"type":"numeric","id":"p2","prompt":"An element has atomic number {z}. How many protons are in each of its atoms?","answer":"z","hint":"Atomic number = number of protons.","explain":"The atomic number is the number of protons, so {z}.","params":{"z":[1,30]}},{"type":"mc","id":"p3","prompt":"Where are the metals in the periodic table?","choices":["On the left and in the middle","Only in the top row","On the far right"],"answer":0,"hint":"Non-metals are on the right.","explain":"Most elements are metals, filling the left and middle."},{"type":"numeric","id":"p4","prompt":"A neutral atom has {z} protons. How many electrons does it have?","answer":"z","hint":"Neutral means the charges balance.","explain":"A neutral atom has as many electrons as protons: {z}.","params":{"z":[1,30]}},{"type":"mc","id":"p5","prompt":"Lithium, sodium and potassium are in Group 1. Which is the most reactive?","choices":["Potassium","Lithium","They are all the same"],"answer":0,"hint":"Reactivity increases down Group 1.","explain":"Potassium is lowest of the three, so it is most reactive."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A neutral atom has {z} electrons. What is its atomic number?","answer":"z","hint":"Electrons = protons in a neutral atom.","explain":"It has {z} protons, so its atomic number is {z}.","params":{"z":[1,36]}},{"type":"numeric","id":"m2","prompt":"An element has atomic number {z}. How many electrons does a neutral atom of it have?","answer":"z","hint":"Same as the protons.","explain":"{z} protons, so {z} electrons.","params":{"z":[1,36]}},{"type":"mc","id":"m3","prompt":"Elements in the same group…","choices":["have similar chemical properties","have the same mass","are all gases"],"answer":0,"hint":"That's why groups are useful.","explain":"Elements in a group react in similar ways."},{"type":"mc","id":"m4","prompt":"What did Mendeleev do that made his table so convincing?","choices":["He left gaps and predicted elements that were found later","He discovered every element","He put the elements in alphabetical order"],"answer":0,"hint":"Think about predictions.","explain":"His gaps predicted elements such as gallium and germanium, which were later found."},{"type":"mc","id":"m5","prompt":"Which group contains the noble gases, which barely react?","choices":["Group 0 (also called Group 18)","Group 1","Group 7"],"answer":0,"hint":"The far right column.","explain":"The noble gases are in Group 0, also numbered Group 18."},{"type":"mc","id":"m6","prompt":"What is the atomic number of an element?","choices":["The number of protons in its atoms","The number of neutrons","Its position in the alphabet"],"answer":0,"hint":"It decides the element.","explain":"It is the number of protons."},{"type":"mc","id":"m7","prompt":"Which of these is a non-metal?","choices":["Sulfur","Iron","Sodium"],"answer":0,"hint":"Non-metals are on the right.","explain":"Sulfur is a non-metal; iron and sodium are metals."}]},"status":"self-checked","visual":{"type":"ptable","caption":"Highlight groups, periods, metals and non-metals. Choose an element to read about it.","opts":{"highlight":"group1"}}},"mt_t20A6RuTJn":{"topicId":"mt_t20A6RuTJn","title":"Counting atoms in formulae","audience":"learner","keyIdea":"A small number after a symbol counts that atom. A big number in front counts whole molecules. Brackets multiply everything inside.","explain":{"kid":["In H₂O, the small 2 belongs to the H. So there are 2 hydrogen atoms and 1 oxygen atom: 3 atoms in all.","A big number in front counts molecules. 3H₂O means 3 water molecules. That is 3 × 2 = 6 hydrogen atoms and 3 oxygen atoms."],"adult":["Brackets multiply everything inside them. In Ca(OH)₂ there is 1 calcium, 2 oxygen and 2 hydrogen atoms: 5 atoms in total.","Use both rules together when needed. 2Ca(OH)₂ has 2 calcium, 4 oxygen and 4 hydrogen atoms. In an equation, count each element on each side. A balanced equation has the same totals on both sides."]},"familyTip":"Write formulae on cards (H₂O, CO₂, 2NH₃) and race each other to count the atoms.","practice":[{"type":"numeric","id":"p1","prompt":"How many atoms in total are in one H₂O molecule?","answer":3,"hint":"2 hydrogen + 1 oxygen.","explain":"2 + 1 = 3 atoms."},{"type":"numeric","id":"p2","prompt":"How many hydrogen atoms are in {n}H₂O?","answer":"2*n","hint":"{n} molecules, each with 2 hydrogen atoms.","explain":"{n} × 2 = {=2*n} hydrogen atoms.","params":{"n":[2,9]}},{"type":"numeric","id":"p3","prompt":"How many oxygen atoms are in Ca(OH)₂?","answer":2,"hint":"The bracket is doubled.","explain":"(OH) × 2 gives 2 oxygen atoms."},{"type":"numeric","id":"p4","prompt":"How many oxygen atoms are in {n}CO₂?","answer":"2*n","hint":"Each CO₂ has 2 oxygen atoms.","explain":"{n} × 2 = {=2*n} oxygen atoms.","params":{"n":[2,9]}},{"type":"mc","id":"p5","prompt":"In 3H₂O, what does the 3 mean?","choices":["3 water molecules","3 hydrogen atoms","3 oxygen atoms"],"answer":0,"hint":"A big number in front counts molecules.","explain":"3H₂O is three whole water molecules."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"How many atoms in total are in {n}CH₄?","answer":"5*n","hint":"Each CH₄ has 1 + 4 atoms.","explain":"Each CH₄ has 5 atoms, so {n} × 5 = {=5*n}.","params":{"n":[2,9]}},{"type":"numeric","id":"m2","prompt":"How many oxygen atoms are in {n}Ca(OH)₂?","answer":"2*n","hint":"Each Ca(OH)₂ has 2 oxygen atoms.","explain":"{n} × 2 = {=2*n} oxygen atoms.","params":{"n":[2,6]}},{"type":"numeric","id":"m3","prompt":"How many hydrogen atoms are in 2NH₃?","answer":6,"hint":"2 molecules × 3 hydrogen atoms.","explain":"2 × 3 = 6."},{"type":"numeric","id":"m4","prompt":"How many atoms in total are in Mg(NO₃)₂?","answer":9,"hint":"The bracket doubles N and O₃.","explain":"1 Mg + 2 N + 6 O = 9 atoms."},{"type":"mc","id":"m5","prompt":"How many oxygen atoms are in Al₂(SO₄)₃?","choices":["12","4","7"],"answer":0,"hint":"The bracket is multiplied by 3.","explain":"4 oxygen atoms × 3 = 12. Adding 4 + 3 = 7 is a common slip."},{"type":"mc","id":"m6","prompt":"How many atoms of each element are in H₂SO₄?","choices":["2 H, 1 S, 4 O","2 H, 2 S, 4 O","1 H, 1 S, 1 O"],"answer":0,"hint":"Each small number belongs to the symbol just before it.","explain":"H₂ gives 2 H, S has no number so 1, O₄ gives 4."},{"type":"numeric","id":"m7","prompt":"The right-hand side of an equation has {n}H₂O. How many hydrogen atoms must the left-hand side have?","answer":"2*n","hint":"Atoms are not made or destroyed.","explain":"{n} × 2 = {=2*n}, so the left needs {=2*n} hydrogen atoms too.","params":{"n":[2,8]}}]},"status":"self-checked","visual":{"type":"sealed","caption":"Heat calcium hydroxide, Ca(OH)₂, in a sealed flask. Count the atoms before and after: the table checks your count.","opts":{"left":[["Ca(OH)2",1]],"right":[["CaO",1],["H2O",1]],"gas":["H2O"]}}},"mt_ehC1wsdmUz":{"topicId":"mt_ehC1wsdmUz","title":"Conservation of mass","audience":"learner","keyIdea":"In any change, the total mass stays the same, as long as nothing gets in or out.","explain":{"kid":["If you dissolve 10 g of sugar in 200 g of water, the solution has a mass of 210 g. The sugar seems to vanish, but its particles are still there, spread out in the water.","This is true for every change: melting, freezing, dissolving and even burning. Nothing is made from nothing, and nothing just disappears. We call this conservation of mass."],"adult":["Sometimes mass seems to change. When wood burns in the open, the ash is lighter. That's because gases, carbon dioxide and water vapour, escape into the air. A rusting nail gets heavier, because it gains oxygen from the air.","If the change happens in a sealed container, the total mass stays exactly the same. Scientists use this to check results, and to work out the mass of a gas that escaped."]},"familyTip":"Weigh a glass of water and a spoonful of sugar, stir the sugar in, then weigh again.","practice":[{"type":"numeric","id":"p1","prompt":"10 g of sugar dissolves in 200 g of water. What is the mass of the solution, in g?","answer":210,"hint":"Add the masses.","explain":"10 + 200 = 210 g."},{"type":"numeric","id":"p2","prompt":"{s} g of salt dissolves in {w} g of water. What is the mass of the salt water, in g?","answer":"s+w","hint":"Nothing is lost when it dissolves.","explain":"{s} + {w} = {=s+w} g. The salt is still there.","params":{"s":[5,30],"w":[100,250]}},{"type":"mc","id":"p3","prompt":"An ice cube with a mass of 25 g melts. What is the mass of the water?","choices":["25 g","Less than 25 g","More than 25 g"],"answer":0,"hint":"No particles are lost.","explain":"Still 25 g. Melting doesn't change the mass."},{"type":"numeric","id":"p4","prompt":"In a sealed flask, chemicals with a total mass of {m} g react and make a gas. What is the total mass afterwards, in g?","answer":"m","hint":"Can the gas escape?","explain":"The flask is sealed, so nothing escapes. The mass stays {m} g.","params":{"m":[100,300]}},{"type":"mc","id":"p5","prompt":"Wood burns in an open fire. The ash is lighter than the wood. Why?","choices":["Gases made in burning escape into the air","Some mass is destroyed","The fire uses some mass up as heat"],"answer":0,"hint":"Where do the products go?","explain":"Carbon dioxide and water vapour escape. Their mass plus the ash equals the wood plus the oxygen used."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"In an open beaker, {m} g of chemicals fizz and give off a gas. Afterwards the beaker's contents have a mass of {=m-g} g. What mass of gas escaped, in g?","answer":"g","hint":"Find the difference.","explain":"{m} − {=m-g} = {g} g of gas escaped.","params":{"m":[100,200],"g":[2,15]}},{"type":"numeric","id":"m2","prompt":"{=7*k} g of iron reacts with {=4*k} g of sulfur to make iron sulfide. Nothing escapes. What mass of iron sulfide forms, in g?","answer":"11*k","hint":"Add the masses.","explain":"{=7*k} + {=4*k} = {=11*k} g.","params":{"k":[1,9]}},{"type":"mc","id":"m3","prompt":"An iron nail rusts and gets heavier. Where does the extra mass come from?","choices":["Oxygen (and water) from the air","Nowhere: rust is made from nothing","The nail grows"],"answer":0,"hint":"Rust forms when iron reacts with something.","explain":"Iron reacts with oxygen and water from the air, so their mass joins the nail."},{"type":"mc","id":"m4","prompt":"In a sealed container, which change does NOT conserve mass?","choices":["None: mass is always conserved","Melting","Burning"],"answer":0,"hint":"Think about every kind of change.","explain":"Mass is conserved in every change if nothing gets in or out."},{"type":"mc","id":"m5","prompt":"Sugar dissolves in tea and can't be seen. Where is it?","choices":["Its particles are spread out between the water particles","It has been destroyed","It has turned into water"],"answer":0,"hint":"Can you still taste it?","explain":"The sugar particles are still there, spread through the water."},{"type":"numeric","id":"m6","prompt":"40 g of vinegar and 5 g of baking soda react in a sealed bottle. What is the total mass afterwards, in g?","answer":45,"hint":"Sealed: nothing escapes.","explain":"40 + 5 = 45 g."},{"type":"mc","id":"m7","prompt":"Why do scientists seal the container when testing conservation of mass?","choices":["So no gas can get in or out","To keep it warm","To speed up the reaction"],"answer":0,"hint":"Gases are easy to lose.","explain":"Sealing stops gases escaping or entering, so the total mass can be compared fairly."}]},"status":"self-checked","visual":{"type":"sealed","caption":"Iron and sulfur in a sealed flask on a scale. React them: the atoms join up as iron sulfide and the reading stays the same.","opts":{"left":[["Fe",2],["S",2]],"right":[["FeS",2]],"names":{"Fe":"iron","S":"sulfur","FeS":"iron sulfide"}}}},"mt_tFOhzG3wLi":{"topicId":"mt_tFOhzG3wLi","title":"Reactions rearrange atoms","audience":"learner","keyIdea":"In a chemical reaction, atoms are rearranged into new substances. No atoms are created or destroyed.","explain":{"kid":["In a chemical reaction, the starting substances are called reactants. The new substances are called products. The atoms swap partners, but they are all still there.","When carbon burns in oxygen, one carbon atom joins two oxygen atoms. Together they make carbon dioxide, CO₂. There is 1 carbon atom before and after, and 2 oxygen atoms before and after."],"adult":["Because every atom is still there, the total mass of the products equals the total mass of the reactants. This is the particle-level reason for conservation of mass.","Particle diagrams show this well. Draw 2H₂ + O₂ → 2H₂O. On the left there are 4 hydrogen atoms and 2 oxygen atoms. On the right there are 4 hydrogen atoms and 2 oxygen atoms. Only the partners have changed."]},"familyTip":"Use coloured sweets or building bricks as atoms. Build the reactants, then rebuild them into the products without adding or removing any.","practice":[{"type":"mc","id":"p1","prompt":"In a chemical reaction, what happens to the atoms?","choices":["They are rearranged into new substances","Some are destroyed","New atoms are created"],"answer":0,"hint":"Atoms swap partners.","explain":"The same atoms join up in new ways."},{"type":"numeric","id":"p2","prompt":"{=3*k} g of magnesium reacts completely with {=2*k} g of oxygen to make magnesium oxide. What mass of magnesium oxide forms, in g?","answer":"5*k","hint":"All the atoms end up in the product.","explain":"{=3*k} + {=2*k} = {=5*k} g.","params":{"k":[1,12]}},{"type":"mc","id":"p3","prompt":"In C + O₂ → CO₂, how many oxygen atoms are on each side?","choices":["2 on each side","2 on the left and 1 on the right","1 on each side"],"answer":0,"hint":"Count the small numbers.","explain":"O₂ has 2, and CO₂ has 2."},{"type":"numeric","id":"p4","prompt":"A reaction makes {n}H₂O. How many oxygen atoms must the reactants contain?","answer":"n","hint":"Each H₂O has 1 oxygen atom.","explain":"{n} × 1 = {n} oxygen atoms. Atoms are not created or destroyed.","params":{"n":[2,9]}},{"type":"mc","id":"p5","prompt":"What are the starting substances in a reaction called?","choices":["Reactants","Products","Catalysts"],"answer":0,"hint":"They react.","explain":"Reactants go in; products come out."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"{=4*k} g of hydrogen reacts with {=32*k} g of oxygen to make water. What mass of water forms, in g?","answer":"36*k","hint":"Add the masses.","explain":"{=4*k} + {=32*k} = {=36*k} g.","params":{"k":[1,6]}},{"type":"numeric","id":"m2","prompt":"The products of a reaction contain {n} carbon atoms. How many carbon atoms were in the reactants?","answer":"n","hint":"Atoms are not created or destroyed.","explain":"The same {n} carbon atoms.","params":{"n":[2,20]}},{"type":"mc","id":"m3","prompt":"Why is mass conserved in a reaction?","choices":["The same atoms are there before and after","The products are always heavier","Energy turns into mass"],"answer":0,"hint":"Count the atoms.","explain":"No atoms are gained or lost, so the mass stays the same."},{"type":"mc","id":"m4","prompt":"In 2H₂ + O₂ → 2H₂O, how many hydrogen atoms are on the right?","choices":["4","2","6"],"answer":0,"hint":"2 molecules × 2 atoms.","explain":"2H₂O has 2 × 2 = 4 hydrogen atoms."},{"type":"mc","id":"m5","prompt":"Iron and sulfur are heated and make iron sulfide. Which is true?","choices":["It is a new substance with different properties","It is a mixture you can separate with a magnet","The iron atoms turn into sulfur atoms"],"answer":0,"hint":"A reaction makes a new substance.","explain":"Iron sulfide is a compound. It isn't magnetic like iron, and atoms never change element."},{"type":"mc","id":"m6","prompt":"Which of these is a chemical reaction rather than a change of state?","choices":["Burning magnesium","Melting ice","Boiling water"],"answer":0,"hint":"Which makes a new substance?","explain":"Burning magnesium makes magnesium oxide, a new substance."},{"type":"numeric","id":"m7","prompt":"C + O₂ → CO₂. 12 g of carbon reacts completely with 32 g of oxygen. What mass of carbon dioxide forms, in g?","answer":44,"hint":"Add the masses.","explain":"12 + 32 = 44 g."}]},"status":"self-checked","visual":{"type":"balancer","caption":"2H₂ + O₂ → 2H₂O: the atoms are rearranged, not created or destroyed.","opts":{"left":[["H2",2],["O2",1]],"right":[["H2O",2]],"lock":true}}},"mt_dzgK92gM32":{"topicId":"mt_dzgK92gM32","title":"Word equations","audience":"learner","keyIdea":"A word equation names the reactants, then an arrow meaning 'react to make', then the products.","explain":{"kid":["A word equation is a short way to describe a reaction. Reactants go on the left and products go on the right. The arrow means 'react to make'.","For example: magnesium + oxygen → magnesium oxide. The + on the left means 'and'. It doesn't mean adding numbers."],"adult":["Names give clues. A compound ending in '-ide' usually has just two elements: sodium chloride is sodium and chlorine. One ending in '-ate' also has oxygen: copper sulfate has copper, sulfur and oxygen.","Some patterns are worth learning. Metal + acid → salt + hydrogen. Acid + alkali → salt + water. When a fuel like methane burns completely: fuel + oxygen → carbon dioxide + water."]},"familyTip":"Write a word equation for something that happens in your kitchen, such as burning gas on a hob.","practice":[{"type":"mc","id":"p1","prompt":"In magnesium + oxygen → magnesium oxide, what is the product?","choices":["Magnesium oxide","Magnesium","Oxygen"],"answer":0,"hint":"Products are on the right.","explain":"Magnesium oxide is on the right of the arrow."},{"type":"numeric","id":"p2","prompt":"iron + sulfur → iron sulfide. {=7*k} g of iron reacts with {=4*k} g of sulfur. What mass of iron sulfide forms, in g?","answer":"11*k","hint":"Mass is conserved.","explain":"{=7*k} + {=4*k} = {=11*k} g.","params":{"k":[1,12]}},{"type":"mc","id":"p3","prompt":"What does the arrow mean in a word equation?","choices":["React to make","Equals","Add together"],"answer":0,"hint":"It shows a change.","explain":"The arrow means the reactants react to make the products."},{"type":"mc","id":"p4","prompt":"Complete: zinc + hydrochloric acid → zinc chloride + …","choices":["hydrogen","water","oxygen"],"answer":0,"hint":"Metal + acid → salt + ?","explain":"Metal + acid → salt + hydrogen."},{"type":"numeric","id":"p5","prompt":"calcium carbonate → calcium oxide + carbon dioxide. Heating {=100*k} g of calcium carbonate makes {=56*k} g of calcium oxide. What mass of carbon dioxide is made, in g?","answer":"44*k","hint":"Total mass stays the same.","explain":"{=100*k} − {=56*k} = {=44*k} g.","params":{"k":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"magnesium carbonate → magnesium oxide + carbon dioxide. {=84*k} g of magnesium carbonate makes {=40*k} g of magnesium oxide. What mass of carbon dioxide is made, in g?","answer":"44*k","hint":"Subtract.","explain":"{=84*k} − {=40*k} = {=44*k} g.","params":{"k":[1,6]}},{"type":"numeric","id":"m2","prompt":"sodium + chlorine → sodium chloride. {=23*k} g of sodium reacts with {=35.5*k} g of chlorine. What mass of sodium chloride forms, in g?","answer":"58.5*k","hint":"Add the masses.","explain":"{=23*k} + {=35.5*k} = {=58.5*k} g.","params":{"k":[1,6]}},{"type":"mc","id":"m3","prompt":"Which word equation shows methane burning completely?","choices":["methane + oxygen → carbon dioxide + water","methane → carbon + hydrogen","methane + water → oxygen"],"answer":0,"hint":"Fuel + oxygen → ?","explain":"Complete burning of a hydrocarbon gives carbon dioxide and water."},{"type":"mc","id":"m4","prompt":"Which elements are in copper sulfate?","choices":["Copper, sulfur and oxygen","Copper and sulfur only","Copper and oxygen only"],"answer":0,"hint":"'-ate' means oxygen is included.","explain":"'-ate' tells you there is oxygen too: copper, sulfur and oxygen."},{"type":"mc","id":"m5","prompt":"Complete: hydrochloric acid + sodium hydroxide → sodium chloride + …","choices":["water","hydrogen","carbon dioxide"],"answer":0,"hint":"Acid + alkali → salt + ?","explain":"Acid + alkali → salt + water."},{"type":"mc","id":"m6","prompt":"In 'iron + oxygen → iron oxide', what does the + on the left mean?","choices":["'And': iron and oxygen react together","Add the numbers","The reaction gives off heat"],"answer":0,"hint":"It isn't maths here.","explain":"The + means 'and'."},{"type":"mc","id":"m7","prompt":"What are the reactants in: zinc + copper sulfate → zinc sulfate + copper?","choices":["Zinc and copper sulfate","Zinc sulfate and copper","Only zinc"],"answer":0,"hint":"Reactants are on the left.","explain":"Zinc and copper sulfate are on the left of the arrow."}]},"status":"self-checked","visual":{"type":"sealed","caption":"magnesium + oxygen → magnesium oxide. React it, read the word equation, and see what opening the flask does.","opts":{"left":[["Mg",2],["O2",1]],"right":[["MgO",2]],"gas":["O2"],"names":{"Mg":"magnesium","O2":"oxygen","MgO":"magnesium oxide"}}}},"mt_BXj4pfdhxO":{"topicId":"mt_BXj4pfdhxO","title":"Balancing chemical equations","audience":"learner","keyIdea":"Balance an equation by changing only the big numbers in front of formulae, until each element has the same number of atoms on both sides.","explain":{"kid":["H₂ + O₂ → H₂O is not balanced. There are 2 oxygen atoms on the left but only 1 on the right. We can't change H₂O into H₂O₂, because that is a different substance.","Instead, put big numbers in front. 2H₂O gives 2 oxygen atoms, but now 4 hydrogen atoms. So write 2H₂ on the left. Now 2H₂ + O₂ → 2H₂O is balanced: 4 H and 2 O on each side."],"adult":["A good method is to count the atoms of each element on both sides in a table. Balance one element at a time. Leave elements that appear on their own, like O₂, until last. Recount after every change.","Never change the small numbers. That would change the substance itself. Give the final numbers in their simplest ratio: 4H₂ + 2O₂ → 4H₂O should be written as 2H₂ + O₂ → 2H₂O."]},"familyTip":"Use coins or buttons as atoms to model an equation, and check both sides have the same of each.","practice":[{"type":"numeric","id":"p1","prompt":"In □H₂ + O₂ → □H₂O, both boxes hold the same number. What is it?","answer":2,"hint":"Balance the oxygen first.","explain":"2H₂ + O₂ → 2H₂O has 4 H and 2 O on each side, so the number is 2."},{"type":"numeric","id":"p2","prompt":"N₂ + 3H₂ → 2NH₃. How many molecules of NH₃ can {k} molecules of N₂ make, with plenty of H₂?","answer":"2*k","hint":"Each N₂ makes 2NH₃.","explain":"{k} × 2 = {=2*k} molecules of NH₃.","params":{"k":[2,12]}},{"type":"mc","id":"p3","prompt":"Why can't you balance H₂ + O₂ → H₂O by writing H₂O₂?","choices":["H₂O₂ is a different substance (hydrogen peroxide)","H₂O₂ has too many hydrogen atoms","You can: that is correct"],"answer":0,"hint":"What do the small numbers decide?","explain":"Changing a small number changes the substance. H₂O₂ is hydrogen peroxide, not water."},{"type":"numeric","id":"p4","prompt":"Balance: □Mg + O₂ → 2MgO. What number goes in the box?","answer":2,"hint":"How many Mg atoms are on the right?","explain":"2MgO has 2 Mg atoms, so you need 2Mg. Then there are 2 Mg and 2 O on each side."},{"type":"numeric","id":"p5","prompt":"2H₂ + O₂ → 2H₂O. How many molecules of O₂ react with {=2*k} molecules of H₂?","answer":"k","hint":"2 H₂ for every 1 O₂.","explain":"{=2*k} ÷ 2 = {k} molecules of O₂.","params":{"k":[2,12]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"CH₄ + 2O₂ → CO₂ + 2H₂O. How many molecules of O₂ are needed to burn {k} molecules of CH₄?","answer":"2*k","hint":"2 O₂ for each CH₄.","explain":"{k} × 2 = {=2*k} molecules of O₂.","params":{"k":[2,12]}},{"type":"numeric","id":"m2","prompt":"N₂ + 3H₂ → 2NH₃. How many H₂ molecules react with {k} N₂ molecules?","answer":"3*k","hint":"3 H₂ for each N₂.","explain":"{k} × 3 = {=3*k} molecules of H₂.","params":{"k":[2,12]}},{"type":"mc","id":"m3","prompt":"Which equation is balanced?","choices":["CH₄ + 2O₂ → CO₂ + 2H₂O","CH₄ + O₂ → CO₂ + H₂O","CH₄ + O₂ → CO₂ + 2H₂O"],"answer":0,"hint":"Count C, H and O on each side.","explain":"CH₄ + 2O₂ → CO₂ + 2H₂O has 1 C, 4 H and 4 O on each side."},{"type":"mc","id":"m4","prompt":"When balancing, what are you allowed to change?","choices":["The big numbers in front of formulae","The small numbers inside formulae","Both"],"answer":0,"hint":"Small numbers define the substance.","explain":"Only the big numbers (coefficients) may change."},{"type":"numeric","id":"m5","prompt":"Balance: N₂ + □H₂ → 2NH₃. What number goes in the box?","answer":3,"hint":"2NH₃ has 6 hydrogen atoms.","explain":"6 hydrogen atoms need 3H₂, so the number is 3."},{"type":"mc","id":"m6","prompt":"Write 4H₂ + 2O₂ → 4H₂O in its simplest ratio.","choices":["2H₂ + O₂ → 2H₂O","H₂ + O₂ → H₂O","2H₂ + 2O₂ → 2H₂O"],"answer":0,"hint":"Divide every big number by 2.","explain":"Halving gives 2H₂ + O₂ → 2H₂O, which is still balanced."},{"type":"numeric","id":"m7","prompt":"Balance: □Na + Cl₂ → 2NaCl. What number goes in the box?","answer":2,"hint":"2NaCl has 2 sodium atoms.","explain":"2 sodium atoms are needed on the left, so the number is 2."}]},"status":"self-checked","visual":{"type":"balancer","caption":"Balance it: change only the big numbers until every row of the table matches.","opts":{"left":[["CH4",1],["O2",1]],"right":[["CO2",1],["H2O",1]]}}},"mt_XW5d2G7v01":{"topicId":"mt_XW5d2G7v01","title":"Estimating areas with rectangles and trapezia","audience":"learner","keyIdea":"Cut the area into thin strips, add up the strip areas, and use more strips for a better estimate.","explain":{"kid":["To find the area under a curve, cut it into thin strips. Each strip is close to a rectangle, and a rectangle's area is easy to find.","Add up all the strips to get an estimate. More strips that are thinner give a better estimate. A trapezium strip follows the curve more closely than a rectangle does."],"adult":["With n strips of width h = (b − a)/n, a left-rectangle estimate is h × (f(x₀) + f(x₁) + … + f(xₙ₋₁)). The trapezium rule uses both ends of each strip: h/2 × (y₀ + 2y₁ + … + 2yₙ₋₁ + yₙ).","For a curve that bends upwards, like y = x², trapezia overestimate. The error shrinks about four times each time you double n."]},"familyTip":"Draw a curve on squared paper and count squares under it. Then try strips of two squares wide, then one. Which count is closest?","practice":[{"type":"numeric","id":"p1","prompt":"Strips from x = 0 to x = {b}, with {n} equal strips. How wide is each strip?","answer":"b/n","hint":"Width = total length ÷ number of strips.","explain":"Width = {b} ÷ {n} = {=b/n}.","params":{"b":[2,8],"n":[2,5]},"where":"(b*100)%n==0"},{"type":"numeric","id":"p2","prompt":"Two rectangles under a curve each have width 1. Their heights are {a} and {b}. Estimate the area.","answer":"a+b","hint":"Area of each rectangle is width × height.","explain":"1 × {a} + 1 × {b} = {=a+b}.","params":{"a":[1,9],"b":[2,12]}},{"type":"mc","id":"p3","prompt":"What usually happens to the estimate as you use more, thinner strips?","choices":["It gets closer to the true area","It gets further away","It stays exactly the same"],"answer":0,"hint":"Thinner strips hug the curve.","explain":"Thinner strips leave less gap or overlap, so the estimate gets closer."},{"type":"numeric","id":"p4","prompt":"One trapezium strip has width {h} and edge heights {a} and {b}. What is its area?","answer":"h*(a+b)/2","hint":"Area of a trapezium = width × (sum of the parallel sides) ÷ 2.","explain":"{h} × ({a} + {b}) ÷ 2 = {=h*(a+b)/2}.","params":{"h":[1,4],"a":[1,9],"b":[1,9]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Use 2 left rectangles of width 1 under y = x² + {c} from x = 0 to 2. Estimate the area.","answer":"2*c+1","hint":"The heights are f(0) and f(1).","explain":"Heights {c} and {=1+c}, so the area ≈ {c} + {=1+c} = {=2*c+1}.","params":{"c":[1,9]}},{"type":"numeric","id":"m2","prompt":"Trapezium rule, strip width 1, heights y₀ = {a}, y₁ = {b}, y₂ = {c}. Estimate the area.","answer":"(a+2*b+c)/2","hint":"½ × width × (first + 2 × middle + last).","explain":"½ × ({a} + 2 × {b} + {c}) = {=(a+2*b+c)/2}.","params":{"a":[1,9],"b":[1,9],"c":[1,9]}},{"type":"numeric","id":"m3","prompt":"{n} equal strips cover x = 0 to x = {b}. How wide is each one?","answer":"b/n","hint":"Divide the length by the number of strips.","explain":"{b} ÷ {n} = {=b/n}.","params":{"n":[2,5],"b":[1,10]},"where":"(b*100)%n==0"},{"type":"mc","id":"m4","prompt":"For y = x² from 0 to 2, left rectangles give an estimate that is…","choices":["too small","too big","exact"],"answer":0,"hint":"The curve rises, so where is each rectangle's height measured?","explain":"The curve rises, so the left edge is the lowest point of each strip: every rectangle sits under the curve."},{"type":"mc","id":"m5","prompt":"For the same number of strips, which estimate usually follows a smooth curve most closely?","choices":["Trapezia","Left rectangles","One big rectangle"],"answer":0,"hint":"Which shape uses both ends of each strip?","explain":"Trapezia join the curve at both ends of each strip, so they hug it better."},{"type":"mc","id":"m6","prompt":"What does doubling the number of strips do to each strip's width?","choices":["Halves it","Doubles it","Nothing"],"answer":0,"hint":"The total length stays the same.","explain":"The same length shared by twice as many strips makes each one half as wide."},{"type":"numeric","id":"m7","prompt":"Right rectangles of width 1 under y = 2x from 0 to {n} have heights 2, 4, … up to {=2*n}. Add them up.","answer":"n*(n+1)","hint":"Add the even numbers from 2 to the last height.","explain":"2 + 4 + … + {=2*n} = {=n*(n+1)}.","params":{"n":[2,6]}}]},"status":"self-checked","visual":{"type":"area","caption":"Change the number of strips and the method. Watch the estimate close in on the exact area under y = x².","opts":{"mode":"riemann","f":"x*x","a":0,"b":2,"n":4,"xr":[-0.2,2.4],"yr":[-0.5,5]}}},"mt_cryXWeeFPc":{"topicId":"mt_cryXWeeFPc","title":"Antiderivatives","audience":"learner","keyIdea":"Integration reverses differentiation: add one to the power, divide by the new power, and add + C.","explain":{"kid":["Differentiating takes a curve and gives its gradient. An antiderivative goes the other way: you know the gradient, and you find the curve.","For a power of x, add one to the power, then divide by the new power. So x² becomes x³ ÷ 3. Always add + C at the end, because a number on its own would vanish when you differentiate."],"adult":["∫xⁿ dx = xⁿ⁺¹/(n + 1) + C for every n except −1. Work term by term and keep any number in front: ∫6x² dx = 2x³ + C.","Check an answer by differentiating it: you should get back what you started with. The + C stands for a whole family of curves, each one a vertical shift of the others."]},"familyTip":"Play 'reverse it': one person says a derivative like 6x², the other gives a curve that has it, then both check by differentiating.","practice":[{"type":"mc","id":"p1","prompt":"∫ x³ dx = ?","choices":["x⁴/4 + C","3x² + C","x⁴ + C"],"answer":0,"hint":"Add one to the power, then divide by the new power.","explain":"x³ → x⁴, then ÷ 4: x⁴/4 + C."},{"type":"numeric","id":"p2","prompt":"∫ {=3*m}x² dx = Ax³ + C. Find A.","answer":"m","hint":"Add one to the power (3), then divide by 3.","explain":"{=3*m} ÷ 3 = {m}, so A = {m}.","params":{"m":[1,6]}},{"type":"numeric","id":"p3","prompt":"∫ {=2*a}x dx = Ax² + C. Find A.","answer":"a","hint":"x becomes x², then divide by 2.","explain":"{=2*a} ÷ 2 = {a}, so A = {a}.","params":{"a":[1,9]}},{"type":"mc","id":"p4","prompt":"Why do we add + C?","choices":["A constant differentiates to 0, so it could have been there","C stands for 'curve'","To make the answer bigger"],"answer":0,"hint":"What is the derivative of 5?","explain":"Any constant has derivative 0, so we cannot tell which constant was there: we write + C."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"∫ 5 dx = ?","choices":["5x + C","0","5 + C"],"answer":0,"hint":"5 is 5x⁰.","explain":"5x⁰ → 5x¹ ÷ 1 = 5x, plus C."},{"type":"mc","id":"m2","prompt":"∫ x dx = ?","choices":["x²/2 + C","1 + C","x² + C"],"answer":0,"hint":"x is x¹.","explain":"x¹ → x², then ÷ 2: x²/2 + C."},{"type":"numeric","id":"m3","prompt":"∫ {=4*a}x³ dx = Ax⁴ + C. Find A.","answer":"a","hint":"Add one to the power (4), then divide by 4.","explain":"{=4*a} ÷ 4 = {a}, so A = {a}.","params":{"a":[1,8]}},{"type":"numeric","id":"m4","prompt":"F(x) = x³ + {c}x is an antiderivative of f(x). Find f(2).","answer":"12+c","hint":"f is the derivative of F.","explain":"f(x) = 3x² + {c}, so f(2) = 12 + {c} = {=12+c}.","params":{"c":[1,9]}},{"type":"mc","id":"m5","prompt":"Which is an antiderivative of 2x?","choices":["x² + 7","2","2x²"],"answer":0,"hint":"Differentiate each choice.","explain":"x² + 7 differentiates to 2x."},{"type":"mc","id":"m6","prompt":"∫ x⁻² dx = ?","choices":["−x⁻¹ + C","x⁻¹ + C","−2x⁻³ + C"],"answer":0,"hint":"Add one to −2, then divide by the new power.","explain":"x⁻² → x⁻¹, then ÷ (−1): −x⁻¹ + C."},{"type":"numeric","id":"m7","prompt":"What number goes in front of x² in ∫ ({=2*a}x + {b}) dx?","answer":"a","hint":"Integrate the x term only.","explain":"{=2*a}x integrates to {a}x², so the number is {a}.","params":{"a":[1,7],"b":[1,9]}}]},"status":"self-checked","visual":{"type":"area","caption":"Every curve y = x² + C has gradient 2x. Slide C: the curve moves, but its gradient at x = 1 never changes.","opts":{"mode":"family","F":"x*x","label":"x²","at":1,"xr":[-3,3],"yr":[-5,9]}}},"mt_gbnMvpN_Lj":{"topicId":"mt_gbnMvpN_Lj","title":"The constant of integration and initial conditions","audience":"learner","keyIdea":"+ C means a whole family of curves; one known point picks out the curve you want.","explain":{"kid":["When you integrate, you get a family of curves. They all have the same shape, just moved up or down. That is the + C.","If you know one point on the curve, put its x and y into your answer. Then you can work out C and pick the right curve."],"adult":["Given dy/dx = f(x) and a point (x₀, y₀), integrate to get y = F(x) + C, then substitute: C = y₀ − F(x₀).","In science this point is often an initial condition, such as a starting position at t = 0. With t = 0 many terms vanish, so C is simply the starting value."]},"familyTip":"Trace one curve, then slide the tracing paper straight up. Every copy has the same slopes. Which copy goes through a dot you drew?","practice":[{"type":"numeric","id":"p1","prompt":"dy/dx = 2x, and the curve passes through (0, {c}). Find C in y = x² + C.","answer":"c","hint":"Put x = 0 and y = {c} into y = x² + C.","explain":"{c} = 0 + C, so C = {c}.","params":{"c":[1,9]}},{"type":"numeric","id":"p2","prompt":"y = x² + C passes through (2, {y}). Find C.","answer":"y-4","hint":"Put x = 2 in: 2² = 4.","explain":"{y} = 4 + C, so C = {=y-4}.","params":{"y":[5,15]}},{"type":"mc","id":"p3","prompt":"How are the curves y = x² + 1 and y = x² + 5 related?","choices":["Same shape; one is 4 units higher","They cross at x = 1","One is steeper"],"answer":0,"hint":"Compare them at the same x.","explain":"At every x, the second is 4 more: the same curve moved up 4."},{"type":"numeric","id":"p4","prompt":"dy/dx = 3x², and y = {c} when x = 1. Find C in y = x³ + C.","answer":"c-1","hint":"Put x = 1 in: 1³ = 1.","explain":"{c} = 1 + C, so C = {=c-1}.","params":{"c":[2,12]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"y = x² + C passes through (3, {y}). Find C.","answer":"y-9","hint":"3² = 9.","explain":"{y} = 9 + C, so C = {=y-9}.","params":{"y":[10,20]}},{"type":"numeric","id":"m2","prompt":"dy/dx = 4x³, and y = {y} when x = 1. Find y when x = 2.","answer":"y+15","hint":"Integrate to y = x⁴ + C, find C, then put x = 2.","explain":"C = {y} − 1 = {=y-1}, so y(2) = 16 + {=y-1} = {=y+15}.","params":{"y":[1,10]}},{"type":"mc","id":"m3","prompt":"Why can't you find C from dy/dx alone?","choices":["Every vertical shift has the same gradient","C is always 0","dy/dx is never known"],"answer":0,"hint":"Do the shifted curves have different slopes?","explain":"Moving a curve up or down doesn't change its gradient, so dy/dx can't tell them apart."},{"type":"numeric","id":"m4","prompt":"A position is s = 5t² + C metres, and s = {h} when t = 0. Find C.","answer":"h","hint":"Put t = 0 in.","explain":"{h} = 0 + C, so C = {h}.","params":{"h":[1,20]}},{"type":"mc","id":"m5","prompt":"y = 2x + C passes through (1, 5). What is C?","choices":["3","5","7"],"answer":0,"hint":"5 = 2 × 1 + C.","explain":"5 = 2 + C, so C = 3."},{"type":"numeric","id":"m6","prompt":"y = x³ + C passes through (2, {y}). Find C.","answer":"y-8","hint":"2³ = 8.","explain":"{y} = 8 + C, so C = {=y-8}.","params":{"y":[9,20]}},{"type":"mc","id":"m7","prompt":"What is enough to fix C?","choices":["Any one point on the curve","The gradient at one point","Nothing: C is always 1"],"answer":0,"hint":"One equation, one unknown.","explain":"One known point gives one equation, which is enough to find C."}]},"status":"self-checked","visual":{"type":"area","caption":"Slide C until the curve y = x² + C passes through the red point (1, 4).","opts":{"mode":"family","F":"x*x","label":"x²","at":1,"point":[1,4],"c":0,"xr":[-3,3],"yr":[-5,9]}}},"mt_P-VlHqNpca":{"topicId":"mt_P-VlHqNpca","title":"The definite integral","audience":"learner","keyIdea":"∫ from a to b of f(x) dx is what the sum of strip areas settles on as the strips get thinner: the signed area.","explain":{"kid":["The long S sign ∫ means 'sum'. The numbers at the bottom and top tell you where to start and stop.","Picture thin strips from the start to the stop. Add up their areas. As the strips get thinner, the total settles on one number. That number is the definite integral. Area below the x-axis counts as minus."],"adult":["∫ₐᵇ f(x) dx = lim (n → ∞) of Σ f(xᵢ) Δx, where Δx = (b − a)/n. The dx is the strip width, shrinking to zero.","Areas below the axis count as negative, so ∫ from −1 to 1 of x dx = 0, even though the shaded region is not empty. Swapping the limits changes the sign."]},"familyTip":"Draw y = 3 from x = 0 to 4 and shade under it. Explain why ∫ from 0 to 4 of 3 dx must be 12 before doing any algebra.","practice":[{"type":"mc","id":"p1","prompt":"In ∫ from 1 to 4 of f(x) dx, what are 1 and 4?","choices":["The limits: where the area starts and stops","Two values of f","The number of strips"],"answer":0,"hint":"Look at where they are written.","explain":"They are the limits of integration: the area runs from x = 1 to x = 4."},{"type":"numeric","id":"p2","prompt":"∫ from 0 to {b} of {k} dx is the area of a rectangle. What is it?","answer":"b*k","hint":"Width × height.","explain":"Width {b}, height {k}: {b} × {k} = {=b*k}.","params":{"b":[1,9],"k":[1,9]}},{"type":"numeric","id":"p3","prompt":"∫ from 0 to {b} of x dx is the area of a triangle. What is it?","answer":"b*b/2","hint":"½ × base × height; the height is also {b}.","explain":"½ × {b} × {b} = {=b*b/2}.","params":{"b":[1,10]}},{"type":"mc","id":"p4","prompt":"∫ from −2 to 2 of x dx = ?","choices":["0","4","−4"],"answer":0,"hint":"Sketch y = x: what is below the axis?","explain":"The triangle below the axis cancels the one above, so the answer is 0."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"∫ from {a} to {b} of 3 dx = ?","answer":"3*(b-a)","hint":"It is a rectangle of height 3.","explain":"Width {=b-a}, height 3: {=3*(b-a)}.","params":{"a":[0,4],"b":[5,9]}},{"type":"mc","id":"m2","prompt":"If ∫ from 0 to 2 of f(x) dx = 5, what is ∫ from 2 to 0 of f(x) dx?","choices":["−5","5","0"],"answer":0,"hint":"Swapping the limits…","explain":"Swapping the limits changes the sign: −5."},{"type":"numeric","id":"m3","prompt":"∫ from 0 to {b} of 2x dx is a triangle. What is its area?","answer":"b*b","hint":"The height at x = {b} is {=2*b}.","explain":"½ × {b} × {=2*b} = {=b*b}.","params":{"b":[1,9]}},{"type":"mc","id":"m4","prompt":"y = −1 from x = 0 to 3. What is ∫ from 0 to 3 of (−1) dx?","choices":["−3","3","0"],"answer":0,"hint":"The rectangle is below the axis.","explain":"Area 3, below the axis, so the integral is −3."},{"type":"mc","id":"m5","prompt":"What does dx stand for in ∫ f(x) dx?","choices":["The width of a strip, shrinking to zero","A second unknown to solve for","The derivative"],"answer":0,"hint":"Think of Σ f(x) Δx.","explain":"It is the strip width Δx in the limit."},{"type":"numeric","id":"m6","prompt":"∫ from 0 to {a} of f dx = {p} and ∫ from {a} to 10 of f dx = {q}. Find ∫ from 0 to 10 of f dx.","answer":"p+q","hint":"The two pieces join up.","explain":"{p} + {q} = {=p+q}.","params":{"a":[2,8],"p":[1,9],"q":[1,9]}},{"type":"mc","id":"m7","prompt":"As the number of strips grows, the sum of strip areas…","choices":["settles on the definite integral","grows without limit","becomes zero"],"answer":0,"hint":"The strips get thinner as well as more numerous.","explain":"The sum approaches a limit: that limit is the definite integral."}]},"status":"self-checked","visual":{"type":"area","caption":"Drag the two limits on y = 2 − x. Area above the x-axis counts as positive, area below as negative.","opts":{"mode":"definite","f":"2-x","a":0,"b":3,"xr":[-1,4],"yr":[-2.5,3.5]}}},"mt_ckLHNZCBUi":{"topicId":"mt_ckLHNZCBUi","title":"The fundamental theorem of calculus","audience":"learner","keyIdea":"The rate the area grows is the height of the curve, so integrating and differentiating undo each other: ∫ₐᵇ f dx = F(b) − F(a).","explain":{"kid":["Imagine painting the area under a curve, moving to the right. How fast does the painted area grow? As fast as the curve is tall.","So the area has gradient f. That means the area is an antiderivative of f. To find an area from a to b, find an antiderivative F and work out F(b) − F(a)."],"adult":["If A(x) = ∫ from a to x of f(t) dt, then A′(x) = f(x): a thin extra strip has area about f(x) × h, so (A(x + h) − A(x))/h → f(x).","Any two antiderivatives differ by a constant, so F(b) − F(a) is the same whichever F you pick; the + C cancels. Differentiation and integration are inverse processes."]},"familyTip":"Fill a tall thin glass and a wide bowl from the same tap. Which water level rises faster? Link the width to how fast the 'area' grows.","practice":[{"type":"mc","id":"p1","prompt":"A(x) is the area under f from 0 to x. What is A′(x)?","choices":["f(x)","A(x)²","0"],"answer":0,"hint":"How fast does the area grow?","explain":"The area grows at the rate of the curve's height: A′(x) = f(x)."},{"type":"numeric","id":"p2","prompt":"F(x) = x² has F′(x) = 2x. Find ∫ from {a} to {b} of 2x dx.","answer":"b*b-a*a","hint":"Work out F(b) − F(a).","explain":"F({b}) − F({a}) = {=b*b} − {=a*a} = {=b*b-a*a}.","params":{"a":[0,4],"b":[5,9]}},{"type":"numeric","id":"p3","prompt":"The height of f at x = {x} is {h}. How fast is the area A(x) growing there?","answer":"h","hint":"A′(x) = f(x).","explain":"A′({x}) = f({x}) = {h}.","params":{"x":[1,9],"h":[1,20]}},{"type":"mc","id":"p4","prompt":"Why does + C not matter in F(b) − F(a)?","choices":["It cancels when you subtract","C is always zero","You add it twice"],"answer":0,"hint":"Write (F(b) + C) − (F(a) + C).","explain":"The two Cs cancel, leaving F(b) − F(a)."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"∫ from 0 to {b} of 3x² dx = ?","answer":"b*b*b","hint":"An antiderivative of 3x² is x³.","explain":"[x³] from 0 to {b} = {=b*b*b}.","params":{"b":[1,5]}},{"type":"numeric","id":"m2","prompt":"∫ from 1 to {b} of 2x dx = ?","answer":"b*b-1","hint":"An antiderivative of 2x is x².","explain":"{=b*b} − 1 = {=b*b-1}.","params":{"b":[2,9]}},{"type":"mc","id":"m3","prompt":"Which pair of processes undo each other?","choices":["Differentiating and integrating","Adding and integrating","Squaring and differentiating"],"answer":0,"hint":"That is the theorem.","explain":"Differentiation and integration are inverse processes."},{"type":"numeric","id":"m4","prompt":"A(x) = ∫ from 0 to x of (t + {c}) dt. Find A′(4).","answer":"4+c","hint":"A′(x) is the curve's height at x.","explain":"A′(4) = 4 + {c} = {=4+c}.","params":{"c":[1,9]}},{"type":"mc","id":"m5","prompt":"If F′(x) = f(x), which equals ∫ from a to b of f(x) dx?","choices":["F(b) − F(a)","F(a) − F(b)","f(b) − f(a)"],"answer":0,"hint":"Top limit first.","explain":"F(b) − F(a)."},{"type":"numeric","id":"m6","prompt":"∫ from 0 to 2 of {=4*k}x³ dx = ?","answer":"16*k","hint":"An antiderivative is {k}x⁴.","explain":"{k} × 2⁴ − 0 = {=16*k}.","params":{"k":[1,5]}},{"type":"mc","id":"m7","prompt":"The area function A(x) grows fastest where…","choices":["f(x) is largest","f(x) is zero","x is zero"],"answer":0,"hint":"A′(x) = f(x).","explain":"Its gradient is f(x), so it rises fastest where f is biggest."}]},"status":"self-checked","visual":{"type":"area","caption":"Drag the right edge. The area graph (right) rises at a rate equal to the height of f (left).","opts":{"mode":"ftc","f":"x/2+1","a":0,"start":2,"xr":[0,4],"yr":[0,4],"ar":[0,9],"step":0.25}}},"mt_KceIV8SGuG":{"topicId":"mt_KceIV8SGuG","title":"Evaluating definite integrals","audience":"learner","keyIdea":"Integrate, write [F(x)] with the limits, then work out F(top) − F(bottom); the result is signed area.","explain":{"kid":["There are three steps. First, integrate each term. Second, put the answer in square brackets with the limits at the side. Third, put in the top number, then the bottom number, and take them away.","If part of the graph is below the x-axis, that part counts as minus. To find a total area, split the integral where the graph crosses the axis."],"adult":["∫ from 1 to 3 of x² dx = [x³/3] from 1 to 3 = 9 − 1/3 = 26/3. Leave out + C; it would cancel.","A negative answer means more signed area lies below the axis than above. For the geometric area, find the roots, integrate each piece separately, and add the sizes."]},"familyTip":"Check an answer with a sketch: is the region mostly above the axis (positive) or below (negative)? Is the size sensible?","practice":[{"type":"numeric","id":"p1","prompt":"∫ from 0 to {b} of 2x dx = ?","answer":"b*b","hint":"[x²] from 0 to {b}.","explain":"{=b*b} − 0 = {=b*b}.","params":{"b":[1,9]}},{"type":"numeric","id":"p2","prompt":"∫ from 1 to {b} of 3x² dx = ?","answer":"b*b*b-1","hint":"[x³] from 1 to {b}.","explain":"{=b*b*b} − 1 = {=b*b*b-1}.","params":{"b":[2,5]}},{"type":"mc","id":"p3","prompt":"[x²] from 1 to 3 means…","choices":["3² − 1²","1² − 3²","3² + 1²"],"answer":0,"hint":"Top limit first, then subtract.","explain":"F(3) − F(1) = 9 − 1 = 8."},{"type":"numeric","id":"p4","prompt":"∫ from 0 to {b} of (2x + {c}) dx = ?","answer":"b*b+c*b","hint":"[x² + {c}x] from 0 to {b}.","explain":"{=b*b} + {=c*b} = {=b*b+c*b}.","params":{"b":[1,6],"c":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"∫ from 0 to {b} of 4x³ dx = ?","answer":"b*b*b*b","hint":"[x⁴] from 0 to {b}.","explain":"{b}⁴ = {=b*b*b*b}.","params":{"b":[1,4]}},{"type":"numeric","id":"m2","prompt":"∫ from {a} to {b} of 6x dx = ?","answer":"3*(b*b-a*a)","hint":"[3x²] from {a} to {b}.","explain":"3 × {=b*b} − 3 × {=a*a} = {=3*(b*b-a*a)}.","params":{"a":[0,3],"b":[4,7]}},{"type":"numeric","id":"m3","prompt":"∫ from 0 to {b} of {k} dx = ?","answer":"k*b","hint":"[{k}x] from 0 to {b}.","explain":"{k} × {b} = {=k*b}.","params":{"k":[2,9],"b":[2,9]}},{"type":"mc","id":"m4","prompt":"∫ from 0 to 2 of (x² − 2x) dx is negative. Why?","choices":["The curve is below the x-axis between 0 and 2","Integrals are always negative","The limits are backwards"],"answer":0,"hint":"Try x = 1.","explain":"At x = 1 the curve is at −1: the whole piece from 0 to 2 lies below the axis."},{"type":"mc","id":"m5","prompt":"Do you need + C in a definite integral?","choices":["No, it cancels","Yes, always","Only if the answer is negative"],"answer":0,"hint":"(F(b) + C) − (F(a) + C).","explain":"It cancels, so leave it out."},{"type":"numeric","id":"m6","prompt":"∫ from 1 to {b} of 2x dx = ?","answer":"b*b-1","hint":"[x²] from 1 to {b}.","explain":"{=b*b} − 1 = {=b*b-1}.","params":{"b":[2,10]}},{"type":"numeric","id":"m7","prompt":"∫ from 0 to 1 of ({=3*a}x² + {=2*b}x) dx = ?","answer":"a+b","hint":"[{a}x³ + {b}x²] from 0 to 1.","explain":"{a} + {b} = {=a+b}.","params":{"a":[1,6],"b":[1,6]}}]},"status":"self-checked","visual":{"type":"area","caption":"Drag the limits on y = x² − 2x. The integral is F(b) − F(a) with F = x³/3 − x², and area below counts as negative.","opts":{"mode":"definite","f":"x*x-2*x","a":0,"b":3,"xr":[-1,4],"yr":[-2,5]}}},"mt_g7J4GJuLrf":{"topicId":"mt_g7J4GJuLrf","title":"Displacement and velocity by integration","audience":"learner","keyIdea":"Displacement is the integral of velocity, and velocity is the integral of acceleration; starting values fix the constants.","explain":{"kid":["On a speed–time graph, the area under the line is how far you went. Twice as fast for the same time gives twice the area.","If the velocity drops below zero, you are moving backwards. That area counts as minus for displacement, which is how far you are from the start. Total distance adds up every bit, forwards and backwards."],"adult":["s = ∫ v dt and v = ∫ a dt. Each integration adds a constant, fixed by initial conditions such as s = 0 and v = u when t = 0.","Displacement from t₁ to t₂ is ∫ v dt. Distance travelled is ∫ |v| dt: split at the times where v = 0 and add the size of each part."]},"familyTip":"Walk 5 steps forward and 3 back. Ask: how far did you walk, and how far are you from the start? Those are distance and displacement.","practice":[{"type":"numeric","id":"p1","prompt":"A car moves at a steady {v} m/s for {t} s. How far does it go, in metres?","answer":"v*t","hint":"Area of a rectangle on the velocity–time graph.","explain":"{v} × {t} = {=v*t} m.","params":{"v":[2,20],"t":[2,10]}},{"type":"numeric","id":"p2","prompt":"v = {=2*k}t m/s, starting at s = 0. Find s, in metres, at t = 3.","answer":"9*k","hint":"Integrate: s = {k}t² + C, and C = 0.","explain":"s = {k}t², so at t = 3, s = {k} × 9 = {=9*k} m.","params":{"k":[1,6]}},{"type":"mc","id":"p3","prompt":"The velocity–time graph dips below the axis. What is happening?","choices":["The object is moving backwards","It has stopped for good","It is speeding up forwards"],"answer":0,"hint":"Negative velocity means…","explain":"Negative velocity means moving in the opposite direction."},{"type":"numeric","id":"p4","prompt":"Acceleration is {a} m/s², starting from rest. Find v, in m/s, at t = {t}.","answer":"a*t","hint":"Integrate a: v = {a}t + C, and C = 0 from rest.","explain":"v = {a} × {t} = {=a*t} m/s.","params":{"a":[1,9],"t":[2,8]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"v = 3t² m/s, and s = {s} m at t = 0. Find s, in metres, at t = 2.","answer":"8+s","hint":"Integrate: s = t³ + C.","explain":"s = t³ + {s}, so s(2) = 8 + {s} = {=8+s} m.","params":{"s":[0,10]}},{"type":"mc","id":"m2","prompt":"Displacement is 0 m but distance is 10 m. What happened?","choices":["It went 5 m out and 5 m back","It never moved","It moved 10 m forwards"],"answer":0,"hint":"Back where it started.","explain":"It ended at the start (displacement 0) after travelling 10 m in total."},{"type":"numeric","id":"m3","prompt":"Walk forwards at 2 m/s for {a} s, then backwards at 2 m/s for {b} s. What is the displacement, in metres?","answer":"2*a-2*b","hint":"Forwards area minus backwards area.","explain":"{=2*a} − {=2*b} = {=2*a-2*b} m.","params":{"a":[3,9],"b":[1,5]},"where":"a>b"},{"type":"numeric","id":"m4","prompt":"Walk forwards at 2 m/s for {a} s, then backwards at 2 m/s for {b} s. What is the total distance, in metres?","answer":"2*a+2*b","hint":"Add both parts.","explain":"{=2*a} + {=2*b} = {=2*a+2*b} m.","params":{"a":[3,9],"b":[1,5]}},{"type":"mc","id":"m5","prompt":"How do you get velocity from acceleration?","choices":["Integrate a with respect to t","Differentiate a","Multiply a by s"],"answer":0,"hint":"Reverse of v → a.","explain":"a = dv/dt, so v = ∫ a dt."},{"type":"numeric","id":"m6","prompt":"v = {u} + {=2*a}t m/s. Find the displacement, in metres, from t = 0 to t = 2.","answer":"2*u+4*a","hint":"s = {u}t + {a}t².","explain":"At t = 2: {=2*u} + {=4*a} = {=2*u+4*a} m.","params":{"u":[1,9],"a":[1,5]}},{"type":"mc","id":"m7","prompt":"What fixes the + C when you integrate velocity?","choices":["Knowing the position at one time","Knowing the speed limit","Nothing; it is always zero"],"answer":0,"hint":"An initial condition.","explain":"A known position, such as s at t = 0, fixes C."}]},"status":"self-checked","visual":{"type":"area","caption":"Velocity v = 4 − t. Drag the end time: area above the axis is moving forwards, area below is moving back.","opts":{"mode":"velocity","f":"4-x","a":0,"b":6,"xr":[0,6.5],"yr":[-3,5],"ux":"m","tu":"s"}}},"mt_v0K6GRi4ZL":{"topicId":"mt_v0K6GRi4ZL","title":"Types of chemical reaction","audience":"learner","keyIdea":"Combustion is burning in oxygen; oxidation is gaining oxygen; thermal decomposition breaks a substance down with heat; displacement swaps in a more reactive metal.","explain":{"kid":["Chemists sort reactions into types. Combustion is burning. A fuel reacts with oxygen and gives out heat and light.","Oxidation means a substance gains oxygen, like iron when it rusts. Thermal decomposition means heat breaks one substance into simpler ones. Displacement means a more reactive metal pushes a less reactive metal out of its compound."],"adult":["Combustion is fast oxidation that gives out energy. Methane burns to make carbon dioxide and water. Rusting is slow oxidation of iron. It needs both air and water.","In thermal decomposition, heat splits one compound. Limestone (calcium carbonate) gives lime and carbon dioxide. In displacement, iron pushes copper out of copper sulfate, because iron is more reactive."]},"familyTip":"Spot reactions at home: the gas hob (combustion), a rusty bike chain (oxidation), baking powder in a hot oven (thermal decomposition).","practice":[{"type":"mc","id":"p1","prompt":"Which is a displacement reaction?","choices":["iron + copper sulfate → iron sulfate + copper","methane + oxygen → carbon dioxide + water","calcium carbonate → calcium oxide + carbon dioxide"],"answer":0,"hint":"One metal swaps places with another.","explain":"Iron takes copper's place in the compound because iron is more reactive."},{"type":"numeric","id":"p2","prompt":"Heating {=a+b} g of calcium carbonate leaves {a} g of calcium oxide. How many grams of carbon dioxide escaped?","answer":"b","hint":"Mass is conserved: the missing mass is the gas.","explain":"{=a+b} − {a} = {b} g of carbon dioxide.","params":{"a":[10,30],"b":[5,25]}},{"type":"numeric","id":"p3","prompt":"{a} g of magnesium is oxidised and gains {b} g of oxygen. What mass of magnesium oxide forms, in grams?","answer":"a+b","hint":"The oxide contains both.","explain":"{a} + {b} = {=a+b} g of magnesium oxide.","params":{"a":[2,12],"b":[1,8]}},{"type":"mc","id":"p4","prompt":"Which type of reaction uses heat to break one substance into two or more?","choices":["Thermal decomposition","Displacement","Combustion"],"answer":0,"hint":"'Thermal' means heat.","explain":"Thermal decomposition: heat breaks a compound down."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Rusting is an example of…","choices":["oxidation","thermal decomposition","displacement"],"answer":0,"hint":"Iron gains something from the air.","explain":"Iron gains oxygen (with water present): oxidation."},{"type":"mc","id":"m2","prompt":"Which metal can displace copper from copper sulfate solution?","choices":["Zinc","Gold","Silver"],"answer":0,"hint":"It must be more reactive than copper.","explain":"Zinc is more reactive than copper; gold and silver are less reactive."},{"type":"mc","id":"m3","prompt":"What does complete combustion of a fuel like methane produce?","choices":["Carbon dioxide and water","Hydrogen and oxygen","Only smoke"],"answer":0,"hint":"The carbon and hydrogen both join with oxygen.","explain":"Carbon → carbon dioxide; hydrogen → water."},{"type":"numeric","id":"m4","prompt":"A candle burns {a} g of wax using {b} g of oxygen. What total mass of products forms, in grams?","answer":"a+b","hint":"No mass is lost or gained.","explain":"{a} + {b} = {=a+b} g of products.","params":{"a":[2,9],"b":[5,20]}},{"type":"numeric","id":"m5","prompt":"Heating {=a+b} g of copper carbonate leaves {a} g of copper oxide. What mass of gas was given off, in grams?","answer":"b","hint":"The difference is the gas.","explain":"{=a+b} − {a} = {b} g.","params":{"a":[10,30],"b":[4,20]}},{"type":"mc","id":"m6","prompt":"Gold does not react with copper sulfate solution. Why?","choices":["Gold is less reactive than copper","Gold is a gas","Copper sulfate is not a compound"],"answer":0,"hint":"Displacement needs a more reactive metal.","explain":"Only a more reactive metal can push copper out, and gold is less reactive."},{"type":"mc","id":"m7","prompt":"Which word equation shows thermal decomposition?","choices":["calcium carbonate → calcium oxide + carbon dioxide","magnesium + oxygen → magnesium oxide","zinc + copper sulfate → zinc sulfate + copper"],"answer":0,"hint":"One reactant, two products.","explain":"One substance breaks into two when heated."}]},"status":"self-checked","visual":{"type":"sorter","caption":"Sort each everyday reaction into its type. Drag a card, or tap it and then tap a box.","opts":{"bins":["Combustion","Oxidation","Thermal decomposition","Displacement"],"items":[["Methane burns on a gas cooker",0],["A candle burns",0],["An iron nail slowly rusts",1],["Copper turns black when heated in air",1],["Heating limestone makes lime",2],["Heating green copper carbonate gives a black solid",2],["An iron nail in copper sulfate turns pink",3],["Zinc in copper sulfate solution goes coppery",3]]}},"lab":{"type":"reactlab","caption":"Try neutralisation, acid + metal and acid + carbonate. Test each gas.","opts":{"acid":1}}},"mt_1hgck6ucII":{"topicId":"mt_1hgck6ucII","title":"Physical vs chemical changes","audience":"learner","keyIdea":"A physical change makes no new substance and is usually reversible; a chemical change makes new substances. Mass is conserved in both.","explain":{"kid":["In a physical change, the stuff stays the same. Melted ice is still water. You can usually change it back.","In a chemical change, new substances are made. Burning wood makes ash, smoke and gases. Signs include a new colour, fizzing, light or heat. In both kinds of change, the total mass stays the same."],"adult":["Physical changes alter state, shape or mixing, but the particles themselves are unchanged, so they are usually reversible: melting, dissolving, evaporating.","Chemical changes rearrange atoms into new substances and are usually hard to reverse. Mass is conserved in both. If a gas escapes from an open container, the mass seems to drop, but the gas still has mass."]},"familyTip":"Cook together and name each change: butter melting (physical), toast browning (chemical), sugar dissolving in tea (physical).","practice":[{"type":"mc","id":"p1","prompt":"Which is a chemical change?","choices":["Toast going brown","Butter melting","Sugar dissolving"],"answer":0,"hint":"Is a new substance made?","explain":"Browning makes new substances; the others are physical changes."},{"type":"numeric","id":"p2","prompt":"{a} g of salt dissolves in {b} g of water. What is the mass of the solution, in grams?","answer":"a+b","hint":"Dissolving is physical: nothing is lost.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[5,40],"b":[50,200]}},{"type":"numeric","id":"p3","prompt":"{a} g of ice melts. What is the mass of the water, in grams?","answer":"a","hint":"Melting changes state, not mass.","explain":"Melting is a physical change, so the water still weighs {a} g.","params":{"a":[5,90]}},{"type":"mc","id":"p4","prompt":"Which is a sign of a chemical change?","choices":["A gas is given off and a new colour appears","The substance changes shape","Ice turns into water"],"answer":0,"hint":"Look for signs of a new substance.","explain":"Fizzing and a new colour show a new substance has formed."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Water boiling is a…","choices":["physical change","chemical change"],"answer":0,"hint":"Is the steam still water?","explain":"Steam is still water, so it is a physical change."},{"type":"mc","id":"m2","prompt":"Frying an egg is a…","choices":["chemical change","physical change"],"answer":0,"hint":"Can it be unfried?","explain":"New substances form in the egg, and it can't be undone."},{"type":"numeric","id":"m3","prompt":"{a} g of magnesium burns in a closed jar and uses {b} g of oxygen. What mass of magnesium oxide forms, in grams?","answer":"a+b","hint":"Mass is conserved in a closed jar.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[2,12],"b":[1,8]}},{"type":"numeric","id":"m4","prompt":"{a} g of sugar dissolves in {b} g of tea. What does the sweet tea weigh, in grams?","answer":"a+b","hint":"Add the masses.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[3,15],"b":[150,300]}},{"type":"mc","id":"m5","prompt":"Why is dissolving salt a physical change?","choices":["The salt is still there: evaporate the water and it comes back","A new substance forms","It can never be undone"],"answer":0,"hint":"Can you get the salt back?","explain":"Evaporating the water gets the salt back, so no new substance formed."},{"type":"mc","id":"m6","prompt":"When wood burns in an open fire, the ash weighs less than the wood. Why?","choices":["Gases escaped into the air","Mass was destroyed","Ash is lighter than air"],"answer":0,"hint":"Where did the missing mass go?","explain":"Carbon dioxide and water vapour went into the air; the mass still exists."},{"type":"mc","id":"m7","prompt":"Which change makes a new substance?","choices":["Rusting","Melting","Freezing"],"answer":0,"hint":"Changes of state don't make new substances.","explain":"Rust is a new substance, iron oxide."}]},"status":"self-checked","visual":{"type":"sorter","caption":"Sort each change: is a new substance made? Drag a card, or tap it and then tap a box.","opts":{"bins":["Physical change","Chemical change"],"items":[["Ice melting",0],["Salt dissolving in water",0],["Water boiling",0],["Cutting paper",0],["Wood burning",1],["Iron rusting",1],["Baking a cake",1],["Milk going sour",1]]}}},"mt_rbPioPELM1":{"topicId":"mt_rbPioPELM1","title":"Irreversible changes","audience":"learner","keyIdea":"Some changes make new materials that cannot easily be turned back, like burning, rusting and acid reactions.","explain":{"kid":["Some changes can be undone. Melted chocolate sets again when it cools. These are reversible changes.","Other changes make new materials that cannot turn back. Burnt toast stays burnt. Rust stays rust. Vinegar and baking soda fizz and make a gas. These are irreversible changes."],"adult":["Irreversible changes are chemical: new materials form. Clues include fizzing (a gas forms), a lasting colour change, heat or light given out, or a new smell.","Burning needs oxygen and makes new substances such as carbon dioxide, water and ash. Rusting needs iron, water and oxygen. Acids react with carbonates to release carbon dioxide."]},"familyTip":"Make a mini volcano with vinegar and bicarbonate of soda. Ask: can we get the vinegar back? Why not?","practice":[{"type":"mc","id":"p1","prompt":"Which change is irreversible?","choices":["Burning paper","Melting butter","Freezing juice"],"answer":0,"hint":"Which one makes new materials?","explain":"Burning makes ash and gases, which cannot turn back into paper."},{"type":"numeric","id":"p2","prompt":"A {a} g ice lolly melts. How much does the juice weigh, in grams?","answer":"a","hint":"Melting is reversible: nothing is lost.","explain":"The juice still weighs {a} g.","params":{"a":[20,90]}},{"type":"numeric","id":"p3","prompt":"{a} g of vinegar and {b} g of baking soda fizz inside a sealed bag. What do the bag's contents weigh afterwards, in grams?","answer":"a+b","hint":"The gas is trapped in the bag.","explain":"Nothing can escape, so it is {a} + {b} = {=a+b} g.","params":{"a":[20,80],"b":[2,10]}},{"type":"mc","id":"p4","prompt":"Which clue shows a new material has formed?","choices":["Bubbles of a new gas","It changed shape","It got wet"],"answer":0,"hint":"Look for something new.","explain":"A new gas means a new material: an irreversible change."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A bike chain rusting is…","choices":["irreversible","reversible"],"answer":0,"hint":"Can rust turn back into shiny iron by itself?","explain":"Rust is a new material, so the change is irreversible."},{"type":"mc","id":"m2","prompt":"What does iron need to rust?","choices":["Water and oxygen","Only heat","Only sunlight"],"answer":0,"hint":"Think of a wet nail in air.","explain":"Rusting needs both water and oxygen."},{"type":"numeric","id":"m3","prompt":"{a} g of candle wax is melted and then left to set. What mass of wax is there now, in grams?","answer":"a","hint":"Melting and setting are reversible.","explain":"No new material formed, so there is still {a} g.","params":{"a":[10,90]}},{"type":"numeric","id":"m4","prompt":"{a} g of chalk reacts with {b} g of acid in a sealed bottle. What do the contents weigh afterwards, in grams?","answer":"a+b","hint":"Sealed: nothing escapes.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[2,10],"b":[20,60]}},{"type":"mc","id":"m5","prompt":"How could you get sugar back after dissolving it in water?","choices":["Evaporate the water","Burn it","You can't"],"answer":0,"hint":"Dissolving is reversible.","explain":"Let the water evaporate and the sugar is left behind."},{"type":"mc","id":"m6","prompt":"Which is NOT a sign of an irreversible change?","choices":["Changing shape","A new smell","Bubbles of gas"],"answer":0,"hint":"Squashing clay doesn't make a new material.","explain":"A change of shape makes nothing new."},{"type":"mc","id":"m7","prompt":"Cooking an egg is irreversible because…","choices":["new substances form in the egg","the egg gets hot","the shell cracks"],"answer":0,"hint":"Can you uncook it?","explain":"Heat changes the egg into new substances that can't change back."}]},"status":"self-checked","visual":{"type":"sorter","caption":"Can it be undone? Sort each change into reversible or irreversible.","opts":{"bins":["Reversible","Irreversible"],"items":[["Melting chocolate",0],["Freezing water",0],["Dissolving sugar",0],["Puddles drying up",0],["Burning toast",1],["A bike rusting",1],["Baking soda fizzing in vinegar",1],["Cooking an egg",1]]}}},"mt_Ge4Wtg6QMM":{"topicId":"mt_Ge4Wtg6QMM","title":"Advanced material properties","audience":"learner","keyIdea":"Group materials by tested properties: conductivity, magnetism, hardness, solubility and transparency decide what each is used for.","explain":{"kid":["Materials have properties. Some are hard and some are soft. Some let light through. Some dissolve in water.","Metals let electricity and heat pass through them easily, so we call them conductors. Plastic, wood and rubber do not, so we call them insulators. Iron and steel are pulled by magnets, but most other metals are not."],"adult":["Group materials by tests, not guesses: a simple circuit with a bulb tests electrical conductivity, a magnet tests magnetism, and stirring in water tests solubility.","Properties decide uses. Copper is used for wires because it conducts electricity and bends easily. Pan handles are plastic or wood because they are thermal insulators."]},"familyTip":"Hunt the kitchen with a fridge magnet: which metal things does it stick to? (Steel cans yes, aluminium foil no.)","practice":[{"type":"mc","id":"p1","prompt":"Which material conducts electricity?","choices":["Copper","Plastic","Wood"],"answer":0,"hint":"Wires are made of it.","explain":"Copper is a metal and a good electrical conductor."},{"type":"mc","id":"p2","prompt":"Which object is attracted to a magnet?","choices":["An iron nail","An aluminium can","A copper coin"],"answer":0,"hint":"Only some metals are magnetic.","explain":"Iron is magnetic; aluminium and copper are not."},{"type":"numeric","id":"p3","prompt":"In a circuit test of {n} materials, {k} made the bulb light. How many are electrical insulators?","answer":"n-k","hint":"Insulators don't light the bulb.","explain":"{n} − {k} = {=n-k} insulators.","params":{"n":[6,12],"k":[1,5]}},{"type":"numeric","id":"p4","prompt":"{a} g of salt dissolves in some water, and the solution weighs {=a+b} g. What did the water weigh, in grams?","answer":"b","hint":"Dissolving keeps all the mass.","explain":"{=a+b} − {a} = {b} g of water.","params":{"a":[5,30],"b":[50,150]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Why are pan handles often plastic?","choices":["Plastic is a thermal insulator","Plastic conducts heat well","Plastic is magnetic"],"answer":0,"hint":"You hold the handle.","explain":"Plastic doesn't let heat through easily, so the handle stays cool."},{"type":"mc","id":"m2","prompt":"Which is transparent?","choices":["Clear glass","Wood","Steel"],"answer":0,"hint":"Can you see clearly through it?","explain":"Clear glass lets light straight through."},{"type":"mc","id":"m3","prompt":"Which dissolves in water?","choices":["Sugar","Sand","Plastic"],"answer":0,"hint":"Which one disappears when stirred?","explain":"Sugar is soluble; sand and plastic are not."},{"type":"mc","id":"m4","prompt":"Copper is used for wires because it…","choices":["conducts electricity and bends easily","is magnetic","dissolves in water"],"answer":0,"hint":"Two properties a wire needs.","explain":"Good conductor, and flexible enough to bend."},{"type":"numeric","id":"m5","prompt":"Of {n} spoons, {k} are steel and the rest are wooden. How many are electrical insulators?","answer":"n-k","hint":"Wood is an insulator.","explain":"{n} − {k} = {=n-k} wooden spoons.","params":{"n":[6,15],"k":[1,5]}},{"type":"numeric","id":"m6","prompt":"A magnet picks up {a} iron paper clips and {b} steel pins. How many magnetic objects is that?","answer":"a+b","hint":"Iron and steel are both magnetic.","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"mc","id":"m7","prompt":"Which test shows if a material conducts electricity?","choices":["Put it in a circuit with a bulb","Hold a magnet near it","Drop it in water"],"answer":0,"hint":"Electricity needs a circuit.","explain":"If the bulb lights, the material conducts."}]},"status":"self-checked","visual":{"type":"circuit","caption":"Put each material in the gap in the circuit. Does the bulb light?","opts":{"items":[["Copper wire",1],["Steel spoon",1],["Aluminium foil",1],["Pencil lead (graphite)",1],["Plastic ruler",0],["Wooden spoon",0],["Glass marble",0],["Rubber band",0]]}}},"mt_htAYR-iCFF":{"topicId":"mt_htAYR-iCFF","title":"Drawing particle diagrams","audience":"learner","keyIdea":"Draw particles as same-sized circles: neat and touching in solids, touching but jumbled in liquids, far apart and fast in gases.","explain":{"kid":["Everything is made of tiny particles, far too small to see. We draw them as small circles.","In a solid, draw the circles touching, in neat rows. In a liquid, draw them touching but jumbled. In a gas, draw just a few, far apart, with arrows to show they move fast."],"adult":["A good diagram shows arrangement, spacing and movement. Solid: regular and touching, vibrating in place. Liquid: touching but random, sliding past each other. Gas: far apart and random, moving quickly in all directions.","Keep the particles the same size in every state. Heating makes particles move faster; it does not make them bigger."]},"familyTip":"Use coins on a table: neat rows for a solid, a jumbled touching heap for a liquid, a few spread across the table for a gas.","practice":[{"type":"mc","id":"p1","prompt":"Which diagram shows a gas?","choices":["A few particles far apart, with arrows","Particles in neat touching rows","Particles touching but jumbled"],"answer":0,"hint":"Gases have big gaps.","explain":"Gas particles are far apart and move fast."},{"type":"mc","id":"p2","prompt":"When ice melts, do the particles get bigger?","choices":["No: they move more but stay the same size","Yes","They disappear"],"answer":0,"hint":"Heating changes movement, not size.","explain":"The particles are the same; they just move more freely."},{"type":"numeric","id":"p3","prompt":"A solid diagram has {r} rows of {c} particles. How many particles is that?","answer":"r*c","hint":"Rows × particles in each row.","explain":"{r} × {c} = {=r*c} particles.","params":{"r":[2,6],"c":[3,8]}},{"type":"numeric","id":"p4","prompt":"A sealed box of gas has {n} particles. The box is heated. How many particles are in it now?","answer":"n","hint":"Sealed: none get in or out.","explain":"Heating makes them faster, but there are still {n}.","params":{"n":[8,30]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"In which state are particles in a regular pattern?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Think of a crystal.","explain":"Solids have a regular arrangement."},{"type":"mc","id":"m2","prompt":"Which state flows and takes the shape of its container but keeps its volume?","choices":["Liquid","Solid","Gas"],"answer":0,"hint":"Pour it into a jug.","explain":"A liquid flows but its particles stay close together."},{"type":"mc","id":"m3","prompt":"Why can a gas be squashed?","choices":["There are big gaps between its particles","Its particles are soft","It has no particles"],"answer":0,"hint":"Look at the spacing.","explain":"The gaps let the particles be pushed closer together."},{"type":"numeric","id":"m4","prompt":"A solid with {r} rows of {c} particles melts. How many particles are in the liquid?","answer":"r*c","hint":"Melting doesn't add or remove particles.","explain":"Still {r} × {c} = {=r*c} particles.","params":{"r":[2,6],"c":[3,8]}},{"type":"numeric","id":"m5","prompt":"A sealed balloon holds {n} particles. It warms up in the sun. How many particles are there now?","answer":"n","hint":"Nothing gets in or out.","explain":"Still {n} particles; they just move faster.","params":{"n":[10,40]}},{"type":"mc","id":"m6","prompt":"What should arrows on a gas diagram show?","choices":["Fast movement in random directions","The particles growing","Particles standing still"],"answer":0,"hint":"Gas particles never stop.","explain":"Arrows show fast, random motion."},{"type":"mc","id":"m7","prompt":"What does heating do to particles?","choices":["Makes them move faster","Makes them bigger","Makes them heavier"],"answer":0,"hint":"Energy goes into movement.","explain":"Hotter particles move faster."}]},"status":"self-checked","visual":{"type":"particles","caption":"Change the temperature. Watch how the particles' arrangement, spacing and speed change, then draw what you see.","opts":{"name":"water","mp":0,"bp":100,"temp":-10}}},"mt_MVovx37Xct":{"topicId":"mt_MVovx37Xct","title":"Material properties vocabulary","audience":"learner","keyIdea":"Use exact words in pairs: transparent/translucent/opaque, conductor/insulator, soluble/insoluble, flexible/rigid, magnetic/non-magnetic.","explain":{"kid":["Scientists use exact words for properties. Transparent means you can see clearly through it. Translucent lets some light through, but things look blurry. Opaque lets no light through.","There are more words in pairs. A conductor lets heat or electricity through, and an insulator does not. Soluble means it dissolves, and insoluble means it does not. Flexible means it bends, and rigid means it does not."],"adult":["Precise words make comparisons clear: 'thermal insulator' says more than 'keeps warm'. Pair each word with its opposite: conductor/insulator, soluble/insoluble, flexible/rigid, magnetic/non-magnetic.","Use the words to justify a choice. A window needs a transparent, rigid, waterproof material, so glass is used. A tea cosy needs a flexible thermal insulator, so wool or fabric works."]},"familyTip":"Shine a torch through things at home: a glass, a tissue, a book. Name each one: transparent, translucent or opaque.","practice":[{"type":"mc","id":"p1","prompt":"Frosted glass lets light through, but you can't see clearly through it. It is…","choices":["translucent","transparent","opaque"],"answer":0,"hint":"Some light, blurry view.","explain":"Some light gets through but the view is blurred: translucent."},{"type":"mc","id":"p2","prompt":"Which word means 'does not dissolve'?","choices":["insoluble","soluble","flexible"],"answer":0,"hint":"'In-' means not.","explain":"Insoluble means it does not dissolve."},{"type":"numeric","id":"p3","prompt":"Out of {n} materials, {k} are opaque. How many let at least some light through?","answer":"n-k","hint":"Opaque ones let no light through.","explain":"{n} − {k} = {=n-k}.","params":{"n":[6,12],"k":[1,5]}},{"type":"numeric","id":"p4","prompt":"{a} g of soluble sugar is stirred into {b} g of water. What is the total mass, in grams?","answer":"a+b","hint":"Dissolving keeps all the mass.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[5,30],"b":[100,250]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A tea cosy should be made of a…","choices":["thermal insulator","electrical conductor","transparent material"],"answer":0,"hint":"It keeps the pot warm.","explain":"It must stop heat escaping: a thermal insulator."},{"type":"mc","id":"m2","prompt":"Rigid means…","choices":["it does not bend easily","it bends easily","it dissolves"],"answer":0,"hint":"The opposite of flexible.","explain":"Rigid is the opposite of flexible."},{"type":"mc","id":"m3","prompt":"Which is opaque?","choices":["A wooden door","A clear plastic bottle","A glass of water"],"answer":0,"hint":"No light gets through.","explain":"Wood lets no light through."},{"type":"mc","id":"m4","prompt":"An electrical conductor…","choices":["lets electricity flow through it","blocks electricity","is always magnetic"],"answer":0,"hint":"Think of a wire.","explain":"Conductors let electricity flow."},{"type":"numeric","id":"m5","prompt":"A test found {k} of {n} metals were magnetic. How many were non-magnetic?","answer":"n-k","hint":"Take the magnetic ones away.","explain":"{n} − {k} = {=n-k}.","params":{"n":[5,10],"k":[1,4]}},{"type":"numeric","id":"m6","prompt":"{a} g of insoluble sand is stirred into {b} g of water, then filtered out. What mass of sand is caught in the filter, in grams?","answer":"a","hint":"Insoluble: it doesn't dissolve.","explain":"All {a} g of sand is caught.","params":{"a":[5,50],"b":[100,200]}},{"type":"mc","id":"m7","prompt":"Which pair are opposites?","choices":["soluble / insoluble","transparent / translucent","flexible / magnetic"],"answer":0,"hint":"One word means 'not' the other.","explain":"Insoluble means not soluble."}]},"status":"self-checked","visual":{"type":"light","caption":"Hold each material in the torch beam. How much light reaches the screen?","opts":{"items":[["Clear window glass",0],["Cling film",0],["Tracing paper",1],["Frosted glass",1],["Tissue paper",1],["Wooden door",2],["Kitchen foil",2],["Cardboard",2]]}}},"mt_EDgw64OmfA":{"topicId":"mt_EDgw64OmfA","title":"Place value: × 10 and ÷ 10","audience":"learner","keyIdea":"Each place is worth ten times the place to its right, so × 10 moves every digit one place left and ÷ 10 moves it one place right.","explain":{"kid":["Each place is worth ten times the place on its right. A ten is ten ones. A one is ten tenths.","When you multiply by 10, every digit moves one place to the left. When you divide by 10, every digit moves one place to the right. The decimal point stays still. A zero holds an empty place."],"adult":["× 10 shifts each digit one column left: 4.7 × 10 = 47 and 4.7 × 100 = 470, with a zero as a placeholder. ÷ 10 shifts right: 47 ÷ 10 = 4.7 and 3 ÷ 100 = 0.03.","'Add a zero' fails for decimals: 4.7 × 10 is not 4.70. 'The digits move and the point stays' always works."]},"familyTip":"Write a number on paper strips, one digit per square, under a fixed decimal point. Slide the strip to multiply or divide by 10.","practice":[{"type":"numeric","id":"p1","prompt":"{=a/10} × 10 = ?","answer":"a","hint":"Every digit moves one place to the left.","explain":"{=a/10} × 10 = {a}.","params":{"a":[11,99]},"where":"a%10!=0"},{"type":"numeric","id":"p2","prompt":"{a} ÷ 10 = ?","answer":"a/10","hint":"Every digit moves one place to the right.","explain":"{a} ÷ 10 = {=a/10}.","params":{"a":[11,999]}},{"type":"mc","id":"p3","prompt":"In 352, what is the 5 worth?","choices":["50","5","500"],"answer":0,"hint":"Which column is it in?","explain":"The 5 is in the tens column, so it is worth 50."},{"type":"mc","id":"p4","prompt":"What is 4.7 × 10?","choices":["47","4.70","470"],"answer":0,"hint":"The digits move one place left.","explain":"4 ones become 4 tens; 7 tenths become 7 ones: 47."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"{a} × 100 = ?","answer":"a*100","hint":"Digits move two places left.","explain":"{a} × 100 = {=a*100}.","params":{"a":[2,99]}},{"type":"numeric","id":"m2","prompt":"{a} ÷ 100 = ?","answer":"a/100","hint":"Digits move two places right.","explain":"{a} ÷ 100 = {=a/100}.","params":{"a":[3,999]},"where":"a%10!=0"},{"type":"mc","id":"m3","prompt":"In 0.35, what is the 3 worth?","choices":["3 tenths","3 ones","3 hundredths"],"answer":0,"hint":"The first place after the point.","explain":"The first place after the point is tenths."},{"type":"numeric","id":"m4","prompt":"{=a/100} × 10 = ?","answer":"a/10","hint":"One place left.","explain":"{=a/100} × 10 = {=a/10}.","params":{"a":[11,99]},"where":"a%10!=0"},{"type":"mc","id":"m5","prompt":"A digit moves from the tens place to the hundreds place. What happened?","choices":["It was multiplied by 10","It was divided by 10","10 was added"],"answer":0,"hint":"Moving left makes it bigger.","explain":"One place left means ten times as much."},{"type":"mc","id":"m6","prompt":"What is 6 ÷ 100?","choices":["0.06","0.6","600"],"answer":0,"hint":"Two places right.","explain":"6 ones become 6 hundredths: 0.06."},{"type":"mc","id":"m7","prompt":"A digit in the hundreds place is worth how many times the same digit in the tens place?","choices":["10 times","100 times","One tenth"],"answer":0,"hint":"Next place to the left.","explain":"Each place is worth 10 times the one to its right."}]},"status":"self-checked","visual":{"type":"placevalue","caption":"Press × 10 or ÷ 10 and watch the digits slide. The decimal point stays put.","opts":{"n":4.7}}},"mt_4Km38F4L-6":{"topicId":"mt_4Km38F4L-6","title":"Fractions as division","audience":"learner","keyIdea":"a/b means a ÷ b: sharing a wholes equally between b people gives each person a/b.","explain":{"kid":["A fraction is a division. 3/4 means 3 ÷ 4.","Share 3 pizzas between 4 people. Cut each pizza into 4 slices. Each person takes one slice from each pizza. That is 3 slices, and each slice is a quarter, so each person gets 3/4 of a pizza."],"adult":["a/b = a ÷ b for any whole numbers. Sharing 7 cakes between 3 people gives 7/3 = 2 1/3 cakes each.","In word problems, decide what is being shared and between how many. The answer may be a fraction or a mixed number. Check: the answer times the number of people should give back the total."]},"familyTip":"Share 2 sandwiches between 3 people for real. How much does each person get? Write it as a fraction.","practice":[{"type":"mc","id":"p1","prompt":"5 ÷ 8 as a fraction is…","choices":["5/8","8/5","5/13"],"answer":0,"hint":"The top number is divided by the bottom.","explain":"5 ÷ 8 = 5/8."},{"type":"numeric","id":"p2","prompt":"{a} pizzas are shared equally by {b} people. How much pizza does each person get? Give a decimal.","answer":"a/b","hint":"Work out {a} ÷ {b}.","explain":"{a} ÷ {b} = {=a/b} of a pizza each.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"numeric","id":"p3","prompt":"{a} metres of ribbon is cut into {b} equal pieces. How long is each piece, in metres?","answer":"a/b","hint":"Length ÷ number of pieces.","explain":"{a} ÷ {b} = {=a/b} m.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"mc","id":"p4","prompt":"7 cakes are shared equally between 3 children. Each child gets…","choices":["2 1/3 cakes","3/7 of a cake","2 cakes, with 1 left over each"],"answer":0,"hint":"7 ÷ 3 = ?","explain":"7 ÷ 3 = 2 remainder 1, and the 1 left over is shared too: 2 1/3."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which equals 2/5?","choices":["2 ÷ 5","5 ÷ 2","2 × 5"],"answer":0,"hint":"Top ÷ bottom.","explain":"2/5 = 2 ÷ 5."},{"type":"numeric","id":"m2","prompt":"{a} litres of juice is poured equally into {b} bottles. How many litres go in each?","answer":"a/b","hint":"Divide the juice by the bottles.","explain":"{a} ÷ {b} = {=a/b} litres.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"mc","id":"m3","prompt":"4 ÷ 3 = ?","choices":["1 1/3","3/4","1 3/4"],"answer":0,"hint":"How many whole 3s fit in 4, and what is left?","explain":"4 ÷ 3 = 1 remainder 1 = 1 1/3."},{"type":"numeric","id":"m4","prompt":"{b} friends share {a} chocolate bars equally. How many bars does each get? Give a decimal.","answer":"a/b","hint":"Bars ÷ friends.","explain":"{a} ÷ {b} = {=a/b} bars each.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"},{"type":"mc","id":"m5","prompt":"3 pizzas are shared by 4 people. What does each person get?","choices":["3/4 of a pizza","4/3 of a pizza","1 pizza"],"answer":0,"hint":"3 ÷ 4.","explain":"3 ÷ 4 = 3/4."},{"type":"mc","id":"m6","prompt":"Which story fits 2/3?","choices":["2 sandwiches shared by 3 people","3 sandwiches shared by 2 people","2 sandwiches and 3 more"],"answer":0,"hint":"2/3 = 2 ÷ 3.","explain":"2 shared between 3 is 2 ÷ 3 = 2/3."},{"type":"numeric","id":"m7","prompt":"{a} kg of flour is split into {b} equal bags. How many kg go in each bag?","answer":"a/b","hint":"Flour ÷ bags.","explain":"{a} ÷ {b} = {=a/b} kg.","params":{"a":[1,9],"b":[2,5]},"where":"(a*100)%b==0 && a%b!=0"}]},"status":"self-checked","visual":{"type":"wholes","caption":"3 pizzas shared between 4 people. Press “Share out” to see why each person gets 3/4.","opts":{"a":3,"b":4}}},"mt_oDlduFnemk":{"topicId":"mt_oDlduFnemk","title":"Coordinates on a grid","audience":"learner","keyIdea":"(x, y) means go x across along the x-axis, then y up, starting from the origin (0, 0).","explain":{"kid":["A grid has two number lines. The x-axis goes across. The y-axis goes up. They meet at the origin, which is (0, 0).","A point is written (x, y). Go across first, then up. Think: along the corridor, then up the stairs. (3, 5) means 3 across and 5 up."],"adult":["The ordered pair (x, y) gives the distance across, then the distance up, from the origin. Order matters: (2, 5) and (5, 2) are different points.","Points on the x-axis have y = 0; points on the y-axis have x = 0. Distances along a grid line are easy: from (1, 4) to (6, 4) is 6 − 1 = 5 units."]},"familyTip":"Play battleships on squared paper. Call out coordinates as (across, up).","practice":[{"type":"mc","id":"p1","prompt":"Which point is 4 across and 2 up?","choices":["(4, 2)","(2, 4)","(4, 4)"],"answer":0,"hint":"Across first.","explain":"Across first, then up: (4, 2)."},{"type":"numeric","id":"p2","prompt":"How far is it from ({a}, 3) to ({b}, 3)?","answer":"b-a","hint":"Same height, so subtract the x-coordinates.","explain":"{b} − {a} = {=b-a} units.","params":{"a":[0,4],"b":[5,10]}},{"type":"numeric","id":"p3","prompt":"A point is {a} across and {b} up. What is its x-coordinate?","answer":"a","hint":"x is the across number.","explain":"The x-coordinate is {a}.","params":{"a":[1,9],"b":[1,9]},"where":"a!=b"},{"type":"mc","id":"p4","prompt":"Where is (0, 0)?","choices":["The origin, where the axes meet","The top right corner","Anywhere on the x-axis"],"answer":0,"hint":"Zero across, zero up.","explain":"(0, 0) is the origin."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"(5, 0) lies…","choices":["on the x-axis","on the y-axis","at the origin"],"answer":0,"hint":"y = 0 means no distance up.","explain":"It is 5 across and 0 up, so it is on the x-axis."},{"type":"numeric","id":"m2","prompt":"How far is it from (2, {a}) to (2, {b})?","answer":"b-a","hint":"Same x, so subtract the y-coordinates.","explain":"{b} − {a} = {=b-a} units.","params":{"a":[0,4],"b":[5,10]}},{"type":"mc","id":"m3","prompt":"In (3, 7), which number tells you how far up?","choices":["7","3","10"],"answer":0,"hint":"The second number.","explain":"y comes second: 7 up."},{"type":"numeric","id":"m4","prompt":"A square has corners (0, 0), ({s}, 0), ({s}, {s}) and (0, {s}). What is its perimeter?","answer":"4*s","hint":"Each side is {s} long.","explain":"4 × {s} = {=4*s} units.","params":{"s":[1,9]}},{"type":"mc","id":"m5","prompt":"Are (2, 6) and (6, 2) the same point?","choices":["No: the order matters","Yes","Only on a big grid"],"answer":0,"hint":"Across first, then up.","explain":"(2, 6) is 2 across; (6, 2) is 6 across. They are different."},{"type":"numeric","id":"m6","prompt":"A rectangle has corners (1, 1), ({a}, 1), ({a}, {b}) and (1, {b}). What is its area?","answer":"(a-1)*(b-1)","hint":"Width = {a} − 1, height = {b} − 1.","explain":"{=a-1} × {=b-1} = {=(a-1)*(b-1)} square units.","params":{"a":[3,9],"b":[3,9]}},{"type":"mc","id":"m7","prompt":"To plot (4, 1), you go…","choices":["4 across, then 1 up","4 up, then 1 across","1 across, then 4 up"],"answer":0,"hint":"Along the corridor, then up the stairs.","explain":"4 across, then 1 up."}]},"status":"self-checked","visual":{"type":"coords","caption":"Move the point to (3, 5). Drag it, or use the arrow keys: across first, then up.","opts":{"max":8,"x":0,"y":0,"target":[3,5]}},"lab":{"type":"geolab","caption":"Drag each corner onto a grid point. Read its coordinates (across, then up), then take the area challenges.","opts":{"pts":[[1,1],[5,1],[5,4]],"grid":1,"area":6}}},"mt_iEXqN48w3x":{"topicId":"mt_iEXqN48w3x","title":"Percentage increase and decrease","audience":"learner","keyIdea":"Use a multiplier: increase by r% means × (1 + r/100), decrease means × (1 − r/100); divide by it to find the original.","explain":{"kid":["To increase by 20%, the new amount is 120% of the old one. So multiply by 1.2.","To decrease by 20%, the new amount is 80% of the old one. So multiply by 0.8. To get back to the start, divide by the multiplier. Do not just take 20% off again."],"adult":["A percentage change uses a multiplier: increase by r% → × (1 + r/100); decrease by r% → × (1 − r/100). Repeated changes multiply: +10% then −10% is × 1.1 × 0.9 = × 0.99.","Reverse percentages: if a price after a 25% rise is £150, the original is 150 ÷ 1.25 = £120. Simple interest adds the same amount each year: interest = amount × rate × years."]},"familyTip":"In a shop, spot a 'was £x, now £y' label. Work out the percentage cut together.","practice":[{"type":"numeric","id":"p1","prompt":"Increase {a} by 10%.","answer":"a*11/10","hint":"Multiply by 1.1.","explain":"{a} × 1.1 = {=a*11/10}.","params":{"a":[20,200]}},{"type":"numeric","id":"p2","prompt":"Decrease {a} by 25%.","answer":"a*3/4","hint":"Multiply by 0.75.","explain":"{a} × 0.75 = {=a*3/4}.","params":{"a":[4,200]},"where":"a%4==0"},{"type":"mc","id":"p3","prompt":"A price rises by 20% to £60. What was it before?","choices":["£50","£48","£40"],"answer":0,"hint":"Divide by 1.2.","explain":"60 ÷ 1.2 = 50."},{"type":"numeric","id":"p4","prompt":"£{=p*100} earns 5% simple interest each year. How much interest, in £, after {y} years?","answer":"p*5*y","hint":"5% of the amount, times the years.","explain":"5% of £{=p*100} is £{=p*5}; × {y} years = £{=p*5*y}.","params":{"p":[1,9],"y":[1,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Increase {a} by {r}%.","answer":"a*(100+r)/100","hint":"Multiply by 1 + {r}/100.","explain":"{a} × {=(100+r)/100} = {=a*(100+r)/100}.","params":{"a":[10,300],"r":[5,50]},"where":"r%5==0"},{"type":"numeric","id":"m2","prompt":"Decrease {a} by {r}%.","answer":"a*(100-r)/100","hint":"Multiply by 1 − {r}/100.","explain":"{a} × {=(100-r)/100} = {=a*(100-r)/100}.","params":{"a":[10,300],"r":[5,50]},"where":"r%5==0"},{"type":"mc","id":"m3","prompt":"Which multiplier decreases an amount by 15%?","choices":["0.85","1.15","0.15"],"answer":0,"hint":"100% − 15%.","explain":"85% = 0.85."},{"type":"numeric","id":"m4","prompt":"After a {r}% increase, a bike costs £{=c*(100+r)/100}. What was the original price, in £?","answer":"c","hint":"Divide by {=(100+r)/100}.","explain":"£{=c*(100+r)/100} ÷ {=(100+r)/100} = £{c}.","params":{"c":[50,500],"r":[5,40]},"where":"(c*(100+r))%100==0 && r%5==0"},{"type":"mc","id":"m5","prompt":"A price goes up 10%, then down 10%. Compared with the start it is…","choices":["99% of the start","100% of the start","90% of the start"],"answer":0,"hint":"1.1 × 0.9.","explain":"1.1 × 0.9 = 0.99, so 99%."},{"type":"numeric","id":"m6","prompt":"Simple interest: £{=p*100} at {r}% a year for {y} years. What is the total interest, in £?","answer":"p*r*y","hint":"Interest each year is {r}% of £{=p*100}.","explain":"£{=p*r} a year × {y} years = £{=p*r*y}.","params":{"p":[1,9],"r":[1,9],"y":[1,5]}},{"type":"mc","id":"m7","prompt":"A shirt is reduced by 30% to £28. What was the original price?","choices":["£40","£36.40","£58"],"answer":0,"hint":"£28 is 70% of the original.","explain":"28 ÷ 0.7 = 40."}]},"status":"self-checked","visual":{"type":"percent","caption":"Slide the percentage change. The new bar is the old one times the multiplier.","opts":{"mode":"change","p":20,"of":80}}},"mt_P8Da-_zGBG":{"topicId":"mt_P8Da-_zGBG","title":"Charges and masses of subatomic particles","audience":"learner","keyIdea":"Protons (+1, mass 1) and neutrons (0, mass 1) sit in the tiny nucleus; electrons (−1, mass almost 0) are outside it.","explain":{"kid":["An atom has a tiny nucleus in the middle. It holds protons and neutrons. Electrons move around the outside in shells.","A proton has a charge of +1. An electron has a charge of −1. A neutron has no charge. Protons and neutrons each have a mass of 1. An electron is so light that we say its mass is almost 0."],"adult":["Relative charges: proton +1, neutron 0, electron −1. Relative masses: proton 1, neutron 1, electron about 1/1840.","Atoms are neutral because they have equal numbers of protons and electrons. Mass number = protons + neutrons. An ion forms when an atom gains or loses electrons: lose one and the charge is +1."]},"familyTip":"Make a table with three rows (proton, neutron, electron) and two columns (charge, mass). Cover it and test each other.","practice":[{"type":"mc","id":"p1","prompt":"Which particle has no charge?","choices":["Neutron","Proton","Electron"],"answer":0,"hint":"'Neutral' sounds like…","explain":"The neutron is neutral."},{"type":"numeric","id":"p2","prompt":"An atom has {p} protons and {n} neutrons. What is its mass number?","answer":"p+n","hint":"Mass number = protons + neutrons.","explain":"{p} + {n} = {=p+n}.","params":{"p":[1,20],"n":[0,22]}},{"type":"numeric","id":"p3","prompt":"A neutral atom has {p} protons. How many electrons does it have?","answer":"p","hint":"Neutral means the charges balance.","explain":"It has {p} electrons to balance {p} protons.","params":{"p":[1,20]}},{"type":"mc","id":"p4","prompt":"Where is almost all of an atom's mass?","choices":["In the nucleus","In the electron shells","Spread out evenly"],"answer":0,"hint":"Electrons are almost massless.","explain":"Protons and neutrons are in the nucleus, and they carry the mass."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"What is the relative mass of an electron?","choices":["Almost 0 (about 1/1840)","1","−1"],"answer":0,"hint":"Much lighter than a proton.","explain":"About 1/1840, so almost 0."},{"type":"numeric","id":"m2","prompt":"An atom has mass number {m} and {p} protons. How many neutrons does it have?","answer":"m-p","hint":"Neutrons = mass number − protons.","explain":"{m} − {p} = {=m-p} neutrons.","params":{"p":[1,20],"m":[2,45]},"where":"m>=p && m<=2*p+4"},{"type":"numeric","id":"m3","prompt":"An ion has {p} protons and {=p-d} electrons. What is its charge?","answer":"d","hint":"Charge = protons − electrons.","explain":"{p} − {=p-d} = +{d}, so the charge is {d}+.","params":{"p":[3,20],"d":[1,3]}},{"type":"mc","id":"m4","prompt":"An atom has no overall charge because…","choices":["it has equal numbers of protons and electrons","it has no protons","neutrons cancel the charge"],"answer":0,"hint":"+1s and −1s.","explain":"Equal numbers of +1 and −1 charges cancel out."},{"type":"mc","id":"m5","prompt":"What is the relative charge of a proton?","choices":["+1","0","−1"],"answer":0,"hint":"Protons are positive.","explain":"+1."},{"type":"mc","id":"m6","prompt":"Which two particles are in the nucleus?","choices":["Protons and neutrons","Protons and electrons","Neutrons and electrons"],"answer":0,"hint":"Electrons are in shells.","explain":"Protons and neutrons."},{"type":"numeric","id":"m7","prompt":"A nucleus has {p} protons and {n} neutrons. What is the nucleus's total relative charge?","answer":"p","hint":"Only the protons are charged.","explain":"{p} protons × +1 = +{p}, so the charge is {p}.","params":{"p":[1,20],"n":[0,22]}}]},"status":"self-checked","visual":{"type":"atom","caption":"Add or remove protons, neutrons and electrons. Watch the element, the charge and the mass number change.","opts":{"p":3,"n":4,"e":3}}},"mt_AN2kJE6I0s":{"topicId":"mt_AN2kJE6I0s","title":"Acids, alkalis and pH","audience":"learner","keyIdea":"pH runs from 0 to 14: below 7 is acidic, 7 is neutral, above 7 is alkaline; indicators show it with colour.","explain":{"kid":["The pH scale runs from 0 to 14. Below 7 is acid, 7 is neutral, and above 7 is alkali.","An indicator changes colour to show pH. Universal indicator is red in strong acid, green when neutral, and purple in strong alkali. Lemon juice is an acid. Soap is an alkali."],"adult":["Acids release hydrogen ions (H⁺) in water; alkalis release hydroxide ions (OH⁻). The more H⁺, the lower the pH. Each step of 1 on the scale is a tenfold change in H⁺.","Neutralisation: acid + alkali → salt + water, because H⁺ and OH⁻ join to make water. Litmus only says acid or alkali; universal indicator or a pH probe gives a number."]},"familyTip":"Make red-cabbage indicator: boil chopped red cabbage, cool and strain. Test vinegar, soap and baking soda and compare the colours.","practice":[{"type":"mc","id":"p1","prompt":"pH 2 is…","choices":["strongly acidic","neutral","alkaline"],"answer":0,"hint":"Far below 7.","explain":"pH 2 is well below 7: a strong acid."},{"type":"mc","id":"p2","prompt":"What colour is universal indicator in pure water?","choices":["Green","Red","Purple"],"answer":0,"hint":"Pure water is pH 7.","explain":"Neutral pH 7 shows green."},{"type":"numeric","id":"p3","prompt":"A solution changes from pH {a} to pH {=a-d}. How many times more hydrogen ions does it have now?","answer":"10**d","hint":"Each pH step is × 10.","explain":"{d} steps of × 10 make {=10**d} times more.","params":{"a":[5,9],"d":[1,3]}},{"type":"numeric","id":"p4","prompt":"{a} cm³ of acid is exactly neutralised by {b} cm³ of alkali. What volume of solution is there, in cm³?","answer":"a+b","hint":"Add the volumes.","explain":"{a} + {b} = {=a+b} cm³.","params":{"a":[5,50],"b":[5,50]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which pH is neutral?","choices":["7","0","14"],"answer":0,"hint":"The middle of the scale.","explain":"pH 7 is neutral."},{"type":"mc","id":"m2","prompt":"Which ions do acids release in water?","choices":["H⁺","OH⁻","Na⁺"],"answer":0,"hint":"Hydrogen ions.","explain":"Acids release H⁺ ions."},{"type":"mc","id":"m3","prompt":"acid + alkali → ?","choices":["salt + water","gas + oxygen","acid + water"],"answer":0,"hint":"Neutralisation.","explain":"They make a salt and water."},{"type":"numeric","id":"m4","prompt":"Solution A is pH {a} and B is pH {=a+d}. How many times more hydrogen ions does A have?","answer":"10**d","hint":"Lower pH means more H⁺; each step is × 10.","explain":"{d} steps: {=10**d} times more.","params":{"a":[1,5],"d":[1,3]}},{"type":"mc","id":"m5","prompt":"Which is most likely to be pH 13?","choices":["Oven cleaner","Lemon juice","Pure water"],"answer":0,"hint":"Strong alkalis clean grease.","explain":"Oven cleaner is a strong alkali."},{"type":"numeric","id":"m6","prompt":"Adding alkali drop by drop, an acid turns green after {a} drops. How many drops would neutralise twice as much of the same acid?","answer":"2*a","hint":"Twice the acid needs twice the alkali.","explain":"2 × {a} = {=2*a} drops.","params":{"a":[5,30]}},{"type":"mc","id":"m7","prompt":"Litmus paper can tell you…","choices":["only whether it is acid or alkali","the exact pH number","the temperature"],"answer":0,"hint":"Litmus has only two colours.","explain":"Red or blue: acid or alkali, not the number."}]},"status":"self-checked","visual":{"type":"phscale","caption":"Drag the pointer or add acid and alkali. The indicator colour shows the pH.","opts":{"ph":3}},"lab":{"type":"reactlab","caption":"Mix acid and alkali with universal indicator. Watch the colour, temperature and bubbles, then test the gas.","opts":{"acid":1,"indicator":true}}},"mt_UoqUPI_uNz":{"topicId":"mt_UoqUPI_uNz","title":"Reactions that release or absorb heat","audience":"learner","keyIdea":"Exothermic reactions give energy out (temperature rises); endothermic reactions take energy in (temperature falls).","explain":{"kid":["Some reactions give out heat. They are called exothermic, and the mixture gets warmer. Burning is exothermic.","Some reactions take in heat. They are called endothermic, and the mixture gets colder. Sherbet fizzing on your tongue feels cool because it takes in heat."],"adult":["Exothermic: energy goes out to the surroundings, so the temperature rises. The products have less energy than the reactants. Examples: burning, neutralisation, hand warmers.","Endothermic: energy is taken in, so the temperature falls. The products have more energy. Examples: heating limestone, photosynthesis and cold packs. Every reaction needs some energy to start. That is the hump on the energy profile."]},"familyTip":"Feel a hand warmer, then a cold pack. Which gives energy to your hand, and which takes it away?","practice":[{"type":"mc","id":"p1","prompt":"The temperature rises from 20 °C to 31 °C. The reaction is…","choices":["exothermic","endothermic"],"answer":0,"hint":"Did it get warmer?","explain":"It got warmer, so energy was given out: exothermic."},{"type":"numeric","id":"p2","prompt":"A reaction starts at {a} °C and ends at {=a+d} °C. By how many degrees did it warm up?","answer":"d","hint":"End − start.","explain":"{=a+d} − {a} = {d} degrees, so it is exothermic.","params":{"a":[15,25],"d":[2,20]}},{"type":"numeric","id":"p3","prompt":"The temperature falls from {a} °C to {=a-d} °C. By how many degrees did it fall?","answer":"d","hint":"Start − end.","explain":"{a} − {=a-d} = {d} degrees, so it is endothermic.","params":{"a":[18,25],"d":[2,12]}},{"type":"mc","id":"p4","prompt":"Which is endothermic?","choices":["Heating limestone to break it down","Burning methane","Neutralising an acid"],"answer":0,"hint":"Which one needs heat put in all the time?","explain":"Thermal decomposition takes in heat."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"In an exothermic reaction the products have…","choices":["less energy than the reactants","more energy than the reactants","the same energy"],"answer":0,"hint":"Energy went out.","explain":"Energy left, so the products have less."},{"type":"mc","id":"m2","prompt":"A hand warmer uses a reaction that is…","choices":["exothermic","endothermic"],"answer":0,"hint":"It warms your hand.","explain":"It gives out heat: exothermic."},{"type":"numeric","id":"m3","prompt":"The reactants have {a} kJ of energy and the products have {=a-d} kJ. How much energy is given out, in kJ?","answer":"d","hint":"Reactants − products.","explain":"{a} − {=a-d} = {d} kJ given out.","params":{"a":[100,200],"d":[10,90]}},{"type":"numeric","id":"m4","prompt":"A cold pack drops from {a} °C to {b} °C. How many degrees did it fall?","answer":"a-b","hint":"Start − end.","explain":"{a} − {b} = {=a-b} degrees.","params":{"a":[18,25],"b":[2,12]}},{"type":"mc","id":"m5","prompt":"What is activation energy?","choices":["The energy needed to start a reaction","The energy given out at the end","The energy of the products"],"answer":0,"hint":"The hump on the profile.","explain":"It is the energy needed to get the reaction going."},{"type":"mc","id":"m6","prompt":"Why does sherbet feel cold on your tongue?","choices":["Its reaction takes in heat from your tongue","It is kept in a freezer","It is exothermic"],"answer":0,"hint":"Endo means 'in'.","explain":"The fizzing reaction is endothermic, so it takes in heat."},{"type":"mc","id":"m7","prompt":"On the energy profile of an endothermic reaction, the products are…","choices":["higher than the reactants","lower than the reactants","level with the reactants"],"answer":0,"hint":"Energy was taken in.","explain":"They have gained energy, so they sit higher."}]},"status":"self-checked","visual":{"type":"energy","caption":"Drag the products' energy level up or down. Watch what happens to the temperature of the surroundings.","opts":{"dh":-40,"reactants":"reactants","products":"products"}}},"mt_OUv-QXmW7_":{"topicId":"mt_OUv-QXmW7_","title":"Reading distance–time graphs","audience":"learner","keyIdea":"On a distance–time graph, flat means stopped, steeper means faster, and the gradient is the speed.","explain":{"kid":["A distance–time graph shows how far you are from the start at each moment. Time goes across. Distance goes up.","A flat line means you have stopped. A line going up means you are moving away. A steeper line means faster. A line going down means you are coming back."],"adult":["The gradient of a distance–time graph is the speed: distance ÷ time for that section. A straight line means a steady speed.","Average speed for the whole trip = total distance ÷ total time, including stops. A curved line means the speed is changing; the gradient of the tangent gives the speed at that moment."]},"familyTip":"Sketch a graph of your walk to school: where did you stop, and where did you hurry?","practice":[{"type":"mc","id":"p1","prompt":"A flat line on a distance–time graph means…","choices":["stopped","steady speed","speeding up"],"answer":0,"hint":"The distance isn't changing.","explain":"No change in distance: not moving."},{"type":"numeric","id":"p2","prompt":"A cyclist rides {d} km in {t} hours at a steady speed. What is the speed in km/h?","answer":"d/t","hint":"Speed = distance ÷ time.","explain":"{d} ÷ {t} = {=d/t} km/h.","params":{"d":[6,60],"t":[2,5]},"where":"d%t==0"},{"type":"numeric","id":"p3","prompt":"A line rises from 0 to {d} m in {t} s. What is its gradient (the speed in m/s)?","answer":"d/t","hint":"Gradient = rise ÷ run.","explain":"{d} ÷ {t} = {=d/t} m/s.","params":{"d":[10,90],"t":[2,5]},"where":"(d*100)%t==0"},{"type":"mc","id":"p4","prompt":"Which line shows the fastest movement?","choices":["The steepest one","The flattest one","The longest one"],"answer":0,"hint":"Gradient = speed.","explain":"The steepest line covers the most distance per unit of time."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A walk: {a} km in 1 hour, a 30-minute stop, then {b} km in 1 hour. What is the average speed in km/h for the whole 2.5 hours?","answer":"(a+b)/2.5","hint":"Total distance ÷ total time.","explain":"({a} + {b}) ÷ 2.5 = {=(a+b)/2.5} km/h.","params":{"a":[2,6],"b":[2,6]}},{"type":"mc","id":"m2","prompt":"A line sloping down towards the time axis means…","choices":["returning towards the start","speeding up away","stopped"],"answer":0,"hint":"The distance from the start is shrinking.","explain":"Getting closer to the start."},{"type":"numeric","id":"m3","prompt":"A section rises {d} km in {t} minutes. What is the speed in km per minute?","answer":"d/t","hint":"Rise ÷ run.","explain":"{d} ÷ {t} = {=d/t} km per minute.","params":{"d":[1,9],"t":[2,5]},"where":"(d*100)%t==0"},{"type":"mc","id":"m4","prompt":"A curve that gets steeper and steeper shows…","choices":["speeding up","slowing down","stopped"],"answer":0,"hint":"Steeper means faster.","explain":"The speed is increasing."},{"type":"numeric","id":"m5","prompt":"At a steady {v} m/s for {t} s, how far do you go, in metres?","answer":"v*t","hint":"Distance = speed × time.","explain":"{v} × {t} = {=v*t} m.","params":{"v":[2,12],"t":[3,20]}},{"type":"mc","id":"m6","prompt":"How do you find the speed from a straight section?","choices":["Distance ÷ time for that section","Distance × time","Time ÷ distance"],"answer":0,"hint":"It's the gradient.","explain":"Speed = distance ÷ time."},{"type":"numeric","id":"m7","prompt":"The graph is flat from minute {a} to minute {b}. How long was the stop, in minutes?","answer":"b-a","hint":"End − start.","explain":"{b} − {a} = {=b-a} minutes.","params":{"a":[2,15],"b":[16,30]}}]},"status":"self-checked","visual":{"type":"journey","caption":"Drag along the graph or press Play. Watch the walker: flat means stopped, steep means fast, down means going home.","opts":{"pts":[[0,0],[10,1],[15,1],[20,1.5],[30,0]],"tu":"min","du":"km","step":1}}},"mt_RVK655t391":{"topicId":"mt_RVK655t391","title":"Measuring temperature with negative numbers","audience":"learner","keyIdea":"Below zero is negative; to find a change across zero, count to zero first and then on.","explain":{"kid":["Temperatures below zero are negative. −5 °C is five degrees colder than 0 °C.","To find a change across zero, count to zero first, then count on. From −5 °C to 8 °C is 5 up to zero, then 8 more. That is a rise of 13 degrees."],"adult":["Negative numbers measure below a zero point: temperature, money owed, depth below sea level. The bigger the number after the minus sign, the lower the value: −12 is colder than −3.","Difference = higher − lower, even with negatives: 8 − (−5) = 13. A number line or a thermometer makes the step through zero easy to see."]},"familyTip":"Check the weather forecast for a cold city. Find the difference between the night and day temperatures.","practice":[{"type":"numeric","id":"p1","prompt":"It is −{a} °C at night and {b} °C at noon. How many degrees did it rise?","answer":"a+b","hint":"Count up to zero, then on.","explain":"{a} up to zero, then {b} more: {=a+b} degrees.","params":{"a":[1,10],"b":[1,15]}},{"type":"numeric","id":"p2","prompt":"How many degrees is the drop from {b} °C to −{a} °C?","answer":"a+b","hint":"Down to zero, then below.","explain":"{b} down to zero, then {a} more: {=a+b} degrees.","params":{"a":[1,10],"b":[1,15]}},{"type":"mc","id":"p3","prompt":"Which is coldest?","choices":["−8 °C","−3 °C","0 °C"],"answer":0,"hint":"Further below zero is colder.","explain":"−8 is the furthest below zero."},{"type":"mc","id":"p4","prompt":"Which order goes from coldest to warmest?","choices":["−7, −2, 0, 4","0, −2, −7, 4","4, 0, −2, −7"],"answer":0,"hint":"Start with the most negative.","explain":"−7 < −2 < 0 < 4."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"It warms from −{a} °C to −{b} °C. How many degrees did it rise?","answer":"a-b","hint":"Both are below zero.","explain":"From −{a} up to −{b} is {=a-b} degrees.","params":{"a":[5,15],"b":[1,4]}},{"type":"numeric","id":"m2","prompt":"A freezer is at −{a} °C and the kitchen is at {b} °C. How many degrees warmer is the kitchen?","answer":"a+b","hint":"Count through zero.","explain":"{a} + {b} = {=a+b} degrees warmer.","params":{"a":[10,25],"b":[15,25]}},{"type":"mc","id":"m3","prompt":"A diver is at −20 m. A bird is at 15 m. How far apart are they?","choices":["35 m","5 m","−5 m"],"answer":0,"hint":"Count through sea level (0).","explain":"20 + 15 = 35 m."},{"type":"mc","id":"m4","prompt":"Which is warmest?","choices":["−1 °C","−10 °C","−4 °C"],"answer":0,"hint":"Closest to zero.","explain":"−1 is the closest to zero, so it is warmest."},{"type":"numeric","id":"m5","prompt":"Overnight it falls {d} degrees from {a} °C and ends below zero. How many degrees below zero is it?","answer":"d-a","hint":"First {a} degrees take it to zero.","explain":"It ends at −{=d-a} °C, which is {=d-a} below zero.","params":{"a":[1,9],"d":[10,20]}},{"type":"mc","id":"m6","prompt":"What is 3 − 8?","choices":["−5","5","−11"],"answer":0,"hint":"Start at 3 and go down 8.","explain":"3 down to 0, then 5 more: −5."},{"type":"numeric","id":"m7","prompt":"A bank balance is −£{a}. You pay in £{b}. What is the balance now, in £?","answer":"b-a","hint":"First £{a} brings it to zero.","explain":"−{a} + {b} = £{=b-a}.","params":{"a":[5,40],"b":[50,90]}}]},"status":"self-checked","visual":{"type":"thermo","caption":"The dashed line is 8 °C. Drag the thermometer, or press Colder and Warmer, and read the change across zero.","opts":{"min":-20,"max":40,"t":-5,"from":8,"step":1}}},"mt_boNo2FHDNR":{"topicId":"mt_boNo2FHDNR","title":"Velocity–time graphs","audience":"learner","keyIdea":"On a velocity–time graph, the gradient is the acceleration and the area underneath is the displacement.","explain":{"kid":["A velocity–time graph shows how fast something moves at each moment. Time goes across and velocity goes up.","A flat line means a steady speed. A line going up means speeding up. The steepness tells you the acceleration. The area under the line tells you how far it went."],"adult":["Gradient = change in velocity ÷ time taken = acceleration, in m/s². A negative gradient is a deceleration.","Area under the graph = displacement. Split it into rectangles and triangles: a car accelerating from rest to 10 m/s in 4 s travels ½ × 4 × 10 = 20 m."]},"familyTip":"On a car journey, note the speed every 10 seconds. Sketch the graph and find where the car sped up, slowed down and cruised.","practice":[{"type":"mc","id":"p1","prompt":"A flat line on a velocity–time graph means…","choices":["moving at a steady speed","stopped","speeding up"],"answer":0,"hint":"The velocity is not changing.","explain":"Constant velocity: steady speed, not necessarily stopped."},{"type":"numeric","id":"p2","prompt":"Velocity rises from 0 to {v} m/s in {t} s. What is the acceleration in m/s²?","answer":"v/t","hint":"Gradient = change in velocity ÷ time.","explain":"{v} ÷ {t} = {=v/t} m/s².","params":{"v":[4,30],"t":[2,5]},"where":"(v*100)%t==0"},{"type":"numeric","id":"p3","prompt":"A runner moves at a steady {v} m/s for {t} s. What area is under the graph, in metres?","answer":"v*t","hint":"A rectangle: velocity × time.","explain":"{v} × {t} = {=v*t} m.","params":{"v":[2,9],"t":[5,20]}},{"type":"mc","id":"p4","prompt":"What does the area under a velocity–time graph give?","choices":["Displacement","Acceleration","Speed"],"answer":0,"hint":"Velocity × time = ?","explain":"Velocity × time is distance moved, so the area gives displacement."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A car accelerates steadily from rest to {v} m/s in {t} s. How far does it go, in metres?","answer":"v*t/2","hint":"Area of a triangle: ½ × base × height.","explain":"½ × {t} × {v} = {=v*t/2} m.","params":{"v":[4,20],"t":[2,10]}},{"type":"mc","id":"m2","prompt":"A line sloping down towards the time axis shows…","choices":["slowing down","speeding up","going backwards at a steady speed"],"answer":0,"hint":"Velocity is falling.","explain":"Falling velocity is deceleration."},{"type":"numeric","id":"m3","prompt":"A bus slows from {u} m/s to 0 in {t} s. What is the size of the deceleration, in m/s²?","answer":"u/t","hint":"Change in velocity ÷ time.","explain":"{u} ÷ {t} = {=u/t} m/s².","params":{"u":[6,30],"t":[2,6]},"where":"(u*100)%t==0"},{"type":"mc","id":"m4","prompt":"Which graph shows constant acceleration?","choices":["A straight sloping line","A flat line","A curve getting flatter"],"answer":0,"hint":"The gradient stays the same.","explain":"A straight line has a constant gradient."},{"type":"numeric","id":"m5","prompt":"Speed {v} m/s for {a} s, then {v} m/s for {b} more seconds. What is the total distance, in metres?","answer":"v*(a+b)","hint":"One long rectangle.","explain":"{v} × {=a+b} = {=v*(a+b)} m.","params":{"v":[2,9],"a":[2,9],"b":[2,9]}},{"type":"mc","id":"m6","prompt":"What are the units of acceleration?","choices":["m/s²","m/s","m"],"answer":0,"hint":"Velocity per second.","explain":"(m/s) per s = m/s²."},{"type":"mc","id":"m7","prompt":"Two cars: A's line is steeper than B's. Which has the greater acceleration?","choices":["A","B","They are the same"],"answer":0,"hint":"Steeper means more acceleration.","explain":"A greater gradient means a greater acceleration."}]},"status":"self-checked","visual":{"type":"area","caption":"Velocity v = 2t (speeding up from rest). Drag the end time: the shaded area is the distance travelled.","opts":{"mode":"velocity","f":"2*x","a":0,"b":3,"xr":[0,5],"yr":[-1,10],"ux":"m","tu":"s"}}},"mt_Rud-oI2XyR":{"topicId":"mt_Rud-oI2XyR","title":"Net change as accumulated rate","audience":"learner","keyIdea":"The signed area under any rate graph is the net change in the quantity; area below the axis counts as a decrease.","explain":{"kid":["A rate tells you how fast something changes, like litres per minute flowing into a tank.","The area under a rate graph is how much the amount changed. When the rate is below zero, the amount is going down, so that area counts as minus."],"adult":["If r(t) is a rate of change, the net change from t = a to t = b is ∫ₐᵇ r(t) dt: the signed area. This works for water in a tank, money in an account or people in a room.","Net change is not total activity: 50 people in and 50 people out is a net change of 0. Add the sizes of the parts to find the total flow."]},"familyTip":"Track a piggy bank for a week: money in is positive, money spent is negative. Is the net change the same as all the money that moved?","practice":[{"type":"numeric","id":"p1","prompt":"Water flows into a tank at {r} litres per minute for {t} minutes. How much does the amount change, in litres?","answer":"r*t","hint":"Rate × time is the area of a rectangle.","explain":"{r} × {t} = {=r*t} litres.","params":{"r":[2,9],"t":[3,12]}},{"type":"numeric","id":"p2","prompt":"In {a} L, then out {b} L. What is the net change in litres?","answer":"a-b","hint":"In counts as plus, out as minus.","explain":"{a} − {b} = {=a-b} litres.","params":{"a":[20,60],"b":[5,19]}},{"type":"mc","id":"p3","prompt":"The rate graph dips below the axis. What does that part mean?","choices":["The amount is decreasing","The amount is zero","The rate is speeding up"],"answer":0,"hint":"Negative rate.","explain":"A negative rate means the amount is going down."},{"type":"mc","id":"p4","prompt":"50 people enter a hall and 50 leave. What is the net change?","choices":["0","100","50"],"answer":0,"hint":"In minus out.","explain":"50 − 50 = 0, even though 100 people moved."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A rate of {r} °C per hour lasts {t} hours. What is the net change in temperature, in °C?","answer":"r*t","hint":"Rate × time.","explain":"{r} × {t} = {=r*t} °C.","params":{"r":[1,5],"t":[2,8]}},{"type":"numeric","id":"m2","prompt":"A bank account gains £{a} and loses £{b} over a month. What is the net change, in £?","answer":"a-b","hint":"Gains minus losses.","explain":"{a} − {b} = £{=a-b}.","params":{"a":[100,300],"b":[10,90]}},{"type":"numeric","id":"m3","prompt":"Fill at {r} L/min for {t} min, then drain at {d} L/min for {s} min. What is the net change, in litres?","answer":"r*t-d*s","hint":"Area above minus area below.","explain":"{=r*t} − {=d*s} = {=r*t-d*s} litres.","params":{"r":[4,9],"t":[5,10],"d":[1,3],"s":[2,6]}},{"type":"mc","id":"m4","prompt":"What does ∫ₐᵇ r(t) dt give when r is a rate of change?","choices":["The net change from a to b","The rate at time b","The largest value of r"],"answer":0,"hint":"Signed area.","explain":"It adds up rate × time: the net change."},{"type":"mc","id":"m5","prompt":"A rate graph is above the axis, then below by the same area. The net change is…","choices":["0","double the first area","negative"],"answer":0,"hint":"They cancel.","explain":"Equal areas above and below cancel out."},{"type":"numeric","id":"m6","prompt":"Fill at {r} L/min for {t} min, then drain at {d} L/min for {s} min. How much water moved in total, in litres?","answer":"r*t+d*s","hint":"Add the sizes of both parts.","explain":"{=r*t} + {=d*s} = {=r*t+d*s} litres.","params":{"r":[4,9],"t":[5,10],"d":[1,3],"s":[2,6]}},{"type":"mc","id":"m7","prompt":"Which is a rate?","choices":["Litres per minute","Litres","Minutes"],"answer":0,"hint":"'Per' means for each.","explain":"A rate compares a change with time."}]},"status":"self-checked","visual":{"type":"area","caption":"Water flows at r = 6 − 2t litres per minute. Drag the limits: area above adds water, area below drains it.","opts":{"mode":"definite","f":"6-2*x","a":0,"b":4,"xr":[-0.5,5],"yr":[-4,7]}}},"mt_qCaCEPFbTc":{"topicId":"mt_qCaCEPFbTc","title":"Physical meaning of gradient and area","audience":"learner","keyIdea":"The gradient of a graph is a rate (speed, acceleration, power); the area under a graph is an accumulated amount (distance, energy).","explain":{"kid":["A graph's steepness shows a rate. On a distance–time graph, steep means fast.","The area under some graphs shows a total. On a speed–time graph, the area is the distance. Always check the units on the axes to see what the gradient and the area mean."],"adult":["To read a gradient, divide the y units by the x units. On a distance–time graph, m ÷ s gives speed. On a velocity–time graph you get acceleration. On an energy–time graph, J ÷ s is power in watts.","To read an area, multiply the units. Velocity × time gives distance, and power × time gives energy. If the units multiply to nothing useful, the area has no real meaning."]},"familyTip":"Pick any graph in a news story. Ask: what would its gradient mean? Does its area mean anything?","practice":[{"type":"mc","id":"p1","prompt":"On a distance–time graph, the gradient is…","choices":["speed","acceleration","distance"],"answer":0,"hint":"m ÷ s.","explain":"m ÷ s = m/s: speed."},{"type":"numeric","id":"p2","prompt":"A distance–time graph rises {d} m in {t} s. What is the speed in m/s?","answer":"d/t","hint":"Gradient = rise ÷ run.","explain":"{d} ÷ {t} = {=d/t} m/s.","params":{"d":[10,90],"t":[2,5]},"where":"(d*100)%t==0"},{"type":"numeric","id":"p3","prompt":"A power–time graph is flat at {p} W for {t} s. How much energy is that, in J?","answer":"p*t","hint":"Area = power × time.","explain":"{p} × {t} = {=p*t} J.","params":{"p":[10,90],"t":[2,20]}},{"type":"mc","id":"p4","prompt":"On a velocity–time graph, the area under the line is…","choices":["displacement","acceleration","speed"],"answer":0,"hint":"(m/s) × s.","explain":"(m/s) × s = m: displacement."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"On a velocity–time graph, the gradient is…","choices":["acceleration","speed","distance"],"answer":0,"hint":"(m/s) ÷ s.","explain":"(m/s) ÷ s = m/s²: acceleration."},{"type":"mc","id":"m2","prompt":"On an energy–time graph, the gradient is…","choices":["power","force","energy"],"answer":0,"hint":"J ÷ s.","explain":"J ÷ s = W: power."},{"type":"numeric","id":"m3","prompt":"Velocity rises from {u} m/s to {v} m/s in {t} s. What is the gradient, in m/s²?","answer":"(v-u)/t","hint":"Change in velocity ÷ time.","explain":"({v} − {u}) ÷ {t} = {=(v-u)/t} m/s².","params":{"u":[0,9],"v":[10,30],"t":[2,5]},"where":"((v-u)*100)%t==0"},{"type":"numeric","id":"m4","prompt":"A constant {v} m/s for {t} s. What is the area under the velocity–time graph, in m?","answer":"v*t","hint":"Rectangle.","explain":"{v} × {t} = {=v*t} m.","params":{"v":[2,15],"t":[2,12]}},{"type":"mc","id":"m5","prompt":"What are the units of the gradient of a distance–time graph?","choices":["m/s","m/s²","s/m"],"answer":0,"hint":"y units ÷ x units.","explain":"m ÷ s = m/s."},{"type":"mc","id":"m6","prompt":"Does the area under a distance–time graph mean anything useful?","choices":["Not usually: m × s is not a useful quantity","Yes: it is the speed","Yes: it is the acceleration"],"answer":0,"hint":"Multiply the units.","explain":"m × s has no everyday physical meaning."},{"type":"mc","id":"m7","prompt":"A curved distance–time graph gets steeper. The object is…","choices":["speeding up","slowing down","stopped"],"answer":0,"hint":"Gradient = speed.","explain":"The gradient (speed) is increasing."}]},"status":"self-checked","visual":{"type":"rate","caption":"Distance s = t²/2. Drag the two points: the line's gradient is the average speed between them.","opts":{"f":"x*x/2","a":1,"b":3,"xr":[-0.5,5],"yr":[-1,12],"ux":"s","uy":"m"}}},"mt_yYs2sYPwjl":{"topicId":"mt_yYs2sYPwjl","title":"Polynomial vocabulary","audience":"learner","keyIdea":"A polynomial is a sum of terms; its degree is the highest power, and standard form lists terms from highest power to lowest.","explain":{"kid":["A term is a number, a letter, or both multiplied, like 3x². Terms are joined by + or −.","One term is a monomial. Two terms make a binomial. Three make a trinomial. The degree is the biggest power of x."],"adult":["Standard form writes the terms from the highest power down: 5 − 3x² + 2x becomes −3x² + 2x + 5.","In standard form the first number is the leading coefficient (−3), and the plain number is the constant term (5). The degree is 2, so this is a quadratic trinomial."]},"familyTip":"Write a few expressions on cards. Take turns naming each one: how many terms, what degree?","practice":[{"type":"mc","id":"p1","prompt":"How many terms does 4x³ − x + 7 have?","choices":["3","2","4"],"answer":0,"hint":"Count the parts joined by + or −.","explain":"4x³, −x and 7: three terms, so it is a trinomial."},{"type":"numeric","id":"p2","prompt":"What is the degree of {a}x^{n} + {b}x + 1?","answer":"n","hint":"Highest power of x.","explain":"The highest power is {n}, so the degree is {n}.","params":{"a":[2,9],"n":[3,6],"b":[2,9]}},{"type":"numeric","id":"p3","prompt":"What is the constant term of {a}x² − 3x + {c}?","answer":"c","hint":"The plain number.","explain":"The constant term is {c}.","params":{"a":[2,9],"c":[2,20]}},{"type":"mc","id":"p4","prompt":"Which is a binomial?","choices":["x² + 5","3x","x² + x + 1"],"answer":0,"hint":"Bi means two.","explain":"x² + 5 has two terms."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is the leading coefficient of {c} + {b}x + {a}x²?","answer":"a","hint":"Write it in standard form first.","explain":"Standard form is {a}x² + {b}x + {c}, so the leading coefficient is {a}.","params":{"a":[2,9],"b":[2,9],"c":[2,9]}},{"type":"mc","id":"m2","prompt":"Which is 5 − 3x² + 2x in standard form?","choices":["−3x² + 2x + 5","5 + 2x − 3x²","2x − 3x² + 5"],"answer":0,"hint":"Highest power first.","explain":"x² first, then x, then the number: −3x² + 2x + 5."},{"type":"numeric","id":"m3","prompt":"What is the degree of {a}x^{n} − x^{k}?","answer":"n","hint":"The biggest power wins.","explain":"The powers are {n} and {k}, so the degree is {n}.","params":{"a":[2,9],"n":[4,7],"k":[1,3]}},{"type":"mc","id":"m4","prompt":"What is 7 called?","choices":["A monomial of degree 0","A binomial","Not a polynomial"],"answer":0,"hint":"One term, no x.","explain":"A single number is a monomial with degree 0."},{"type":"mc","id":"m5","prompt":"Which is NOT a polynomial?","choices":["1/x + 2","x² − 1","5x"],"answer":0,"hint":"Powers must be whole and not negative.","explain":"1/x is x⁻¹, a negative power, so it is not a polynomial."},{"type":"mc","id":"m6","prompt":"A degree-2 polynomial is called…","choices":["quadratic","linear","cubic"],"answer":0,"hint":"Degree 1 is linear, 3 is cubic.","explain":"Degree 2 is quadratic."},{"type":"numeric","id":"m7","prompt":"How many terms are in x^{n} + x^{k} + x + {c}?","answer":"4","hint":"Count them.","explain":"There are 4 terms.","params":{"n":[5,8],"k":[2,4],"c":[1,9]}}]},"status":"self-checked","visual":{"type":"polyterms","caption":"Tap a term, change it, add or remove terms. The names update as you go.","opts":{"terms":[[5,0],[-3,2],[2,1]]}}},"mt_93GREOFJAe":{"topicId":"mt_93GREOFJAe","title":"Laws of exponents","audience":"learner","keyIdea":"When you multiply powers of the same base you add the powers, when you divide you subtract them, and a power of a power multiplies them.","explain":{"kid":["x³ means x × x × x. The small number counts how many x's are multiplied.","x³ × x⁵ puts 3 x's next to 5 more. That is 8 x's, so it is x⁸. You add the powers."],"adult":["Multiply: aᵐ × aⁿ = aᵐ⁺ⁿ. Divide: aᵐ ÷ aⁿ = aᵐ⁻ⁿ, because n factors cancel. Power of a power: (aᵐ)ⁿ = aᵐⁿ.","The laws need the same base. 2³ × 3² cannot be combined this way. A common slip is x³ × x⁵ = x¹⁵. Counting the factors shows it is x⁸."]},"familyTip":"Write x³ × x⁵ the long way, with every x. Count them together.","practice":[{"type":"numeric","id":"p1","prompt":"x^{a} × x^{b} = x^? What is the power?","answer":"a+b","hint":"Add the powers.","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"numeric","id":"p2","prompt":"x^{a} ÷ x^{b} = x^? What is the power?","answer":"a-b","hint":"Subtract the powers.","explain":"{a} − {b} = {=a-b}.","params":{"a":[8,12],"b":[2,7]}},{"type":"numeric","id":"p3","prompt":"(x^{a})^{b} = x^? What is the power?","answer":"a*b","hint":"Multiply the powers.","explain":"{a} × {b} = {=a*b}.","params":{"a":[2,5],"b":[2,4]}},{"type":"mc","id":"p4","prompt":"Why is x³ × x⁵ not x¹⁵?","choices":["There are only 3 + 5 = 8 factors of x","Because 15 is too big","You should subtract"],"answer":0,"hint":"Count the x's.","explain":"3 x's and 5 x's make 8 x's: x⁸."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Simplify 2^{a} × 2^{b} as 2 to what power?","answer":"a+b","hint":"Same base, add.","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"numeric","id":"m2","prompt":"Simplify y^{a} ÷ y^{b}. What is the power?","answer":"a-b","hint":"Same base, subtract.","explain":"{a} − {b} = {=a-b}.","params":{"a":[9,15],"b":[2,8]}},{"type":"numeric","id":"m3","prompt":"Simplify (a^{p})^{q}. What is the power?","answer":"p*q","hint":"Multiply.","explain":"{p} × {q} = {=p*q}.","params":{"p":[2,6],"q":[2,5]}},{"type":"mc","id":"m4","prompt":"Which can the laws NOT combine into one power?","choices":["2³ × 3²","2³ × 2²","5⁴ ÷ 5"],"answer":0,"hint":"Bases must match.","explain":"2 and 3 are different bases."},{"type":"numeric","id":"m5","prompt":"{c}x^{a} × {d}x^{b} = kx^n. What is k?","answer":"c*d","hint":"Multiply the numbers, add the powers.","explain":"{c} × {d} = {=c*d}.","params":{"c":[2,6],"d":[2,6],"a":[2,5],"b":[2,5]}},{"type":"mc","id":"m6","prompt":"x⁷ ÷ x⁷ = ?","choices":["1","0","x"],"answer":0,"hint":"Anything divided by itself.","explain":"Every factor cancels: the answer is 1."},{"type":"mc","id":"m7","prompt":"(x²)³ is…","choices":["x⁶","x⁵","x⁸"],"answer":0,"hint":"Three lots of x².","explain":"x² × x² × x² = x⁶."}]},"status":"self-checked","visual":{"type":"expo","caption":"Choose a law and change the powers. Count the tiles to check the rule.","opts":{"mode":"laws","m":3,"n":2,"op":"mul"}}},"mt_mq4eGlJDk9":{"topicId":"mt_mq4eGlJDk9","title":"Zero and negative exponents","audience":"learner","keyIdea":"Each step down in the power divides by the base, so a⁰ = 1 and a⁻ⁿ = 1/aⁿ.","explain":{"kid":["Look at 2³ = 8, 2² = 4, 2¹ = 2. Each time the power goes down by 1, we halve.","Halve once more: 2⁰ = 1. Then 2⁻¹ = 1/2 and 2⁻² = 1/4. A minus power means a fraction."],"adult":["Going down the pattern divides by the base each time, so a⁰ = 1 for any a that is not 0. The laws agree: a³ ÷ a³ = a⁰, and it also equals 1.","Continue the pattern: a⁻ⁿ = 1/aⁿ. So 10⁻² = 1/100 = 0.01 and 2⁻³ = 1/8. A negative power is small but still positive."]},"familyTip":"Write the powers of 10 down a page, from 1000 to 0.001. Label each with its power.","practice":[{"type":"mc","id":"p1","prompt":"5⁰ = ?","choices":["1","0","5"],"answer":0,"hint":"Follow the pattern.","explain":"Any non-zero number to the power 0 is 1."},{"type":"numeric","id":"p2","prompt":"2^-{n} = 1/? (give the denominator)","answer":"2**n","hint":"2⁻ⁿ = 1/2ⁿ.","explain":"2^{n} = {=2**n}, so the answer is 1/{=2**n}.","params":{"n":[1,6]}},{"type":"numeric","id":"p3","prompt":"10^-{n} as a decimal: how many places after the point is the 1?","answer":"n","hint":"10⁻¹ = 0.1.","explain":"10⁻{n} has the 1 in place {n}.","params":{"n":[1,6]}},{"type":"mc","id":"p4","prompt":"Is 3⁻² negative?","choices":["No, it is 1/9","Yes, it is −9","Yes, it is −6"],"answer":0,"hint":"Negative power, not negative number.","explain":"3⁻² = 1/9, a small positive number."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"{b}^-1 = 1/? (give the denominator)","answer":"b","hint":"Flip it.","explain":"{b}⁻¹ = 1/{b}.","params":{"b":[2,12]}},{"type":"numeric","id":"m2","prompt":"4^-{n} = 1/? (give the denominator)","answer":"4**n","hint":"4ⁿ underneath.","explain":"4^{n} = {=4**n}.","params":{"n":[1,4]}},{"type":"mc","id":"m3","prompt":"10⁻² = ?","choices":["0.01","−100","0.2"],"answer":0,"hint":"1/10².","explain":"1/100 = 0.01."},{"type":"mc","id":"m4","prompt":"Why is a⁰ = 1?","choices":["a³ ÷ a³ is a⁰ and also 1","Zero times anything is 0","It is just a rule with no reason"],"answer":0,"hint":"Use the divide law.","explain":"a³ ÷ a³ = a³⁻³ = a⁰, and any number ÷ itself = 1."},{"type":"numeric","id":"m5","prompt":"x^{a} × x^-{b} = x^? What is the power?","answer":"a-b","hint":"Add the powers.","explain":"{a} + (−{b}) = {=a-b}.","params":{"a":[5,9],"b":[1,4]}},{"type":"numeric","id":"m6","prompt":"What is 2^-{n} × 2^{n}?","answer":"1","hint":"Powers add to 0.","explain":"−{n} + {n} = 0, and 2⁰ = 1.","params":{"n":[2,6]}},{"type":"mc","id":"m7","prompt":"Which is the largest?","choices":["2⁰","2⁻¹","2⁻³"],"answer":0,"hint":"1, 1/2, 1/8.","explain":"2⁰ = 1 is the largest."}]},"status":"self-checked","visual":{"type":"expo","caption":"Step down the ladder. Each step divides by 2 and lowers the power by 1.","opts":{"mode":"ladder","base":2,"n":3}}},"mt_OcSj7J9q1t":{"topicId":"mt_OcSj7J9q1t","title":"Fractional exponents and radicals","audience":"learner","keyIdea":"a^(1/n) is the nth root of a, and a^(m/n) is that root raised to the power m.","explain":{"kid":["9 = 3 × 3. So 3 is the square root of 9. We can also write it as 9 to the power 1/2.","27 = 3 × 3 × 3. So the cube root of 27 is 3, and 27 to the power 1/3 is 3."],"adult":["Use the power-of-a-power law: (a^(1/n))ⁿ = a¹ = a. So a^(1/n) is the number that gives a when it is multiplied n times: the nth root.","For a^(m/n), take the root first, then the power: 8^(2/3) = (∛8)² = 2² = 4. Taking the root first keeps the numbers small."]},"familyTip":"Find numbers that are perfect squares and cubes, like 64. Then try 64 to the powers 1/2, 1/3 and 2/3.","practice":[{"type":"numeric","id":"p1","prompt":"What is {=r*r}^(1/2)?","answer":"r","hint":"Which number squared gives it?","explain":"{r} × {r} = {=r*r}, so the answer is {r}.","params":{"r":[2,12]}},{"type":"numeric","id":"p2","prompt":"What is {=r*r*r}^(1/3)?","answer":"r","hint":"Which number cubed gives it?","explain":"{r}³ = {=r*r*r}, so the answer is {r}.","params":{"r":[2,6]}},{"type":"mc","id":"p3","prompt":"x^(1/2) is the same as…","choices":["√x","x/2","x²"],"answer":0,"hint":"A half power.","explain":"A power of 1/2 is a square root."},{"type":"mc","id":"p4","prompt":"8^(2/3) = ?","choices":["4","16","5.33"],"answer":0,"hint":"Cube root first, then square.","explain":"∛8 = 2 and 2² = 4."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"Find the square root of {=r*r}, written as a power: {=r*r}^(1/2).","answer":"r","hint":"Square root.","explain":"√{=r*r} = {r}.","params":{"r":[3,15]}},{"type":"numeric","id":"m2","prompt":"What is {=r*r*r}^(2/3)?","answer":"r*r","hint":"Cube root, then square.","explain":"∛{=r*r*r} = {r} and {r}² = {=r*r}.","params":{"r":[2,5]}},{"type":"mc","id":"m3","prompt":"Write ∛x as a power.","choices":["x^(1/3)","x³","x/3"],"answer":0,"hint":"Cube root is 1/3.","explain":"∛x = x^(1/3)."},{"type":"mc","id":"m4","prompt":"16^(3/4) = ?","choices":["8","12","64"],"answer":0,"hint":"Fourth root first.","explain":"16^(1/4) = 2 and 2³ = 8."},{"type":"numeric","id":"m5","prompt":"x^(1/2) × x^(1/2) = x^? Give the power.","answer":1,"hint":"Add the powers.","explain":"1/2 + 1/2 = 1, so x¹ = x."},{"type":"mc","id":"m6","prompt":"Why is 25^(1/2) = 5?","choices":["(25^(1/2))² = 25¹ = 25, and 5² = 25","25 ÷ 2 is about 5","Half of 10 is 5"],"answer":0,"hint":"Power of a power.","explain":"Squaring 25^(1/2) gives 25, so it must be 5."},{"type":"mc","id":"m7","prompt":"Write x^(3/2) with a root.","choices":["(√x)³","∛(x²)","3√x/2"],"answer":0,"hint":"Denominator is the root.","explain":"The 2 means a square root, the 3 means cubed: (√x)³."}]},"status":"self-checked","visual":{"type":"expo","caption":"Split 8 into equal factors. Change the root and the power to see a^(m/k).","opts":{"mode":"root","a":8,"k":3,"m":1}}},"mt_iHEB0g_nCc":{"topicId":"mt_iHEB0g_nCc","title":"Solving x² = p and x³ = p","audience":"learner","keyIdea":"x² = p has two solutions, ±√p, when p is positive; x³ = p has exactly one, ∛p.","explain":{"kid":["6 × 6 = 36. But −6 × −6 = 36 too! So x² = 36 has two answers: 6 and −6.","For cubes, 3 × 3 × 3 = 27, but −3 cubed is −27. So x³ = 27 has just one answer, 3."],"adult":["To solve x² = p, take the square root of both sides and keep both signs: x = ±√p. If p is negative there is no real answer, because a square is never negative.","To solve x³ = p, take the cube root: x = ∛p. Cubes keep the sign, so ∛(−8) = −2. Some roots, like √2, are irrational. Their decimals never end or repeat."]},"familyTip":"Draw y = x² and a flat line y = 9 on squared paper. Where do they meet?","practice":[{"type":"numeric","id":"p1","prompt":"x² = {=r*r}. What is the positive solution?","answer":"r","hint":"Square root.","explain":"√{=r*r} = {r}, so x = ±{r}; the positive one is {r}.","params":{"r":[2,12]}},{"type":"numeric","id":"p2","prompt":"x³ = {=r*r*r}. What is x?","answer":"r","hint":"Cube root.","explain":"∛{=r*r*r} = {r}.","params":{"r":[2,6]}},{"type":"mc","id":"p3","prompt":"How many real solutions does x² = 49 have?","choices":["2","1","0"],"answer":0,"hint":"7 and…?","explain":"7 and −7: two solutions."},{"type":"mc","id":"p4","prompt":"x² = −4 has…","choices":["no real solutions","x = −2","x = ±2"],"answer":0,"hint":"Can a square be negative?","explain":"A square is never negative, so there is no real solution."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"x² = {=r*r}. What is the negative solution?","answer":"-r","hint":"Use −√p.","explain":"x = −√{=r*r} = −{r}.","params":{"r":[2,12]}},{"type":"numeric","id":"m2","prompt":"x³ = -{=r*r*r}. What is x?","answer":"-r","hint":"Cubes keep the sign.","explain":"∛(−{=r*r*r}) = −{r}.","params":{"r":[2,5]}},{"type":"mc","id":"m3","prompt":"√2 is…","choices":["irrational","exactly 1.4","a whole number"],"answer":0,"hint":"Its decimal never stops.","explain":"√2 = 1.41421… never ends or repeats: irrational."},{"type":"numeric","id":"m4","prompt":"x² = {=r*r}. What is the sum of the two solutions?","answer":"0","hint":"They are opposites.","explain":"{r} + (−{r}) = 0.","params":{"r":[2,12]}},{"type":"mc","id":"m5","prompt":"Solve x³ = 1000.","choices":["x = 10","x = ±10","x = 100"],"answer":0,"hint":"One cube root.","explain":"10³ = 1000, and only one real answer."},{"type":"mc","id":"m6","prompt":"On a graph of y = x², the line y = 9 crosses at…","choices":["x = −3 and x = 3","x = 3 only","x = 81"],"answer":0,"hint":"The curve is symmetric.","explain":"Both ±3 give 9."},{"type":"numeric","id":"m7","prompt":"A square has area {=r*r} cm². How long is its side, in cm?","answer":"r","hint":"Length can't be negative.","explain":"√{=r*r} = {r} cm (ignore −{r} for a length).","params":{"r":[3,15]}}]},"status":"self-checked","visual":{"type":"roots","caption":"Drag the level line up and down. Watch where it meets y = x²: two points, one, or none.","opts":{"k":2,"p":9,"xr":[-5,5],"yr":[-4,25]}}},"mt_x68PoRveI0":{"topicId":"mt_x68PoRveI0","title":"What makes a function","audience":"learner","keyIdea":"A function gives exactly one output for each input.","explain":{"kid":["A function is like a machine. You put a number in and one number comes out.","If the same input could give two different outputs, it is not a function. Two inputs giving the same output is fine."],"adult":["A function assigns exactly one output to each input. Tables, mapping diagrams, graphs and rules can all show functions.","In a table, check that no input appears with two outputs. On a graph, use the vertical line test: if any vertical line hits the graph twice, it is not a function. A circle fails; y = x² passes."]},"familyTip":"Play 'function machine': one person secretly picks a rule, the others give inputs and guess the rule.","practice":[{"type":"mc","id":"p1","prompt":"A table has input 3 with outputs 5 and 7. Is it a function?","choices":["No, 3 has two outputs","Yes","Only if 5 < 7"],"answer":0,"hint":"One input, one output.","explain":"The input 3 has two outputs, so it is not a function."},{"type":"mc","id":"p2","prompt":"Inputs 1 and 2 both give 4. Is that allowed in a function?","choices":["Yes","No"],"answer":0,"hint":"It's inputs that must not repeat.","explain":"Different inputs can share an output."},{"type":"numeric","id":"p3","prompt":"The rule is 'multiply by {a} then add {b}'. What is the output for input {x}?","answer":"a*x+b","hint":"Do the rule.","explain":"{a} × {x} + {b} = {=a*x+b}.","params":{"a":[2,6],"b":[1,9],"x":[2,9]}},{"type":"numeric","id":"p4","prompt":"f(x) = x² − {b}. What is f({x})?","answer":"x*x-b","hint":"Square, then subtract.","explain":"{x}² − {b} = {=x*x-b}.","params":{"b":[1,9],"x":[2,7]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which graph fails the vertical line test?","choices":["A circle","A straight line y = 2x","y = x²"],"answer":0,"hint":"Can a vertical line hit it twice?","explain":"A vertical line through a circle crosses it twice."},{"type":"mc","id":"m2","prompt":"Person → their birthday. Is it a function?","choices":["Yes, each person has one birthday","No, people share birthdays","No, it is not numbers"],"answer":0,"hint":"One output per input.","explain":"Each person has exactly one birthday, so yes. Sharing is allowed."},{"type":"mc","id":"m3","prompt":"Birthday → person. Is it a function?","choices":["No, one date can match many people","Yes","Only in a small class"],"answer":0,"hint":"Can one input give two outputs?","explain":"One date can belong to several people."},{"type":"numeric","id":"m4","prompt":"f(x) = {a}x − {b}. What is f({x})?","answer":"a*x-b","hint":"Substitute.","explain":"{a} × {x} − {b} = {=a*x-b}.","params":{"a":[2,9],"b":[1,9],"x":[2,9]}},{"type":"numeric","id":"m5","prompt":"g(x) = (x + {a})². What is g({x})?","answer":"(x+a)**2","hint":"Add, then square.","explain":"({x} + {a})² = {=(x+a)**2}.","params":{"a":[1,5],"x":[1,5]}},{"type":"mc","id":"m6","prompt":"The pairs (1, 2), (2, 4), (1, 3). Is this a function?","choices":["No","Yes"],"answer":0,"hint":"Look at input 1.","explain":"Input 1 gives both 2 and 3."},{"type":"mc","id":"m7","prompt":"A vertical line x = 4 on a graph is…","choices":["not a function","a function","the function y = 4"],"answer":0,"hint":"Input 4 has every output.","explain":"x = 4 gives infinitely many outputs for one input."}]},"status":"self-checked","visual":{"type":"vlt","caption":"Pick a graph and drag the red vertical line. If it ever hits the graph twice, the graph is not a function.","opts":{"graphs":["line","parab","circle","side","cubic"],"x":1}},"lab":{"type":"graphlab","caption":"Type any rule for y. Each x gives one y, so it is a function. Pass through the targets.","opts":{"f":"a*x+b","a":1,"b":0,"xr":[-5,5],"yr":[-5,9],"targets":[[1,3],[3,7]]}}},"mt_Vn2yQGKnvi":{"topicId":"mt_Vn2yQGKnvi","title":"Multiplying polynomials","audience":"learner","keyIdea":"To multiply polynomials, multiply every term in one by every term in the other, then collect like terms.","explain":{"kid":["(x + 2)(x + 3) means x + 2 lots of x + 3. Draw a grid: put x and 2 down the side, x and 3 along the top.","Fill each box by multiplying: x², 3x, 2x, 6. Add the like terms: x² + 5x + 6."],"adult":["Every term of the first bracket multiplies every term of the second. A binomial times a trinomial makes 2 × 3 = 6 products before you simplify.","(x − 1)(x² + x + 1) = x³ + x² + x − x² − x − 1 = x³ − 1. A grid keeps track of each product and its sign. For three brackets, multiply two first, then the third."]},"familyTip":"Multiply 12 × 13 with a grid: (10 + 2)(10 + 3). It's the same method as (x + 2)(x + 3).","practice":[{"type":"numeric","id":"p1","prompt":"(x + {a})(x + {b}) = x² + kx + c. What is k?","answer":"a+b","hint":"Add the two middle boxes.","explain":"{a}x + {b}x = {=a+b}x.","params":{"a":[1,9],"b":[1,9]}},{"type":"numeric","id":"p2","prompt":"(x + {a})(x + {b}) = x² + kx + c. What is c?","answer":"a*b","hint":"Multiply the numbers.","explain":"{a} × {b} = {=a*b}.","params":{"a":[1,9],"b":[1,9]}},{"type":"mc","id":"p3","prompt":"How many products before simplifying (x + 1)(x² + 2x + 3)?","choices":["6","5","3"],"answer":0,"hint":"2 terms × 3 terms.","explain":"2 × 3 = 6."},{"type":"mc","id":"p4","prompt":"(x − 1)(x² + x + 1) = ?","choices":["x³ − 1","x³ + 1","x³ − x − 1"],"answer":0,"hint":"Most terms cancel.","explain":"x³ + x² + x − x² − x − 1 = x³ − 1."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"(x − {a})(x + {b}) = x² + kx + c. What is c?","answer":"-a*b","hint":"Watch the sign.","explain":"−{a} × {b} = {=-a*b}.","params":{"a":[1,9],"b":[1,9]}},{"type":"numeric","id":"m2","prompt":"(x − {a})(x + {b}) = x² + kx + c. What is k?","answer":"b-a","hint":"−{a}x + {b}x.","explain":"{b} − {a} = {=b-a}.","params":{"a":[1,9],"b":[1,9]}},{"type":"numeric","id":"m3","prompt":"({p}x + 1)(x + {q}) = ax² + bx + c. What is a?","answer":"p","hint":"x² terms only.","explain":"{p}x × x = {p}x².","params":{"p":[2,6],"q":[1,9]}},{"type":"mc","id":"m4","prompt":"(x + 1)³ = ?","choices":["x³ + 3x² + 3x + 1","x³ + 1","x³ + 3x + 1"],"answer":0,"hint":"Multiply two brackets first.","explain":"(x + 1)² = x² + 2x + 1; times (x + 1) gives x³ + 3x² + 3x + 1."},{"type":"mc","id":"m5","prompt":"What degree is (x² + 1)(x³ − 2)?","choices":["5","6","3"],"answer":0,"hint":"Highest powers multiply.","explain":"x² × x³ = x⁵, degree 5."},{"type":"mc","id":"m6","prompt":"(x + 3)² = ?","choices":["x² + 6x + 9","x² + 9","x² + 3x + 9"],"answer":0,"hint":"(x + 3)(x + 3).","explain":"x² + 3x + 3x + 9 = x² + 6x + 9."},{"type":"numeric","id":"m7","prompt":"(x + {a})(x − {a}) = x² + kx + c. What is k?","answer":"0","hint":"The middle terms cancel.","explain":"{a}x − {a}x = 0.","params":{"a":[1,9]}}]},"status":"self-checked","visual":{"type":"grid","caption":"Each box is one term times one term. Change the numbers and watch the like terms collect.","opts":{"a":[1,-1],"b":[1,1,1]}}},"mt_zt4q9lu5va":{"topicId":"mt_zt4q9lu5va","title":"Adding and subtracting polynomials","audience":"learner","keyIdea":"Add or subtract polynomials by combining like terms; when subtracting, change the sign of every term in the second polynomial.","explain":{"kid":["Like terms have the same letter and the same power, like 3x² and 5x². You can add them: 8x².","x² and x are not like terms. Keep them apart, like apples and oranges."],"adult":["To add, group like terms: (3x² + 2x − 1) + (x² − 5x + 4) = 4x² − 3x + 3.","To subtract, the minus sign hits every term in the second bracket. So (5x² + x − 4) − (2x² − 3x + 1) = 5x² + x − 4 − 2x² + 3x − 1 = 3x² + 4x − 5."]},"familyTip":"Write terms on sticky notes. Group the ones that are like terms, then add them up.","practice":[{"type":"numeric","id":"p1","prompt":"({a}x² + 2x) + ({b}x² + x). What is the x² coefficient?","answer":"a+b","hint":"Add like terms.","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"numeric","id":"p2","prompt":"({a}x + 5) − ({b}x + 1). What is the x coefficient?","answer":"a-b","hint":"Subtract like terms.","explain":"{a} − {b} = {=a-b}.","params":{"a":[5,12],"b":[1,4]}},{"type":"mc","id":"p3","prompt":"Are 3x² and 3x like terms?","choices":["No, the powers differ","Yes, both have 3","Yes, both have x"],"answer":0,"hint":"Same letter AND same power.","explain":"x² and x have different powers."},{"type":"mc","id":"p4","prompt":"−(2x − 3) = ?","choices":["−2x + 3","−2x − 3","2x + 3"],"answer":0,"hint":"Change every sign.","explain":"−2x and +3."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"(5x² + x − 4) − (2x² − 3x + 1) = ?","choices":["3x² + 4x − 5","3x² − 2x − 3","3x² + 4x − 3"],"answer":0,"hint":"Flip every sign in the second.","explain":"5x² − 2x² = 3x², x + 3x = 4x, −4 − 1 = −5."},{"type":"numeric","id":"m2","prompt":"({a}x − {b}) − ({c}x − {d}). What is the constant term?","answer":"d-b","hint":"−{b} − (−{d}).","explain":"−{b} + {d} = {=d-b}.","params":{"a":[3,9],"b":[1,9],"c":[1,3],"d":[1,9]}},{"type":"numeric","id":"m3","prompt":"({a}x² + {b}x) + ({c}x² − {b}x). What is the x coefficient?","answer":"0","hint":"They cancel.","explain":"{b} − {b} = 0.","params":{"a":[1,9],"b":[1,9],"c":[1,9]}},{"type":"mc","id":"m4","prompt":"Which pair are like terms?","choices":["4xy and −xy","x²y and xy²","3x and 3"],"answer":0,"hint":"Same letters, same powers.","explain":"4xy and −xy match exactly."},{"type":"mc","id":"m5","prompt":"(x³ + 2) + (x² − 2) = ?","choices":["x³ + x²","2x⁵","x³ + x² + 4"],"answer":0,"hint":"Nothing to combine except numbers.","explain":"2 − 2 = 0, so x³ + x²."},{"type":"numeric","id":"m6","prompt":"({a}x² + 1) − ({b}x² + 1). What is the x² coefficient?","answer":"a-b","hint":"Subtract.","explain":"{a} − {b} = {=a-b}.","params":{"a":[6,12],"b":[1,5]}},{"type":"mc","id":"m7","prompt":"A common mistake in (6x + 2) − (x − 4) is getting…","choices":["5x − 2","5x + 6","7x − 2"],"answer":0,"hint":"Forgetting to flip −4.","explain":"The right answer is 5x + 6; forgetting the sign gives 5x − 2."}]},"status":"self-checked","visual":{"type":"tiles","caption":"(5x² + x − 4) − (2x² − 3x + 1) with tiles. Subtracting flips the second bracket; Combine joins like tiles and cancels zero pairs.","opts":{"a":[5,1,-4],"b":[2,-3,1],"op":"-"}}},"mt_o2vTJv1KoM":{"topicId":"mt_o2vTJv1KoM","title":"Acceleration","audience":"learner","keyIdea":"Acceleration is how quickly velocity changes: a = change in velocity ÷ time, measured in m/s².","explain":{"kid":["Speeding up is called acceleration. A bike that goes 2 faster each second has an acceleration of 2.","Slowing down is a minus acceleration. We call it slowing down."],"adult":["a = (v − u) ÷ t, where u is the starting velocity and v is the final one. A car going from 0 to 20 m/s in 5 s has a = 4 m/s². Each second it gains 4 m/s.","If v is less than u, a is negative: the object is slowing down. On a velocity–time graph, acceleration is the gradient."]},"familyTip":"In a car or on a bike, notice the speed every few seconds while speeding up. Work out how much faster each second.","practice":[{"type":"numeric","id":"p1","prompt":"0 to {v} m/s in {t} s. What is the acceleration, in m/s²?","answer":"v/t","hint":"Change ÷ time.","explain":"{v} ÷ {t} = {=v/t} m/s².","params":{"v":[10,40],"t":[2,5]},"where":"(v*100)%t==0"},{"type":"mc","id":"p2","prompt":"What does 3 m/s² mean?","choices":["Velocity rises by 3 m/s every second","It moves 3 m each second","It takes 3 s to stop"],"answer":0,"hint":"Per second, per second.","explain":"Each second, 3 m/s faster."},{"type":"numeric","id":"p3","prompt":"From {u} m/s to {v} m/s in {t} s. What is a, in m/s²?","answer":"(v-u)/t","hint":"(v − u) ÷ t.","explain":"({v} − {u}) ÷ {t} = {=(v-u)/t} m/s².","params":{"u":[2,9],"v":[12,30],"t":[2,5]},"where":"((v-u)*100)%t==0"},{"type":"mc","id":"p4","prompt":"A negative acceleration means…","choices":["slowing down","going backwards","standing still"],"answer":0,"hint":"Velocity is falling.","explain":"Velocity drops: deceleration."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A bike slows from {u} m/s to 0 in {t} s. What is a, in m/s²?","answer":"-u/t","hint":"Final minus start.","explain":"(0 − {u}) ÷ {t} = {=-u/t} m/s².","params":{"u":[4,20],"t":[2,5]},"where":"(u*100)%t==0"},{"type":"numeric","id":"m2","prompt":"a = {a} m/s² from rest for {t} s. What is the final velocity, in m/s?","answer":"a*t","hint":"v = u + at.","explain":"0 + {a} × {t} = {=a*t} m/s.","params":{"a":[2,6],"t":[2,9]}},{"type":"mc","id":"m3","prompt":"On a velocity–time graph, acceleration is…","choices":["the gradient","the area","the y-intercept"],"answer":0,"hint":"Rise over run.","explain":"Change in velocity ÷ time = gradient."},{"type":"mc","id":"m4","prompt":"The unit m/s² means…","choices":["metres per second, per second","metres per square second of distance","metres times seconds"],"answer":0,"hint":"Velocity change per second.","explain":"(m/s) gained each second."},{"type":"numeric","id":"m5","prompt":"a = {a} m/s², starting at {u} m/s, for {t} s. Final velocity in m/s?","answer":"u+a*t","hint":"v = u + at.","explain":"{u} + {a} × {t} = {=u+a*t} m/s.","params":{"a":[1,5],"u":[2,10],"t":[2,6]}},{"type":"mc","id":"m6","prompt":"A car moves at a steady 30 m/s. Its acceleration is…","choices":["0","30 m/s²","1 m/s²"],"answer":0,"hint":"No change.","explain":"Velocity isn't changing, so a = 0."},{"type":"mc","id":"m7","prompt":"Which has the greater acceleration?","choices":["0 to 10 m/s in 2 s","0 to 20 m/s in 10 s","They are equal"],"answer":0,"hint":"Work out both.","explain":"5 m/s² beats 2 m/s²."}]},"status":"self-checked","visual":{"type":"rate","caption":"Velocity v = 2t + 1. Drag the two points: the gradient between them is the acceleration.","opts":{"f":"2*x+1","a":1,"b":4,"xr":[-0.5,6],"yr":[-1,14],"ux":"s","uy":"m/s"}}},"mt_3AuVh--Vla":{"topicId":"mt_3AuVh--Vla","title":"Displacement and velocity in a line","audience":"learner","keyIdea":"Displacement is how far you end up from the start in a chosen direction; average velocity is displacement ÷ time.","explain":{"kid":["Pick a direction to be positive, like east. Walking east is plus, walking west is minus.","Walk 30 m east, then 10 m west. You walked 40 m in all. But you are only 20 m east of the start. That 20 m is your displacement."],"adult":["Distance and speed ignore direction. Displacement and velocity are signed: choose a positive direction and give each move a sign.","Average speed = total distance ÷ time. Average velocity = displacement ÷ time. For 30 m east then 10 m west in 20 s, the average speed is 40 ÷ 20 = 2 m/s. The average velocity is 20 ÷ 20 = 1 m/s east."]},"familyTip":"Walk along a hallway, forward then back. Measure both the steps you took and how far you ended from the start.","practice":[{"type":"numeric","id":"p1","prompt":"Walk {a} m east, then {b} m west. What is the displacement east, in m?","answer":"a-b","hint":"East +, west −.","explain":"{a} − {b} = {=a-b} m east.","params":{"a":[20,60],"b":[5,19]}},{"type":"numeric","id":"p2","prompt":"Walk {a} m east, then {b} m west. What is the distance, in m?","answer":"a+b","hint":"Add every step.","explain":"{a} + {b} = {=a+b} m.","params":{"a":[20,60],"b":[5,19]}},{"type":"mc","id":"p3","prompt":"One full lap of a 400 m track. Displacement?","choices":["0 m","400 m","200 m"],"answer":0,"hint":"Where do you end?","explain":"You end where you started, so 0 m."},{"type":"mc","id":"p4","prompt":"Velocity is speed with…","choices":["a direction","a time","a mass"],"answer":0,"hint":"Signed.","explain":"Velocity includes direction."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"{d} m east in {t} s. What is the average velocity, in m/s east?","answer":"d/t","hint":"Displacement ÷ time.","explain":"{d} ÷ {t} = {=d/t} m/s.","params":{"d":[20,90],"t":[2,5]},"where":"(d*100)%t==0"},{"type":"numeric","id":"m2","prompt":"{a} m east then {b} m west in {t} s. Average speed in m/s?","answer":"(a+b)/t","hint":"Distance ÷ time.","explain":"{=a+b} ÷ {t} = {=(a+b)/t} m/s.","params":{"a":[20,40],"b":[10,20],"t":[5,10]},"where":"((a+b)*100)%t==0"},{"type":"numeric","id":"m3","prompt":"{a} m east then {b} m west in {t} s. Average velocity (east), in m/s?","answer":"(a-b)/t","hint":"Displacement ÷ time.","explain":"{=a-b} ÷ {t} = {=(a-b)/t} m/s.","params":{"a":[20,40],"b":[10,19],"t":[5,10]},"where":"((a-b)*100)%t==0"},{"type":"mc","id":"m4","prompt":"A velocity of −3 m/s (east positive) means…","choices":["3 m/s west","slowing down","3 m/s east"],"answer":0,"hint":"Sign is direction.","explain":"Negative means the other way: west."},{"type":"mc","id":"m5","prompt":"Can average velocity be 0 when speed is not?","choices":["Yes, if you return to the start","No, never","Only if you stop"],"answer":0,"hint":"Round trip.","explain":"Back to the start means zero displacement."},{"type":"mc","id":"m6","prompt":"Which is a vector?","choices":["Displacement","Distance","Speed"],"answer":0,"hint":"Has a direction.","explain":"Displacement has size and direction."},{"type":"numeric","id":"m7","prompt":"Start at +{a} m, end at −{b} m. Displacement, in m?","answer":"-b-a","hint":"End − start.","explain":"−{b} − {a} = {=-b-a} m.","params":{"a":[2,9],"b":[2,9]}}]},"status":"self-checked","visual":{"type":"journey","caption":"Position east of the start: 30 m out, then 10 m back. Play it and compare distance with displacement.","opts":{"pts":[[0,0],[12,30],[15,30],[20,20]],"tu":"s","du":"m","step":1}}},"mt_ZBFDXdwUNC":{"topicId":"mt_ZBFDXdwUNC","title":"Key features of graphs","audience":"learner","keyIdea":"Read a graph's story from its features: intercepts, where it rises or falls, its highest and lowest points, symmetry and end behaviour.","explain":{"kid":["A graph tells a story. Going up means getting bigger. Going down means getting smaller.","The top of a hill is a maximum. The bottom of a valley is a minimum. Where the graph crosses an axis is an intercept."],"adult":["Increasing means y rises as x moves right, so the tangent slopes up. Decreasing means it slopes down. At a maximum or minimum, the tangent is flat.","The y-intercept is where x = 0. The x-intercepts are the zeros. Symmetry and end behaviour describe the overall shape, such as a parabola that rises at both ends."]},"familyTip":"Look at a weather app's temperature graph. When was it warmest? When was it rising?","practice":[{"type":"mc","id":"p1","prompt":"Where is a graph's y-intercept?","choices":["Where x = 0","Where y = 0","At the top"],"answer":0,"hint":"It's on the y-axis.","explain":"On the y-axis, x = 0."},{"type":"numeric","id":"p2","prompt":"y = (x − {h})² − 4. At what x is the minimum?","answer":"h","hint":"The square is smallest at 0.","explain":"x − {h} = 0 gives x = {h}.","params":{"h":[1,6]}},{"type":"numeric","id":"p3","prompt":"y = {a}x + {b}. What is the y-intercept?","answer":"b","hint":"Put x = 0.","explain":"y = {b}.","params":{"a":[2,9],"b":[1,12]}},{"type":"mc","id":"p4","prompt":"At a maximum, the tangent is…","choices":["flat","steep upwards","vertical"],"answer":0,"hint":"Top of a hill.","explain":"Its gradient is 0, so it is flat."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"y = −(x − 3)² + 9 increases when…","choices":["x < 3","x > 3","always"],"answer":0,"hint":"It's a hill with its top at 3.","explain":"It rises up to x = 3, then falls."},{"type":"numeric","id":"m2","prompt":"y = −(x − {h})² + {k}. What is the maximum value?","answer":"k","hint":"The squared part is 0 at best.","explain":"The maximum is {k}.","params":{"h":[1,6],"k":[2,12]}},{"type":"numeric","id":"m3","prompt":"y = x² − {=r*r}. Give the positive x-intercept.","answer":"r","hint":"Set y = 0.","explain":"x² = {=r*r}, so x = {r}.","params":{"r":[2,9]}},{"type":"mc","id":"m4","prompt":"A graph of temperature over a day peaks at 3 pm. That is…","choices":["the maximum","an intercept","the end behaviour"],"answer":0,"hint":"Highest point.","explain":"The highest point is the maximum."},{"type":"mc","id":"m5","prompt":"y = x² is symmetric about…","choices":["the y-axis","the x-axis","the line y = x"],"answer":0,"hint":"Mirror left and right.","explain":"f(−x) = f(x): symmetric about the y-axis."},{"type":"mc","id":"m6","prompt":"As x gets very large, y = −x² …","choices":["goes down without end","goes up","levels off at 0"],"answer":0,"hint":"End behaviour.","explain":"−x² becomes more and more negative."},{"type":"mc","id":"m7","prompt":"A tangent slopes down. The graph there is…","choices":["decreasing","increasing","at a maximum"],"answer":0,"hint":"Gradient sign.","explain":"A negative gradient means decreasing."}]},"status":"self-checked","visual":{"type":"plot","caption":"A hill-shaped graph. Drag the point: the tangent slopes up while increasing, is flat at the maximum, and slopes down after.","opts":{"mode":"tangent","f":"-(x-3)*(x-3)+9","a":1,"xr":[-1,7],"yr":[-4,11],"step":0.5,"label":"f(x)"}},"lab":{"type":"graphlab","caption":"Edit the quadratic. Move it so its roots sit on the red targets.","opts":{"f":"a*x^2+b*x+c","a":1,"b":0,"c":0,"xr":[-5,5],"yr":[-6,10],"targets":[[1,0],[3,0]]}}},"mt_Sa5JjOvfhX":{"topicId":"mt_Sa5JjOvfhX","title":"Sketching and describing qualitative graphs","audience":"learner","keyIdea":"A graph without numbers can still tell a story: rising, falling, flat, steeper or levelling off.","explain":{"kid":["You can draw a graph from a story, even with no numbers. 'I ran to the bus stop' is a steep line going up.","'I waited' is a flat line. 'The bus took me home fast' is a steep line going back down."],"adult":["Match each part of a story to a shape. Steady change is a straight line. Faster change is steeper. No change is flat. Change that slows down is a curve that levels off.","When you describe a graph, use words like increasing, decreasing, constant, steeper and levelling off. Always say what the axes stand for."]},"familyTip":"Tell a short story about a trip, then each person sketches it. Compare the sketches.","practice":[{"type":"mc","id":"p1","prompt":"A flat line on a distance–time graph means…","choices":["not moving","moving fast","coming back"],"answer":0,"hint":"Distance doesn't change.","explain":"No change in distance: standing still."},{"type":"numeric","id":"p2","prompt":"Walk for {a} min, then wait for {b} min. For how many minutes is the graph flat?","answer":"b","hint":"Flat means waiting.","explain":"The flat part lasts {b} min.","params":{"a":[2,9],"b":[1,6]}},{"type":"numeric","id":"p3","prompt":"Walk {a} km in {t} min, then rest. How far from home is the flat part, in km?","answer":"a","hint":"Flat means no change.","explain":"It stays at {a} km.","params":{"a":[1,5],"t":[10,30]}},{"type":"mc","id":"p4","prompt":"A hot drink cooling quickly, then more slowly. The temperature graph…","choices":["falls steeply, then levels off","is a straight line down","rises"],"answer":0,"hint":"Cooling slows down.","explain":"Steep fall, then levelling off."}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Running to the bus stop, then waiting, looks like…","choices":["steep up, then flat","flat, then steep","a straight line down"],"answer":0,"hint":"Distance from home.","explain":"Distance rises fast, then stays the same."},{"type":"mc","id":"m2","prompt":"A line sloping back down to zero distance from home means…","choices":["going back home","slowing down","waiting"],"answer":0,"hint":"Distance shrinks.","explain":"Getting closer to home."},{"type":"mc","id":"m3","prompt":"Filling a bath, the water depth graph rises then is flat. The flat part means…","choices":["the tap is off","the bath is draining","the tap is fast"],"answer":0,"hint":"No change.","explain":"Depth stays the same, so the tap is off."},{"type":"mc","id":"m4","prompt":"A plant's height rises fast, then levels off. Describe it.","choices":["Increasing, then levelling off","Decreasing","Constant"],"answer":0,"hint":"Growth slows.","explain":"It grows quickly at first, then hardly at all."},{"type":"numeric","id":"m5","prompt":"Walk {a} min, wait {b} min, walk {c} min. How many minutes long is the graph?","answer":"a+b+c","hint":"Add all the times.","explain":"{a} + {b} + {c} = {=a+b+c} min.","params":{"a":[2,9],"b":[1,5],"c":[2,9]}},{"type":"numeric","id":"m6","prompt":"Walk {a} km at a steady pace in {t} min. What is the gradient, in km per min?","answer":"a/t","hint":"Rise ÷ run.","explain":"{a} ÷ {t} = {=a/t} km/min.","params":{"a":[1,4],"t":[10,20]},"where":"(a*100)%t==0"},{"type":"mc","id":"m7","prompt":"Which story matches 'rises steadily, flat, then rises more gently'?","choices":["Walk, rest, walk more slowly","Run, rest, run faster","Walk home and stop"],"answer":0,"hint":"Gentler means slower.","explain":"Second walking part is less steep, so slower."}]},"status":"self-checked","visual":{"type":"journey","caption":"Run to the bus stop, wait, then ride the bus. Play the story and watch each part of the graph.","opts":{"pts":[[0,0],[5,0.6],[12,0.6],[20,4]],"tu":"min","du":"km","step":1}}},"mt_hdlI0Sacpa":{"topicId":"mt_hdlI0Sacpa","title":"Scalars and vectors","audience":"learner","keyIdea":"A scalar has only a size; a vector has a size and a direction.","explain":{"kid":["Some amounts just have a size, like 5 kg or 20 seconds. These are scalars.","Others need a direction too, like 5 m north or a push to the left. These are vectors. We draw them as arrows."],"adult":["Scalars: distance, speed, mass, time, energy, temperature. Vectors: displacement, velocity, force, acceleration, momentum.","A vector arrow's length shows its size and its direction shows the way. Run one lap of a 400 m track: the distance is 400 m, but the displacement is 0, because you end at the start."]},"familyTip":"Name things around you and decide together: would a direction help describe it?","practice":[{"type":"mc","id":"p1","prompt":"Which is a vector?","choices":["Velocity","Speed","Mass"],"answer":0,"hint":"Needs a direction.","explain":"Velocity has a direction."},{"type":"mc","id":"p2","prompt":"Which is a scalar?","choices":["Temperature","Force","Displacement"],"answer":0,"hint":"No direction.","explain":"Temperature has no direction."},{"type":"numeric","id":"p3","prompt":"Two forces push right: {a} N and {b} N. What is the total, in N?","answer":"a+b","hint":"Same direction: add.","explain":"{a} + {b} = {=a+b} N.","params":{"a":[2,20],"b":[2,20]}},{"type":"numeric","id":"p4","prompt":"{a} N right and {b} N left. What is the resultant to the right, in N?","answer":"a-b","hint":"Opposite: subtract.","explain":"{a} − {b} = {=a-b} N right.","params":{"a":[12,30],"b":[1,11]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Run one lap of a 400 m track. Displacement is…","choices":["0 m","400 m","200 m"],"answer":0,"hint":"End = start.","explain":"You end at the start: 0 m."},{"type":"mc","id":"m2","prompt":"Which pair is (scalar, vector)?","choices":["(speed, velocity)","(force, mass)","(velocity, distance)"],"answer":0,"hint":"Speed has no direction.","explain":"Speed is scalar, velocity is vector."},{"type":"mc","id":"m3","prompt":"Acceleration is…","choices":["a vector","a scalar"],"answer":0,"hint":"Change in velocity.","explain":"It has a direction, so it is a vector."},{"type":"numeric","id":"m4","prompt":"{a} m north then {b} m south. Displacement north, in m?","answer":"a-b","hint":"Opposite directions.","explain":"{a} − {b} = {=a-b} m.","params":{"a":[20,50],"b":[1,19]}},{"type":"numeric","id":"m5","prompt":"{a} m north then {b} m south. Distance, in m?","answer":"a+b","hint":"Scalar: add.","explain":"{a} + {b} = {=a+b} m.","params":{"a":[20,50],"b":[1,19]}},{"type":"mc","id":"m6","prompt":"A vector arrow's length shows…","choices":["its size","its direction","its time"],"answer":0,"hint":"Longer is bigger.","explain":"Length shows size; direction shows the way."},{"type":"mc","id":"m7","prompt":"Energy is…","choices":["a scalar","a vector"],"answer":0,"hint":"Does it point anywhere?","explain":"Energy has no direction."}]},"status":"self-checked","visual":{"type":"vectors","caption":"Drag the two arrow tips (or use arrow keys). Compare the distance walked (a scalar) with the displacement (a vector).","opts":{"a":[3,0],"b":[0,4]}}},"mt_-hTTat0mBR":{"topicId":"mt_-hTTat0mBR","title":"What is a half?","audience":"family","keyIdea":"A half is one of two equal parts.","explain":{"kid":["Cut a cake into two parts that are the same size. Each part is a half.","If one part is big and one is small, they are not halves."],"adult":["A half is one of two equal parts of a whole shape or a group. The key word is equal: two unequal pieces are not halves.","Children meet halves first with shapes and food, then with groups: half of 8 sweets is 4, because 8 shared fairly between two is 4 each."]},"familyTip":"Fold a piece of paper in half. Check the two parts match exactly. Then share 6 grapes into two fair halves.","practice":[{"type":"mc","id":"p1","prompt":"A pizza is cut into 2 equal parts. Each part is…","choices":["a half","a quarter","a whole"],"answer":0,"hint":"Two equal parts.","explain":"Two equal parts: each is a half."},{"type":"numeric","id":"p2","prompt":"What is half of {=2*n} sweets?","answer":"n","hint":"Share them into 2 fair piles.","explain":"{=2*n} shared into 2 piles is {n} each.","params":{"n":[2,6]}},{"type":"mc","id":"p3","prompt":"A cake is cut into one big part and one small part. Are they halves?","choices":["No, they are not the same size","Yes","Only the big part"],"answer":0,"hint":"Halves must match.","explain":"Halves are equal, so these are not halves."},{"type":"numeric","id":"p4","prompt":"Half of the {=2*n} cars are red. How many are red?","answer":"n","hint":"Share into 2 equal groups.","explain":"{=2*n} ÷ 2 = {n}.","params":{"n":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"What is half of {=2*n}?","answer":"n","hint":"Two equal groups.","explain":"Half of {=2*n} is {n}.","params":{"n":[1,8]}},{"type":"mc","id":"m2","prompt":"How many halves make a whole?","choices":["2","1","4"],"answer":0,"hint":"Two parts.","explain":"Two halves make one whole."},{"type":"numeric","id":"m3","prompt":"Sam eats half of {=2*n} grapes. How many does Sam eat?","answer":"n","hint":"Share fairly in two.","explain":"{=2*n} ÷ 2 = {n} grapes.","params":{"n":[2,7]}},{"type":"mc","id":"m4","prompt":"Which shows a half?","choices":["A square cut into 2 same-size parts, one shaded","A square cut into 3 parts, one shaded","A square cut into 2 different parts, one shaded"],"answer":0,"hint":"Two equal parts.","explain":"Only the first has two equal parts."},{"type":"mc","id":"m5","prompt":"Half an apple and half an apple make…","choices":["one whole apple","a quarter","two apples"],"answer":0,"hint":"2 halves.","explain":"Two halves make a whole."},{"type":"mc","id":"m6","prompt":"Is half of 10 the same as 5?","choices":["Yes","No"],"answer":0,"hint":"Share 10 in two.","explain":"10 shared in two is 5 each."},{"type":"mc","id":"m7","prompt":"A sandwich is cut into 2 equal parts. You eat 1. What did you eat?","choices":["Half","All of it","A quarter"],"answer":0,"hint":"One of two equal parts.","explain":"One of two equal parts is a half."}]},"status":"self-checked","visual":{"type":"fracbar","caption":"Tap the parts. Shade one of the two equal parts: that is a half.","opts":{"d":2,"shade":1,"pie":true}}},"mt_g3W0mdADVu":{"topicId":"mt_g3W0mdADVu","title":"Finding halves and quarters","audience":"family","keyIdea":"A quarter is one of four equal parts; two quarters make a half.","explain":{"kid":["Cut a cake into 4 parts that are all the same size. Each part is a quarter.","Two quarters are as big as one half."],"adult":["A quarter is one of four equal parts, so it is half of a half. Fold a paper square in half, then in half again, and you get quarters.","For groups, find a quarter by sharing between four: a quarter of 12 is 3. Two quarters equal one half, which is a first taste of equivalent fractions."]},"familyTip":"Fold a paper square into quarters. Shade one quarter, then two. Is two quarters the same as half?","practice":[{"type":"mc","id":"p1","prompt":"A pie is cut into 4 equal parts. One part is…","choices":["a quarter","a half","a third"],"answer":0,"hint":"Four equal parts.","explain":"One of four equal parts is a quarter."},{"type":"numeric","id":"p2","prompt":"What is a quarter of {=4*n}?","answer":"n","hint":"Share into 4 equal groups.","explain":"{=4*n} ÷ 4 = {n}.","params":{"n":[1,5]}},{"type":"mc","id":"p3","prompt":"How many quarters make a half?","choices":["2","4","1"],"answer":0,"hint":"Fold a half in half.","explain":"Two quarters make a half."},{"type":"numeric","id":"p4","prompt":"Half of {=4*n} is…","answer":"2*n","hint":"Share into 2.","explain":"{=4*n} ÷ 2 = {=2*n}.","params":{"n":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A quarter of {=4*n} cars is how many?","answer":"n","hint":"Four equal groups.","explain":"{=4*n} ÷ 4 = {n}.","params":{"n":[1,6]}},{"type":"mc","id":"m2","prompt":"How many quarters make a whole?","choices":["4","2","3"],"answer":0,"hint":"Four parts.","explain":"Four quarters make one whole."},{"type":"numeric","id":"m3","prompt":"Mia eats 2 quarters of a pizza cut into 4. How many slices are left?","answer":2,"hint":"4 − 2.","explain":"4 − 2 = 2 slices left."},{"type":"mc","id":"m4","prompt":"Which is bigger?","choices":["A half","A quarter","They are the same"],"answer":0,"hint":"Fewer parts, bigger parts.","explain":"A half is two quarters, so it is bigger."},{"type":"numeric","id":"m5","prompt":"Ben has {=4*n} sweets and gives away a quarter. How many does he give away?","answer":"n","hint":"Share by 4.","explain":"{=4*n} ÷ 4 = {n}.","params":{"n":[2,5]}},{"type":"mc","id":"m6","prompt":"A square is cut into 4 parts of different sizes. Is each a quarter?","choices":["No","Yes"],"answer":0,"hint":"Quarters are equal.","explain":"Quarters must all be the same size."},{"type":"mc","id":"m7","prompt":"Two quarters of a cake are the same as…","choices":["half the cake","the whole cake","a quarter"],"answer":0,"hint":"2 of 4.","explain":"2 of 4 equal parts is a half."}]},"status":"self-checked","visual":{"type":"fracbar","caption":"One bar in halves, one in quarters. Shade two quarters: does it match one half?","opts":{"d":2,"shade":1,"compare":4,"compareShade":0}}},"mt_5r47Pvstyn":{"topicId":"mt_5r47Pvstyn","title":"Objects and materials","audience":"family","keyIdea":"An object is a thing; a material is what the thing is made of.","explain":{"kid":["A spoon is an object. It can be made of metal, wood or plastic. Those are materials.","It is still a spoon, whatever it is made of."],"adult":["Children often mix up objects (spoon, chair, window) with materials (metal, wood, glass). Ask 'what is it?' for the object and 'what is it made of?' for the material.","The same object can be made of different materials, and the same material can make many objects. That idea leads to choosing materials for a job."]},"familyTip":"Pick three things in the kitchen. For each, say the object and the material: 'a cup, made of china'.","practice":[{"type":"mc","id":"p1","prompt":"Which is a material?","choices":["wood","chair","table"],"answer":0,"hint":"What things are made of.","explain":"Wood is a material; chairs and tables are objects."},{"type":"mc","id":"p2","prompt":"Which is an object?","choices":["spoon","metal","plastic"],"answer":0,"hint":"A thing you can use.","explain":"A spoon is an object."},{"type":"numeric","id":"p3","prompt":"{n} spoons are made of metal and {m} of wood. How many spoons?","answer":"n+m","hint":"Add them.","explain":"{n} + {m} = {=n+m} spoons.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"{n} cups are plastic and {m} are glass. How many glass cups?","answer":"m","hint":"Just the glass ones.","explain":"{m} are glass.","params":{"n":[1,5],"m":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A window is made of…","choices":["glass","a window","a door"],"answer":0,"hint":"What is it made of?","explain":"Windows are made of glass."},{"type":"mc","id":"m2","prompt":"Can a spoon be made of wood?","choices":["Yes","No"],"answer":0,"hint":"Think of a cooking spoon.","explain":"Yes, wooden spoons are common."},{"type":"mc","id":"m3","prompt":"Which pair is (object, material)?","choices":["(chair, wood)","(wood, chair)","(metal, glass)"],"answer":0,"hint":"Thing first.","explain":"A chair is the object; wood is the material."},{"type":"numeric","id":"m4","prompt":"There are {n} wooden blocks and {m} plastic blocks. How many blocks?","answer":"n+m","hint":"Add.","explain":"{n} + {m} = {=n+m}.","params":{"n":[2,6],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"{n} toys are metal. {m} are not. How many toys?","answer":"n+m","hint":"Add both.","explain":"{=n+m} toys.","params":{"n":[1,6],"m":[1,6]}},{"type":"mc","id":"m6","prompt":"Is plastic an object or a material?","choices":["A material","An object"],"answer":0,"hint":"Can you make things from it?","explain":"Plastic is a material."},{"type":"mc","id":"m7","prompt":"A metal spoon and a wooden spoon are both…","choices":["spoons","metal","wood"],"answer":0,"hint":"Same object.","explain":"Both are spoons, made of different materials."}]},"status":"self-checked","visual":{"type":"objects","caption":"Pick an object, then change its material. Is it still the same object?","opts":{"objects":[["spoon",[["metal","#cbd5e1"],["wood","#d6a35c"],["plastic","#f472b6"]]],["cup",[["glass","#bae6fd"],["china","#f8fafc"],["plastic","#86efac"]]],["chair",[["wood","#d6a35c"],["metal","#cbd5e1"],["plastic","#fdba74"]]]]}}},"mt_ZAJvTcroFO":{"topicId":"mt_ZAJvTcroFO","title":"Naming everyday materials","audience":"family","keyIdea":"Everyday things are made of materials such as wood, plastic, glass, metal, rock and fabric.","explain":{"kid":["Look around. A door is wood. A window is glass. A key is metal. A bag can be fabric or plastic.","Each of these is a material."],"adult":["The core list for young children is wood, plastic, glass, metal, water, rock, brick, paper, card and fabric. Naming them gives words for later work on properties.","Point out that one object can use several materials: a pencil is wood with graphite inside and a metal end."]},"familyTip":"Go on a material hunt at home. Find something made of wood, metal, glass, plastic and fabric.","practice":[{"type":"mc","id":"p1","prompt":"A key is usually made of…","choices":["metal","glass","paper"],"answer":0,"hint":"Hard and shiny.","explain":"Keys are metal."},{"type":"mc","id":"p2","prompt":"A window is made of…","choices":["glass","wood","fabric"],"answer":0,"hint":"You can see through it.","explain":"Windows are glass."},{"type":"numeric","id":"p3","prompt":"You find {n} wooden things and {m} metal things. How many things?","answer":"n+m","hint":"Add.","explain":"{n} + {m} = {=n+m}.","params":{"n":[1,6],"m":[1,6]}},{"type":"numeric","id":"p4","prompt":"{n} of your {=n+m} toys are plastic. How many are not plastic?","answer":"m","hint":"Take away.","explain":"{=n+m} − {n} = {m}.","params":{"n":[1,5],"m":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A T-shirt is made of…","choices":["fabric","metal","rock"],"answer":0,"hint":"Soft, you wear it.","explain":"Clothes are fabric."},{"type":"mc","id":"m2","prompt":"A book's pages are made of…","choices":["paper","glass","plastic"],"answer":0,"hint":"Thin, you turn them.","explain":"Pages are paper."},{"type":"mc","id":"m3","prompt":"A wall is often made of…","choices":["brick","fabric","paper"],"answer":0,"hint":"Strong blocks.","explain":"Walls are often brick."},{"type":"numeric","id":"m4","prompt":"{n} cups are glass and {m} are plastic. How many cups?","answer":"n+m","hint":"Add.","explain":"{=n+m} cups.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"A pencil is made of {n} parts. Each part is one material. How many materials?","answer":"n","hint":"One each.","explain":"{n} parts, so {n} materials.","params":{"n":[2,5]}},{"type":"mc","id":"m6","prompt":"A spoon can be made of…","choices":["metal, wood or plastic","only glass","only paper"],"answer":0,"hint":"Think of your kitchen.","explain":"Spoons come in metal, wood and plastic."},{"type":"mc","id":"m7","prompt":"Which is NOT a material?","choices":["a table","wood","glass"],"answer":0,"hint":"Things vs stuff.","explain":"A table is an object."}]},"status":"self-checked","visual":{"type":"objects","caption":"Choose an object and press Change material to hear the names of materials.","opts":{"objects":[["window",[["glass","#bae6fd"]]],["key",[["metal","#cbd5e1"]]],["T-shirt",[["fabric","#a5b4fc"]]],["wall",[["brick","#f87171"],["rock","#a8a29e"]]],["bag",[["fabric","#a5b4fc"],["plastic","#86efac"],["paper","#fde68a"]]]]}}},"mt_auVZZEuXjs":{"topicId":"mt_auVZZEuXjs","title":"Describing material properties","audience":"family","keyIdea":"We describe materials with pairs of words: hard or soft, stiff or bendy, shiny or dull, waterproof or not.","explain":{"kid":["Is it hard or soft? Is it shiny or dull? Does it bend? Does water soak in?","These words tell us what a material is like."],"adult":["Property words come in opposite pairs: hard/soft, stiff/bendy (flexible), shiny/dull, rough/smooth, waterproof/absorbent, transparent/opaque. Testing is better than guessing.","Let children test: bend it, drip water on it, scratch it with a coin, shine a torch at it. Then name the property in a sentence: 'foil is shiny and bendy'."]},"familyTip":"Test a sock, a spoon and a plastic bag. Is each one bendy? Waterproof? Shiny?","practice":[{"type":"mc","id":"p1","prompt":"Water soaks into a sponge. The sponge is…","choices":["absorbent","waterproof","shiny"],"answer":0,"hint":"It soaks up water.","explain":"Soaks up water: absorbent."},{"type":"mc","id":"p2","prompt":"The opposite of stiff is…","choices":["bendy","hard","dull"],"answer":0,"hint":"Can it bend?","explain":"Stiff and bendy are opposites."},{"type":"numeric","id":"p3","prompt":"You test {n} things. {m} are shiny. How many are dull?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"numeric","id":"p4","prompt":"{n} things are waterproof and {m} are not. How many things?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[1,5],"m":[1,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A coat that keeps rain out is…","choices":["waterproof","absorbent","transparent"],"answer":0,"hint":"Water stays out.","explain":"It keeps water out: waterproof."},{"type":"mc","id":"m2","prompt":"A metal spoon is…","choices":["shiny and stiff","soft and bendy","dull and absorbent"],"answer":0,"hint":"Test it in your mind.","explain":"Metal spoons are shiny and stiff."},{"type":"mc","id":"m3","prompt":"A towel is…","choices":["soft and absorbent","hard and shiny","waterproof"],"answer":0,"hint":"It dries you.","explain":"Towels soak up water and feel soft."},{"type":"numeric","id":"m4","prompt":"{n} of {=n+m} materials bend. How many do not bend?","answer":"m","hint":"Take away.","explain":"{=n+m} − {n} = {m}.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"You did {n} tests on each of {m} materials. How many tests?","answer":"n*m","hint":"Groups of tests.","explain":"{n} × {m} = {=n*m}.","params":{"n":[2,3],"m":[2,4]}},{"type":"mc","id":"m6","prompt":"The opposite of rough is…","choices":["smooth","soft","shiny"],"answer":0,"hint":"Run your hand on it.","explain":"Rough and smooth are opposites."},{"type":"mc","id":"m7","prompt":"Which test checks if a material is waterproof?","choices":["Drip water on it","Bend it","Scratch it"],"answer":0,"hint":"Water test.","explain":"Drip water and see if it soaks in."}]},"status":"self-checked","visual":{"type":"matlab","caption":"Pick a material, then do a test. What word describes it?","opts":{"materials":[["metal",{"bend":true,"water":true,"light":false,"scratch":true,"shine":true},"#cbd5e1"],["wood",{"bend":true,"water":false,"light":false,"scratch":true,"shine":false},"#d6a35c"],["glass",{"bend":true,"water":true,"light":true,"scratch":true,"shine":true},"#bae6fd"],["fabric",{"bend":false,"water":false,"light":false,"scratch":false,"shine":false},"#a5b4fc"],["plastic bag",{"bend":false,"water":true,"light":true,"scratch":false,"shine":true},"#86efac"],["paper",{"bend":false,"water":false,"light":false,"scratch":false,"shine":false},"#fde68a"]]}}},"mt_rTn43s8RNX":{"topicId":"mt_rTn43s8RNX","title":"Choosing the right material","audience":"family","keyIdea":"We choose a material because its properties suit the job.","explain":{"kid":["An umbrella must keep rain off, so we need a waterproof material. Paper would get soggy!","Think about what the job needs, then pick a material that does it."],"adult":["Ask two questions: what does the job need (waterproof, see-through, stiff, soft)? Which material has that property? Then explain the choice with 'because'.","Some materials fail in funny ways: a chocolate teapot melts, a paper umbrella soaks through. These help children reason about properties."]},"familyTip":"Ask: why are windows glass and not wood? Why are towels fabric and not plastic?","practice":[{"type":"mc","id":"p1","prompt":"An umbrella should be…","choices":["waterproof","absorbent","see-through"],"answer":0,"hint":"It keeps rain off.","explain":"It must keep water out: waterproof."},{"type":"mc","id":"p2","prompt":"A window needs a material that is…","choices":["see-through","soft","absorbent"],"answer":0,"hint":"You look through it.","explain":"You need to see through it, so glass."},{"type":"numeric","id":"p3","prompt":"You try {n} materials for an umbrella. {m} let water through. How many work?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,8],"m":[1,4]}},{"type":"numeric","id":"p4","prompt":"A bag holds {n} books. You need {=n*2}. How many bags?","answer":"2","hint":"Double.","explain":"{=n*2} ÷ {n} = 2 bags.","params":{"n":[2,5]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Why is a towel made of fabric?","choices":["Fabric soaks up water","Fabric is see-through","Fabric is shiny"],"answer":0,"hint":"A towel dries you.","explain":"Fabric is absorbent."},{"type":"mc","id":"m2","prompt":"Why is a saucepan made of metal?","choices":["Metal is strong and lets heat through","Metal is soft","Metal soaks up water"],"answer":0,"hint":"It goes on the cooker.","explain":"Metal is strong and conducts heat."},{"type":"mc","id":"m3","prompt":"A chocolate teapot is a bad idea because…","choices":["chocolate melts when hot","chocolate is see-through","chocolate is too hard"],"answer":0,"hint":"Hot tea!","explain":"It would melt."},{"type":"numeric","id":"m4","prompt":"{n} kids want raincoats. {m} have one. How many still need one?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"numeric","id":"m5","prompt":"Each window has {n} panes of glass. How many panes in {m} windows?","answer":"n*m","hint":"Groups.","explain":"{n} × {m} = {=n*m}.","params":{"n":[2,4],"m":[2,3]}},{"type":"mc","id":"m6","prompt":"Which is best for a wellington boot?","choices":["rubber","paper","fabric"],"answer":0,"hint":"Puddles!","explain":"Rubber is waterproof and bendy."},{"type":"mc","id":"m7","prompt":"A good material for a window is…","choices":["glass","wood","brick"],"answer":0,"hint":"See through.","explain":"Glass is transparent."}]},"status":"self-checked","visual":{"type":"matlab","caption":"The job: an umbrella. Try each material. Which ones would keep you dry?","opts":{"materials":[["metal",{"bend":true,"water":true,"light":false,"scratch":true,"shine":true},"#cbd5e1"],["wood",{"bend":true,"water":false,"light":false,"scratch":true,"shine":false},"#d6a35c"],["glass",{"bend":true,"water":true,"light":true,"scratch":true,"shine":true},"#bae6fd"],["fabric",{"bend":false,"water":false,"light":false,"scratch":false,"shine":false},"#a5b4fc"],["plastic bag",{"bend":false,"water":true,"light":true,"scratch":false,"shine":true},"#86efac"],["paper",{"bend":false,"water":false,"light":false,"scratch":false,"shine":false},"#fde68a"]],"job":["An umbrella",["water"]]}}},"mt_SwaNNdm_Ks":{"topicId":"mt_SwaNNdm_Ks","title":"Grouping materials","audience":"family","keyIdea":"We can group materials by a property, such as hard or soft, or shiny or dull.","explain":{"kid":["Put the hard things in one pile and the soft things in another. That is grouping.","You can group the same things a new way, like shiny and dull."],"adult":["Grouping means choosing one property and sorting by it. The same set can be grouped in several ways, which shows that a material has many properties at once.","Ask children to name the rule they used. A good rule is one you can test, like 'does a magnet stick?' or 'does it bend?'."]},"familyTip":"Tip out a box of odds and ends. Sort by one rule, then mix up and sort by another rule.","practice":[{"type":"mc","id":"p1","prompt":"Which goes with a rock, a spoon and a brick?","choices":["a coin (hard)","a sock (soft)","a pillow (soft)"],"answer":0,"hint":"They are all hard.","explain":"A coin is hard too."},{"type":"mc","id":"p2","prompt":"You sort by 'shiny or dull'. Where does a mirror go?","choices":["shiny","dull"],"answer":0,"hint":"Can you see yourself?","explain":"Mirrors are shiny."},{"type":"numeric","id":"p3","prompt":"You sort {n} things into 2 groups. One group has {m}. How many in the other?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[6,10],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"Group A has {n}, group B has {m}. How many in all?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[1,6],"m":[1,6]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A sock, a scarf and a teddy are all…","choices":["soft","hard","shiny"],"answer":0,"hint":"Squeeze them.","explain":"They are all soft."},{"type":"mc","id":"m2","prompt":"Which could be a sorting rule?","choices":["Does it bend?","Do I like it?","Is it Tuesday?"],"answer":0,"hint":"You can test it.","explain":"You can test if it bends."},{"type":"numeric","id":"m3","prompt":"{n} things are hard and {m} are soft. How many more hard than soft?","answer":"n-m","hint":"Find the difference.","explain":"{n} − {m} = {=n-m}.","params":{"n":[6,10],"m":[1,5]}},{"type":"numeric","id":"m4","prompt":"You have {n} shiny and {m} dull things. How many things?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[2,6],"m":[2,6]}},{"type":"mc","id":"m5","prompt":"Can a spoon be in the 'hard' group and the 'shiny' group?","choices":["Yes","No"],"answer":0,"hint":"Materials have many properties.","explain":"A metal spoon is both hard and shiny."},{"type":"mc","id":"m6","prompt":"Where does a wooden block go: shiny or dull?","choices":["dull","shiny"],"answer":0,"hint":"Look at it.","explain":"Wood is usually dull."},{"type":"mc","id":"m7","prompt":"Which does NOT belong with glass, metal and foil (shiny)?","choices":["a wool sock","a mirror","a coin"],"answer":0,"hint":"Which is dull?","explain":"Wool is dull."}]},"status":"self-checked","visual":{"type":"sorter","caption":"Pick a rule: is it hard or soft? Sort each thing.","opts":{"bins":["Hard","Soft"],"items":[["Rock",0],["Metal spoon",0],["Brick",0],["Wooden block",0],["Sock",1],["Sponge",1],["Teddy",1],["Scarf",1]]}}},"mt_1JFUNQDwAJ":{"topicId":"mt_1JFUNQDwAJ","title":"Solid, liquid and gas words","audience":"family","keyIdea":"A solid keeps its shape, a liquid flows and takes the shape of its container, and a gas spreads out to fill any space.","explain":{"kid":["A block of ice is a solid. It keeps its shape.","Water is a liquid. It runs and fills the bottom of a cup. Air is a gas. It spreads out to fill the room."],"adult":["Solids are hard and keep their shape. Liquids are runny: they flow, pour and take the shape of the container. Gases spread out to fill the space, and you often cannot see them.","Tricky cases help. Sand pours, but each grain is a solid. Honey is a slow liquid. Steam is water as a gas."]},"familyTip":"Find a solid, a liquid and a gas in the kitchen. Tip a cup of water: what does the top of the water do?","practice":[{"type":"mc","id":"p1","prompt":"Ice is a…","choices":["solid","liquid","gas"],"answer":0,"hint":"It keeps its shape.","explain":"Ice keeps its shape: solid."},{"type":"mc","id":"p2","prompt":"Milk is a…","choices":["liquid","solid","gas"],"answer":0,"hint":"It pours.","explain":"Milk pours: liquid."},{"type":"numeric","id":"p3","prompt":"You pour {n} cups of juice and {m} cups of milk. How many cups of liquid?","answer":"n+m","hint":"Add.","explain":"{=n+m} cups.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"{n} balloons are full of air. {m} pop. How many are left?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,9],"m":[1,4]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which fills the whole room?","choices":["a gas","a solid","a liquid"],"answer":0,"hint":"Spreads out.","explain":"Gases spread out to fill the space."},{"type":"mc","id":"m2","prompt":"Which takes the shape of the bottom of its cup?","choices":["a liquid","a solid","nothing"],"answer":0,"hint":"It flows.","explain":"Liquids flow to fill the bottom."},{"type":"mc","id":"m3","prompt":"Steam is water as a…","choices":["gas","solid","liquid"],"answer":0,"hint":"It floats up.","explain":"Steam is a gas."},{"type":"numeric","id":"m4","prompt":"{n} ice cubes melt. How many puddles of water? (one each)","answer":"n","hint":"Each cube makes one.","explain":"{n} puddles.","params":{"n":[2,8]}},{"type":"numeric","id":"m5","prompt":"There are {n} solids and {m} liquids on a table. How many things?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[1,6],"m":[1,6]}},{"type":"mc","id":"m6","prompt":"A word for a liquid is…","choices":["runny","rigid","hard"],"answer":0,"hint":"It flows.","explain":"Liquids are runny."},{"type":"mc","id":"m7","prompt":"A word for a solid is…","choices":["keeps its shape","pours","fills the room"],"answer":0,"hint":"Ice cube.","explain":"Solids keep their shape."}]},"status":"self-checked","visual":{"type":"states","caption":"Choose something, then tilt the jar. Does it keep its shape, flow, or fill the jar?","opts":{"items":[["Ice",0],["Water",1],["Air",2],["Wooden block",0],["Milk",1],["Steam",2]]}}},"mt_YQkUdIHO8L":{"topicId":"mt_YQkUdIHO8L","title":"Solids, liquids and gases","audience":"family","keyIdea":"We group materials as solids, liquids or gases by how they behave: keep shape, flow, or spread out.","explain":{"kid":["Solids keep their shape. Liquids flow and can be poured. Gases spread out to fill a space.","Sand can pour, but each grain is a tiny solid. It keeps its shape."],"adult":["Grouping by behaviour: does it keep its own shape (solid), flow and keep the same volume (liquid), or spread out to fill any container (gas)? Gases can be squashed; liquids and solids hardly can.","Powders such as sand and flour pour like liquids but are solids, because each grain keeps its shape. Gases are often invisible, so we notice them by smell or by what they push (wind, bubbles)."]},"familyTip":"Squeeze a syringe of air, then a syringe of water (outside, with care). Which one squashes?","practice":[{"type":"mc","id":"p1","prompt":"Sand pours. Is it a liquid?","choices":["No, each grain is a solid","Yes","It is a gas"],"answer":0,"hint":"Look at one grain.","explain":"Each grain keeps its shape: sand is a solid."},{"type":"mc","id":"p2","prompt":"Which can be squashed easily?","choices":["a gas","a liquid","a solid"],"answer":0,"hint":"Squeeze a balloon.","explain":"Gas particles are far apart, so gases squash."},{"type":"numeric","id":"p3","prompt":"A jar holds {n} bubbles of gas. {m} escape. How many are left?","answer":"n-m","hint":"Take away.","explain":"{=n-m} left.","params":{"n":[6,10],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"{n} cups of water fill a jug. How many cups fill {m} jugs?","answer":"n*m","hint":"Groups.","explain":"{n} × {m} = {=n*m}.","params":{"n":[2,5],"m":[2,3]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Honey flows slowly. It is a…","choices":["liquid","solid","gas"],"answer":0,"hint":"It pours.","explain":"Honey is a slow liquid."},{"type":"mc","id":"m2","prompt":"Which keeps the same shape in any container?","choices":["a solid","a liquid","a gas"],"answer":0,"hint":"Ice cube in a glass.","explain":"Solids keep their shape."},{"type":"mc","id":"m3","prompt":"Bubbles in fizzy drink are…","choices":["gas","liquid","solid"],"answer":0,"hint":"They float up.","explain":"The bubbles are gas."},{"type":"numeric","id":"m4","prompt":"You sort {n} solids, {m} liquids and 1 gas. How many things?","answer":"n+m+1","hint":"Add all.","explain":"{n} + {m} + 1 = {=n+m+1}.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"{n} of {=n+m} things pour. How many do not pour?","answer":"m","hint":"Take away.","explain":"{m}.","params":{"n":[1,5],"m":[1,5]}},{"type":"mc","id":"m6","prompt":"Flour pours. Is flour a solid?","choices":["Yes, it is a powder of tiny solid bits","No, it is a liquid","No, it is a gas"],"answer":0,"hint":"One grain.","explain":"Powders are solids."},{"type":"mc","id":"m7","prompt":"Which spreads out to fill a whole box?","choices":["a gas","a liquid","a solid"],"answer":0,"hint":"Spray scent.","explain":"Gases fill the space."}]},"status":"self-checked","visual":{"type":"states","caption":"Try each one in the jar and tilt it. Sand is a tricky one!","opts":{"items":[["Sand",0],["Honey",1],["Air",2],["Rock",0],["Juice",1],["Fizzy drink bubbles",2]]}},"lab":{"type":"gaslab","caption":"This is a gas: particles far apart and moving fast. Heat it or cool it and watch.","opts":{"n":25,"temp":300,"vol":1}}},"mt_Pl-nsjYGZ3":{"topicId":"mt_Pl-nsjYGZ3","title":"Heating and cooling changes","audience":"family","keyIdea":"Heating can melt a solid and boil a liquid; cooling can freeze a liquid; we measure the temperature in °C.","explain":{"kid":["Heat chocolate and it melts. Put water in the freezer and it turns to ice.","A thermometer tells us how hot or cold something is, in degrees (°C)."],"adult":["Each material changes state at its own temperature. Water melts at 0 °C and boils at 100 °C. Chocolate melts at about 34 °C, which is why it melts in a warm hand.","Heating moves along solid → liquid → gas; cooling goes back. Reading a thermometer at the moment of change is a good first science measurement."]},"familyTip":"Put a square of chocolate in your hand and one on a cold plate. Which melts first? Why?","practice":[{"type":"mc","id":"p1","prompt":"Ice melts when it is…","choices":["heated","cooled","squashed"],"answer":0,"hint":"Warm hands.","explain":"Heating melts ice."},{"type":"mc","id":"p2","prompt":"Water freezes at…","choices":["0 °C","100 °C","50 °C"],"answer":0,"hint":"Freezer.","explain":"Water freezes at 0 °C."},{"type":"numeric","id":"p3","prompt":"Water is at {t} °C. How many degrees warmer until it boils at 100 °C?","answer":"100-t","hint":"100 take away.","explain":"100 − {t} = {=100-t}.","params":{"t":[20,90]}},{"type":"numeric","id":"p4","prompt":"Room is {t} °C. Chocolate melts at 34 °C. How many degrees warmer?","answer":"34-t","hint":"Find the gap.","explain":"34 − {t} = {=34-t}.","params":{"t":[15,30]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Water boils at…","choices":["100 °C","0 °C","37 °C"],"answer":0,"hint":"Kettle.","explain":"Water boils at 100 °C."},{"type":"mc","id":"m2","prompt":"Cooling a liquid can make it…","choices":["freeze (turn solid)","boil","vanish"],"answer":0,"hint":"Freezer.","explain":"Cooling freezes it."},{"type":"numeric","id":"m3","prompt":"A drink is {t} °C. It cools by {d} °C. What is it now?","answer":"t-d","hint":"Take away.","explain":"{t} − {d} = {=t-d} °C.","params":{"t":[40,80],"d":[5,30]}},{"type":"numeric","id":"m4","prompt":"Ice is at −{d} °C. How many degrees warmer until it melts at 0 °C?","answer":"d","hint":"Up to zero.","explain":"{d} degrees.","params":{"d":[2,15]}},{"type":"mc","id":"m5","prompt":"Why does chocolate melt in your hand?","choices":["Your hand is warmer than its melting point","Hands are wet","It is a gas"],"answer":0,"hint":"About 34 °C.","explain":"Your hand is above 34 °C."},{"type":"mc","id":"m6","prompt":"We measure temperature with a…","choices":["thermometer","ruler","scale"],"answer":0,"hint":"°C.","explain":"A thermometer."},{"type":"mc","id":"m7","prompt":"Heating water a lot makes…","choices":["steam (a gas)","ice","sand"],"answer":0,"hint":"Kettle.","explain":"Boiling makes steam."}]},"status":"self-checked","visual":{"type":"particles","caption":"Chocolate: drag the temperature. Watch it melt near 34 °C.","opts":{"mp":34,"bp":200,"temp":20,"name":"chocolate","min":0,"max":60}},"lab":{"type":"gaslab","caption":"Heat the gas: the particles speed up. Cool it: they slow down.","opts":{"n":30,"temp":250,"vol":1}}},"mt_Mf-T-fYRLX":{"topicId":"mt_Mf-T-fYRLX","title":"Dissolving and solutions","audience":"family","keyIdea":"Some solids dissolve in water to make a solution; we get the solid back by evaporating the water.","explain":{"kid":["Stir sugar into warm water. The sugar seems to vanish. It has dissolved and made a solution.","Leave salty water in a warm place. The water dries up, and the salt is left behind."],"adult":["A soluble solid (salt, sugar) breaks into particles too small to see and spreads through the liquid: a solution. An insoluble solid (sand, chalk) does not, and can be caught by a filter.","Dissolving is reversible: evaporating the water leaves the solid behind. The mass is not lost; the dissolved solid is still there."]},"familyTip":"Try sugar, sand and salt in three cups of warm water. Which dissolve? Leave the salt water on a sunny sill for a few days.","practice":[{"type":"mc","id":"p1","prompt":"Sugar stirred into water…","choices":["dissolves","melts into a gas","stays as lumps"],"answer":0,"hint":"It seems to vanish.","explain":"It dissolves to make a solution."},{"type":"mc","id":"p2","prompt":"Sand in water…","choices":["does not dissolve","dissolves","turns to gas"],"answer":0,"hint":"It sinks.","explain":"Sand is insoluble."},{"type":"numeric","id":"p3","prompt":"You dissolve {n} g of salt in water. How much salt is left after it evaporates, in g?","answer":"n","hint":"Salt stays behind.","explain":"All {n} g is left.","params":{"n":[5,30]}},{"type":"numeric","id":"p4","prompt":"{n} g of sugar goes into {m} g of water. What is the mass of the solution, in g?","answer":"n+m","hint":"Add the masses.","explain":"{n} + {m} = {=n+m} g.","params":{"n":[5,20],"m":[100,200]}}],"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"How do you get salt back from salty water?","choices":["Evaporate the water","Use a sieve","Use a magnet"],"answer":0,"hint":"Heat it gently.","explain":"Evaporating leaves the salt."},{"type":"mc","id":"m2","prompt":"How do you get sand out of water?","choices":["Filter it","Evaporate only","Stir it"],"answer":0,"hint":"Sand is insoluble.","explain":"A filter catches the sand."},{"type":"mc","id":"m3","prompt":"A material that dissolves is…","choices":["soluble","insoluble","opaque"],"answer":0,"hint":"Sol-.","explain":"Soluble means it dissolves."},{"type":"numeric","id":"m4","prompt":"{n} g of salt in {m} g of water. Mass of the salt water, in g?","answer":"n+m","hint":"Nothing is lost.","explain":"{=n+m} g.","params":{"n":[5,25],"m":[50,150]}},{"type":"numeric","id":"m5","prompt":"You start with {n} g of sugar and dissolve it. How many grams are still in the water?","answer":"n","hint":"It's still there.","explain":"{n} g.","params":{"n":[5,40]}},{"type":"mc","id":"m6","prompt":"Is dissolving reversible?","choices":["Yes, evaporate to get the solid back","No, never"],"answer":0,"hint":"Salt from sea water.","explain":"You can get the solid back."},{"type":"mc","id":"m7","prompt":"Warm water usually dissolves sugar…","choices":["faster","slower","not at all"],"answer":0,"hint":"Tea!","explain":"Warmer water dissolves sugar faster."}]},"status":"self-checked","visual":{"type":"separate","caption":"A mixture of gravel, sand, salt and water. Try each method: which takes out what?","opts":{"mix":[["gravel","sieve"],["sand","filter"],["salt (dissolved)","evaporate"],["water","none"]]}}}},"goals":{"note":"Profile goals and age-band defaults. Each goal points at a target topic; 'learn next' only suggests topics on the way to it, ranked by distance to it.","goals":[{"id":"fractions","label":"Fractions","target":"mt_FbDKeLfBCo"},{"id":"algebra","label":"Algebra: linear equations","target":"mt_mmUVPwnv3o"},{"id":"calculus","label":"Calculus: tangents with the derivative","target":"mt_vqlq_sKWKm"},{"id":"integration","label":"Calculus: integration and area","target":"mt_KceIV8SGuG"},{"id":"chemistry","label":"Chemistry: balancing equations","target":"mt_BXj4pfdhxO"},{"id":"explore","label":"Just exploring","target":null}],"bands":[{"id":"u10","label":"Under 10","assumeKnownUpTo":0,"reading":"kid"},{"id":"10-12","label":"10–12","assumeKnownUpTo":10,"reading":"kid"},{"id":"13-15","label":"13–15","assumeKnownUpTo":12,"reading":"adult"},{"id":"16-18","label":"16–18","assumeKnownUpTo":14,"reading":"adult"},{"id":"adult","label":"Adult","assumeKnownUpTo":14,"reading":"adult"},{"id":"grand","label":"Grandparent","assumeKnownUpTo":14,"reading":"adult"}],"skipFromBand10":{"note":"Early-years skills that aren't meaningful 'next steps' for learners aged 10+; treated as done for them.","subjects":["Personal & Social Development","Learning to Learn","Life Skills"],"domains":["Handwriting & Transcription","Phonics & Word Reading"]}},"resources":[{"subject":"Mathematics","maxAge":6,"label":"BBC Bitesize: KS1 Maths","url":"https://www.bbc.co.uk/bitesize/subjects/zjxhfg8"},{"subject":"Mathematics","maxAge":10,"label":"BBC Bitesize: KS2 Maths","url":"https://www.bbc.co.uk/bitesize/subjects/z826n39"},{"subject":"Mathematics","maxAge":13,"label":"BBC Bitesize: KS3 Maths","url":"https://www.bbc.co.uk/bitesize/subjects/zqhs34j"},{"subject":"Mathematics","maxAge":99,"label":"BBC Bitesize: GCSE Maths","url":"https://www.bbc.co.uk/bitesize/subjects/z38pycw"},{"subject":"Science","maxAge":6,"label":"BBC Bitesize: KS1 Science","url":"https://www.bbc.co.uk/bitesize/subjects/z6svr82"},{"subject":"Science","maxAge":10,"label":"BBC Bitesize: KS2 Science","url":"https://www.bbc.co.uk/bitesize/subjects/z2pfb9q"},{"subject":"Science","maxAge":13,"label":"BBC Bitesize: KS3 Science","url":"https://www.bbc.co.uk/bitesize/subjects/zng4d2p"},{"subject":"Science","maxAge":99,"label":"BBC Bitesize: GCSE Science","url":"https://www.bbc.co.uk/bitesize/subjects/zrkw2hv"}],"resourcesVerified":"2026-10-19"};
