 ctl(hA,()=>A,v=>{const T=[A[0]+B[0],A[1]+B[1]];A=clampA(v);B=[T[0]-A[0],T[1]-A[1]]},'First walk');ctl(hB,()=>[A[0]+B[0],A[1]+B[1]],v=>{const T=clampA(v);B=[T[0]-A[0],T[1]-A[1]]},'Second walk');
