  let d='',pen=false;for(let i=0;i<=300;i++){const x=Pl.x0+(Pl.x1-Pl.x0)*i/300,y=f(x);if(!isFinite(y)||Math.abs(y)>1e4){pen=false;continue}d+=(pen?'L':'M')+Pl.sx(x).toFixed(1)+' '+Pl.sy(y).toFixed(1);pen=true}cur.setAttribute('d',d);
